RG.HK["19"] = [{"id":"19_takeda_yakata","n":"躑躅ヶ崎館（武田氏館・今の武田神社）","yomi":"つつじがさきやかた","cat":"城","rank":"S","y":1519,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"甲府市古府中町","st":"JR甲府駅北口からバスで約8分「武田神社」下車。歩くと約25分","la":35.6868,"lo":138.5775,"hook":"«天下の名将» 武田信玄は、高い石垣の城ではなく、堀と土塁に囲まれた «館» に住んでいた。","lead":"1519年、信玄の父・武田信虎が石和から本拠を移して建てた館です。信玄・勝頼まで3代、約60年にわたって甲斐の政治の中心でした。いまは館の跡に武田神社が建ち、まわりの堀や土塁から当時の形を想像できます。","story":["1519年、甲斐の国をようやくまとめつつあった武田信虎は、それまでの石和の館をはなれ、北の山すそ «躑躅ヶ崎» に新しい館を建てました。背中に山、前に甲府盆地。«なぜここに?» 平地の真ん中より守りやすく、しかも城下町を広げる土地がある。信虎はここを中心に家臣を住まわせ、今の甲府の町の原形をつくりました。","翌年には館の北の山に «要害山城» を築きます。ふだんは館で暮らし、いざという時は山の城に立てこもる。これが戦国の «館＋詰めの城» のセットでした。1521年、今川方の軍勢が甲斐に攻め込んだとき、信虎の妻は要害山のふもとに避難し、そこで男の子を産みます。のちの信玄です。","1541年、21歳の晴信（信玄）は父・信虎を駿河へ追い出し、この館の主になりました。ここから信濃へ兵を進め、川中島で上杉謙信と何度も戦います。館には家臣が集まって作戦を練り、全国の大名への手紙がここから送られました。«人は城、人は石垣、人は堀» という歌が信玄の言葉として語られますが、これは後の時代の軍記物にもとづくもので、本人の言葉と確かめられてはいません。","信玄の死後、息子の勝頼は1581年、韮崎に新府城を築いて本拠を移します。館を捨てた翌年、武田氏は織田・徳川の攻撃で滅びました。その後、館は徳川方の城として手が入れられましたが、甲府城ができると役目を終え、しだいに田畑にもどっていきました。","大正時代の1919年、信玄をまつる武田神社が館の跡に建てられました。いま参道の橋をわたる時、足元の堀は戦国時代の堀そのもの。神社の裏手にまわると、土塁や曲輪（くるわ）の形が今も残っています。"],"tl":[["1519年","武田信虎が石和から本拠を移し、館を築く"],["1520年","北の山に詰めの城・要害山城を築く"],["1521年","信玄（晴信）が誕生"],["1541年","晴信が父・信虎を駿河へ追放し、館の主となる"],["1573年","信玄、西上作戦の帰りに信濃で病死"],["1581年","勝頼が新府城へ本拠を移す"],["1582年","武田氏滅亡。のち徳川方が館に手を入れる"],["1919年","館の跡に武田神社が創建される"],["1938年","«武田氏館跡» として国の史跡に指定"]],"who":[["武田信虎","館を築いた信玄の父。のちに信玄に追放される"],["武田信玄（晴信）","この館を本拠に甲斐・信濃を治めた戦国大名"],["武田勝頼","信玄の子。館を出て新府城へ移った"],["大井夫人","信虎の妻で信玄の母。戦の中で信玄を産んだ"]],"deep":["館は一辺およそ200mの四角い «方形居館» が中心で、まわりに西曲輪・味噌曲輪・梅翁曲輪などが付け足されていきました。最初から完成形だったのではなく、代を重ねて広がったと考えられています。","館の北西には «天守台» とよばれる石積みがあります。石垣を使う技術から見て、武田氏が滅んだ後、徳川・豊臣の時代に手を加えたものと考えられています。","発掘では «かわらけ»（素焼きの皿）が大量に出ています。宴会や儀式で使い捨てにされた器で、館が政治と儀礼の場だったことを物語ります。","«人は城、人は石垣…» の歌は、江戸時代にまとめられた軍学書『甲陽軍鑑』の世界から広まったものとされます。信玄が大きな城を造らなかった理由を説明する話として人気ですが、実際には要害山城という山城も持っていました。","信虎が本拠を移したことで、家臣たちも館のまわりに屋敷を構えました。これが «甲府» という地名の始まりで、«甲斐の府中» を意味します。","武田神社の宝物殿では、武田氏ゆかりの品が見られます（展示は時期で変わります）。"],"look":["神社の正面の橋と水堀（戦国時代の堀）","大手門の東側に残る土塁と石塁の跡","西曲輪の土塁と、北西の天守台の石積み","神社裏手の «姫の井戸» など館にまつわる井戸","甲府駅前の信玄公の銅像とあわせて城下の広がりを感じる"],"q":["«甲府» という地名は、どんな意味から生まれた？","«甲斐の府中»、つまり甲斐の国の中心という意味。信虎がここに館を移したことで生まれた呼び名です。"],"koji":[{"w":"人は城、人は石垣、人は堀","m":"国を守るのは建物ではなく人だ、という意味。信玄の言葉として伝わるが、後世の軍記物にもとづく"}],"myth":"«人は城…» の歌が信玄自身の作かどうかは不明。天守台の築かれた時期にも諸説ある。","img":["武田神社","武田信玄","武田信虎"],"wp":"武田氏館","rel":{"ev":[],"grave":[]},"ph":[["c:b/bf/Takedasi-Yakata20251017.jpg",6000,4000,"武田氏館"],["c:e/e7/Takedasi-Yakata20251017b.jpg",6000,4000],["c:b/ba/Takedasi-Yakata20251017a.jpg",6000,4000],["c:a/ad/Takeda-jinja-1.jpg",2627,1700,"武田神社"],["c:3/33/Takeda_Harunobu.jpg",1400,1707,"武田信玄"],["c:f/fc/Takeda_Nobutora_by_Takeda_Nobukado_%28Daisenji_Kofu%29.jpg",358,864,"武田信虎"]]},{"id":"19_kuonji","n":"身延山久遠寺（日蓮が晩年を過ごし眠る総本山）","yomi":"みのぶさんくおんじ","cat":"寺社","rank":"S","y":1274,"era":["kamakura","muromachi","edo"],"sh":"","ad":"南巨摩郡身延町身延","st":"JR身延線 身延駅からバスで約12分「身延山」下車、歩いて約10分","la":35.3855,"lo":138.4232,"hook":"鎌倉幕府と対立し、島流しから帰った日蓮が «最後の居場所» に選んだのは、山深い身延の谷だった。","lead":"1274年、日蓮が弟子とともに身延の山に入り、小さな草庵を結んだのが始まりです。日蓮はここで約9年を過ごし、亡くなったあとお墓もここに作られました。今は日蓮宗の総本山で、287段の石段 «菩提梯» で知られます。","story":["1274年、佐渡への流罪を許されて鎌倉に戻った日蓮は、幕府に三度目の意見をしましたが、聞き入れられませんでした。«国をいさめても用いられないなら、山に入ろう»。そう決めた日蓮を迎えたのが、身延一帯を治めていた地頭・波木井実長（南部実長）でした。","日蓮が身延に着いたのは、その年の5月。はじめは山の中の小さな庵で、冬は雪に閉ざされ、食べ物にも困る暮らしだったといいます。それでも全国の信者に向けてたくさんの手紙を書き、弟子を育てました。今に伝わる日蓮の手紙の多くは、この身延時代のものです。","1282年、体の弱った日蓮は、病をいやすため常陸の温泉へ向かいます。しかし途中の武蔵国池上（今の東京都大田区）で力つき、亡くなりました。遺骨は身延に運ばれ、山の中に墓が作られます。日蓮は生前、«どこで死んでも、墓は身延の沢に» という意味のことを書き残したと伝わります。","日蓮の死後、弟子たちが交代で墓を守りました。そのうちの一人、日興は波木井氏との考えの違いから山を下り、富士山のふもとに移ります。«なぜ一番弟子クラスの人が去ったのか?»。この «身延離山» は、のちに日蓮宗の中でいくつもの流れが生まれるきっかけのひとつになりました。","室町時代の1474年、第11世の日朝が、狭い谷から現在の広い場所へ寺を移し、大きな伽藍を整えました。江戸時代には大名から庶民まで参詣者が集まり、«身延詣で» は一生に一度の旅になりました。今も、朝のお勤めの太鼓の音が杉林にひびいています。"],"tl":[["1274年","日蓮が身延に入り、草庵を結ぶ"],["1282年","日蓮、武蔵国池上で亡くなる。遺骨は身延へ"],["1289年ごろ","日興が身延を離れる（身延離山）"],["1474年","日朝が寺を現在地へ移し、伽藍を整える"],["江戸時代","身延詣でが盛んになり、門前町がにぎわう"],["1875年","大火で多くの堂が焼ける"],["2009年","五重塔が再建される"]],"who":[["日蓮","鎌倉時代の僧。法華経を広め、晩年をここで過ごした"],["波木井実長","身延の地頭。日蓮を招き、寺の土地を寄進した"],["日興","日蓮の弟子。のちに身延を離れて富士へ移った"],["日朝","室町時代の第11世。寺を現在地に移して大きくした"]],"deep":["«菩提梯»は287段、高低差は約100m。«南無妙法蓮華経» の7字になぞらえて7つの区切りがあるといわれます。きつい人のために «男坂»«女坂» という迂回路もあります。","日蓮の草庵があった場所は、今の本堂から少し離れた «御草庵跡» として残り、日蓮の墓所 «御廟所» もその近くにあります。本堂の場所と日蓮の住まいの場所がちがうのは、日朝の移転のためです。","日蓮の身延時代の手紙（遺文）は、信者の家族のことを気づかう温かい内容も多く、きびしい宗教家というイメージとは別の顔を見せてくれます。","身延離山の理由は、波木井実長が日蓮の教えに反する行いをしたため、と日興側の史料は伝えます。一方、身延側には別の見方もあり、宗派によって評価が分かれます。","奥之院 «思親閣» は身延山の山頂にあり、日蓮が故郷の安房の父母をしのんだ場所と伝わります。今はロープウェイで上がれます。","1875年の大火では多くの建物と宝物が失われました。今の三門や本堂の多くは明治以降の再建です。"],"look":["287段の石段 «菩提梯»","日蓮の御廟所と御草庵跡","本堂・祖師堂と、再建された五重塔","春の «しだれ桜»","ロープウェイで上る奥之院思親閣からの眺め"],"q":["菩提梯の石段は何段ある？","287段。題目の7字になぞらえた7つの区切りがあるといわれます。"],"koji":[],"myth":"«墓は身延の沢に» の言葉は遺文の一節として伝わるもの。身延離山の理由は宗派で見方が分かれる。","img":["日蓮","日興","南部実長"],"wp":"久遠寺","rel":{"ev":[],"grave":[]},"ph":[["c:a/af/Kuonji-temple-Hondou.jpg",800,600,"久遠寺"],["c:1/1e/%E8%BA%AB%E5%BB%B6%E5%B1%B1%E4%B9%85%E9%81%A0%E5%AF%BA%E5%A4%A7%E5%A5%A5_-_panoramio.jpg",5156,3414],["c:c/c1/%E8%BA%AB%E5%BB%B6%E5%B1%B1%E4%B9%85%E9%81%A0%E5%AF%BA_-_panoramio_%282%29.jpg",5146,3223],["c:5/58/%E8%BA%AB%E5%BB%B6%E5%B1%B1%E4%B9%85%E9%81%A0%E5%AF%BA_-_panoramio_%2812%29.jpg",5054,3248],["c:9/9f/NDL-DC_2586550-15_Kawase_Hasui_S0509_crd.jpg",4368,6448],["c:d/d2/KuonjileBodaitei.JPG",3000,4000],["c:7/71/Kuonji-1.jpg",3823,3005],["c:5/5f/%E8%BA%AB%E5%BB%B6%E5%B1%B1%E4%B9%85%E9%81%A0%E5%AF%BA_-_panoramio.jpg",4823,2786]]},{"id":"19_erinji","n":"恵林寺（武田信玄の墓所・快川紹喜「心頭滅却」）","yomi":"えりんじ","cat":"墓所","rank":"S","y":1582,"era":["kamakura","azuchi","edo"],"sh":"国指定名勝（庭園）・国の重要文化財（四脚門）","ad":"甲州市塩山小屋敷","st":"JR中央本線 塩山駅からバスで約10分「恵林寺」下車","la":35.7223,"lo":138.7448,"hook":"燃えさかる山門の上で、老僧は言った。«心頭を滅却すれば、火もまたおのずから涼し»。","lead":"鎌倉時代の終わりに夢窓疎石を開山として開かれた禅寺で、武田信玄が菩提寺と定めました。信玄のお墓があり、武田氏が滅んだ1582年には織田軍に焼かれ、住職の快川紹喜が火の中で亡くなったことで知られます。","story":["1330年、甲斐の領主・二階堂貞藤が、名僧・夢窓疎石をまねいて寺を開きました。夢窓疎石は庭づくりの名人でもあり、今も本堂の裏には夢窓の作と伝わる池泉の庭が残っています。","戦国時代、信玄はこの寺を自分の菩提寺と決め、美濃から名高い禅僧・快川紹喜をまねきました。信玄は快川を深く敬い、たびたび教えを受けたといわれます。1573年に信玄が亡くなると、その死は3年間かくされ、1576年にこの寺で正式な葬儀が行われました。","1582年、織田・徳川の大軍が甲斐に攻め込み、武田勝頼は3月に田野で命を落とします。ところが恵林寺は、織田に敵対した近江・六角氏ゆかりの人物などをかくまい、引き渡しませんでした。4月、織田信忠の軍勢は僧たちを山門の楼上に追い上げ、下から火を放ったと伝わります。","炎に包まれながら、快川はこう唱えたといいます。«安禅は必ずしも山水をもちいず、心頭を滅却すれば火もおのずから涼し»。静かに座禅をするのに山や川は必要ない、心の持ちようしだいで火さえ涼しい――。百人をこえる僧が命を落としたとされ、門の «快川国師» の額の前では、今も手を合わせる人がたえません。","焼け跡の寺は、武田を滅ぼした側の徳川家康によって再建されました。江戸時代には甲府藩主・柳沢吉保とその家族の墓も移され、武田と柳沢、甲斐をおさめた二つの家の記憶が一つの境内にねむっています。"],"tl":[["1330年","二階堂貞藤が夢窓疎石を開山として創建"],["1564年ごろ","信玄が快川紹喜をまねく"],["1573年","信玄死去。死は3年間かくされる"],["1576年","恵林寺で信玄の本葬が行われる"],["1582年4月","織田軍の焼き討ち。快川ら多くの僧が亡くなる"],["1582年以後","徳川家康が寺の再建を支える"],["江戸時代","柳沢吉保一族の墓が境内に置かれる"]],"who":[["夢窓疎石","開山。庭をつくった名僧と伝わる"],["武田信玄","この寺を菩提寺とした。墓所がある"],["快川紹喜","信玄が招いた住職。焼き討ちで火中に亡くなる"],["織田信忠","信長の長男。甲州征伐の総大将"],["柳沢吉保","江戸時代の甲府藩主。墓がこの寺にある"]],"deep":["«心頭滅却すれば火もまた涼し» の句は、もとは唐の詩人・杜荀鶴の詩にもとづく言葉とされます。快川がそれを最期に唱えた、というのが伝わる話です。","焼き討ちの理由には、六角氏ゆかりの人物をかくまったことのほか、武田方の残党をかばったこと、寺が武田の精神的な支えだったことなどが挙げられます。","信玄の墓は本堂の奥にあり、ふだんは拝観料を払った見学ルートの中で参拝できます。毎年4月12日ごろ、信玄の命日にあわせた法要が行われます。","柳沢吉保は将軍・徳川綱吉の側近として知られ、甲府15万石の藩主になりました。武田氏の旧臣の流れをくむともいわれ、武田ゆかりの寺にねむっています。","赤い «三門» は焼き討ちの現場とされる門を受けついだもので、快川の句を記した額がかかっています。四脚門（赤門）は江戸時代初めの建物で国の重要文化財です。","境内には «武田不動尊» という、信玄をモデルにしたと伝わる不動明王の像がまつられています。"],"look":["快川の句がかかる三門","夢窓疎石作と伝わる庭園（国指定名勝）","本堂奥の武田信玄の墓所","柳沢吉保夫妻の墓","信玄をモデルにしたと伝わる武田不動尊"],"q":["快川紹喜が火の中で唱えたと伝わる言葉は？","«心頭を滅却すれば火もおのずから涼し»。心を無にすれば火さえ涼しく感じる、という意味です。"],"koji":[{"w":"心頭滅却すれば火もまた涼し","m":"心の持ち方しだいで、どんな苦しみも苦しくなくなるということ"}],"myth":"快川の最期の言葉や焼き討ちの細かい様子は、後の記録や伝承による部分が多い。亡くなった僧の人数にも諸説。","img":["快川紹喜","夢窓疎石","武田信玄","柳沢吉保"],"wp":"恵林寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/Erinji_main_gate.JPG",4000,3000,"恵林寺"],["c:0/09/Monument_of_Daishogiri-sodo_peasant_uprising.JPG",3000,4000],["c:1/15/Grave_of_Takeda_Shingen_in_Erinji.JPG",4000,3000],["c:1/11/Erinji_rock_garden.JPG",4000,3000],["c:5/55/Erinji_garden_and_Corridors.JPG",4000,3000],["c:e/e6/Erinji_garden_Places_of_Scenic_Beauty.JPG",4000,3000],["c:1/12/Erinji_Uguisu_Corridors.JPG",4000,3000],["c:1/1e/Erinji_Takeda_Acala.JPG",4000,3000]]},{"id":"19_kofu_jo","n":"甲府城（舞鶴城・豊臣方の東国押さえ）","yomi":"こうふじょう","cat":"城","rank":"S","y":1590,"era":["azuchi","edo"],"sh":"国指定史跡","ad":"甲府市丸の内","st":"JR甲府駅南口から歩いて約5分","la":35.663,"lo":138.57,"hook":"武田氏の館とはまるでちがう、高い石垣の城。それは «武田のあと» を治める天下人の力を見せつける城だった。","lead":"武田氏が滅んだあと、甲府駅のすぐ南の小高い丘に築かれた石垣の城です。豊臣秀吉の時代に、関東の徳川家康をにらむ «押さえの城» として完成したと考えられています。いまは «舞鶴城公園» として整備され、石垣と復元された門や櫓が見られます。","story":["1582年、武田氏が滅びると、甲斐はしばらく争いの舞台になりました。やがて徳川家康がこの国を手に入れ、一条小山とよばれた丘に新しい城を計画したとされます。«なぜ武田の館ではなく新しい城を?» 武田の時代の館は土の城。新しい支配者は、石垣と瓦の城で «時代が変わった» ことを示す必要がありました。","1590年、豊臣秀吉が北条氏を倒すと、家康は関東へ移されます。空いた甲斐には秀吉の一族や信頼する家臣が次々に入りました。羽柴秀勝、加藤光泰、そして浅野長政・幸長の父子。彼らのもとで工事が進み、城は完成へ向かいます。東の家康を見張る、豊臣政権の最前線だったのです。","発掘では、金箔を貼った瓦が見つかっています。金箔瓦は豊臣政権の大名の城でよく使われたもので、«天守があったのでは?» という議論のきっかけになりました。天守台の石垣は今も残りますが、天守が実際に建っていたかどうかは、はっきりしていません。","江戸時代になると、甲府城は徳川家の親族や重臣が治める大事な城になりました。1704年には将軍の側近・柳沢吉保が城主となり、城下町を整えます。しかし吉保の子が大和郡山へ移ると、甲府は幕府の直接の支配地になり、«甲府勤番» という旗本たちが城を守りました。","明治になると城は廃止され、敷地の一部には鉄道が通り、建物は失われました。それでも石垣はよく残り、平成に入ってから稲荷櫓や鉄門が昔の姿に復元されました。天守台に立つと、南アルプスや富士山まで見わたせます。"],"tl":[["1583年ごろ","徳川家康の時代に築城が計画されたとされる（諸説）"],["1590年","秀吉の天下統一後、豊臣方の大名が甲斐に入る"],["1590年代","浅野長政・幸長のころにほぼ完成したと考えられる"],["1704年","柳沢吉保が甲府城主となる"],["1724年","柳沢家が大和郡山へ移り、甲府勤番の支配に"],["1873年","廃城"],["2004年","稲荷櫓が復元される"],["2013年","鉄門が復元される"],["2019年","国の史跡に指定"]],"who":[["浅野長政","秀吉の重臣。甲斐を治め、城の完成に関わった"],["加藤光泰","浅野氏の前の城主。築城を進めたとされる"],["徳川家康","武田滅亡後に甲斐を手に入れた。築城の始まりに関わる説がある"],["柳沢吉保","江戸時代の甲府城主。城下を整えた"]],"deep":["石垣の多くは自然の石をあまり加工せずに積む «野面積み» です。豊臣政権のころの古い石垣の特徴がよく残り、東日本では貴重な例とされます。","金箔瓦のほか、鯱瓦や家紋入りの瓦も出土しています。浅野家の家紋の瓦もあり、城主の移り変わりを瓦から読み取れます。","築城の始まりについては、家康の時代とする説、秀吉の時代とする説があり、はっきりしません。長い工事の間に何人もの大名が関わったと考えられます。","城の中に «謝恩碑» という高い石碑があります。明治の終わりに山梨県で大水害が起き、皇室の林が県に下げ渡されたことへの感謝を記したもので、大正時代に建てられました。","城の北側はJR中央線に分断されています。駅の北にも城の一部だった場所があり、線路をはさんで城域が広がっていたことがわかります。","«舞鶴城» という呼び名は、城の形が鶴が舞う姿に見えたから、などといわれますが、由来ははっきりしません。"],"look":["天守台と、そこからの眺め","野面積みの高い石垣","復元された稲荷櫓と鉄門","金箔瓦などの出土品の展示（稲荷櫓内など）","謝恩碑"],"q":["甲府城が豊臣政権にとって大事だった理由は？","関東に移った徳川家康を西側から見張る «押さえの城» だったからです。"],"koji":[],"myth":"築城開始の時期と天守の有無は諸説。«舞鶴城» の名の由来も不明。","img":["舞鶴城公園","浅野長政","甲府勤番"],"wp":"甲府城","rel":{"ev":["k_koshu"],"grave":[]},"ph":[["c:3/3b/Koufu_Castle_%284936837377%29.jpg",1280,853,"甲府城"],["c:0/06/Uchimatsukage_Gate_Kofu_Castle.JPG",4608,3072],["c:6/6f/Onshirin_Kinen_Kan_Kofu_Castle.JPG",4608,3072],["c:2/2d/Monument_of_Kofu_Castle.JPG",4608,3072],["c:d/d1/Kurogane_Gate_Kofu_Castle.JPG",4608,3072],["c:7/7d/Kofu_Castle_and_Kofu_Station.JPG",4000,3000],["c:1/19/Kofu_Castle4.jpg",4496,3000],["c:a/a7/Kajikuruwa_Gate_Kofu_Castle.JPG",4608,3072]]},{"id":"19_shinpu_jo","n":"新府城（武田勝頼が築いた最後の本拠）","yomi":"しんぷじょう","cat":"城","rank":"S","y":1581,"era":["azuchi"],"sh":"国指定史跡","ad":"韮崎市中田町中條","st":"JR中央本線 新府駅から歩いて約20分","la":35.7355,"lo":138.446,"hook":"新しい都を夢見て築いた城に、勝頼が住めたのはわずか3か月足らず。最後は自らの手で火をかけた。","lead":"武田信玄の子・勝頼が、織田・徳川に備えて韮崎の «七里岩» の台地に築いた城です。1581年の暮れに移り住みましたが、翌1582年3月、敵が迫る中で火を放って捨てました。土塁や堀、«丸馬出» などの跡がよく残っています。","story":["1575年、長篠の戦いで大きな痛手を受けた武田勝頼は、父の代からの躑躅ヶ崎館では守りきれないと考えるようになります。«もっと強い城を、新しい場所に»。選ばれたのは、釜無川と塩川にけずられてできた断崖の台地 «七里岩» の上でした。","1581年、工事が始まります。家臣の真田昌幸が築城の指図に関わったと伝わり、昌幸の名で各地に人手を集める文書も残るとされます。その年の12月、勝頼は一族や家臣とともに甲府から新府へ移りました。新しい府、«新府» の名には、再出発の願いがこめられていたのでしょう。","しかし翌1582年2月、信濃の木曽義昌が織田方に寝返ったのをきっかけに、織田・徳川の大軍が一気に攻め込みます。3月2日、弟の仁科盛信が守る高遠城が落ちると、勝頼は新府城での籠城をあきらめました。«まだ完成していない城では戦えない»――。","3月3日、勝頼は城に火を放ち、東へ向かいました。人質として預かっていた人々も城とともに焼かれたと伝わります。わずか8日後、勝頼は田野で最期をむかえます。新府城は、武田氏の夢と終わりの両方を見届けた城になりました。","武田氏が滅んだ年の夏、今度は北条氏と徳川氏が甲斐をめぐって争います。このとき家康は新府城に本陣を置き、北条の大軍とにらみ合いました。捨てられた城が、もう一度だけ歴史の表舞台に立った瞬間です。"],"tl":[["1575年","長篠の戦いで武田軍が大敗"],["1581年","新府城の築城が始まる"],["1581年12月","勝頼が甲府から新府城へ移る"],["1582年3月2日","高遠城が落城"],["1582年3月3日","勝頼が新府城に火を放って退く"],["1582年3月11日","勝頼、田野で自害。武田氏滅亡"],["1582年夏〜秋","天正壬午の乱で徳川家康が本陣を置く"],["1973年","国の史跡に指定"]],"who":[["武田勝頼","城を築き、3か月足らずで捨てた武田家最後の当主"],["真田昌幸","武田の家臣。築城に関わったと伝わる"],["木曽義昌","信濃の武将。織田方に寝返り、甲州征伐のきっかけを作った"],["徳川家康","武田滅亡後、この城に本陣を置いて北条軍と対した"]],"deep":["城の西側は高さ数十mの七里岩の断崖で、ここからは攻められません。そのため、守りの工夫は東と北に集中しています。","北側には堀の中へ突き出した «出構（でがまえ）» という珍しい遺構が2か所あります。鉄砲で横から撃つための施設、水をためる施設など、用途には諸説あります。","南側には半円形の «丸馬出» と «三日月堀» が残ります。丸馬出は武田氏の城の特徴として知られる形です。","勝頼が移った時点で城は未完成だったとする見方と、ある程度できあがっていたとする見方があり、発掘の成果をもとに議論が続いています。","本丸の跡には藤武稲荷神社があり、勝頼をしのぶ石碑も建っています。毎年4月には «新府城跡まつり» などの催しが行われてきました。","«真田昌幸が築城を指揮した» 話は有名ですが、どこまで関わったかは史料の読み方で意見が分かれます。"],"look":["本丸跡と藤武稲荷神社の長い石段","北側の出構（2か所）","南側の丸馬出と三日月堀","西側の七里岩の断崖（外から見上げるとよくわかる）"],"q":["勝頼が新府城に住んだのは、およそどのくらいの期間？","1581年12月から翌年3月3日まで、3か月足らずです。"],"koji":[],"myth":"真田昌幸の関わりの程度、出構の用途、城がどこまで完成していたかは諸説。","img":["武田勝頼","真田昌幸","七里岩","天正壬午の乱"],"wp":"新府城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7e/Shinpu_Castle.jpg",2048,1536,"新府城"],["c:1/19/Takeda_Katsuyori.jpg",1000,1300],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/66/Sanada_Masayuki2.jpg",658,621],["c:0/0b/Sanada-Masayuki.jpg",1400,1750,"真田昌幸"],["c:3/37/Shichiri_rock_plateau_Nirasaki_Aerial_photograph.jpg",2355,3139,"七里岩"]]},{"id":"19_tenmokuzan","n":"天目山・田野（武田氏滅亡の地）","yomi":"てんもくざん・たの","cat":"古戦場","rank":"S","y":1582,"era":["azuchi"],"sh":"","ad":"甲州市大和町田野","st":"JR中央本線 甲斐大和駅からバスで約10分、または歩いて約40分","la":35.656,"lo":138.796,"hook":"新羅三郎義光から約500年続いた甲斐武田氏。その最後の日は、山あいの小さな村でむかえられた。","lead":"1582年3月、織田・徳川の大軍に追われた武田勝頼は、天目山をめざす途中の田野の地で、妻や子とともに自害しました。この戦いは «甲州征伐» とよばれ、名門・武田氏はわずか1か月あまりで滅びました。今は景徳院が建ち、一族をとむらっています。","story":["1582年2月、信濃の木曽義昌が武田を裏切って織田方につきました。これを合図に、織田信長の長男・信忠が伊那から、徳川家康が駿河から、北条氏も東から攻め込みます。«なぜこんなに早く崩れたのか?» 長篠の敗戦以来、武田の家臣たちの心はすでに離れはじめていました。城は次々に戦わずに開き、一族の穴山梅雪までが徳川に通じます。","3月3日、勝頼は完成まもない新府城に火をかけ、家臣・小山田信茂のすすめで、東の郡内にある岩殿城をめざしました。ところが笹子峠の手前で、信茂は態度を変え、勝頼一行を受け入れなかったと伝わります。行き場を失った一行は、はるか昔に武田の先祖が逃げこんだともいわれる天目山をめざして、日川の谷へ入りました。","このとき勝頼に従う者は、もう数十人ほどだったといいます。3月11日、滝川一益の軍勢が田野に追いつきます。家臣の土屋昌恒は細い道で敵を防ぎ、«片手千人斬り» の名で語りつがれる奮戦をしたと伝わります。その間に、勝頼、嫡男の信勝、そして北条氏から嫁いだ19歳の夫人が、次々に命を絶ちました。","勝頼の首は信長のもとへ送られ、確かめられたといわれます。信長はこの年の6月、京都の本能寺で家臣の明智光秀に討たれました。武田の滅亡から3か月もたっていませんでした。","戦いのあと、村人たちは一族の遺体をひそかに葬ったと伝わります。のちに甲斐を治めた徳川家康は、この地に景徳院を建てて供養しました。田野の周辺には «四郎作»«鳥居畑» など、最後の戦いにちなむ地名や言い伝えが残っています。"],"tl":[["1582年2月","木曽義昌が織田方に寝返る。織田・徳川の侵攻が始まる"],["1582年3月2日","仁科盛信の守る高遠城が落城"],["1582年3月3日","勝頼が新府城に火を放って東へ"],["1582年3月","小山田信茂が勝頼を拒む"],["1582年3月11日","田野で勝頼・信勝・北条夫人らが自害"],["1582年6月","本能寺の変で信長が討たれる"],["1588年","徳川家康が景徳院を建てる"]],"who":[["武田勝頼","武田家最後の当主。田野で自害"],["武田信勝","勝頼の嫡男。父とともに亡くなった"],["北条夫人","北条氏政の妹。勝頼に嫁ぎ、ともに命を絶った"],["小山田信茂","郡内の領主。最後に勝頼を受け入れなかった"],["土屋昌恒","勝頼の側近。最後まで戦ったと伝わる"],["滝川一益","織田方の武将。田野で勝頼を追いつめた"]],"deep":["天目山には室町時代に開かれた «棲雲寺» があります。1417年、上杉禅秀の乱に加わった武田信満がこの山で自害したとされ、武田氏にとって «二度目の天目山» だった、と語られます。","勝頼が実際に亡くなったのは天目山の山中ではなく、手前の田野です。«天目山で滅んだ» という言い方は、地域の総称として広まったものです。","«天王山» と並んで «天目山» は «勝負の分かれ目» という意味で使われることがありますが、ここでは «最後の場面» の意味で使われることが多い言葉です。","小山田信茂は、武田滅亡後に織田方に出向きましたが、主君を裏切った者として処刑されたと伝わります。","織田方の記録『信長公記』には、勝頼の最期の様子や、甲州征伐の進み方がくわしく記されています。","勝頼の年齢は37歳、信勝は16歳ほどでした。"],"look":["景徳院の «生害石»（一族が最期をむかえたと伝わる石）","勝頼・信勝・北条夫人の墓","日川沿いの谷の地形（逃避行の道）","少し奥の天目山棲雲寺"],"q":["勝頼が最後に頼った家臣・小山田信茂の本拠の城は？","岩殿城（岩殿山城）。しかし信茂は勝頼を受け入れませんでした。"],"koji":[{"w":"天目山","m":"最後の決戦、運命の分かれ目のたとえとして使われる"}],"myth":"土屋昌恒の «片手千人斬り»、小山田信茂の裏切りの細かい経緯、北条夫人の年齢などは伝承や諸説を含む。","img":["武田勝頼","景徳院","小山田信茂","土屋昌恒"],"wp":"甲州征伐","rel":{"ev":[],"grave":[]},"ph":[["c:3/30/Katsuyori_died_at_Mt.Tenmoku_02.jpg",1600,800,"甲州征伐"],["c:f/f3/Katategiri_monument.JPG",4000,3000],["c:8/88/Katsuyori_died_at_Mt.Tenmoku_01.jpg",1600,783],["c:1/19/Takeda_Katsuyori.jpg",1000,1300,"武田勝頼"],["c:e/e5/Keitokuin_Sanmon_2006.JPG",1024,768,"景徳院"]]},{"id":"19_saruhashi","n":"猿橋（日本三奇橋のひとつ）","yomi":"さるはし","cat":"街道","rank":"S","y":1676,"era":["asuka","muromachi","edo"],"sh":"国指定名勝","ad":"大月市猿橋町猿橋","st":"JR中央本線 猿橋駅から歩いて約15分","la":35.6133,"lo":138.9983,"hook":"橋脚が一本もない。両岸から木を少しずつせり出して、深い谷にかけた不思議な橋。","lead":"甲州街道が桂川の深い谷をわたる場所にかかる木の橋です。橋脚を立てず、両岸の岩に «はね木» を何段も重ねてせり出させる «刎橋（はねばし）» というつくりで、«日本三奇橋» のひとつに数えられます。","story":["桂川は、このあたりで両岸がせまり、水面まで30mほどの深い谷になっています。谷が深すぎて、川の中に橋脚を立てることができません。«ではどうやって橋をかけたのか?»","言い伝えでは、飛鳥時代、百済から来た «志羅呼（しらこ）» という人がここで困っていたところ、たくさんの猿がつながり合って谷をわたる様子を見て、橋のかけ方を思いついたといいます。«猿橋» の名はそこから、と語られます。もちろん伝説ですが、猿の «手渡し» と刎木のせり出しは、どこか似ています。","江戸時代、甲州街道は江戸と甲府を結ぶ大事な道でした。大名行列や甲府勤番の侍、身延や富士へ向かう参詣者も、みなこの橋をわたりました。宿場町の猿橋宿は、橋を見物する旅人でにぎわったといいます。","浮世絵師の歌川広重も甲州を旅し、この橋を描きました。谷底から見上げたような大胆な構図は、橋の高さとふしぎな形をいきいきと伝えています。儒学者の荻生徂徠も紀行文で猿橋にふれ、その景色をたたえました。","木の橋は腐りやすいため、昔から何度もかけ替えられてきました。今の橋は1984年にかけ替えられたもので、はね木の中に鉄骨を入れて丈夫にしながら、見た目は江戸時代の姿を再現しています。橋の上に立ち、足元の谷をのぞくと、昔の旅人がどんな気持ちでわたったのか想像できます。"],"tl":[["飛鳥時代","百済の志羅呼が橋をかけたと伝わる"],["室町時代","旅の記録に猿橋が登場するようになる"],["江戸時代","甲州街道の名所としてにぎわい、たびたびかけ替えられる"],["1840年代","歌川広重が猿橋を描く"],["1932年","国の名勝に指定"],["1984年","現在の橋にかけ替え"]],"who":[["志羅呼","百済の人。猿を見て橋をかけたと伝わる（伝説）"],["歌川広重","浮世絵師。甲州を旅して猿橋を描いた"],["荻生徂徠","江戸時代の儒学者。紀行文で猿橋にふれた"]],"deep":["«刎橋» は、岸の岩にはね木を斜めに差しこみ、その上に少し長いはね木を重ねて、両岸から少しずつせり出させる工法です。猿橋は、この形が今も見られる、全国でも数少ない橋です。","橋の長さは約31m、幅は約3.3m、水面からの高さは約31mといわれます。","はね木の上には小さな屋根がかけられています。雨から木を守り、腐りにくくするための工夫です。","«日本三奇橋» は、ふつう山口の錦帯橋、猿橋、そしてもう一つを富山の愛本橋（今は形が変わっている）とすることが多いですが、ほかの橋を挙げる説もあります。","すぐ近くには明治時代の発電所の水路橋（八ツ沢発電所の施設、国の重要文化財）があり、江戸の木の橋と近代の石・コンクリートの橋が並ぶ景色が見られます。","猿橋の下の谷は «猿橋の奇景» として公園になっていて、谷へ下りて橋を下から見上げることができます。"],"look":["谷底から見上げる刎木の重なり","橋の上から見下ろす桂川の深い谷","はね木にかけられた小さな屋根","近くの水路橋（八ツ沢発電所施設）"],"q":["猿橋のように橋脚を使わず、はね木をせり出させてつくる橋を何という？","«刎橋（はねばし）»。深い谷で川に柱を立てられないときの工夫です。"],"koji":[],"myth":"志羅呼と猿の話は伝説。日本三奇橋の三つ目には諸説ある。","img":["甲州街道","歌川広重","日本三奇橋"],"wp":"猿橋","rel":{"ev":[],"grave":[]},"ph":[["c:1/15/Saru_hashi-1a.jpg",4233,2781,"猿橋"],["c:1/1c/Saru_hashi-2.jpg",2848,4288],["c:4/40/Yatsuzawa-aqueduct_bridge-1.jpg",3648,2736],["c:f/f1/Saru_hashi-3.jpg",2136,3216],["c:a/af/Saruhashi_-02.jpg",2592,1944],["c:0/01/SaruHashi2005-8b.jpg",1600,1200],["c:4/4d/Hiroshige_Kai_Saruhashi.jpg",1036,1536],["c:a/a3/100_views_edo_086.jpg",793,1200,"甲州街道"]]},{"id":"19_kitaguchi_sengen","n":"北口本宮冨士浅間神社（富士講の登山口）","yomi":"きたぐちほんぐうふじせんげんじんじゃ","cat":"寺社","rank":"S","y":1615,"era":["muromachi","edo"],"sh":"国の重要文化財（本殿など）・世界遺産構成資産","ad":"富士吉田市上吉田","st":"富士急行線 富士山駅からバスで約5分、または歩いて約20分","la":35.474,"lo":138.7976,"hook":"江戸の庶民は、この大鳥居をくぐって一歩目をふみ出した。頂上まで、ここから歩いて登る。","lead":"富士山の北側、吉田口登山道のスタート地点にある神社です。うっそうとした杉並木の参道の先に、木でできた巨大な鳥居と朱塗りの社殿が並びます。江戸時代には、富士山を信仰する «富士講» の人々が全国から集まりました。","story":["社伝では、古く日本武尊が東へ向かう途中、この地から富士山を遥拝したのが始まりとされます。本当の始まりはわかりませんが、少なくとも戦国時代には、富士山に登る人々の拠点としてにぎわっていました。","戦国時代、甲斐の武田信玄もこの神社を大事にしました。本殿の東にある «東宮本殿» は、信玄が造営したと伝わる建物です。武田氏が滅んだあと、甲斐を治めた浅野氏が «西宮本殿» を、江戸時代のはじめには、この地の領主・鳥居成次が今の本殿を建てました。戦国から江戸へ、時代の支配者たちが次々に手を入れたのです。","江戸時代の中ごろ、江戸で «富士講» が大流行しました。«富士山に登ると生まれ変われる»。講の仲間はお金を出しあい、代表を富士へ送りました。1733年、講の指導者・食行身禄が富士山で断食して亡くなると、その教えはさらに広がります。«江戸八百八町に八百八講» といわれるほどでした。","同じころ、江戸の商人で富士講の指導者・村上光清が私財を投じて、この神社を大修理しました。«光清は宮を建て、身禄は講を広めた» と並べて語られます。講の人々は神社の近くの «御師（おし）» の家に泊まり、身を清めてから、白い装束で山へ向かいました。","今も毎年8月下旬、富士山の山じまいに行われる «吉田の火祭り» では、町じゅうに大きなたいまつがともされます。2013年、富士山は世界文化遺産になり、この神社も «信仰の対象と芸術の源泉» の一部として登録されました。"],"tl":[["古代","日本武尊の遥拝の地という社伝が伝わる"],["1561年","武田信玄が東宮本殿を造営したと伝わる"],["1594年","浅野氏が西宮本殿を建てたとされる"],["1615年","鳥居成次が現在の本殿を建てる"],["1733年","食行身禄が富士山で入定。同じころ村上光清が大修理"],["2013年","富士山が世界文化遺産に。構成資産の一つとなる"]],"who":[["武田信玄","東宮本殿を造営したと伝わる"],["鳥居成次","江戸初期の領主。今の本殿を建てた"],["村上光清","江戸の富士講指導者。社殿を大修理した"],["食行身禄","富士講の指導者。富士山で断食して亡くなった"],["長谷川角行","富士講の祖とあおがれる修行者"]],"deep":["木造の大鳥居は高さ約18mあり、木造の鳥居としては国内最大級です。おおむね60年ごとに建てかえられてきました。","«富士山» の扁額が鳥居にかかっていて、神社そのものではなく «山» を拝む場所だということがよくわかります。","境内の «富士山登山道吉田口» の碑の先から登山道が始まります。今は五合目までバスで行く人が多いですが、ここから歩く «麓から登る» 人も増えています。","本殿・東宮本殿・西宮本殿など多くの建物が国の重要文化財に指定されています。建てた時代がちがうため、装飾の細かさや色の使い方をくらべるとおもしろいです。","御神木の «太郎杉»«夫婦檜» は樹齢千年とも伝わる大木です。","«吉田の火祭り» は、この神社と境内社の諏訪神社の祭りで、日本三奇祭のひとつに数えられることがあります。"],"look":["杉並木の参道と巨大な木造の大鳥居","本殿・東宮本殿・西宮本殿の彫刻と彩色","登山道吉田口の起点","御神木の太郎杉","近くの御師住宅（旧外川家住宅など）"],"q":["富士講の人々が富士山に登る前に泊まった、神社の近くの宿を何という？","«御師（おし）» の家。祈祷や宿の世話をした人たちの家です。"],"koji":[],"myth":"創建の由来は社伝。東宮本殿を信玄が建てたことや、各建物の建立年は伝承・諸説を含む。","img":["富士講","食行身禄","吉田の火祭り","富士山"],"wp":"北口本宮冨士浅間神社","rel":{"ev":[],"grave":[]},"ph":[["c:8/87/Kitaguchi_Hongu_Fuji_Sengen_jinja_Torii.jpg",4480,2980,"北口本宮冨士浅間神社"],["c:c/c7/Kitaguchi_Hongu_Fuji_Sengen_jinja_20190826d8.jpg",4496,3000],["c:d/d9/Kitaguchi_Hongu_Fuji_Sengen_jinja_20190826d7.jpg",4496,3000],["c:7/7a/Kitaguchi_Hongu_Fuji_Sengen_jinja_20190826d4.jpg",4496,3000],["c:3/3c/Kitaguchi_Hongu_Fuji_Sengen_jinja_20190826c2.jpg",3000,4496],["c:6/6d/Kitaguchi_Hongu_Fuji_Sengen_jinja_20190826a4.jpg",4496,3000],["c:5/5e/Kitaguchi_Hongu_Fuji_Sengen_jinja_20190826a2.jpg",4496,3000],["c:3/38/Kitaguchi_Hongu_Fuji_Sengen_jinja_20190826d5.jpg",4481,2980]]},{"id":"19_katsunuma_sen","n":"柏尾古戦場（甲州勝沼の戦い・近藤勇の甲陽鎮撫隊）","yomi":"かしおこせんじょう","cat":"幕末","rank":"S","y":1868,"era":["edo","meiji"],"sh":"","ad":"甲州市勝沼町柏尾","st":"JR中央本線 勝沼ぶどう郷駅から車で約5分（歩くと約40分）","la":35.6646,"lo":138.7415,"hook":"新選組の近藤勇は «大名» として甲府城をめざした。だが、たった数時間の戦いで夢はくずれた。","lead":"1868年、江戸へ攻め上る新政府軍を甲府で食い止めようと、近藤勇らの «甲陽鎮撫隊» が板垣退助らの新政府軍と戦った場所です。戦いはわずかな時間で終わり、鎮撫隊は敗れて江戸へ退きました。深沢川の近くに近藤勇の像が建っています。","story":["1868年のはじめ、鳥羽・伏見の戦いで旧幕府軍は敗れ、新選組も江戸へ引き上げました。新政府軍は東海道・中山道・甲州街道から江戸をめざします。«甲府城を先におさえれば、新政府軍を山の向こうで止められる»。そう考えた旧幕府側は、近藤勇に甲府へ向かう役目を与えました。","近藤は «大久保剛（のち大和）» と名を変え、新選組の仲間や新たに集めた兵とともに «甲陽鎮撫隊» として出発します。途中、故郷の多摩では大歓迎を受け、行軍は思うように進まなかったと伝わります。そのあいだに、新政府軍の東山道の部隊が先に甲府城に入ってしまいました。","この部隊を率いていたのが土佐の乾退助です。甲斐に入るにあたり、武田家ゆかりの «板垣» の姓を名のったといわれ、以後は板垣退助として知られるようになります。«武田の家臣の子孫が甲斐へ帰ってきた» と印象づけ、地元の人々の心をつかむねらいがあったとされます。","1868年3月6日、鎮撫隊は勝沼の柏尾に陣をかまえ、大善寺の近くで新政府軍をむかえ撃ちました。しかし兵の数も武器も新政府軍が上でした。戦いは数時間で決着し、鎮撫隊は散りぢりになって退きます。土方歳三は援軍を求めて江戸へ走りましたが、間に合いませんでした。","このあと近藤は下総の流山で新政府軍に捕らえられ、4月に板橋で処刑されます。勝沼の戦いは、近藤が新選組の隊長として戦った最後の戦いのひとつになりました。いま古戦場には近藤の像が建ち、ぶどう畑の間の静かな川辺で、亡くなった人々をしのぶことができます。"],"tl":[["1868年1月","鳥羽・伏見の戦い。旧幕府軍が敗れる"],["1868年3月","甲陽鎮撫隊が江戸を出発。新政府軍が先に甲府城に入る"],["1868年3月6日","柏尾で甲州勝沼の戦い。鎮撫隊が敗れる"],["1868年4月","近藤勇が流山で投降し、板橋で処刑される"],["1868年4月","江戸城が新政府軍に明け渡される"]],"who":[["近藤勇","新選組局長。甲陽鎮撫隊を率いて敗れた"],["土方歳三","新選組副長。援軍を求めて江戸へ向かった"],["板垣退助","土佐藩士。新政府軍を率い、甲斐で «板垣» の姓を名のったとされる"],["谷干城","土佐藩士。新政府軍としてこの戦いに加わった"]],"deep":["戦いの日付は旧暦の3月6日で、新暦では3月末ごろにあたります。","鎮撫隊の兵力は200〜300人ほど、新政府軍はそれを上回ったといわれますが、数字は史料によってちがいます。","鎮撫隊には大砲もありましたが、うまく使えなかったという話が伝わります。兵の多くは急に集められた人たちで、訓練が足りなかったとされます。","板垣の姓は、武田信玄の重臣・板垣信方にちなむものといわれます。乾家はその子孫を名のっていました。","戦場となった柏尾は、国宝の薬師堂がある大善寺のすぐそばです。寺は兵火をまぬがれ、今も鎌倉時代の建物が残っています。","近藤が故郷の多摩で宴会を重ねて出陣が遅れた、という話は有名ですが、後の聞き書きによる部分も多いとされます。"],"look":["深沢川近くの近藤勇の像と古戦場の碑","柏尾の地形（街道が山にはさまれる場所）","すぐそばの大善寺","勝沼のぶどう畑と甲州街道の町並み"],"q":["甲州勝沼の戦いで新政府軍を率いた人物は、甲斐に入るときに何という姓を名のった？","«板垣»。武田の重臣・板垣信方にちなむとされ、以後、板垣退助と名のりました。"],"koji":[],"myth":"兵力、行軍が遅れた理由、戦いの細部には諸説がある。","img":["近藤勇","甲陽鎮撫隊","板垣退助","新選組"],"wp":"甲州勝沼の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:b/b1/KoshuKatsunuma.jpg",1600,766,"甲州勝沼の戦い"],["c:3/37/Itagaki_Taisuke_1870.jpg",1696,2268],["c:5/56/Kondo_Isami.jpg",900,1348],["c:b/b2/Kondo_Isami02.jpg",658,954,"近藤勇"],["c:2/26/ITAGAKI_Taisuke.jpg",1024,1335,"板垣退助"]]},{"id":"19_kurokawa_kinzan","n":"黒川金山（武田の軍資金を支えた金山）","yomi":"くろかわきんざん","cat":"産業","rank":"S","y":1560,"era":["muromachi","azuchi"],"sh":"国指定史跡（甲斐金山遺跡）","ad":"甲州市塩山上萩原（鶏冠山）","st":"JR塩山駅から車で約40分のあと山道を歩く。公共交通では行けず、一般向けの見学路もない","la":35.795,"lo":138.86,"hook":"«武田の強さは金にあり»。山奥の谷に、千軒の家が並んだといわれる鉱山の町があった。","lead":"甲州市の北東、鶏冠山のふもとにある戦国時代の金山の跡です。武田氏の時代に金が盛んに掘られ、軍資金を支えたと考えられています。国の史跡ですが、深い山の中にあり、ふだん気軽に見学できる場所ではありません。","story":["戦国大名が戦を続けるには、たくさんのお金が必要でした。武器を買い、兵を養い、城を築く。«武田信玄はどうして強かったのか?» その理由のひとつとして、甲斐の山々でとれた «金» がよく挙げられます。黒川金山は、その代表といわれる金山です。","金山がいつ開かれたのかははっきりしませんが、発掘では戦国時代の遺物がたくさん見つかっています。谷の斜面には «平場» とよばれる平らな土地が段々に作られ、そこに金掘りの人々の家や作業場が並んでいました。«黒川千軒» と呼ばれるほどのにぎわいだったと伝わります。","金を取り出すには、まず金をふくむ石を掘り出し、臼で細かくくだき、水で洗って重い金だけを集めます。遺跡からは石臼やるつぼ、金をふくむ土のかたまりが見つかり、山の中で金の «精錬» まで行っていたことがわかりました。","武田氏のもとでは、甲州金とよばれる金貨も作られたといわれます。金の単位を «両・分・朱» と四つずつ区切る数え方は、のちに江戸幕府のお金の単位にも受けつがれました。甲斐の金山は、日本のお金の歴史にも名前を残しているのです。","金山の近くには «おいらん淵» と呼ばれる場所があり、武田氏が滅んだとき、金山の秘密を守るため女性たちが淵に沈められたという悲しい伝説があります。しかし、これを裏づける史料は見つかっておらず、あくまで言い伝えとして語られています。"],"tl":[["戦国時代","金山が盛んに稼働する（開始時期ははっきりしない）"],["16世紀後半","武田氏の支配のもとで金が掘られたと考えられる"],["江戸時代","しだいに産出が減り、衰える"],["1980年代","研究グループによる本格的な発掘調査"],["1997年","中山金山とともに «甲斐金山遺跡» として国の史跡に"]],"who":[["武田信玄","金山の金を軍資金にしたといわれる戦国大名"],["金山衆","金掘りの技術者集団。戦のときは城攻めで坑道を掘ったとも"]],"deep":["«金山衆» は金を掘るだけでなく、戦国の城攻めで地下にトンネルを掘る役目も務めたといわれます。武田軍の «もぐら攻め» の話として伝わります。","遺跡では、住まいの跡、墓地、寺の跡とみられる場所まで見つかっていて、単なる作業場ではなく «山の中の町» だったことがわかります。","発掘されたのは遺跡のごく一部で、多くはまだ山の中に眠っています。遺跡を守るため、立ち入りが制限されている場所もあります。","甲州金の «両・分・朱» は、1両＝4分、1分＝4朱という四進法です。この数え方が江戸幕府の貨幣制度に取り入れられました。","山梨県内には、身延町の湯之奥金山など、ほかにも戦国時代の金山跡があります。身延町には金山の暮らしを紹介する博物館もあります。","«おいらん淵» の伝説は、一之瀬高橋の柳沢川の淵にまつわるものです。史実とは確かめられていません。"],"look":["金山の資料や甲州金を紹介する博物館の展示","青梅街道沿いの «おいらん淵» 周辺の渓谷（伝説の地）","遠くから見上げる鶏冠山の山容"],"q":["甲州金で使われた «両・分・朱» は何進法？","四進法。1両は4分、1分は4朱で、のちに江戸幕府の貨幣にも受けつがれました。"],"koji":[],"myth":"金山の開始時期、武田氏との関係の程度、«おいらん淵» の話は伝承・諸説を含む。","img":["甲州金","武田信玄","甲斐国"],"wp":"黒川金山","rel":{"ev":[],"grave":[]},"ph":[["c:4/48/The_main_gate_of_a_Buddhist_temple_of_the_Hokoji-_temple.JPG",4000,3000],["c:9/93/Ichinose_Takahashi_no_Harukoma_Indoors_A.JPG",4000,3000],["c:f/fe/%E5%8B%9D%E6%B2%BC%E6%B0%8F%E9%A4%A8.jpg",1280,960],["c:1/1a/Koshu1bu-zyu.jpg",160,160,"甲州金"],["c:3/33/Takeda_Harunobu.jpg",1400,1707,"武田信玄"]]},{"id":"19_shingen_zutsumi","n":"信玄堤（信玄の治水）","yomi":"しんげんづつみ","cat":"産業","rank":"S","y":1560,"era":["muromachi","edo"],"sh":"","ad":"甲斐市竜王","st":"JR中央本線 竜王駅から歩いて約20分（信玄堤公園）","la":35.672,"lo":138.508,"hook":"戦の名人・信玄は、川とも戦った。相手は、甲府盆地を毎年のように襲う暴れ川だった。","lead":"甲府盆地の西で、釜無川と御勅使川（みだいがわ）が合流するあたりに築かれた堤防です。武田信玄の時代に整えられたと伝わり、川の流れを変え、水の勢いをそぐさまざまな工夫が組み合わされています。今も堤防の一部が残り、公園として歩けます。","story":["甲府盆地は、まわりを高い山にかこまれた «すりばち» のような土地です。大雨が降ると、山から一気に水が流れこみます。とくに西の御勅使川は、南アルプスから石や砂を運ぶ暴れ川で、釜無川とぶつかる竜王のあたりで、たびたび大水をおこしていました。","«どうすれば水をおさえられるのか?» 信玄の時代に考えられたのは、力ずくで水をせき止めるのではなく、水の勢いを少しずつ弱めていく方法でした。まず御勅使川の流れを石の堤で分け、向きを変えます。さらに «高岩» とよばれる崖に水をぶつけて勢いを殺し、そのうえで長い堤防で町と田畑を守ったのです。","堤防は一度に完成したものではなく、長い年月をかけて築かれたと考えられています。1560年には、信玄が堤のそばに人々を住まわせ、税を免除するかわりに堤を守らせる文書を出したことが知られています。できた村は «竜王河原宿» とよばれました。","毎年春には «おみゆきさん（御幸祭り）» という祭りが行われます。神輿をかついだ人々が堤防の上を練り歩き、足で土をふみ固めるのだといわれます。祭りそのものは信玄よりずっと古い起源をもつと伝わりますが、«みんなで堤を守る» 仕組みとして大事にされてきました。","信玄の治水の工夫は江戸時代にも受けつがれ、全国の治水のお手本とされることもありました。いまも公園の中に «聖牛» という木組みの水制が復元され、戦国時代の人々の知恵を目で見ることができます。"],"tl":[["16世紀中ごろ","信玄のもとで堤防づくりが進んだと伝わる（開始時期は諸説）"],["1560年","信玄が堤のそばに住む人々に税の免除を認める文書を出す"],["江戸時代","堤の修理が続けられ、«信玄堤» の名が広まる"],["現在","信玄堤公園として整備され、毎年おみゆきさんが行われる"]],"who":[["武田信玄","治水を進めた戦国大名"],["竜王河原宿の人々","堤のそばに住み、堤を守った住民"]],"deep":["«将棋頭» は、御勅使川の流れを二つに分けるための石積みの堤で、将棋の駒のような形からこう呼ばれます。南アルプス市などに跡が残ります。","«高岩» は釜無川ぞいの赤い崖で、川の水をここにぶつけて勢いを弱めたと考えられています。自然の地形をそのまま堤防の一部として使った例です。","«霞堤» は、堤防をわざと切れ目のある形にし、洪水のとき水を一時的に田畑へ逃がし、水が引くと川へ戻す仕組みです。«全部せき止めない» のが特徴です。","«聖牛» は丸太を三角に組んだ水制で、川の流れを弱めて堤防を守ります。今の河川工事でも似た考え方が使われています。","治水がいつ始まり、いつ完成したかは、史料が少なくはっきりしません。«約20年かけて完成» といった言い方は、後の時代の伝えによるものです。","1560年の文書は、堤を守る人々への見返りを約束したもので、«人に住んでもらって堤を守る» という発想が読み取れます。"],"look":["信玄堤公園に残る堤防","復元された聖牛","釜無川ぞいの高岩","三社神社とおみゆきさんの祭り"],"q":["堤防にわざと切れ目をつくり、洪水の水を一時的に逃がす仕組みを何という？","«霞堤»。水を全部せき止めず、あふれた水を川へ戻す工夫です。"],"koji":[],"myth":"堤の着工・完成年や、どこまで信玄自身が関わったかは諸説。おみゆきさんの起源も伝承。","img":["釜無川","御勅使川","霞堤","武田信玄"],"wp":"信玄堤","rel":{"ev":[],"grave":[]},"ph":[["c:3/38/Outside_of_Shingen_embankment.JPG",4000,3000,"信玄堤"],["c:9/92/Shingen_embankment_and_Kamanashi_River.JPG",4000,3000],["c:0/0c/Seigyu.JPG",4608,3072],["c:8/85/Sansya_Suwa_Shrine_Kofu_City.jpg",4608,3072],["c:d/d2/Sansya_Jinjya_Torii.JPG",4608,3072],["c:2/2c/Ryuo_Kawara_Syuku.JPG",4608,3456],["c:7/78/Kuzuryushin_Hokora.JPG",4608,3072],["c:2/24/Inside_forest_of_Shingen_embankment.JPG",4000,3000]]},{"id":"19_choshizuka","n":"甲斐銚子塚古墳（東日本屈指の前方後円墳）","yomi":"かいちょうしづかこふん","cat":"遺跡","rank":"S","y":370,"era":["kofun"],"sh":"国指定史跡","ad":"甲府市下曽根町","st":"JR甲府駅からバスで約30分「考古博物館」下車","la":35.6035,"lo":138.588,"hook":"ヤマト王権と甲斐をつなぐ «証拠»。全長約170mの巨大な墓は、4世紀の甲府盆地に何があったかを語る。","lead":"甲府盆地の南、曽根丘陵にある4世紀後半ごろの前方後円墳です。全長は約169mあり、山梨県で一番大きく、この時期の古墳としては東日本でも有数の大きさです。まわりは «風土記の丘・曽根丘陵公園» として整備され、墳丘に登ることもできます。","story":["甲府盆地を見下ろす曽根丘陵。今から約1650年前、この丘に、見上げるほど大きな墓が築かれました。«なぜこんなに大きな墓を?» 古墳は、ただの墓ではありません。葬られた人の力と、その人がヤマト王権とどれほど強く結びついていたかを示す «記念碑» でもありました。","前方後円墳という形は、近畿地方の王たちの墓と同じ形です。しかも甲斐銚子塚古墳は、この時代の東日本で指折りの大きさ。甲斐の王が、遠く近畿の大王とつながりをもち、その力を背景に盆地を治めていたことがうかがえます。","昭和のはじめ、古墳から鏡や腕輪形の石製品などが見つかりました。鏡の中には、近畿地方の古墳とよく似たものもふくまれ、王権から配られたものではないか、と考えられています。副葬品の多くは今、国立の博物館などで大切に保管されています。","すぐ隣には、少し古いと考えられる «丸山塚古墳» という円墳があります。二つの古墳が並ぶ姿は、この地に代々の有力者がいたことを物語ります。丘陵の上からは甲府盆地が一望でき、葬られた王が自分の治めた土地を見守っているかのようです。当時の人々は、盆地のどこからでも見える丘の上に墓を築くことで、王の力を毎日目にするようにしたのかもしれません。","近くには山梨県立考古博物館があり、県内の遺跡から出た土器や土偶とともに、古墳の時代の甲斐のようすを学ぶことができます。墳丘は発掘の成果をもとに一部が整えられ、段の形や周りの堀の位置がわかるようになっています。"],"tl":[["4世紀後半","甲斐銚子塚古墳が築かれる"],["昭和のはじめ","鏡や石製品などが見つかる"],["1930年","国の史跡に指定"],["1982年","近くに山梨県立考古博物館が開館"],["現在","曽根丘陵公園として墳丘が整備される"]],"who":[["甲斐の首長","古墳に葬られた人物。名前は伝わらない"],["ヤマト王権の大王","近畿の王。甲斐の首長と結びつき、鏡などを配ったと考えられる"]],"deep":["全長は約169m、後円部の直径は約92mとされます。4世紀の古墳としては東日本で最大級の一つです。","墳丘は三段に築かれ、表面は石でおおわれた «葺石»、まわりには円筒埴輪が並んでいたと考えられています。","出土品には、三角縁神獣鏡をふくむ鏡、碧玉でつくった腕輪形の石製品（車輪石・石釧など）があり、近畿の古墳とよく似た組み合わせです。","甲斐銚子塚古墳の後、甲府盆地では大型の前方後円墳が続かず、有力者の中心が別の地域へ移ったと考えられています。","曽根丘陵には縄文から古墳時代までの遺跡が数多くあり、丘全体が «遺跡の宝庫» となっています。","«銚子塚» の名は、形が酒を注ぐ «銚子» に似ていることから、といわれます。同じ名前の古墳が各地にあるため «甲斐» をつけて区別しています。"],"look":["墳丘の上から見る甲府盆地（晴れた日は富士山や南アルプスも）","葺石と埴輪列が再現された墳丘","隣の丸山塚古墳","山梨県立考古博物館の展示"],"q":["甲斐銚子塚古墳の形は何とよばれる？","«前方後円墳»。四角と円を組み合わせた、ヤマト王権とつながる王たちの墓の形です。"],"koji":[],"myth":"葬られた人物は不明。出土品の発見の経緯や細かい数には資料によって差がある。","img":["前方後円墳","山梨県立考古博物館","三角縁神獣鏡"],"wp":"甲斐銚子塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:4/49/Kai_Choshizuka_Kofun_zenkei.JPG",6016,4000,"甲斐銚子塚古墳"],["c:6/6a/Sakaorimiya_zenkei.jpg",4000,3000],["c:d/dd/Omaruyama-kofun_enkei.JPG",6016,4000],["c:e/ed/Maruyamazuka_Kofun_%28Kofu%29_zenkei.JPG",6012,3994],["c:5/5d/Maruyamazuka_Kofun_%28Kofu%29_funcho.JPG",6016,4000],["c:2/2a/Kai_Choshizuka_Kofun_tosshutsu-bu.JPG",6016,4000],["c:9/97/Kai_Choshizuka_Kofun_ricchu.JPG",6016,4000],["c:8/8d/Kai_Choshizuka_Kofun_funcho.JPG",6016,4000]]},{"id":"19_shakado","n":"釈迦堂遺跡（1000点超の縄文土偶）","yomi":"しゃかどういせき","cat":"遺跡","rank":"S","y":-3000,"era":["jomon"],"sh":"国の重要文化財（出土品）","ad":"笛吹市一宮町千米寺","st":"中央自動車道 釈迦堂PAから歩いてすぐ。JR石和温泉駅・勝沼ぶどう郷駅からは車で約15分","la":35.661,"lo":138.702,"hook":"高速道路の工事で掘り出されたのは、1000点をこえる «こわれた土偶» だった。","lead":"笛吹市と甲州市の境にある縄文時代中ごろの大きな集落の跡です。中央自動車道の建設にともなう発掘で、1000点をこえる土偶や、豪華な飾りのついた土器が見つかりました。出土品の多くは国の重要文化財で、遺跡のそばの «釈迦堂遺跡博物館» で見られます。","story":["1980年ごろ、中央自動車道の工事を前に、京戸川がつくった扇状地で発掘調査が行われました。掘り進めると、たくさんの竪穴住居の跡、そして土器のかけらが次々に出てきます。«これはただの村ではない»。調査員たちは驚きました。","とくに人々を驚かせたのは土偶の多さでした。その数は1000点をこえ、一つの遺跡としては全国でも指折りです。ところが、ほとんどの土偶は手や足、頭がとれた «かけら» の状態でした。«なぜ、こわれているの?»","一つの考えは、わざとこわしたというものです。病気やけがを土偶に移し、その部分をこわして治りを願った、あるいは豊かな実りを願ってばらまいた、など、さまざまな説があります。一方で、もともとこわれやすい作りだっただけ、という意見もあり、答えはまだ出ていません。","釈迦堂の人々は、今から約5000年前、縄文時代の中ごろに最も栄えました。この時代の甲府盆地や八ヶ岳のふもとでは、うずまきや動物の顔のような飾りをつけた立体的な土器がつくられました。釈迦堂の土器にも、見る人をひきつける大胆な飾りがあります。","発掘が終わると、遺跡の多くは高速道路の下になりました。そのかわり、出土品を展示する博物館が遺跡のそばに建てられ、高速道路のパーキングエリアからも歩いて行けるようになっています。«高速道路の休けいのついでに縄文時代へ» という、ちょっと変わった体験ができる場所です。"],"tl":[["約5500〜4500年前","縄文時代中期、大きな集落が営まれる"],["1980年ごろ","中央自動車道の建設にともない発掘調査"],["1988年","釈迦堂遺跡博物館が開館"],["現在","出土品の多くが国の重要文化財に指定されている"]],"who":[["縄文の人々","この地に暮らし、土偶や土器をつくった人たち"]],"deep":["土偶は1000点をこえ、その多くがかけらです。同じ土偶のかけらが別の場所から見つかり、くっつくこともあるため、«わざと割ってばらまいた» 説の根拠の一つとされます。","土偶には、お腹が大きくふくらんだ妊婦の姿のものがあり、子どもが無事に生まれることを願ったのでは、と考えられています。","«水煙» のような大きな飾りや、人の顔をつけた土器など、中期の甲府盆地らしい立体的な土器が多く見つかっています。","遺跡は京戸川の扇状地にあり、水が得やすく日当たりのよい南向きの斜面でした。縄文人が住む場所を選ぶときの条件がよくわかります。","出土品のうち数千点がまとめて国の重要文化財に指定されています。土偶の数だけでなく、そろって残っていることが評価されています。","博物館は中央自動車道の上り線・下り線どちらの釈迦堂PAからも歩いて行ける位置にあります（道の構造は現地の案内を確認）。"],"look":["釈迦堂遺跡博物館の土偶のずらりと並ぶ展示","人の顔や動物の飾りがついた土器","妊婦をかたどったとされる土偶","遺跡のある扇状地の地形と盆地の眺め"],"q":["釈迦堂遺跡の土偶の多くは、どんな状態で見つかった？","手足や頭がとれた «かけら» の状態。わざと割ったという説などがあり、理由はまだわかっていません。"],"koji":[],"myth":"土偶が割られた理由は諸説で、確定していない。","img":["土偶","縄文時代","縄文土器"],"wp":"釈迦堂遺跡群","rel":{"ev":[],"grave":[]},"ph":[["c:0/0f/SHAKAD%C5%8C_remains_YAMANASHI_Prefecture_2024-08-10.jpg",2048,1536],["c:f/f5/SHAKAD%C5%8C_Parking_Area_YAMANASHI_Prefecture_2024-08-10.jpg",2048,1536],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["j:3/3d/%E9%9D%92%E6%A3%AE%E7%9C%8C%E3%81%A4%E3%81%8C%E3%82%8B%E5%B8%82%E6%9C%A8%E9%80%A0%E4%BA%80%E3%83%B6%E5%B2%A1%E5%87%BA%E5%9C%9F_%E9%81%AE%E5%85%89%E5%99%A8%E5%9C%9F%E5%81%B6-2.JPG",3711,4947,"土偶"],["j:6/63/%E7%AC%B9%E5%B1%B1%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E7%81%AB%E7%84%94%E5%9E%8B%E5%9C%9F%E5%99%A8_%28%E6%B7%B1%E9%89%A2%E5%BD%A2%29_%28%E5%9B%BD%E5%AE%9D%E6%8C%87%E5%AE%9A%E7%95%AA%E5%8F%B71%29.JPG",3413,3386,"縄文土器"]]},{"id":"19_sakaorinomiya","n":"酒折宮（日本武尊と連歌発祥の伝承）","yomi":"さかおりのみや","cat":"伝承","rank":"S","y":100,"era":["kofun","edo"],"sh":"","ad":"甲府市酒折","st":"JR中央本線 酒折駅から歩いて約5分","la":35.67,"lo":138.595,"hook":"«何日寝ただろう?» 英雄の問いかけに、火をたく老人が歌で答えた。それが «連歌» の始まりと伝わる。","lead":"『古事記』『日本書紀』で、日本武尊が東の国からの帰り道に立ち寄ったと語られる場所です。ここで尊と、火の番をしていた老人が歌を交わした話から、«連歌発祥の地» とされています。住宅地の中にある小さな神社ですが、古代の物語の舞台として知られます。","story":["遠い昔、天皇の命令で東の国々へ向かった日本武尊は、けわしい旅を終えて帰る途中、甲斐の国の酒折の宮に立ち寄りました。夜、火をたいていると、尊はふと口ずさみます。«新治（にいばり）、筑波を過ぎて、幾夜か寝つる»――常陸の新治や筑波を過ぎてから、いったい何晩寝ただろうか。","まわりの家来たちは、だれも答えられませんでした。すると、かがり火の番をしていた老人が歌で返します。«日々（かが）なべて、夜には九夜、日には十日を»――日数を重ねて、夜は九晩、昼は十日でございます。尊はその見事な返しに感心し、老人をほめて «東国造（あずまのくにのみやつこ）» にとりたてた、と『古事記』は伝えます。","«なぜこれが連歌の始まりなの?» 連歌は、一人が上の句をよみ、別の人が下の句をつけて、一首の歌を二人で作る遊びです。尊の問いと老人の答えが、ちょうど二人で一つの歌を完成させる形になっていることから、後の時代の人々は、ここを連歌のふるさとと考えました。","室町時代には連歌が大流行し、連歌のことを «筑波の道» と呼ぶようになります。尊の歌に出てくる «筑波» にちなむ名前です。酒折宮は、その «筑波の道» の出発点として、連歌をたしなむ人々のあこがれの地になりました。","江戸時代には国学者たちも酒折宮に注目し、古典の舞台として碑が建てられました。現代でも、この伝承にちなむ «酒折連歌賞» という全国規模の文芸賞が開かれ、問いの句に答えの句をつける形で、たくさんの作品が寄せられています。"],"tl":[["伝説の時代","日本武尊が立ち寄り、火焼の老人と歌を交わしたと伝わる"],["712年","『古事記』にこの話が記される"],["720年","『日本書紀』にも酒折宮の話が記される"],["室町時代","連歌が «筑波の道» と呼ばれ、酒折がそのふるさととされる"],["江戸時代","国学者らが注目し、碑が建てられる"],["平成","«酒折連歌賞» が始まる"]],"who":[["日本武尊","東征の帰り道に酒折宮に立ち寄ったと伝わる英雄"],["御火焼の老人","かがり火の番の老人。尊の問いに歌で答えた"],["本居宣長","江戸時代の国学者。『古事記』の研究で酒折の話も広めた"]],"deep":["『古事記』では尊の問いと老人の答えが «片歌» の問答として記されます。二つを合わせると五七七・五七七の形になり、これが連歌の源と考えられました。","『日本書紀』にも同じ話がありますが、細かい言葉や人物のあつかいに『古事記』との違いがあります。","«酒折» の名の由来には、酒を造った場所、坂が折れ曲がった地形など諸説があります。","神社がもともと今の場所にあったかどうかは不明で、古くは近くの山の中腹にあったという言い伝えもあります。","境内には国学者の文を刻んだ石碑などが残り、江戸時代の人々がこの地をどう見ていたかを伝えます。","老人が任じられた «東国造» は、東の国を治める役目という意味とされますが、実際の官職かどうかははっきりしません。"],"look":["小さな社殿と境内の石碑","連歌発祥の地を示す碑","酒折駅からの参道と周辺の地形","近くの甲斐善光寺とあわせて歩く"],"q":["連歌が «筑波の道» と呼ばれるのはなぜ？","日本武尊が酒折宮でよんだ歌に «筑波» という地名が出てくるからです。"],"koji":[{"w":"筑波の道","m":"連歌のこと。酒折宮での日本武尊の歌に由来する"}],"myth":"日本武尊の話は古典に記された伝承で、史実かどうかは確かめられない。神社の創建時期も不明。","img":["日本武尊","連歌","古事記"],"wp":"酒折宮","rel":{"ev":[],"grave":[]},"ph":[["c:a/a8/Sakaori_miya_Shrine_Torii_Nov._2016.jpg",6000,4000,"酒折宮"],["c:8/87/Sakaorimiya_sekihi.jpg",3000,4000],["c:8/87/Sakaori_miya_Shrine_Nov._2016.jpg",6000,4000],["c:6/6b/Sakaori_miya_Shrine_Chozuya.jpg",12000,8000],["c:c/c8/Sakaori-miya_sekihi_%E2%84%963.JPG",4000,3000],["c:9/9a/Sakaori-miya_sekihi_%E2%84%962.JPG",4000,3000],["c:5/5c/Sakaori-miya_RENGA_sekihi.JPG",4000,3000],["j:2/2a/%E9%85%92%E6%8A%98%E5%AE%AE_%E6%9C%AC%E6%AE%BF.JPG",3648,2736]]},{"id":"19_yoshida_tozando","n":"吉田口登山道（富士登山の古道）","yomi":"よしだぐちとざんどう","cat":"街道","rank":"S","y":1733,"era":["muromachi","edo","meiji"],"sh":"国指定史跡・特別名勝（富士山）・世界遺産構成資産","ad":"富士吉田市上吉田〜富士山","st":"富士急行線 富士山駅からバスで北口本宮冨士浅間神社へ。麓の «馬返し» までは車かバス（季節運行）","la":35.4337,"lo":138.7625,"hook":"五合目からではなく、麓から。江戸の人々が白装束で歩いた道が、森の中に今も続いている。","lead":"北口本宮冨士浅間神社から富士山頂へ向かう、昔からの登山道です。江戸時代には «富士講» の人々が、麓の御師の町・上吉田に泊まり、この道を一歩ずつ登りました。今は五合目まで車道がありますが、麓から歩く古道も残り、世界遺産の構成資産になっています。","story":["富士山は、昔から «遠くから拝む山» でした。やがて修行者たちが山に登りはじめ、室町時代には、ふつうの人々も信仰のために登るようになります。吉田口は、その北側の玄関口でした。","江戸時代、長谷川角行を祖とあおぐ «富士講» が江戸で大流行します。講の仲間は、白い行衣を着て金剛杖をつき、«六根清浄（ろっこんしょうじょう）» と唱えながら登りました。«山に登ると、心も体も清められて生まれ変わる»。そう信じられていたのです。","講の人々はまず上吉田の «御師（おし）» の家に泊まりました。御師は、祈祷をし、宿や食事を世話し、山の案内人を手配する、登山のプロデューサーのような存在です。上吉田には、道の両側に御師の家がずらりと並んでいました。","神社から登山道を上がると、«馬返し» に着きます。ここから先は馬が入れない、という意味です。その先には、小さな社や茶屋の跡、石碑が点々と残り、森の中を歩くと、昔の人が休んだ場所がわかります。女性の登山はながく禁じられていましたが、江戸時代の終わりに、高山たつという女性が頂上まで登ったと伝わります。","1964年、富士スバルラインが開通すると、多くの人が五合目から登るようになり、麓からの道は一時さびれました。しかし近年、古道を整備して «麓から登る» 富士登山がふたたび注目されています。2013年、富士山は世界文化遺産に登録され、この道もその一部となりました。"],"tl":[["室町時代","信仰のための富士登山が広まる"],["1733年","富士講の指導者・食行身禄が富士山で入定。講が大流行へ"],["1832年","高山たつが女性として頂上に登ったと伝わる"],["1872年","女性の富士登山の禁止が解かれる"],["1964年","富士スバルライン開通。五合目からの登山が主流に"],["2011年","富士山が国の史跡に指定"],["2013年","世界文化遺産に登録"]],"who":[["長谷川角行","富士講の祖とあおがれる修行者"],["食行身禄","江戸の富士講指導者。富士山で断食して亡くなった"],["高山たつ","江戸時代の女性。頂上まで登ったと伝わる"],["御師","登山者の宿や祈祷を世話した上吉田の人々"]],"deep":["富士山の «合目» は距離や標高を均等に分けたものではありません。お米を量る «合» にたとえたなど、由来には諸説があります。","上吉田の御師の家は、通りに面した入り口がせまく、奥に長くのびる敷地が特徴です。奥の屋敷まで細い道を歩くうちに、気持ちが改まったともいわれます。","富士講では60年に一度の «庚申（かのえさる）» の年を «御縁年» として特に大切にしました。1860年の縁年には、ふだんより多くの人が登ったと伝わります。","旧外川家住宅など、上吉田の御師住宅の一部は公開され、講の人々が泊まった部屋を見学できます。","馬返しから五合目までの道には、中の茶屋、一合目の鈴原社など、信仰の跡が残ります。建物の多くは失われたり、跡だけになったりしています。","富士講の人々は各地に «富士塚» という小さな富士山をつくり、登れない人も拝めるようにしました。江戸の町にはいくつも富士塚が残っています。"],"look":["北口本宮冨士浅間神社の登山道起点","馬返しの石の鳥居や石碑","中の茶屋・一合目の社などの跡","上吉田の御師住宅（旧外川家住宅など）","登山の場合は季節と天候の最新情報を必ず確認"],"q":["富士講の人々が登りながら唱えた言葉は？","«六根清浄»。目・耳・鼻・舌・身・意の六つを清めるという意味です。"],"koji":[{"w":"六根清浄","m":"人の六つの感覚と心を清めること。山に登る修行者が唱えた"}],"myth":"高山たつの登頂年や «合目» の由来には諸説がある。","img":["富士講","北口本宮冨士浅間神社","富士山","食行身禄"],"wp":"富士登山","rel":{"ev":[],"grave":[]},"ph":[["c:a/ac/Hasshinpo_of_Mt.Fuji_40-2.jpg",7683,3631],["c:8/81/Mt.Fuji_Horse.jpg",3648,2736],["c:5/59/Mt.Fuji_from_Subashiri_Trail_04.jpg",3888,2592],["c:9/9f/Hasshinpo_of_Mt.Fuji_18.jpg",3888,2592],["c:e/e8/Forest_in_Mt.Fuji_05.jpg",3888,2592],["c:1/15/120824_Kagefuji.jpg",3872,2592],["c:6/6b/Fuji663.jpg",2580,1932],["c:f/fc/Fuji662.jpg",2580,1932]]},{"id":"19_keitokuin","n":"景徳院（武田勝頼一族の墓所）","yomi":"けいとくいん","cat":"墓所","rank":"A","y":1588,"era":["azuchi","edo"],"sh":"","ad":"甲州市大和町田野","st":"JR中央本線 甲斐大和駅からバスで約10分「景徳院入口」付近下車、または歩いて約40分","la":35.6567,"lo":138.7974,"hook":"武田を滅ぼした側の家康が、滅ぼされた勝頼のために建てた寺。そこには敵味方をこえた弔いの心がある。","lead":"1582年に武田勝頼・信勝父子と北条夫人が最期をむかえた田野の地に、徳川家康が一族の菩提を弔うため建てた寺です。境内には三人が自害したと伝わる «生害石» と墓があり、勝頼をしのぶ人々が今も訪れます。","story":["1582年3月11日、田野の地で武田勝頼、嫡男の信勝、そして勝頼の妻である北条夫人が命を絶ちました。したがっていた家臣や侍女たちも、多くがここで亡くなったと伝わります。村人たちは戦いのあと、残された遺体をひそかに葬ったといいます。","その年の6月、本能寺の変で織田信長が倒れると、甲斐は徳川と北条の奪い合いになり、最後は徳川家康が手に入れました。家康は、甲斐の人々の心をつかむため、武田の旧臣を大切にあつかいます。«なぜ、滅ぼした敵の寺を建てたのか?» 武田を慕う甲斐の人々に、«徳川は武田の心を受けつぐ» と示す意味もあったと考えられています。","こうして1588年、家康の命で、勝頼一族の菩提を弔う寺が田野に建てられました。寺の名 «景徳院» は、勝頼の法名にちなむといわれます。","境内の奥の «甲将殿» には、勝頼・信勝・北条夫人の像がまつられています。その近くには、三人がそれぞれ最期をむかえたと伝わる «生害石» が並びます。北条夫人は小田原の北条家から嫁いできた人で、実家に帰ることもできたのに、勝頼とともにいることを選んだと伝わります。","勝頼は辞世として、«おぼろなる 月もほのかに 雲かすみ 晴れて行くへの 西の山の端» とよんだと伝わります。境内を歩くと、山にかこまれた静かな谷の中で、440年以上前の悲しい朝に思いをはせることができます。"],"tl":[["1582年3月11日","勝頼・信勝・北条夫人らが田野で自害"],["1582年","天正壬午の乱を経て、徳川家康が甲斐を治める"],["1588年","家康の命で景徳院が建てられる"],["江戸時代","勝頼らの墓が整えられ、法要が続けられる"],["現在","毎年の命日のころに法要が行われる"]],"who":[["武田勝頼","武田家最後の当主。この地で亡くなった"],["武田信勝","勝頼の嫡男。父とともに亡くなった"],["北条夫人","北条氏政の妹。勝頼の妻"],["徳川家康","一族の菩提を弔うためにこの寺を建てさせた"]],"deep":["«生害石» は三つあり、それぞれ勝頼・信勝・北条夫人の最期の場所と伝わります。石そのものは言い伝えによるもので、正確な場所を示すものかは確かめられません。","北条夫人は勝頼の後妻で、嫁いだのは10代のころでした。亡くなったときは19歳といわれます。","勝頼の辞世の歌のほか、北条夫人や信勝の辞世とされる歌も伝わりますが、後の時代にまとめられたもので、本人の作か確かめられないものもあります。","今の墓石は江戸時代の中ごろ、勝頼らの年忌にあわせて整えられたものといわれます。","家康は武田の旧臣を多く家臣に取り立てました。«井伊の赤備え» は、武田の旧臣を井伊直政の部隊に配したものとして知られます。","寺の周辺には、家臣たちの墓や供養塔もあり、勝頼に最後までしたがった人々の名がしのばれています。"],"look":["甲将殿（勝頼・信勝・北条夫人の像）","三つの生害石","勝頼一族と家臣の墓","山にかこまれた田野の谷の地形"],"q":["景徳院を建てさせたのはだれ？","徳川家康。武田を滅ぼした側ですが、勝頼一族の菩提を弔うため1588年に建てさせました。"],"koji":[],"myth":"生害石の位置、辞世の歌の作者、北条夫人の年齢などは伝承・諸説を含む。","img":["武田勝頼","北条氏政","甲州征伐"],"wp":"景徳院","rel":{"ev":[],"grave":[]},"ph":[["c:e/e5/Keitokuin_Sanmon_2006.JPG",1024,768,"景徳院"],["c:6/60/The_area_of_Keitokuin_temple.JPG",4000,3000],["c:6/60/Keitokuin_Temple_cherry_blossoms.JPG",4000,3000],["c:b/b9/Grave_of_Takeda_Katsuyori.JPG",4000,3000],["c:1/19/Takeda_Katsuyori.jpg",1000,1300,"武田勝頼"],["c:e/ed/Ujimasa_Hojo.jpg",900,890,"北条氏政"],["c:3/30/Katsuyori_died_at_Mt.Tenmoku_02.jpg",1600,800,"甲州征伐"]]},{"id":"19_yogaisan","n":"要害山城（武田信玄誕生の詰城）","yomi":"ようがいさんじょう","cat":"城","rank":"A","y":1520,"era":["muromachi","azuchi"],"sh":"国指定史跡（武田氏館跡の一部）","ad":"甲府市上積翠寺町","st":"JR甲府駅北口からバスで約20分「積翠寺」付近下車、登山口から山頂まで歩いて約40分","la":35.703,"lo":138.596,"hook":"ふだんは麓の館、いざという時は山の城へ。信玄の母が戦火の中で逃げこんだのは、この山だった。","lead":"武田信虎が躑躅ヶ崎館の北、標高約780mの山に築いた «詰めの城» です。館が攻められたときに立てこもるための城で、1521年、信玄はこの山のふもと（または城内）で生まれたと伝わります。山中には堀や土塁、石積みがよく残っています。","story":["1519年に躑躅ヶ崎館を築いた武田信虎は、翌1520年、館の北にそびえる山に城を築きました。館は平地にあり、堀と土塁で囲まれてはいても大軍には弱い。«もしもの時に逃げこめる山城を»。これが戦国時代の大名の常識でした。","その «もしも» は、すぐにやってきます。1521年、駿河の今川氏に仕える武将が大軍で甲斐に攻めこみ、甲府のすぐ近くまで迫りました。信虎は迎え撃ちに出ますが、身ごもっていた妻の大井夫人は、要害山のふもとの積翠寺、あるいは山城そのものに避難したといわれます。","その年の11月、戦のさなかに男の子が生まれました。のちの武田信玄です。信虎は今川方の軍勢を打ち破り、息子の誕生と勝利が重なったことを喜んだと伝わります。戦に勝った喜びから、赤ん坊は «勝千代» と名づけられたとも伝わります。","その後も要害山城は、武田氏の本拠を守る最後のとりでとして手入れされました。武田氏が滅んだ後は徳川方が使ったとされ、今も残る石積みの一部は、その時代のものとも考えられています。","山道を登ると、何重にも重なる曲輪と、敵を足止めする «竪堀»、折れ曲がった入口 «枡形虎口» が次々に現れます。頂上の主郭からは木々の間から甲府の町が見え、麓の館との位置関係がよくわかります。"],"tl":[["1520年","武田信虎が要害山城を築く"],["1521年","今川方の軍勢が甲斐に侵攻。信玄が誕生"],["戦国時代","武田氏の詰めの城として使われる"],["1582年以後","武田滅亡後、徳川方が使ったとされる"],["1991年","武田氏館跡の一部として国の史跡に追加指定"]],"who":[["武田信虎","城を築いた信玄の父"],["大井夫人","信虎の妻。戦乱の中この城の近くに避難した"],["武田信玄","この地で生まれたと伝わる"]],"deep":["信玄の誕生の場所については、要害山城の中とする説、麓の積翠寺とする説があります。どちらも伝承にもとづくもので、はっきりしません。","1521年の戦いは «飯田河原の戦い» や «上条河原の戦い» として知られます。今川方の武将の名は福島正成などと伝わりますが、人物像には諸説あります。","信玄の幼名は «勝千代» と伝わり、戦に勝った喜びにちなむとされますが、後の時代の書物による話です。","城は尾根に沿って細長く曲輪を連ね、ところどころに竪堀を落として、斜面を横に移動しにくくしています。","主郭の近くには井戸の跡とされる場所があります。山城では水の確保が籠城の生命線でした。","登山口近くには «武田信玄公誕生之地» の碑が建っています。","要害山城は躑躅ヶ崎館から北へ約2.5kmほど。館で異変があれば、半日もかからず山城へ移れる距離に置かれていました。"],"look":["登山口の «武田信玄公誕生之地» の碑","枡形虎口と石積み","尾根の竪堀","主郭跡と木々の間から見る甲府の町"],"q":["要害山城のように、ふだん住む館とは別に、いざという時に立てこもる山の城を何という？","«詰めの城»。館と山城をセットにするのが戦国時代によく見られた形です。"],"koji":[],"myth":"信玄の誕生地（城内か積翠寺か）、幼名の由来、今川方の武将の名には諸説がある。","img":["武田信虎","武田氏館","武田信玄"],"wp":"要害山城","rel":{"ev":[],"grave":[]},"ph":[["c:6/60/Mt.Yogai_Kofu_city.JPG",4000,3000,"要害山城"],["c:5/51/Stele_for_Takeda_Shingen_birthplace_at_Yogaisan_Castle.jpg",5116,3411],["c:8/83/Site_of_moat_and_mound_at_Yogaisan_Castle.jpg",5472,3648],["c:d/df/Site_of_kuruwa_at_Yogaisan_Castle.jpg",5472,3648],["c:c/c6/Site_of_honmaru_at_Yogaisan_Castle.jpg",5472,3648],["c:e/e7/Site_of_gate_at_Yogaisan_Castle.jpg",5472,3648],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940]]},{"id":"19_sekisuiji","n":"積翠寺（信玄の産湯伝承の寺）","yomi":"せきすいじ","cat":"寺社","rank":"A","y":1521,"era":["nara","muromachi"],"sh":"","ad":"甲府市上積翠寺町","st":"JR甲府駅北口からバスで約20分「積翠寺」下車すぐ","la":35.6975,"lo":138.592,"hook":"戦国最強の武将も、生まれたときは産湯につかる赤ん坊だった。その湯をくんだと伝わる井戸が、この寺にある。","lead":"要害山のふもとにある古い寺で、奈良時代の僧・行基が開いたと伝わります。1521年、戦乱の中で母・大井夫人がこの寺に避難し、信玄を産んだという言い伝えがあり、境内には «信玄の産湯の井戸» と伝わる井戸があります。","story":["積翠寺は、甲府の北の山すそ、要害山のふもとにある静かな寺です。寺の伝えでは、奈良時代に行基が開いたとされ、のちに禅宗の寺として受けつがれてきました。«積翠» とは、緑が重なって見える様子を表す言葉で、山あいの寺らしい名前です。","1521年の秋、駿河の今川方の大軍が甲斐に攻めこみました。甲府の町が戦場になりそうになり、身重だった信虎の妻・大井夫人は、館の北の山あいへ避難します。«どこなら安全か?» 館の北の山には、前の年に築いたばかりの要害山城がありました。","寺の言い伝えでは、大井夫人は積翠寺に身を寄せ、11月3日にここで男の子を産みました。のちの武田信玄です。境内の井戸の水を産湯に使ったと伝わり、今も «産湯の井戸» として大切にされています。一方で、要害山城の中で生まれたとする説もあります。","信玄が成人したのち、この寺では和歌や漢詩の会が開かれたとも伝わります。信玄は武勇だけでなく、和歌や漢詩をたしなむ教養人でもありました。生まれた土地の寺で、家臣たちと歌をよみ交わした姿を想像すると、戦国大名の別の顔が見えてきます。","大井夫人は信玄の成長を見守り、晩年は甲府の長禅寺にゆかりをもったといわれます。積翠寺は、そんな母と子の物語を今に伝える寺として、信玄ファンが訪れる場所になっています。"],"tl":[["奈良時代","行基が開いたと伝わる"],["1520年","寺の背後の山に要害山城が築かれる"],["1521年","大井夫人が避難し、信玄が生まれたと伝わる"],["戦国時代","信玄ゆかりの寺として武田氏に大切にされる"],["現在","産湯の井戸が伝わり、信玄誕生の地として知られる"]],"who":[["行基","奈良時代の僧。寺を開いたと伝わる"],["大井夫人","信玄の母。戦乱の中でこの寺に避難したと伝わる"],["武田信玄","この寺で生まれたと伝わる"],["武田信虎","信玄の父。今川方の軍勢と戦っていた"]],"deep":["信玄の誕生日は大永元年11月3日（旧暦）と伝わります。新暦に直すと12月の初めごろになります。","«積翠寺で生まれた» 説と «要害山城で生まれた» 説があり、どちらも後の時代の書物や伝承によるものです。寺の近くには要害山の登山口もあります。","寺の近くには積翠寺温泉があり、信玄が隠し湯として使ったという伝えもあります。«信玄の隠し湯» の伝承は山梨県内各地に数多くあります。","大井夫人は大井氏の出身で、信虎と敵対した一族から嫁いだとされます。政略結婚でしたが、信玄の教育に熱心だったと伝わります。","寺には信玄ゆかりの品が伝わるといわれますが、公開されていないものもあり、見学は寺の案内に従う必要があります。","積翠寺の周辺は «上積翠寺町» という地名になっていて、寺の名前が町の名前として残っています。背後の要害山、麓の躑躅ヶ崎館と合わせて歩くと、武田氏の本拠の立体的な守りがよくわかります。"],"look":["信玄の産湯の井戸と伝わる井戸","本堂と山あいの境内","寺の裏手に見える要害山","周辺の積翠寺温泉の町並み"],"q":["積翠寺で信玄が生まれたとき、戦っていた相手はどこの勢力？","駿河の今川方の軍勢です。父の信虎がこれを打ち破りました。"],"koji":[],"myth":"寺の開山、信玄の誕生地、産湯の井戸、信玄が歌会を開いたことは伝承によるもの。","img":["武田信玄","大井夫人","要害山城"],"wp":"積翠寺","rel":{"ev":[],"grave":[]},"ph":[["c:9/9d/Entrance_of_the_Sekisuiji.JPG",4000,3000,"積翠寺"],["c:0/03/Takeda_Shingen_statue_of_FUDOUDOU_in_the_Sekisuiji.JPG",4000,3000],["c:4/40/Shingenko_ubuyu_no_ido.JPG",4000,3000],["c:a/a0/Sekisuiji_temple_garden.JPG",4000,3000],["c:e/e1/Kuri_and_Main_hall_of_Sekisui-ji_Templeple.JPG",4000,3000],["c:3/33/Takeda_Harunobu.jpg",1400,1707,"武田信玄"],["c:d/da/%E7%91%9E%E9%9B%B2%E9%99%A2%E5%83%8F%28%E6%AD%A6%E7%94%B0%E4%BF%A1%E5%BB%89%E8%87%AA%E6%8F%8F%29.jpg",2119,4901,"大井夫人"],["c:6/60/Mt.Yogai_Kofu_city.JPG",4000,3000,"要害山城"]]},{"id":"19_iwadono","n":"岩殿山城（小山田氏の岩山の城）","yomi":"いわどのやまじょう","cat":"城","rank":"A","y":1582,"era":["muromachi","azuchi"],"sh":"","ad":"大月市賀岡","st":"JR中央本線 大月駅から歩いて約15分で登山口、山頂まで約1時間（登山道の通行止めに注意）","la":35.6225,"lo":138.948,"hook":"武田勝頼が最後に頼ったのは、巨大な岩壁の上の城だった。しかし城の門は開かなかった。","lead":"大月駅の北にそびえる岩殿山（標高約634m）の上にあった戦国時代の山城です。南側に «鏡岩» とよばれる巨大な岩壁がそびえ、関東の山城の中でも屈指の堅さといわれました。1582年、武田勝頼がこの城をめざしながら、城主・小山田信茂に受け入れられなかった話で知られます。","story":["大月の町から北を見上げると、灰色の巨大な岩壁がそそり立っています。これが岩殿山です。«こんな岩山に、どうやって城を?» 岩壁の上には、わずかな平らな土地がいくつも連なり、そこに見張りの建物や兵の詰め所が置かれていました。","このあたり «郡内» は、戦国時代、小山田氏が治めていました。小山田氏は武田氏の家臣でありながら、半ば独立した領主として力をもち、甲斐と相模・武蔵を結ぶ道をおさえていました。岩殿山城は、その東の守りのかなめでした。","1582年3月、織田・徳川の大軍が甲斐に攻めこみ、新府城を捨てた武田勝頼は、小山田信茂のすすめでこの城をめざしました。しかし、郡内へ向かう途中、信茂は勝頼を受け入れないと態度を変えたと伝わります。«ここまで来て、どこへ行けばよいのか»。行き場をなくした勝頼一行は田野へ向かい、そこで最期をむかえました。","信茂はその後、織田方に降ろうとしましたが、主君を見捨てた者として許されず、処刑されたと伝わります。信茂の家族も城を出て山中を逃げ、その途中に悲しい出来事があったという «稚児落とし» の伝説が、岩殿山の奥の岩場に残っています。","江戸時代に入ると城は使われなくなりました。今は登山道が整備され、頂上の本丸跡からは大月の町と、晴れた日には富士山が見えます。ただし、岩壁の崩落などで登山道の一部が通行止めになることもあるので、出かける前に最新の情報を確かめましょう。"],"tl":[["戦国時代","岩殿山に城が築かれる（築城時期は諸説）"],["16世紀","郡内の小山田氏の拠点として重要視される"],["1582年3月","勝頼が岩殿城をめざすが、小山田信茂に拒まれる"],["1582年","小山田信茂が処刑されたと伝わる"],["江戸時代","城は使われなくなる"]],"who":[["小山田信茂","郡内の領主。最後に勝頼を受け入れなかった"],["武田勝頼","この城をめざしたが入れなかった武田家最後の当主"],["織田信忠","甲州征伐の総大将。信茂を許さなかったとされる"]],"deep":["岩殿山城が小山田氏の城だったのか、武田氏が直接管理していた城だったのかは、研究者の間で意見が分かれています。","軍記物『甲陽軍鑑』などには、勝頼の逃げ先を話し合う場面で、真田昌幸が上野の岩櫃城を勧め、小山田信茂が岩殿城を勧めた、という話が出てきます。後の時代の物語による部分が大きいとされます。","南側の «鏡岩» は、一枚岩のようにそそり立つ巨大な岩壁で、城への攻め口を大きく限っていました。","山頂付近には «揚城戸跡» とよばれる、二つの大岩の間を抜ける門の跡があり、自然の岩をそのまま城門に使っています。","«稚児落とし» は、岩殿山の北西にある高い岩壁の名前です。信茂の家族にまつわる悲しい伝説があり、名前の由来とされます。","小山田信茂の裏切りについては、信茂の側にも郡内の民を戦火から守るための判断だった、という見方があります。"],"look":["大月駅から見上げる鏡岩","揚城戸跡（大岩の門）","本丸跡からの大月の町と富士山","登山道の急な岩場（安全第一で）"],"q":["岩殿山の南側にそびえる巨大な岩壁は何と呼ばれる？","«鏡岩»。この岩壁が天然の城壁の役目を果たしました。"],"koji":[],"myth":"岩殿城の城主の性格、勝頼の逃げ先を話し合った場面、稚児落としの話は軍記物・伝承による部分が大きい。","img":["小山田信茂","武田勝頼","大月市"],"wp":"岩殿山城","rel":{"ev":[],"grave":[]},"ph":[["c:3/3b/IwadonoYama2004.jpg",640,480,"岩殿山城"],["c:0/0f/Otsuki_Station-4.jpg",3191,2096],["c:9/9a/%E7%A8%9A%E5%85%90%E8%90%BD%E3%81%A8%E3%81%97.JPG",2048,1536],["c:5/5f/%E5%B2%A9%E6%AE%BF%E5%B1%B1%E3%81%AE%E9%8E%96%E5%A0%B4.JPG",1536,2048],["c:7/74/%E5%B2%A9%E6%AE%BF%E5%B1%B1%E3%81%8B%E3%82%89%E5%AF%8C%E5%A3%AB%E5%B1%B1%E3%82%92%E6%9C%9B%E3%82%80.JPG",2048,1536],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:1/19/Takeda_Katsuyori.jpg",1000,1300,"武田勝頼"],["c:1/15/Saru_hashi-1a.jpg",4233,2781,"大月市"]]},{"id":"19_kai_zenkoji","n":"甲斐善光寺（信玄が信濃善光寺を移した寺）","yomi":"かいぜんこうじ","cat":"寺社","rank":"A","y":1558,"era":["muromachi","edo"],"sh":"国の重要文化財（金堂・山門）","ad":"甲府市善光寺","st":"JR身延線 善光寺駅から歩いて約7分","la":35.668,"lo":138.5935,"hook":"戦から守るため、信玄は信濃の善光寺の «仏さま» ごと甲府へ運んだ。","lead":"1558年、武田信玄が、上杉謙信との川中島の戦いで信濃の善光寺が焼けることを心配し、本尊の善光寺如来などを甲府に移して建てた寺です。今の本堂（金堂）と山門は江戸時代に再建されたもので、国の重要文化財です。金堂の «鳴き龍» が有名です。","story":["戦国時代、信濃の北部は、甲斐の武田信玄と越後の上杉謙信が激しく争う場所でした。その近くにあった善光寺は、日本じゅうから参詣者が集まる大寺院です。«戦で焼けてしまったら大変だ»。信玄は、善光寺の本尊や僧たちを甲府へ移すことを決めました。","1558年、甲府の板垣の地に新しい善光寺が建てられました。信濃の人々から見れば «仏さまを連れ去られた» ともいえます。信玄のねらいは、戦から守るためだけでなく、大勢の参詣者を甲府に集め、自分の国の力を高めることにもあったと考えられています。","ところが、本尊の旅はここで終わりませんでした。1582年に武田氏が滅ぶと、本尊は織田氏のもとへ、その後は徳川氏、さらに豊臣秀吉のもとへと移されます。秀吉は京都に建てた大仏殿の本尊にしようとしたといわれます。そして1598年、本尊はようやく信濃の善光寺へ帰りました。","甲府の善光寺には、そのあとも «前立仏» などの仏像が残り、信仰を集め続けました。江戸時代の1754年、火事で伽藍が焼けてしまいますが、人々の寄付で再建が進み、1796年ごろに今の大きな金堂が完成しました。","金堂の中に入り、天井の下で手をたたくと、«ビーン» と龍が鳴くような音がひびきます。これが «鳴き龍» です。広い天井と床の間で音が何度も反射して起こる現象で、日本最大級の鳴き龍といわれています。"],"tl":[["1558年","信玄が信濃の善光寺の本尊を移し、甲府に善光寺を建てる"],["1582年","武田氏滅亡。本尊は織田氏のもとへ"],["1598年","本尊が信濃の善光寺へ戻される"],["1754年","火事で伽藍が焼ける"],["1796年ごろ","金堂が再建される"],["現在","金堂と山門が国の重要文化財に"]],"who":[["武田信玄","善光寺の本尊を甲府に移した"],["上杉謙信","川中島で信玄と戦った越後の大名"],["豊臣秀吉","本尊を京都へ移したといわれる"]],"deep":["本尊の善光寺如来は、ふだん人の目にふれない «秘仏» として知られます。信濃の善光寺と同じく、甲斐善光寺でも前立仏が大切にされています。","寺には «源頼朝像» と伝わる木像があり、鎌倉時代の作で、頼朝の像としては古い例とされています（国の重要文化財）。","信玄は本尊だけでなく、善光寺の僧たちやゆかりの品々も甲府へ移したといわれます。","甲斐善光寺の金堂は、東日本でも最大級の木造建築のひとつとされます。","«鳴き龍» は、天井に描かれた龍の絵の下で手をたたくと響く現象です。日光東照宮の本地堂の鳴き龍なども知られています。","本尊を移したことは、信濃の人々にとって大きな出来事でした。信濃側の記録や言い伝えでは、甲府での日々は «仮住まい» として語られます。"],"look":["大きな金堂と、天井下の «鳴き龍»","朱塗りの山門","宝物館の仏像（源頼朝像と伝わる像など）","JR善光寺駅から寺へ向かう参道"],"q":["信玄が善光寺の本尊を甲府へ移した理由として、よく言われるのは？","上杉謙信との戦いで信濃の善光寺が焼けるのを防ぐためです。"],"koji":[],"myth":"源頼朝像の像主、本尊の移動の細かい経緯には諸説がある。","img":["善光寺","武田信玄","川中島の戦い"],"wp":"甲斐善光寺","rel":{"ev":[],"grave":[]},"ph":[["c:5/5b/Kai-Zenkoji-temple_Kofu-city_Yamanashi_Japan.JPG",4000,3000,"甲斐善光寺"],["c:7/7e/Kai-Zenkoji-temple_main_gate.JPG",4000,3000],["c:1/1f/Kai-Zenkoji-temple_hall_of_a_Buddhist_temple_inside_%E2%84%962.JPG",4000,3000],["c:2/24/Kai-Zenkoji-temple_hall_of_a_Buddhist_temple_inside_%E2%84%961.JPG",4000,3000],["c:e/ed/Kai_Zenkouji_Temple_from_the_gate.jpg",4362,2850],["c:5/5b/Kai_Zenkoji-1.jpg",3795,2772],["c:5/52/Zenkoji02s3200.jpg",3200,2142],["c:3/33/Takeda_Harunobu.jpg",1400,1707]]},{"id":"19_daizenji","n":"大善寺（ぶどう寺・国宝薬師堂）","yomi":"だいぜんじ","cat":"寺社","rank":"A","y":1286,"era":["nara","kamakura","azuchi"],"sh":"国宝（薬師堂）","ad":"甲州市勝沼町勝沼","st":"JR中央本線 勝沼ぶどう郷駅から車で約5分（歩くと約40分）","la":35.664,"lo":138.7435,"hook":"手にぶどうを持つ薬師さま。山梨の «ぶどうのはじまり» を語る寺に、県内最古の建物が建っている。","lead":"勝沼の柏尾にある古い寺で、奈良時代に行基が開いたと伝わります。本堂の «薬師堂» は1286年に建てられた鎌倉時代の建物で、国宝です。ぶどうを手にした薬師如来の伝説から «ぶどう寺» とも呼ばれ、甲州ぶどうの歴史と深く結びついています。","story":["寺の言い伝えによると、奈良時代の718年、行基がこの地で修行していたところ、夢の中に、右手にぶどうを持った薬師如来があらわれました。行基はその姿を木に刻んでまつり、寺を開いたといいます。そして、村人にぶどうの育て方を教えた――これが甲州ぶどうの始まりだ、という伝説です。","«本当に行基がぶどうを?» 甲州ぶどうの起源には、ほかにも鎌倉時代の初めに地元の人が山でぶどうのつるを見つけて育てた、という伝えもあります。どちらも言い伝えですが、この寺がぶどうの里・勝沼の心のよりどころだったことは確かです。","薬師堂は1286年に建てられました。山梨県で最も古い木造建築の一つで、軒の深い屋根と、太い柱がどっしりとした姿を見せます。鎌倉時代の建物が、戦国の戦乱も江戸の火事もくぐりぬけて残ったのは奇跡のようです。","1582年、新府城を捨てて逃げる武田勝頼の一行が、この寺に立ち寄ったと伝わります。寺には武田氏の一族で尼となった理慶尼がいて、一行をもてなしたといわれます。理慶尼は武田氏滅亡の様子を書き残したと伝わり、その記録は «理慶尼記» として知られます。","その286年後の1868年、寺のすぐそばの柏尾で、近藤勇の甲陽鎮撫隊と新政府軍が戦いました。戦いの舞台のすぐ隣で、薬師堂は静かに時代の移り変わりを見つめてきたのです。今も境内にはぶどう棚があり、秋には実りの風景が広がります。"],"tl":[["718年","行基が開いたと伝わる"],["1286年","薬師堂（本堂）が建てられる"],["1582年","逃避行中の武田勝頼一行が立ち寄ったと伝わる"],["1868年","近くの柏尾で甲州勝沼の戦い"]],"who":[["行基","奈良時代の僧。寺を開き、ぶどうを伝えたとされる（伝説）"],["理慶尼","武田氏ゆかりの尼。勝頼一行をもてなしたと伝わる"],["武田勝頼","最期の直前、この寺に立ち寄ったと伝わる"]],"deep":["薬師堂は、正面・側面とも5間の «五間堂» で、檜皮葺の大きな屋根をもちます。和様を基本に、鎌倉時代の力強さがよく表れています。","本尊の薬師如来と日光・月光菩薩は平安時代の作とされ、国の重要文化財です。ふだんは秘仏で、公開される時期が限られています。","堂内には十二神将像も伝わり、鎌倉時代の仏像として知られます。","毎年5月8日には «藤切り祭» が行われ、大きな藤づるを大蛇に見立てて切り、魔よけとする行事が続いています。","«理慶尼記» は、勝頼一行の最期を身近で見聞きした人の記録として注目されますが、後の時代に書き加えられた部分もあるといわれます。","寺では昔からぶどう酒づくりとの関わりもあり、境内でぶどうにちなむ品を見ることができます。"],"look":["国宝・薬師堂の大きな屋根と柱","ぶどうを持つ薬師如来の伝説にちなむ展示","境内のぶどう棚","すぐそばの柏尾古戦場"],"q":["大善寺の薬師如来が手に持っていたと伝わるものは？","ぶどう。そのため «ぶどう寺» とも呼ばれます。"],"koji":[],"myth":"行基の開山とぶどう伝来は伝説。理慶尼が勝頼一行をもてなした話や理慶尼記の成立には諸説。","img":["甲州 (ブドウ)","行基","甲州勝沼の戦い"],"wp":"大善寺 (甲州市)","rel":{"ev":[],"grave":[]},"ph":[["c:2/21/Daizen-ji-4a.jpg",4496,3000,"大善寺 (甲州市)"],["c:b/b8/Daizen-ji-7.jpg",4496,3000],["c:3/35/Daizen-ji-6a.jpg",4496,3000],["c:d/de/Daizen-ji-6.jpg",4496,3000],["c:a/a2/Daizen-ji-5.jpg",4496,3000],["c:3/3d/Daizen-ji-4d.jpg",4496,3000],["c:f/fd/Daizen-ji-4b.jpg",4496,3000],["c:f/fd/Daizen-ji-4.jpg",4496,3000]]},{"id":"19_seihakuji","n":"清白寺（国宝仏殿）","yomi":"せいはくじ","cat":"寺社","rank":"A","y":1415,"era":["kamakura","muromachi"],"sh":"国宝（仏殿）","ad":"山梨市三ヶ所","st":"JR中央本線 東山梨駅から歩いて約10分","la":35.6858,"lo":138.7075,"hook":"反り上がった屋根、花のような形の窓。600年前の «禅の建築» が、ぶどう畑の中にそのまま立っている。","lead":"南北朝時代に夢窓疎石を開山として開かれた禅寺です。1415年に建てられた «仏殿» は、中国から伝わった «禅宗様» という建築の特徴をよく残し、国宝に指定されています。梅の名所としても知られます。","story":["山梨市の果樹園の中に、ひときわ屋根の反りが美しい建物が見えてきます。清白寺の仏殿です。«なぜこんなに屋根がはね上がっているの?» それは、鎌倉時代に中国（宋）から禅宗とともに伝わった建築スタイル «禅宗様» の特徴なのです。","清白寺は、南北朝時代、夢窓疎石を開山として開かれました。夢窓疎石は足利尊氏・直義兄弟に深く尊敬された禅僧で、甲斐にも恵林寺など多くのゆかりの寺があります。清白寺は、夢窓の故郷ともいわれる甲斐の地で、禅の教えを広める拠点の一つになりました。","1415年、今の仏殿が建てられました。室町時代の初めのことです。屋根は反りの強い入母屋造りで、軒下には «扇垂木» という、扇の骨のように放射状に広がる垂木が並びます。窓は上の部分が花のような曲線を描く «花頭窓»。どれも禅宗様ならではの形です。","禅宗様の古い建物は全国でも多くはなく、鎌倉の円覚寺舎利殿などと並んで、この様式を知るための大切なお手本とされています。戦国の戦乱も乗りこえ、600年以上前の姿を今に伝えています。","寺の «庫裏» も江戸時代の建物で、国の重要文化財です。春先には境内の梅が咲き、国宝の仏殿と梅の花が並ぶ景色を見に、多くの人が訪れます。","清白寺を訪れたら、仏殿を正面からだけでなく、横やななめからも眺めてみましょう。屋根の四すみが空に向かってはね上がる線、軒下にぎっしり並ぶ組物、細くしぼられた柱の足もと。«どこからが禅宗様らしさなのか?» と探しながら歩くと、600年前の大工たちが中国の最新の建築をどう学び、どう甲斐の地に建てたのかが少しずつ見えてきます。"],"tl":[["1333年ごろ","夢窓疎石を開山として寺が開かれたと伝わる"],["1415年","仏殿が建てられる"],["江戸時代","庫裏が建てられる"]],"who":[["夢窓疎石","開山とされる南北朝時代の禅僧"],["足利尊氏","夢窓疎石を尊敬した室町幕府の初代将軍。寺の開基とする伝えがある"],["大工たち","中国から伝わった禅宗様の技法で仏殿を建てた職人。名前は伝わらない"]],"deep":["仏殿は «方三間・裳階付き» という形で、外から見ると二重の屋根に見えますが、実際は一階建てです。下の屋根は «裳階（もこし）» というひさしです。","«扇垂木» は禅宗様の代表的な特徴で、屋根の隅に向かって垂木が扇のように広がります。和様の平行な垂木とくらべるとちがいがよくわかります。","«花頭窓» は、上部が火炎や花びらのような曲線になった窓で、禅宗寺院の建物によく見られます。","柱の上下を細くした «粽（ちまき）» や、柱の下に置く «礎盤» など、細部にも禅宗様の特徴がそろっています。","寺の創建の年や開基については、史料によってちがいがあり、はっきりしない部分があります。","禅宗様の建物は、柱の上だけでなく柱と柱の間にも «組物» を置く «詰組» が特徴です。軒下がにぎやかに見えるのはこのためで、和様の建物との大きなちがいになっています。"],"look":["国宝・仏殿の反り上がった屋根","軒下の扇垂木","花頭窓の曲線","重要文化財の庫裏","早春の梅の花"],"q":["清白寺の仏殿のような、中国の宋から伝わった禅寺の建築様式を何という？","«禅宗様»。扇垂木や花頭窓などが特徴です。"],"koji":[],"myth":"創建年や開基（足利尊氏とする説など）には諸説がある。","img":["夢窓疎石","禅宗様","円覚寺"],"wp":"清白寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Buddha_Hall%2C_Seihaku-ji_201906-1.jpg",3639,2731,"清白寺"],["c:d/de/Seihaku-ji_Temple_main_gate.JPG",4000,3000],["c:0/0e/Buddha_Hall_Seihaku-ji.%E2%84%962.JPG",4000,3000],["c:c/ca/Seihaku-ji_Kuri_01.jpg",3936,2952],["c:e/ee/Muso_Soseki.jpg",1297,1584,"夢窓疎石"],["c:0/04/Kozanji_Temple_%28Shimonoseki%29.JPG",1280,960,"禅宗様"],["c:e/e9/Engakuji_Sanmon_Kamakura.jpg",800,600,"円覚寺"]]},{"id":"19_kogakuji","n":"向嶽寺（抜隊得勝の禅寺）","yomi":"こうがくじ","cat":"寺社","rank":"A","y":1380,"era":["muromachi"],"sh":"国宝（絹本著色達磨図）・国の重要文化財（中門）","ad":"甲州市塩山上於曽","st":"JR中央本線 塩山駅から歩いて約15分","la":35.7045,"lo":138.7315,"hook":"«自分とは何か?» その問い一つを生涯つきつめた僧が、塩の山のふもとに開いた道場。","lead":"室町時代の1380年、禅僧・抜隊得勝（ばっすいとくしょう）が、塩山駅の北にある «塩ノ山» のふもとに開いた禅寺です。今も修行僧が学ぶ道場で、臨済宗向嶽寺派の本山です。鎌倉時代の «達磨図» は国宝に指定されています。","story":["抜隊得勝は、相模の国の生まれと伝わります。幼いころに父を亡くし、«死んだ父はどこへ行ったのか?»«いったい、この自分とは何者なのか?» と問い続けたことが、僧になるきっかけだったといわれます。","各地をめぐって修行した抜隊は、やがて甲斐の国にたどりつきます。1380年ごろ、塩ノ山のふもとに «向嶽庵» という小さな庵を結びました。«嶽»（富士山）に向かう庵、という意味と伝わります。その教えを慕って多くの人が集まり、庵はしだいに大きな寺になっていきました。","抜隊の教えは、むずかしい理屈より «自分の心を見よ» という、まっすぐなものでした。その言葉は『塩山和泥合水集』という本にまとめられ、ふつうの人にもわかることばで禅を説いたことで知られます。","戦国時代には武田氏がこの寺を大切にし、多くの保護を与えました。江戸時代にも修行の寺として受けつがれ、今も禅の道場として僧たちが修行を続けています。そのため、境内のすべてを自由に見学できるわけではありません。","寺に伝わる «絹本著色達磨図» は、鎌倉時代にえがかれた達磨大師の絵で、赤い衣をまとい、鋭い目でこちらをにらむ姿が迫力満点です。国宝に指定され、ふだんは公開されていませんが、特別な展示の機会に見られることがあります。","境内に入ると、ほうき目の立った庭や、すみずみまで掃き清められた道に気づくはずです。掃除も修行のひとつ。抜隊が開いてから600年以上、この寺では毎日同じように朝が始まり、同じように僧たちが座禅を組んできました。«自分とは何か?» という抜隊の問いは、今もこの静かな境内で問い続けられているのです。"],"tl":[["1380年","抜隊得勝が塩ノ山のふもとに向嶽庵を開く"],["1387年","抜隊得勝が亡くなる"],["戦国時代","武田氏の保護を受ける"],["江戸時代","禅の道場として受けつがれる"],["明治以降","臨済宗向嶽寺派の本山となる"],["現在","修行道場として続き、国宝の達磨図が伝わる"]],"who":[["抜隊得勝","寺を開いた室町時代の禅僧"],["武田信玄","寺を保護した戦国大名"]],"deep":["«塩山» という地名は、寺の背後の «塩ノ山» に由来するといわれます。抜隊はこの山の名にちなんで «塩山» と号したとも伝わります。","『塩山和泥合水集』は、抜隊が弟子や信者に語った言葉をまとめたもので、仮名まじりのやさしい文で書かれています。","国宝の «達磨図» は、鎌倉時代の禅宗の肖像画の名品とされます。作者は不明です。","中門は国の重要文化財で、室町時代の禅寺の門の形を伝えるとされます。","修行の寺のため、見学できる範囲や時期が限られています。訪れるときは寺の案内に従い、修行のさまたげにならないよう静かにしましょう。","抜隊得勝は、弟子を育てることに厳しく、寺を大きくすることよりも修行の質を重んじたと伝わります。向嶽寺が今も専門の修行道場として続いていることは、その精神を受けついだものといえます。"],"look":["重要文化財の中門","境内の庭園と背後の塩ノ山","修行道場としての静かなたたずまい（見学は案内に従う）"],"q":["抜隊得勝が寺を開いたふもとの山の名前は？","«塩ノ山»。«塩山» という地名の由来になったといわれます。"],"koji":[],"myth":"«向嶽» の意味、抜隊の出家のきっかけ、塩山の地名の由来は伝承を含む。","img":["抜隊得勝","塩ノ山","臨済宗"],"wp":"向嶽寺","rel":{"ev":[],"grave":[["shingen","武田信玄"]]},"ph":[["c:9/9c/Kogakuji_temple_Oct._10%2C_2021_A.jpg",6000,4000,"向嶽寺"],["c:f/f5/The_Middle_gate_of_Kogakuji_temple_Oct._10%2C_2021.jpg",6000,4000],["c:0/06/Kogakuji-1.jpg",3817,3002],["c:d/d0/Daruma_Kogakuji.jpg",784,1414],["c:8/81/Daien_Zenji_%28Kogakuji_Koshu%29.jpg",131,270,"抜隊得勝"],["c:e/e8/RinzaiGigen.jpg",413,600,"臨済宗"]]},{"id":"19_unpoji","n":"雲峰寺（日の丸御旗・風林火山の孫子の旗）","yomi":"うんぽうじ","cat":"寺社","rank":"A","y":1582,"era":["nara","muromachi","azuchi"],"sh":"国の重要文化財（本堂など）","ad":"甲州市塩山上萩原","st":"JR中央本線 塩山駅からバスで約30分「大菩薩峠登山口」付近下車、歩いて約5分","la":35.747,"lo":138.82,"hook":"«疾きこと風の如く…»。武田の旗が、大菩薩峠へ向かう山寺にひっそりと伝わっている。","lead":"大菩薩峠へ向かう道の途中にある山寺で、奈良時代に行基が開いたと伝わります。武田氏ゆかりの «日の丸御旗»、«孫子の旗（風林火山の旗）»、«馬印» などが伝わり、1582年の武田滅亡の際に家臣たちが寺に託した、という言い伝えがあります。","story":["寺の伝えでは、奈良時代、行基が山中の大きな岩が裂けているのを見つけ、そこに十一面観音をまつったのが始まりといいます。寺の山号 «裂石山» は、この岩にちなむ名前です。","戦国時代、甲斐の武田氏は、この寺を大切にしました。やがて1582年、武田氏が織田・徳川の大軍に追われて滅びます。このとき、勝頼の家臣たちが大菩薩峠を越えて落ちのびようとし、武田家に伝わる大事な旗を寺に預けた――そんな言い伝えがあります。","その旗の一つが «日の丸御旗»。白地に赤い丸を描いた旗で、平安時代、天皇から源氏の祖先に与えられ、武田家に代々伝わったといわれます。«楯無の鎧» とともに武田家の家宝とされ、«御旗楯無もご照覧あれ» と誓えば、どんな決定もくつがえせなかったといいます。","もう一つは «孫子の旗»。«疾如風 徐如林 侵掠如火 不動如山»――«はやきこと風のごとく、しずかなること林のごとく、侵掠すること火のごとく、動かざること山のごとし»。中国の兵法書『孫子』の言葉を書いた旗で、今では «風林火山» の名で知られます。","旗は長い年月の間に傷みましたが、大切に守られ、寺の宝物館で見ることができます（公開の状況は寺に確認）。本堂や庫裏などは室町時代の終わりごろの建物で、国の重要文化財に指定されています。山あいの長い石段を上ると、苔むした境内に古い本堂が静かに建っています。"],"tl":[["奈良時代","行基が開いたと伝わる"],["戦国時代","武田氏の保護を受ける"],["16世紀","今の本堂などが建てられたとされる"],["1582年","武田家の旗が寺に託されたと伝わる"],["現在","宝物館で旗などが伝えられている"]],"who":[["行基","奈良時代の僧。寺を開いたと伝わる"],["武田信玄","孫子の旗を掲げたとされる戦国大名"],["武田勝頼","武田家最後の当主。滅亡の際に家臣が旗を託したと伝わる"]],"deep":["«日の丸御旗» は、日の丸を描いた旗として日本で最も古いものの一つとされますが、作られた時期には諸説があります。","«御旗楯無» は、武田家の家宝である «日の丸御旗» と «楯無の鎧» のことです。楯無の鎧は甲州市の菅田天神社に伝わり、国宝に指定されています。","«風林火山» という呼び方は、実は近代になって広まったもので、戦国時代には «孫子の旗» と呼ばれていたと考えられています。小説やドラマの影響で有名になりました。","孫子の旗の文字は、快川紹喜が書いたと伝わりますが、確かな史料で裏づけられているわけではありません。","寺には «馬印» など、ほかにも武田家ゆかりの旗が伝わっています。","本堂は室町時代の終わりごろの建築とされ、山寺らしい素朴で力強い姿を伝えています。"],"look":["山あいの長い石段と仁王門","重要文化財の本堂","宝物館の日の丸御旗・孫子の旗（公開状況は要確認）","大菩薩峠へ続く山道の風景"],"q":["«風林火山» の言葉のもとになった中国の書物は？","兵法書『孫子』。旗は «孫子の旗» と呼ばれていました。"],"koji":[{"w":"疾きこと風の如く、徐かなること林の如く、侵掠すること火の如く、動かざること山の如し","m":"『孫子』の言葉。軍の動き方を風・林・火・山にたとえたもの"}],"myth":"寺の開山、旗が1582年に託された経緯、孫子の旗の書き手、日の丸御旗の年代は伝承・諸説。","img":["風林火山","菅田天神社","孫子 (書物)"],"wp":"雲峰寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/07/Unpoji-Temple_old_stone_stairway.JPG",4000,3000,"雲峰寺"],["c:5/59/Unpoji-Temple_main_hall.JPG",4000,3000],["c:1/15/Kandatenjinja_shrine.JPG",1944,1296,"菅田天神社"],["c:2/2a/Bamboo_book_-_closed_-_UCR.jpg",2448,1880,"孫子 (書物)"]]},{"id":"19_kubohachiman","n":"大井俣窪八幡神社（室町の社殿群）","yomi":"おおいまたくぼはちまんじんじゃ","cat":"寺社","rank":"A","y":1410,"era":["heian","muromachi"],"sh":"国の重要文化財（本殿など多数）","ad":"山梨市北","st":"JR中央本線 山梨市駅から車で約10分（バス便は少ない）","la":35.7135,"lo":138.677,"hook":"一つの神社に、国の重要文化財がずらり。室町時代の «社殿の博物館» と呼ばれる場所。","lead":"平安時代に宇佐八幡宮から神を迎えたと伝わる神社です。室町時代に建てられた本殿をはじめ、拝殿、鳥居、摂社などの建物が多く残り、その多くが国の重要文化財に指定されています。武田氏にも大切にされました。","story":["山梨市の北、笛吹川の支流が流れる静かな土地に、大井俣窪八幡神社はあります。社伝では、平安時代のはじめ、九州の宇佐八幡宮から八幡神を迎えたのが始まりとされます。八幡神は武士の守り神として、多くの武家に信仰されました。","«なぜこんなに古い建物がたくさん残ったの?» この神社は、室町時代から戦国時代にかけて、甲斐の守護である武田氏から厚く保護されました。社殿の建てかえや修理が武田氏の力で行われ、その後、大きな戦火や火事にあわなかったことで、多くの建物がそのまま残ったのです。","本殿は、小さな社がいくつも横につながったような、とても横に長いめずらしい形をしています。室町時代の初めごろに建てられたもので、極彩色の彫刻や飾り金具が、当時の華やかさを伝えています。","境内には木造の大きな鳥居も立っています。室町時代の終わりごろのもので、木の鳥居としては全国でもとても古い例です。鳥居をくぐって参道を歩くと、拝殿、神楽殿、摂社の若宮八幡など、時代の異なる建物が次々に現れ、まるで建物の歴史をたどるようです。","戦国時代には、武田信虎・信玄らがこの神社に社殿を寄進したり、祈願をしたりしたと伝わります。国の重要文化財に指定された建物の数は山梨県内で最も多いクラスで、建築好きにはたまらない神社です。","参道を歩くと、建物ごとに屋根の形や彫刻のにぎやかさ、色の使い方が少しずつちがうことに気づきます。«これはいつの時代の建物だろう?» と比べながら歩けば、室町から江戸にかけての神社建築の移り変わりが自然と見えてきます。訪れる人が少ない静かな境内で、古い木の香りと、ていねいに守られてきた社殿の姿をじっくり味わえます。"],"tl":[["平安時代","宇佐八幡宮から神を迎えたと伝わる"],["1410年ごろ","今の本殿が建てられたとされる"],["室町時代","武田氏の保護を受け、社殿が整えられる"],["16世紀","木造の鳥居が建てられる"],["明治以降","多くの建物が国の重要文化財に指定される"]],"who":[["武田信虎","社殿の造営に関わったと伝わる"],["武田信玄","神社に祈願したと伝わる"],["武田氏","室町時代から神社を保護した甲斐の守護"]],"deep":["本殿は «十一間社流造» とよばれる横に長い形で、正面の柱の間が11もあります。全国でも例の少ない形とされます。","木造の鳥居は «両部鳥居» の形式で、室町時代の終わりごろに建てられたものといわれ、木造の鳥居としてはとても古い例です。","重要文化財に指定された建物は10件をこえ、一つの神社としては全国でも多い部類に入ります。","社殿の彩色や彫刻は、何度かの修理で色がよみがえっています。修理のときに見つかった墨書から、建てられた年や大工の名がわかったものもあります。","神社の名前にある «大井俣» は昔の地名、«窪» は土地のくぼみを表すといわれます。","八幡神は応神天皇と同じ神とされ、源氏が氏神として信仰したことから、武士の神として全国に広まりました。源氏の流れをくむ武田氏がこの神社を大事にしたのも、そうした背景があると考えられます。"],"look":["横に長い十一間社流造の本殿","木造の大鳥居","拝殿と神楽殿","摂社・若宮八幡神社の本殿"],"q":["大井俣窪八幡神社の本殿は、どんな形をしている？","正面の柱の間が11もある «十一間社流造» という、横に長いめずらしい形です。"],"koji":[],"myth":"創建の由来は社伝。各建物の建立年や武田氏の関与の程度には諸説がある。","img":["八幡神","宇佐神宮","流造"],"wp":"大井俣窪八幡神社","rel":{"ev":[],"grave":[]},"ph":[["c:8/81/Oimatakubo-hachiman_shrine_Haiden_March_2014.JPG",4000,2250,"大井俣窪八幡神社"],["c:6/64/Oimatakubo-hachiman_shrine_%E2%84%962.JPG",4000,3000],["c:9/9c/Kita%2C_Yamanashi%2C_Yamanashi_Prefecture_405-0041%2C_Japan_-_panoramio_%285%29.jpg",2048,1536],["c:0/0c/Kita%2C_Yamanashi%2C_Yamanashi_Prefecture_405-0041%2C_Japan_-_panoramio_%284%29.jpg",2048,1536],["c:3/3e/Kita%2C_Yamanashi%2C_Yamanashi_Prefecture_405-0041%2C_Japan_-_panoramio_%2817%29.jpg",2048,1536],["c:5/5c/Kita%2C_Yamanashi%2C_Yamanashi_Prefecture_405-0041%2C_Japan_-_panoramio_%2816%29.jpg",2048,1536],["c:c/c4/Kita%2C_Yamanashi%2C_Yamanashi_Prefecture_405-0041%2C_Japan_-_panoramio_%2815%29.jpg",2048,1536],["c:0/00/%E5%85%AB%E5%B9%A1%E7%A5%9E%E5%9D%90%E5%83%8F%2C_Hachiman.jpg",4912,3264,"八幡神"]]},{"id":"19_takeda_hachiman","n":"武田八幡宮（甲斐源氏・武田氏の氏神）","yomi":"たけだはちまんぐう","cat":"寺社","rank":"A","y":1541,"era":["heian","muromachi","azuchi"],"sh":"国の重要文化財（本殿）","ad":"韮崎市神山町北宮地","st":"JR韮崎駅から車で約10分（バスは本数が少ない）","la":35.7133,"lo":138.4228,"hook":"«武田» という名字が生まれた里の氏神。信玄が建て直した本殿と、滅亡直前に勝頼の妻が書いた祈りの手紙が残る。","lead":"韮崎市の山すその «武田» という土地にある八幡さまです。甲斐源氏の武田信義がここで元服（大人になる儀式）をしたと伝わり、武田氏は代々この神社を大切にしました。いまの本殿は1541年に武田晴信（のちの信玄）が建て直したもので、国の重要文化財です。","story":["韮崎の町から西へ、釜無川をわたって山すそを上ると、石の鳥居の向こうに静かな杜が見えてきます。このあたりの古い地名は «武田»。平安時代の終わり、源氏の一族がこの土地に根をおろし、やがて地名を名字にして «武田氏» と名乗りました。戦国最強とうたわれた武田家の、まさにふるさとなのです。","神社のはじまりは、平安時代の822年に嵯峨天皇の命令で建てられたと伝わります。のちに甲斐源氏がこの地に住むと、源氏の守り神である八幡神は一族の氏神になりました。武田信義は13歳のときにこの社の前で元服し、«武田太郎» と名乗ったと伝わります。«ここから武田の歴史が始まった» と言いたくなる場所です。","時は流れて1541年。この年、21歳の晴信は父・信虎を駿河へ追い出し、武田家の当主になりました。その同じ年に、晴信はこの神社の本殿を建て直しています。«なぜ、このタイミングで?» 家を継いだばかりの若い当主が、ご先祖の神さまに «これからの自分を見守ってください» と誓う。そんな思いがあったのかもしれません。","それから約40年後。武田家は織田・徳川の大軍に攻められ、追いつめられていました。1582年2月、勝頼の妻（北条氏から嫁いだため «北条夫人» と呼ばれます）は、この神社に一通の願文をおさめます。«どうか夫をお守りください。敵を退けてください»。けれど祈りはとどかず、翌月、夫婦は天目山のふもとで最期をむかえました。","願文は今も神社に伝わり、19歳の女性のまっすぐな言葉として読む人の胸を打ちます。武田家のはじまりと終わりの両方が、この小さな杜に刻まれているのです。境内に立つと、甲府盆地と八ヶ岳の方角を見わたせます。武田の人々も、同じ景色をながめていたのでしょう。"],"tl":[["822年","嵯峨天皇の命令で創建されたと伝わる"],["12世紀","甲斐源氏が武田の地に住み、武田氏を名乗る"],["12世紀中ごろ","武田信義がこの社で元服したと伝わる"],["1541年","武田晴信が当主となり、同年に本殿を再建"],["1581年","勝頼が近くに新府城を築き、本拠を移す"],["1582年2月","北条夫人が勝頼の武運を祈る願文をおさめる"],["1582年3月","勝頼・北条夫人が天目山のふもとで自害し、武田氏滅亡"]],"who":[["武田信義","甲斐源氏の武将。ここで元服し «武田» を名乗ったと伝わる"],["武田晴信（信玄）","当主になった年に本殿を再建した"],["武田勝頼","信玄の子。近くの新府城に本拠を移した"],["北条夫人","勝頼の妻。滅亡直前に夫の無事を祈る願文をおさめた"]],"deep":["本殿は三間社流造（さんげんしゃながれづくり）で、戦国時代の甲斐の神社建築を今に伝えます。武田氏が建てた建物がそのまま残る例は多くなく、とても貴重です。","«武田» の名字の由来には諸説あります。この韮崎の武田の地とする説のほか、常陸国（茨城県）の «武田郷» にちなむとする説もあり、研究者の間で議論が続いています。","北条夫人の願文は、敵を «逆臣» と呼び、勝頼の苦しい立場を神に訴える内容で、滅亡直前の武田家の空気を伝える一級の史料です。","神社のすぐ近くには、勝頼が築いた新府城跡があります。武田のはじまりの社と、武田最後の城がとなり合っているのは偶然ではなく、勝頼が先祖の地を強く意識した表れと見る人もいます。","境内の石鳥居も古く、戦国時代のものと伝わります。本殿とともに、武田氏がこの社をどれほど大切にしたかを物語ります。"],"look":["信玄が再建した本殿（覆い屋ごしに見る）","参道の石鳥居","境内から見わたす甲府盆地と韮崎の町","近くの新府城跡とあわせて «武田のはじまりと終わり» をたどる"],"q":["武田晴信（信玄）がこの神社の本殿を建て直したのは、どんな年？","武田家の当主になったのと同じ1541年。父・信虎を駿河へ追放した年です。"],"koji":[],"myth":"創建年（822年）や信義元服の話、«武田» の名字の由来は伝承・諸説を含む。","img":["武田信義","新府城","武田勝頼"],"wp":"武田八幡宮","rel":{"ev":[],"grave":[]},"ph":[["c:5/50/TakedahatimanguuDVC00241.JPG",240,400,"武田八幡宮"],["c:6/6f/TAKEDAHACHIMANGU.JPG",4288,3216],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:8/84/Takeda_Nobuyoshi.jpg",1214,1467,"武田信義"],["c:7/7e/Shinpu_Castle.jpg",2048,1536,"新府城"],["c:1/19/Takeda_Katsuyori.jpg",1000,1300,"武田勝頼"]]},{"id":"19_kai_ichinomiya","n":"甲斐国一宮 浅間神社","yomi":"かいのくにいちのみや あさまじんじゃ","cat":"寺社","rank":"A","y":865,"era":["heian","muromachi","edo"],"sh":"国の重要文化財（摂社山宮神社本殿）","ad":"笛吹市一宮町一ノ宮","st":"JR山梨市駅または石和温泉駅から車で約10〜15分","la":35.6405,"lo":138.6961,"hook":"富士山が大噴火した翌年、甲斐の人々が «山の神» をしずめるために祀った国一番の神社。春には神輿が40kmを歩く。","lead":"甲斐国（今の山梨県）で最も格の高い «一宮» の神社です。富士山の女神・木花開耶姫命（このはなさくやひめのみこと）をまつります。富士山が大噴火した翌年の865年に今の場所へ移されたと伝わり、甲斐の人々の祈りの中心でした。","story":["春、笛吹市一宮のあたりは一面の桃の花でピンク色にそまります。その花の海の中に、甲斐国でいちばん格の高い神社 «一宮» があります。まつられているのは木花開耶姫命。富士山の神さまとして知られる、美しい女神です。けれど、ここから富士山はほとんど見えません。«なぜ、富士の神さまがここに?»","答えのかぎは、平安時代の大噴火です。864年、富士山が大噴火を起こしました。流れ出た溶岩は湖を埋め、今の青木ヶ原のもとになったといわれます。人々は «山の神がお怒りだ» と恐れました。そして翌865年、神社を山の奥から里へ移し、ていねいにおまつりしたと伝わります。もとの場所は、今も摂社の «山宮神社» として残っています。","この神社には、もうひとつ大切な仕事がありました。甲府盆地の川の水をしずめることです。毎年4月15日の «大神幸祭（おみゆきさん）» では、神輿が甲斐市竜王の三社神社まで出かけ、水害がないよう祈ります。往復はおよそ40km。かつがれた神輿が桃畑や町を進む姿は、春の甲府盆地の風物詩です。","戦国時代には武田氏もこの神社をあつく敬いました。武田信玄も一宮に祈りをささげたと伝わります。甲斐の国を治める者にとって、国いちばんの神さまを大切にすることは、国をひとつにまとめることでもあったのです。","境内には安産や子授けを願う人が多く訪れます。燃える産屋の中で子を生んだという木花開耶姫の神話から、火と子どもを守る神さまとして信じられてきたからです。富士山の噴火をしずめる祈りと、赤ちゃんの誕生を願う祈り。はげしさとやさしさの両方を、この社は受けとめてきました。"],"tl":[["伝・古代","神山（山宮）に神をまつったのが始まりと伝わる"],["864年","富士山の貞観大噴火。青木ヶ原溶岩が流れる"],["865年","今の場所に移されたと伝わる"],["10世紀","『延喜式』の神名帳に甲斐国八代郡の «浅間神社» が載る"],["戦国時代","武田氏があつく敬う"],["江戸時代","甲斐国一宮として幕府からも保護される"],["現在","毎年4月15日に大神幸祭（おみゆきさん）が続く"]],"who":[["木花開耶姫命","まつられている神。富士山の女神"],["武田信玄","甲斐の国主として一宮を敬ったと伝わる"],["甲府盆地の人々","おみゆきさんで水害よけを祈ってきた"]],"deep":["«甲斐国八代郡の浅間神社» が一宮浅間神社か、富士河口湖町の河口浅間神社かは、昔から議論があります。『延喜式』の «浅間神社» がどちらにあたるかも諸説あります。","摂社の山宮神社は神社のもとの鎮座地と伝わり、その本殿は国の重要文化財です。本社から少し山に入ったところにあります。","おみゆきさんの行き先・竜王の三社神社は、信玄が築いたと伝わる «信玄堤» のそばです。水の神を川の要所にお連れするこの祭りは、治水と信仰が一体だったことを示します。","一宮の周りには甲斐国分寺跡・国分尼寺跡があり、このあたりが古代甲斐の政治と信仰の中心地だったと考えられています。","境内のご神木や «夫婦梅» など、安産・縁結びにまつわる見どころも多く、今も地域の人の身近な神社です。"],"look":["拝殿と境内の森","摂社・山宮神社（本社から山手へ）","春の桃の花（3月下旬〜4月上旬）","4月15日の大神幸祭に出発する神輿"],"q":["一宮浅間神社から出発する «おみゆきさん» の神輿は、何を祈って出かける？","川の水害がないように祈ります。甲斐市竜王の三社神社まで往復約40kmを進みます。"],"koji":[],"myth":"865年に今の場所へ移った話や、『延喜式』の浅間神社がどこを指すかには諸説がある。","img":["木花咲耶姫","貞観大噴火","信玄堤"],"wp":"浅間神社 (笛吹市)","rel":{"ev":[],"grave":[]},"ph":[["c:e/ee/Asama-jinja_%28Fuefuki%29%2C_haiden-3.jpg",5568,3712,"浅間神社 (笛吹市)"],["c:7/74/YamamiyaP9130064.jpg",4288,3216],["c:3/39/Asama-jinja_%28Fuefuki%29%2C_torii.jpg",5566,3710],["c:c/c7/Asama-jinja_%28Fuefuki%29%2C_shinmon.jpg",5568,3712],["c:5/57/Asama-jinja_%28Fuefuki%29%2C_komochiishi.jpg",5554,3692],["c:c/c5/Asama-jinja_%28Fuefuki%29%2C_kaguraden.jpg",5568,3712],["c:5/55/Asama-jinja_%28Fuefuki%29%2C_honden.jpg",5562,3702],["c:f/f4/Asama-jinja_%28Fuefuki%29%2C_Shinmeisha.jpg",5568,3712]]},{"id":"19_kawaguchi_sengen","n":"河口浅間神社（富士山信仰の古社）","yomi":"かわぐちあさまじんじゃ","cat":"寺社","rank":"A","y":865,"era":["heian","edo"],"sh":"世界文化遺産「富士山」の構成資産","ad":"南都留郡富士河口湖町河口","st":"富士急行河口湖駅からバスで約15分","la":35.5239,"lo":138.764,"hook":"富士山が火をふいた翌年に建てられた «噴火しずめ» の社。樹齢千年をこえるといわれる七本の杉が、今も境内を守る。","lead":"河口湖の北岸にある古い神社です。864年の富士山の大噴火のあと、噴火をしずめるために建てられたと考えられています。巨大な «七本杉» や子どもが舞う «稚児の舞» で知られ、世界文化遺産「富士山」の一部になっています。","story":["864年、富士山が大きく火をふきました。赤い溶岩は北の «せの海» という大きな湖に流れこみ、湖は二つに分かれました。これが今の西湖と精進湖だといわれます。流れた溶岩の上には、長い年月をかけて森が育ちました。それが青木ヶ原の樹海です。ふもとの人々にとって、それは «この世の終わり» のような光景だったでしょう。","国の歴史書『日本三代実録』には、噴火の翌年、甲斐国八代郡に浅間明神をまつる社を建て、神官を置いたと記されています。«山の神をしずめなければ» という必死の祈りでした。その社が、ここ河口浅間神社だと考えられています。富士山と河口湖の間に立つこの神社は、まさに噴火の最前線でした。","境内に入ると、空をつくような杉の大木が目に飛びこみます。«七本杉» と呼ばれ、それぞれに名前がついています。樹齢は千年をこえるともいわれ、幹に手を当てると、噴火からの長い時間を感じるようです。«この木は、どれだけの人の祈りを見てきたのだろう?»","江戸時代になると、河口は富士山に登る人々の宿場町になりました。富士講の人々をむかえて泊め、お祈りをする «御師（おし）» の家が並び、にぎわいました。河口浅間神社は、そうした登山者たちが最初に手を合わせる場所でもありました。","春と夏の祭りでは、白い着物に花の冠をつけた少女たちが «稚児の舞» を舞います。古い神楽の形を伝える、県の無形民俗文化財です。2013年、この神社は富士山の世界文化遺産の一部になりました。火の山をおそれ、あがめてきた人々の心が、世界に認められたのです。"],"tl":[["864年","富士山の貞観大噴火。せの海が分かれ、青木ヶ原のもとができる"],["865年","甲斐国八代郡に浅間明神の社が建てられる（『日本三代実録』）"],["中世","富士山信仰の拠点として栄える"],["江戸時代","河口が富士講の人々を泊める御師の町としてにぎわう"],["2013年","世界文化遺産「富士山—信仰の対象と芸術の源泉」の構成資産に"]],"who":[["木花開耶姫命","まつられている富士山の女神"],["河口の御師たち","富士登山の人々を泊め、祈りを案内した"],["稚児の舞の少女たち","古い神楽を今に伝える担い手"]],"deep":["『日本三代実録』の «八代郡の浅間明神» が、この河口浅間神社か笛吹市の一宮浅間神社かは、長く議論されてきたテーマです。河口は噴火の現場に近く、有力な候補とされます。","七本杉は県の天然記念物で、«産屋杉»«父杉»«母杉» などの名がついています。樹齢は千年以上といわれますが、正確な年代はわかっていません。","稚児の舞（太々御神楽）は県の無形民俗文化財。少女が舞う神楽は全国的にも珍しく、古い形を残すと評価されています。","神社の奥の山中には «母の白滝» があり、富士登山の前に身を清める場所だったと伝わります。これも世界遺産の構成資産です。","河口は御坂峠をこえて甲府盆地から富士山へ向かう道の入口にあたり、江戸時代には多くの御師の家がありました。"],"look":["七本杉（とくに «産屋杉» の太さ）","拝殿と境内の森","母の白滝（神社から山道で）","湖の対岸から見る富士山"],"q":["864年の富士山の噴火で、溶岩が流れこんだ湖が分かれてできたといわれる湖は？","西湖と精進湖。もとは «せの海» という一つの大きな湖でした。"],"koji":[],"myth":"『日本三代実録』の社がこの神社を指すかは諸説。七本杉の樹齢は推定。","img":["貞観大噴火","青木ヶ原","富士山—信仰の対象と芸術の源泉"],"wp":"河口浅間神社","rel":{"ev":[],"grave":[]},"ph":[["c:d/d6/Kawaguchi-asama-jinja_haiden_and_sugi_%281%29.JPG",6016,4000,"河口浅間神社"],["c:a/a3/Kawaguchisengen_jinja_torii.JPG",4000,3000],["c:f/ff/Kawaguchi-asama-jinja_zuishinmon.jpg",6016,4000],["c:1/1e/Kawaguchi-asama-jinja_sugi_%287%29.JPG",4000,6016],["c:0/03/Kawaguchi-asama-jinja_sugi_%285%2C6%29.JPG",4000,6016],["c:8/8b/Kawaguchi-asama-jinja_sugi_%282%2C3%29.JPG",3808,5725],["c:1/12/Kawaguchi-asama-jinja_sandou.JPG",4000,6016],["c:c/c2/Kawaguchi-asama-jinja_honden.JPG",6016,4000]]},{"id":"19_kanazakura","n":"金櫻神社（御岳の古社）","yomi":"かなざくらじんじゃ","cat":"寺社","rank":"A","y":1300,"era":["heian","kamakura","edo"],"sh":"","ad":"甲府市御岳町","st":"JR甲府駅からバスで昇仙峡方面へ、そこからさらに車で約10分。車が便利","la":35.7516,"lo":138.5761,"hook":"奥秩父の霊峰・金峰山をあおぐ «御岳さん»。黄色い花をさかせる «鬱金の桜» を拝むと、お金に困らないと言われてきた。","lead":"昇仙峡の上、御岳の山里にある古い神社です。奥秩父の金峰山（きんぷさん）を神さまの山としてあおぎ、その «里宮» として栄えました。黄色がかった花をさかせる «鬱金の桜» と、神宝の水晶の玉で知られています。","story":["甲府の北にそびえる奥秩父の山々。その中でもひときわ高い金峰山の頂には、«五丈岩» という巨大な岩が天をさしています。昔の人は、この山に神が宿ると信じました。けれど頂上まで登るのは大変です。そこで山のふもとに «里宮» がつくられました。それが、御岳の金櫻神社です。","平安時代から、奈良の吉野にある金峯山と同じように、山で修行する修験者たちがこの地に集まったといわれます。«御岳さん» と呼ばれ、甲府盆地のあちこちから «御岳道» と呼ばれる参詣の道が何本ものびていました。人々は峠をこえ、谷を歩いて、はるばるお参りに来たのです。","神社の名前の «櫻» は、境内のご神木 «鬱金の桜（うこんのさくら）» から来ています。ふつうの桜より少しおそく、黄色みを帯びた花をさかせます。«金は金櫻、鬱金の桜を拝めば一生お金に困らない» という言い伝えがあり、今も春には花を見上げて手を合わせる人が絶えません。","この神社には、もうひとつの宝があります。神宝の水晶の玉です。御岳一帯は昔から水晶がとれる土地で、ここで生まれた水晶みがきの技は、やがて甲府に伝わり、今の «甲府の宝石・水晶細工» につながったといわれます。«山の神さまが、甲府に宝石の技をさずけた?» そう考えると、神社がぐっと身近になります。","昭和の中ごろには火事で社殿が焼けてしまいましたが、地元の人々の手で再建されました。長い石段を上り、朱色の社殿の前に立つと、山の冷たい空気が体を包みます。すぐ下の昇仙峡の渓谷美とあわせて、山の信仰の世界にふれられる場所です。"],"tl":[["伝・古代","金峰山を神の山とあおぎ、ふもとに社をまつったのが始まりと伝わる"],["平安〜鎌倉時代","修験者が集まり、金峰山信仰の拠点として栄えたといわれる"],["戦国時代","武田氏からも敬われたと伝わる"],["江戸時代","«御岳道» が整い、甲府盆地から多くの参詣者が訪れる"],["江戸〜明治","御岳の水晶みがきの技が甲府に伝わり、水晶細工の産業へ"],["1955年","火災で社殿が焼け、のちに再建される"]],"who":[["少彦名命ほか","まつられている神々"],["修験者（山伏）","金峰山で修行し、信仰を広めた"],["御岳の職人たち","水晶みがきの技を育てたといわれる"]],"deep":["金峰山の読みは «きんぷさん»。奈良の吉野の «金峯山（きんぷせん）» と同じく、蔵王権現をまつる修験道の山として栄えたといわれます。","甲府盆地から御岳へ向かう参詣道は «御岳道» と呼ばれ、«九筋» あったと伝わります。昇仙峡の渓谷沿いの道は、江戸時代の終わりに地元の人が切り開いたものです。","鬱金の桜は «うこん» の根のような黄色みのある花をつけるサトザクラの一種。ご神木の桜は何度か植え継がれてきたといわれます。","甲府の水晶細工は、御岳周辺でとれた水晶をみがいたことが始まりとされ、のちに宝飾品の町・甲府の土台になりました。","社殿の焼失後、宝物の一部は救い出されたと伝わり、神宝の水晶の玉 «火の玉» «水の玉» の話はその象徴として語られています。"],"look":["鬱金の桜（例年4月下旬〜5月ごろ）","長い石段と朱色の社殿","神宝の水晶にまつわる展示や説明","近くの昇仙峡・覚円峰の渓谷"],"q":["金櫻神社の «金は金櫻» の言い伝えで、何を拝むとお金に困らないと言われる？","ご神木の «鬱金の桜»。黄色みのある花をさかせる桜です。"],"koji":[],"myth":"創建年代、御岳道が九筋あった話、水晶の玉の由来は伝承を含む。社殿焼失の年（1955年）は確認を推奨。","img":["金峰山 (奥秩父)","昇仙峡","甲府の水晶"],"wp":"金櫻神社","rel":{"ev":[],"grave":[]},"ph":[["c:a/a5/Kanazakura_shrine_%E2%84%961.JPG",4000,3000,"金櫻神社"],["c:5/59/Kanazakura_shrine_%E2%84%962.JPG",4000,3000],["c:3/39/Kanazakura-jinja-1.jpg",3773,2977],["c:e/ee/Mt.Kimpu_from_Mt.Kitaokusenjodake_03.jpg",3888,2592],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:9/94/Kanazakura_shrine_1912.jpg",1280,960],["c:f/fb/Kinpu-gojoiwa.jpg",640,480],["c:c/cc/Kakuenpou_in_autumn.jpg",1167,1800,"昇仙峡"]]},{"id":"19_yunooku_kinzan","n":"湯之奥金山（中山金山ほかの甲斐金山）","yomi":"ゆのおくきんざん","cat":"産業","rank":"A","y":1560,"era":["muromachi","azuchi","edo"],"sh":"国指定史跡","ad":"南巨摩郡身延町湯之奥（博物館は身延町上之平）","st":"JR身延線下部温泉駅から歩いて約3分で湯之奥金山博物館。金山跡は険しい山道で、単独での入山はすすめられない","la":35.3869,"lo":138.448,"hook":"標高1500m近い山の中に、戦国の «金掘り» たちの村があった。武田の軍資金をささえたといわれる金山の記憶。","lead":"身延町の毛無山の山中にある、中山・内山・茅小屋の三つの金山のあとをまとめて «湯之奥金山» と呼びます。戦国時代を中心に金がほられ、甲斐の金はお金 «甲州金» にもなりました。発掘で見つかった品々は、ふもとの湯之奥金山博物館で見られます。","story":["富士山の西、静岡県との境に «毛無山» という山があります。その中腹、標高1500mに近い急な斜面に、いくつもの平らな段が階段のように並んでいます。ここは戦国時代の «金掘り» たちが暮らし、はたらいた場所。山の中に、ひとつの村があったのです。","金はどうやってとったのでしょう。まず、金を含む石をほり出します。それを石臼でこなごなにすりつぶし、水で洗って、重い金のつぶだけを残します。発掘では、石臼や、金をとかすための道具、住まいのあとなどがたくさん見つかりました。«こんな山奥で?» と思うほど、人々は熱心にはたらいていました。","戦国時代、甲斐は金がよくとれる国でした。武田信玄の強さのひみつのひとつは «金» だったといわれます。金は鉄砲や火薬を買い、兵を集めるためのお金になりました。湯之奥のあたりは、武田一族の穴山氏が治める土地で、金山ではたらく «金山衆» と呼ばれる人々がいました。","甲斐では、金を重さではかるだけでなく、形を決めたお金 «甲州金» が作られました。1両を4分、1分を4朱とする «4つずつ» の単位は、のちに江戸幕府のお金のしくみにも受けつがれたといわれます。«江戸のお金のルールの一部は甲斐生まれ?» そう思うと、山奥の金山が急に大きく見えてきます。","金がとれなくなると、金山は忘れられていきました。平成の初めに本格的な学術調査が行われ、1997年に国の史跡になりました。ふもとの博物館では、砂金とり体験もできます。皿をゆすって、小さな金のつぶが光った瞬間、戦国の金掘りたちの胸の高鳴りがわかるかもしれません。"],"tl":[["15世紀ごろ","このころから採掘が始まったと考えられている"],["16世紀","戦国時代、武田氏・穴山氏のもとで最盛期をむかえる"],["16世紀後半","甲斐で甲州金が作られ、流通する"],["江戸時代","採掘はしだいにおとろえる"],["1989〜1992年","中山金山などの本格的な学術調査が行われる"],["1997年","国指定史跡になる"]],"who":[["武田信玄","甲斐の金を軍資金にしたといわれる戦国大名"],["穴山信君（梅雪）","湯之奥を含む河内地方を治めた武田一族"],["金山衆","金山を開き、ほり、精錬した技術者集団"]],"deep":["中山金山では、平らにならした段（テラス）が数百か所確認され、そこに作業場や住まいがあったと考えられています。山の斜面に村がまるごとあったような姿です。","出土した «石臼» は、金を含む石をこなにするための道具。ほかに金をとかす «るつぼ» や «かわらけ» なども見つかり、ほり出しから精錬までを山の中で行っていたことがわかりました。","甲州金は «両・分・朱» の四進法で、この単位は江戸幕府の金貨の単位に受けつがれたとされます。甲州金には «碁石金» と呼ばれる丸い形のものもあります。","金山衆は武田氏の城攻めで、坑道をほって城の井戸をからすなどの土木作業にも動員されたといわれます。技術者は戦の道具でもありました。","甲斐の金山には湯之奥のほか、甲州市の黒川金山などがあり、«武田の隠し金» の伝説は今も語られますが、史料で確かめられたものではありません。"],"look":["湯之奥金山博物館の出土品と金山の模型","砂金とり体験","博物館から見る毛無山の山並み","近くの下部温泉（信玄の隠し湯と伝わる）"],"q":["甲州金の «1両» は何分？","4分です。1分は4朱で、この «4つずつ» の数え方は江戸幕府のお金にも受けつがれました。"],"koji":[],"myth":"採掘の始まりの時期は推定。«武田の隠し金» は伝説で史実ではない。","img":["甲州金","黒川金山","穴山信君"],"wp":"湯之奥金山","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:7/73/%E6%B9%AF%E4%B9%8B%E5%A5%A5%E9%87%91%E5%B1%B1%E8%B7%A1.JPG",2736,1824],["c:1/1a/Koshu1bu-zyu.jpg",160,160,"甲州金"],["c:a/a4/Anayama_Nobukimi.jpg",1935,1635,"穴山信君"]]},{"id":"19_kai_kokubunji","n":"甲斐国分寺跡","yomi":"かいこくぶんじあと","cat":"遺跡","rank":"A","y":745,"era":["nara","heian"],"sh":"国指定史跡","ad":"笛吹市一宮町国分","st":"JR石和温泉駅または山梨市駅から車で約10分","la":35.647,"lo":138.684,"hook":"奈良の都から «国を守る寺をつくれ» の命令がとどいた。畑の中に、七重の塔をささえた巨大な礎石がぽつんと残る。","lead":"奈良時代、聖武天皇の命令で国ごとに建てられた «国分寺» のひとつが、甲斐ではここにありました。建物は残っていませんが、七重塔の中心の柱をささえた大きな礎石（心礎）や、金堂・講堂のあとがわかります。1922年に国の史跡になりました。","story":["奈良時代の日本は、悩みごとだらけでした。病気の流行、ききん、地震、そして反乱。聖武天皇は «仏の力で国を守ろう» と考え、741年、国ごとに寺を建てるよう命じました。それが «国分寺» と «国分尼寺» です。甲斐国にも、その命令がとどきました。","甲斐の役人たちは、国の中心に近い、今の笛吹市一宮のあたりに寺を建てました。南に金堂、その後ろに講堂、そして東には高い七重の塔。塔の高さは、ほかの国の例から考えると数十メートルにもなったでしょう。まわりに高い建物などない時代、«あれが国分寺の塔だ» と遠くからでも見えたはずです。","けれど、その塔も寺も、長い年月の中で失われました。今、畑と住宅の間に残っているのは、塔の中心の柱をささえた大きな石 «心礎»。石の真ん中には、柱を立てるための穴があいています。«この上に七重の塔が立っていたの?» 石の前に立つと、見えない塔を見上げたくなります。","金堂や講堂のあった場所にも、礎石が並んでいます。発掘ではたくさんの瓦も見つかり、屋根が瓦でおおわれたりっぱな建物だったことがわかりました。国分寺の近くには、尼さんのための国分尼寺のあともあり、こちらも国の史跡です。二つの寺が、甲斐の国の祈りの中心でした。","あとには «護国山国分寺» という寺が法灯を受けつぎ、今も同じ土地で人々に親しまれています。すぐそばには甲斐国一宮浅間神社もあり、このあたりが古代甲斐の «心臓部» だったことを感じられます。桃の花の季節に歩くと、奈良の都の人々が思いえがいた «仏の国» の風景が、少しだけ見えてくるかもしれません。"],"tl":[["741年","聖武天皇が国分寺・国分尼寺の建立を命じる"],["8世紀中ごろ","甲斐国分寺が建てられたと考えられている"],["平安時代","しだいにおとろえる"],["1922年","国分寺跡が国指定史跡に"],["戦後","発掘調査で伽藍の配置が明らかになる"],["現在","跡地の一部は史跡公園として整備"]],"who":[["聖武天皇","国分寺建立の命令を出した天皇"],["甲斐国の国司","都から派遣され、国分寺の建設を進めた役人"],["光明皇后","聖武天皇の皇后。国分寺・国分尼寺の建立をすすめたといわれる"]],"deep":["伽藍は南から中門・金堂・講堂が一直線に並び、塔が東側に置かれる配置と考えられています。これは各地の国分寺によく見られる形です。","塔の心礎には柱をはめる穴があり、塔の規模を考える手がかりになります。国分寺の塔は七重とされるのが基本ですが、実際の高さは推定です。","国分尼寺跡は国分寺跡の東にあり、こちらも国指定史跡です。僧寺と尼寺がセットで残る例として貴重です。","甲斐国府（国の役所）の場所は、笛吹市春日居町説・御坂町説などがあり、はっきりしません。国分寺の位置は国府の場所を考える材料にもなっています。","出土した瓦の文様を調べると、ほかの国や都の寺とのつながりがわかります。瓦は古代の «ネットワーク» を読みとく手がかりです。"],"look":["七重塔の心礎","金堂・講堂の礎石","近くの甲斐国分尼寺跡","甲斐国一宮浅間神社とあわせて古代の中心地を歩く"],"q":["国分寺跡に残る «心礎» とは何？","塔の中心の柱（心柱）をささえた大きな礎石。七重塔が立っていた証拠です。"],"koji":[],"myth":"塔の高さや建立年代は推定。甲斐国府の所在地は諸説。","img":["国分寺","聖武天皇","甲斐国分尼寺"],"wp":"甲斐国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:c/cc/Kai-kokubunji_hondou.JPG",3642,2726,"甲斐国分寺"],["c:1/12/Kai_Kokubunji-ato%2C_toushinso.jpg",5568,3712],["c:2/2a/Kai_Kokubunji-ato%2C_tou.jpg",5562,3702],["c:9/94/Kai_Kokubunji-ato%2C_enkei-2.jpg",5568,3712],["c:b/b6/Kai_Kokubunji-ato%2C_chumon.jpg",5568,3712],["c:b/bc/Kai-kokubunniji-ato_koudou.JPG",3648,2736],["c:0/08/Kai-kokubunji_kuri.JPG",3648,2736],["c:f/fd/Kai-kokubunji-ato_koudou.JPG",3648,2736]]},{"id":"19_kinsei","n":"金生遺跡（縄文の配石遺構）","yomi":"きんせいいせき","cat":"遺跡","rank":"A","y":-1000,"era":["jomon"],"sh":"国指定史跡","ad":"北杜市大泉町谷戸","st":"JR小海線甲斐小泉駅から歩いて約20〜25分。車なら中央道長坂ICから約10分","la":35.868,"lo":138.42,"hook":"八ヶ岳のふもとに、縄文人が石を並べてつくった «祈りの広場» があった。焼かれたイノシシの子どもの骨が、何を語るのか。","lead":"八ヶ岳の南のふもとにある、縄文時代の終わりごろ（今から約4000〜2500年前）の遺跡です。石をたくさん並べた «配石遺構» が見つかり、お墓やお祭りの場だったと考えられています。1983年に国の史跡になり、一部が復元されています。","story":["1980年、八ヶ岳の南のふもとで田畑を整える工事をしていたところ、土の中から次々に石の列があらわれました。石は自然にころがっていたのではなく、明らかに人の手で並べられています。調査を進めると、長さ数十メートルにわたって石が帯のように続く、大きな «配石遺構» だとわかりました。","縄文時代の終わりごろ、このあたりに暮らした人々は、石を並べてお墓をつくり、そこで祈りをささげたと考えられています。石の中には、男性をかたどったような «石棒» や、まんまるな «丸石» もありました。«どうして石を並べたの?» 亡くなった人を思い、命がまためぐってくることを願ったのかもしれません。","ある穴からは、焼かれたイノシシの下あごの骨がたくさん見つかりました。その多くは子どものイノシシでした。«なぜ、子どものイノシシを?» 山の恵みがこれからも続くように、生まれた命を神にささげたのではないか、と考える研究者もいます。はっきりした答えはまだ出ていません。","この遺跡からは、中が空洞になった «中空土偶» も見つかりました。少しおどけたような表情の土偶は、縄文人の豊かな心を感じさせます。今では北杜市の考古資料館などで見ることができ、多くの人を楽しませています。","遺跡は «金生遺跡公園» として整備され、配石の一部や竪穴住居が復元されています。南アルプスと富士山、北には八ヶ岳。縄文人が見上げたのと同じ山々に囲まれて、石の広場に立ってみてください。3000年前の祈りの声が、風に乗って聞こえてくるようです。"],"tl":[["約4000年前","縄文時代後期、このころから人々が集まり配石がつくられる"],["約3000年前","縄文時代晩期にかけて祭りや墓の場として使われる"],["1980年","ほ場整備の工事中に発見され、発掘調査"],["1983年","国指定史跡になる"],["その後","遺跡公園として配石や住居が復元される"]],"who":[["八ヶ岳南麓の縄文人","石を並べて祈りの場をつくった人々"],["発掘調査にあたった研究者たち","配石遺構や土偶を掘りあて、記録した"]],"deep":["配石遺構は長さ数十メートルにおよび、石を組んだ墓（石棺状の墓）もふくまれます。墓地と祭りの場が一体になった «祈りの空間» と考えられています。","穴の中から見つかったイノシシの下あごの骨は、焼けたあとがあり、幼い個体が多いのが特徴です。儀礼との関係が議論されていますが、意味はわかっていません。","出土した中空土偶は縄文晩期のもので、国の重要文化財に指定されています。空洞につくる技術はむずかしく、作り手の高い技を示します。","丸石は山梨県内で道祖神としてまつられる «丸石信仰» との関係を考える人もいますが、縄文時代とのつながりは証明されておらず、推測の段階です。","八ヶ岳南麓は縄文時代中期に遺跡が集中する «縄文銀座» ですが、金生遺跡はそれより後の時代の祭祀遺跡として、縄文社会の変化を知る手がかりになります。"],"look":["復元された配石遺構","復元竪穴住居","遺跡から見る富士山・南アルプス・八ヶ岳","北杜市の考古資料館で出土品（中空土偶など）"],"q":["金生遺跡の穴から見つかった、焼けた骨は何の動物のもの？","イノシシ。それも子どもの下あごの骨が多く見つかりました。儀礼に使われたと考えられています。"],"koji":[],"myth":"配石やイノシシの骨の意味は研究者の推測で、確定していない。","img":["配石遺構","土偶","八ヶ岳"],"wp":"金生遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:6/6d/Kinsei_iseki.JPG",3072,2304,"金生遺跡"],["c:1/1c/%E9%87%91%E7%94%9F%E9%81%BA%E8%B7%A1%E9%85%8D%E7%9F%B3%E9%81%BA%E6%A7%8B.JPG",5184,3456],["c:9/93/%E9%87%91%E7%94%9F%E9%81%BA%E8%B7%A1%E5%BE%A9%E5%85%83%E4%BD%8F%E5%B1%85%E3%81%A8%E9%85%8D%E7%9F%B3%E9%81%BA%E6%A7%8B.JPG",5184,3456],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:3/38/Tsukiyono_Fukasawa_Archaeological_site_2.jpg",4608,3456,"配石遺構"],["j:3/3d/%E9%9D%92%E6%A3%AE%E7%9C%8C%E3%81%A4%E3%81%8C%E3%82%8B%E5%B8%82%E6%9C%A8%E9%80%A0%E4%BA%80%E3%83%B6%E5%B2%A1%E5%87%BA%E5%9C%9F_%E9%81%AE%E5%85%89%E5%99%A8%E5%9C%9F%E5%81%B6-2.JPG",3711,4947,"土偶"],["c:3/38/Minami-Yatsugatake_from_Mt.Kitayokodake_05.jpg",2081,1000,"八ヶ岳"]]},{"id":"19_umenoki","n":"梅之木遺跡（茅ヶ岳西麓の縄文ムラ）","yomi":"うめのきいせき","cat":"遺跡","rank":"A","y":-3000,"era":["jomon"],"sh":"国指定史跡","ad":"北杜市明野町浅尾","st":"JR韮崎駅から車で約20分。公共交通では行きにくい","la":35.798,"lo":138.46,"hook":"縄文人は谷底の川まで «道» をつくって水をくみに行った。5000年前のムラと、その通い道がまるごと見つかった遺跡。","lead":"北杜市明野町の、茅ヶ岳のふもとの台地にある縄文時代中期（今から約5000〜4500年前）のムラのあとです。たくさんの竪穴住居が輪のように並び、さらに谷の川へ下りていく «道» のあとも見つかりました。2014年に国の史跡になりました。","story":["山梨県の北西部、八ヶ岳と茅ヶ岳にはさまれた一帯は、縄文時代の遺跡がとても多い場所です。とくに約5000年前の縄文時代中期には、あちこちに大きなムラがありました。梅之木遺跡もそのひとつ。茅ヶ岳の西のふもと、日当たりのよい台地の上に人々が暮らしていました。","発掘すると、竪穴住居のあとが、広場を囲むように輪になって並んでいることがわかりました。その数は百数十軒。もちろん、全部が同時に建っていたわけではなく、何百年もの間に建てかえをくり返した結果です。«ひとつの場所に、そんなに長く暮らし続けたの?» 縄文人にとって、ここはよほど住みやすい土地だったのでしょう。","この遺跡でいちばん話題になったのは «道» の発見です。ムラから台地の下を流れる湯沢川へ向かって、地面がくぼんだ細い筋がのびていました。人が何度も何度も歩いたために、ふみ固められた跡だと考えられています。縄文人は毎日この道を通って、水をくみに行ったのでしょう。","想像してみてください。土器をかかえた子どもたちが、坂道をかけおりて川へ向かう姿を。ドングリを水にさらしたり、魚をとったり、洗いものをしたり。«道» が見つかったことで、ムラの暮らしが一気に生き生きと見えてきたのです。","今、遺跡は公園として整備され、竪穴住居が復元されています。体験イベントでは、縄文土器づくりや火おこしにも挑戦できます。北に八ヶ岳、南に富士山。5000年前の人々が見た空の下で、ムラの輪の中に立ってみましょう。"],"tl":[["約5500年前","縄文時代中期の初めごろ、ムラが営まれ始める"],["約5000〜4500年前","環状に住居が並ぶ大きなムラとして栄える"],["2000年代","本格的な発掘調査で住居群と «道» のあとが見つかる"],["2014年","国指定史跡になる"],["その後","史跡公園として竪穴住居などが復元される"]],"who":[["茅ヶ岳西麓の縄文人","長い年月このムラで暮らした人々"],["北杜市の調査担当者たち","ムラの全体と «道» のあとを明らかにした"]],"deep":["住居が円形の広場を囲む «環状集落» は、縄文中期の中部高地に多い形です。広場の中央部には墓などがあったと考えられています。","見つかった «道» は、台地から谷底の湯沢川へ下る斜面にあり、縄文時代の通路の跡がはっきり残る例は全国でも少なく、とても貴重です。","住居跡の数は百数十軒と報告されていますが、同時に建っていたのはその一部です。ムラの人口を推定するには、時期ごとの住居の数を分けて考える必要があります。","このあたりの縄文中期の土器は «井戸尻式» などと呼ばれる、立体的でにぎやかな飾りを持つものが多く、豊かな精神世界を感じさせます。","遺跡の名前のもとになった土地のすぐ近くには、戦国時代の «明野» の開発や、近代の «明野のひまわり畑» など、時代ごとの人の営みが重なっています。"],"look":["環状に並ぶ住居のあと（平面表示）","復元された竪穴住居","湯沢川へ下る «縄文の道» のあと","晴れた日の富士山と八ヶ岳の眺め"],"q":["梅之木遺跡で見つかった、全国でもめずらしい縄文時代のあととは？","ムラから谷底の川へ下りる «道» のあと。人が何度も歩いてできたと考えられています。"],"koji":[],"myth":"住居の軒数や道の用途は調査に基づく推定。遺跡の立地は八ヶ岳南麓というより茅ヶ岳西麓。","img":["環状集落","茅ヶ岳","縄文時代"],"wp":"梅之木遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:c/c6/Umenoki_Site.jpg",2048,1365,"梅之木遺跡"],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:5/54/Fujimi_Mizukokaiduka_Park_3.JPG",3264,2448,"環状集落"],["c:4/45/Kayagatake.jpg",1112,821,"茅ヶ岳"]]},{"id":"19_yato_jo","n":"谷戸城（逸見清光・甲斐源氏の城）","yomi":"やとじょう","cat":"城","rank":"A","y":1140,"era":["heian","muromachi"],"sh":"国指定史跡","ad":"北杜市大泉町谷戸","st":"JR小海線甲斐小泉駅から歩いて約20分。中央道長坂ICから車で約10分","la":35.8632,"lo":138.4118,"hook":"都を追われた源氏の親子が、八ヶ岳のふもとで再出発した。武田信玄の «ひいひいひい…おじいさん» が住んだといわれる城。","lead":"八ヶ岳の南のふもと、«城山» と呼ばれる小さな山を丸ごと城にした場所です。平安時代の終わり、甲斐源氏の祖の一人・逸見清光（へみ きよみつ）がここを本拠にしたと伝わります。のちの武田氏は、この清光の子孫です。","story":["平安時代の終わり、1130年ごろのことです。常陸国（今の茨城県）にいた源義清と、その子の清光が、争いを起こした罪で甲斐国へ流されました。«遠い山国で、源氏の名はここで終わるのか» ——親子はそう思ったかもしれません。ところが、ここから新しい歴史が始まります。","清光は、八ヶ岳のふもとの «逸見（へみ）» という土地に根をおろし、«逸見清光» と名乗りました。そして本拠にしたと伝わるのが、この谷戸城です。平らな大地にぽこりと盛り上がった小山をけずって、いくつもの平らな段（郭）をつくり、堀と土塁でまもりを固めました。","清光にはたくさんの子どもがいました。武田信義、加賀美遠光、安田義定……。彼らは甲斐のあちこちに散らばって勢力を広げ、«甲斐源氏» と呼ばれる強い武士団になりました。やがて源平合戦では、源頼朝と手を組んで平氏と戦います。そのうちの武田信義の家系が、のちの武田信玄につながるのです。","«信玄のご先祖が、ここから出発した?» そう思って城山に登ると、見える景色がちがってきます。頂上からは甲府盆地の方角、そして富士山や南アルプスが見わたせます。清光も、この景色をながめながら «いつか甲斐をひとつにしたい» と夢を描いたのでしょうか。","谷戸城はその後も戦国時代まで使われたと考えられています。今は国の史跡として整備され、ふもとの «谷戸城ふるさと歴史館» では、出土品や城の模型を見ることができます。小さな山ですが、日本の武士の歴史にとって大きな意味をもつ場所です。"],"tl":[["1130年","源義清・清光の親子が常陸国から甲斐国へ流される"],["12世紀中ごろ","逸見清光が逸見の地を本拠とし、谷戸城に住んだと伝わる"],["1180年","清光の子・武田信義らが源平合戦で挙兵"],["戦国時代","城として改修されながら使われたと考えられる"],["1993年","国指定史跡になる"],["現在","ふもとに谷戸城ふるさと歴史館"]],"who":[["逸見清光（源清光）","甲斐源氏の祖の一人。谷戸城を本拠にしたと伝わる"],["源義清","清光の父。親子で甲斐へ流された"],["武田信義","清光の子。武田氏の祖"],["安田義定","清光の子と伝わる。源平合戦で活躍"]],"deep":["義清・清光の配流は、公家の日記『長秋記』に記録があるとされ、甲斐源氏の始まりを語るうえで重要な手がかりです。","城山は標高約860mで、ふもととの高さの差は数十メートルほど。独立した小山を利用し、頂上の一の郭から段々に郭を配置した «輪郭式» に近い形です。","現在見られる堀や土塁は、戦国時代に改修された姿と考えられており、清光の時代そのままではありません。どこまでが平安時代の遺構かは議論があります。","清光の本拠については、谷戸城のほかに «若神子» とする説などもあり、はっきりしません。谷戸城は «清光の城と伝わる» 城です。","近くには縄文時代の金生遺跡があり、同じ «谷戸» の地に数千年を隔てた二つの国史跡が並んでいます。"],"look":["城山の頂上（一の郭）からの眺め","郭を区切る堀と土塁","谷戸城ふるさと歴史館の城の模型と出土品","近くの金生遺跡"],"q":["逸見清光の子どもで、武田氏の祖となったのはだれ？","武田信義。この家系が戦国時代の武田信玄につながります。"],"koji":[],"myth":"清光が谷戸城に住んだことは伝承。現在の遺構の多くは戦国期の改修とみられる。","img":["源清光","武田信義","甲斐源氏"],"wp":"谷戸城","rel":{"ev":[],"grave":[]},"ph":[["c:d/d3/%E8%B0%B7%E6%88%B8%E5%9F%8E%E8%B7%A1.jpg",5472,3648,"谷戸城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:8/84/Takeda_Nobuyoshi.jpg",1214,1467,"武田信義"]]},{"id":"19_wakamiko","n":"若神子城（天正壬午の乱の北条本陣）","yomi":"わかみこじょう","cat":"城","rank":"A","y":1582,"era":["heian","azuchi"],"sh":"","ad":"北杜市須玉町若神子","st":"JR韮崎駅から車で約15分。中央道須玉ICから車で約5分","la":35.803,"lo":138.44,"hook":"本能寺の変のあと、武田の旧領をめぐって北条と徳川がにらみ合った。4万の北条軍が陣をしいたのが、この丘だといわれる。","lead":"北杜市須玉町の丘の上にある城あとです。平安時代の源氏・新羅三郎義光（しんらさぶろう よしみつ）の館と伝わりますが、有名なのは1582年の «天正壬午の乱»。北条氏直の大軍がここに本陣を置き、新府城の徳川家康と向かい合いました。","story":["1582年3月、武田氏がほろびました。甲斐は織田信長の家臣が治めることになります。ところがわずか3か月後の6月、京都で本能寺の変が起こり、信長が倒れます。甲斐と信濃は、とつぜん «主のいない土地» になりました。«今こそ手に入れるチャンスだ!» 周りの大名がいっせいに動き出します。","関東からは北条氏直が大軍をひきいて信濃を通り、甲斐に入ってきました。その数は4万ともいわれます。いっぽう東海道からは徳川家康が甲斐へ。家康の兵は1万ほどと少なかったといわれます。北条軍は若神子に、家康は勝頼が築いた新府城に陣をしき、両軍はわずか数kmをはさんでにらみ合いました。","«数では北条が圧倒的。なのに、なぜ北条は攻めなかったのか?» 家康は武田の旧臣たちを味方につけ、地元の地理をよく知る彼らの力で北条軍の補給を苦しめました。8月には、別の北条軍が甲斐の東の黒駒で徳川方に敗れます。大軍ほど、食べ物や道の確保がむずかしくなるのです。","にらみ合いは80日ほど続き、10月末、ついに和睦が結ばれました。甲斐と信濃は徳川、上野（群馬県）は北条。そのしるしに、家康の娘・督姫が氏直に嫁ぐことになりました。この戦いで家康は大きく領地を広げ、のちの «天下人・家康» への道を固めたのです。","若神子城のあとは今 «若神子城ふるさと公園» となり、戦国時代の «のろし台» が復元されています。丘の上から新府城の方角をながめると、4万の兵がひしめき、相手の動きを息をひそめて見つめていた夏の日の緊張が伝わってくるようです。"],"tl":[["平安時代後期","新羅三郎義光の館があったと伝わる"],["1582年3月","武田氏がほろびる"],["1582年6月","本能寺の変。甲斐・信濃が混乱に"],["1582年8月","北条氏直が若神子に本陣を置き、家康は新府城に入る。黒駒で北条軍が敗れる"],["1582年10月","北条と徳川が和睦。甲斐・信濃は徳川の領地に"],["現在","若神子城ふるさと公園として整備"]],"who":[["北条氏直","北条氏の当主。若神子に本陣を置いた"],["徳川家康","新府城に陣をしき、北条軍と対峙した"],["督姫","家康の娘。和睦のしるしに氏直に嫁いだ"],["新羅三郎義光（源義光）","甲斐源氏の祖。館があったと伝わる"]],"deep":["«天正壬午の乱» の名は、1582年が干支で «壬午（みずのえうま）» にあたることから。近年の研究で、戦国史の大きな転換点として注目されるようになった戦いです。","両軍の兵数は史料によって異なり、北条軍4万余・徳川軍1万ほどという数字がよく語られますが、正確ではありません。","若神子城は «北城・南城・古城» などに分かれた城域をもつとされ、北条軍の本陣はこの城を中心に周囲に広がっていたと考えられます。","和睦の条件をめぐっては、上野の沼田領をどうするかでもめ、のちに真田氏と北条氏の対立、さらには豊臣秀吉による小田原征伐へとつながっていきます。","復元されたのろし台は、武田氏が甲斐と信濃に張りめぐらせた «のろしのネットワーク» をしのぶものです。のろしで情報を早く伝える仕組みは戦国大名の武器でした。"],"look":["復元されたのろし台","丘の上からの新府城方面の眺め","城域の空堀のあと","七里岩の台地（新府城）とあわせて両軍の位置関係を歩く"],"q":["天正壬午の乱の和睦のしるしとして、家康の娘・督姫はだれに嫁いだ？","北条氏直。甲斐・信濃は徳川、上野は北条という形で手打ちになりました。"],"koji":[],"myth":"義光の館の話は伝承。兵数は諸説。城の指定区分は未確認。","img":["天正壬午の乱","北条氏直","新府城"],"wp":"若神子城","rel":{"ev":[],"grave":[]},"ph":[["c:4/44/Wakamiko_castle_01.jpg",5184,3456,"若神子城"],["c:6/6f/Wakamiko_castle_02.jpg",5184,3456],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:2/2c/Hojo_Ujinao.jpg",466,745,"北条氏直"],["c:7/7e/Shinpu_Castle.jpg",2048,1536,"新府城"]]},{"id":"19_yamura_jo","n":"谷村城（郡内・秋元氏の陣屋）","yomi":"やむらじょう","cat":"城","rank":"A","y":1633,"era":["muromachi","edo"],"sh":"","ad":"都留市上谷","st":"富士急行谷村町駅から歩いて約5分","la":35.552,"lo":138.905,"hook":"天守も石垣もない «城»。けれどここの殿さまは用水を引き、織物をすすめ、俳人・芭蕉までこの町にやって来た。","lead":"富士山の北東、«郡内（ぐんない）» と呼ばれる地域の中心・都留市にあった城（陣屋）のあとです。戦国時代は小山田氏、江戸時代の初めは秋元氏が治めました。建物は残っていませんが、城下町の町割りや用水路に当時の面影があります。","story":["山梨県は、昔から二つの地域に分けて語られます。甲府盆地の «国中（くになか）» と、富士山の北東の山あいの «郡内»。山にへだてられた郡内は、言葉も暮らしも国中とは少しちがっていました。その郡内の中心が、今の都留市・谷村です。","戦国時代、郡内を治めたのは小山田氏でした。武田氏の家臣でありながら半ば独立した力をもち、谷村に館を構えたといわれます。1582年、織田軍に追われた武田勝頼は、小山田信茂の岩殿城をたよりましたが、信茂は勝頼を受け入れませんでした。武田家の最期を決めた出来事のひとつです。","江戸時代に入り、1633年に秋元泰朝（やすとも）が谷村の殿さまになります。秋元氏は3代およそ70年にわたってこの地を治めました。山あいで田んぼの少ない郡内のため、秋元氏は用水路を整え、蚕を育てて絹を織る仕事をすすめたと伝わります。のちに «郡内織» «甲斐絹» と呼ばれる織物の土台がここで育ちました。","1683年、ひとりの俳人がこの町をたずねます。松尾芭蕉です。前の年の江戸の大火で住まいの芭蕉庵を失った芭蕉は、秋元家の家老で弟子でもあった高山麋塒（びじ）をたより、谷村でしばらく暮らしました。«江戸を焼け出された芭蕉が、山の城下町で何を思ったのか?» 町には今も芭蕉ゆかりの碑が立っています。","1704年、秋元氏が川越へ移ると、谷村は幕府の領地となり、城は陣屋として使われました。今、城あとは市街地の中にあり、石碑が往時を伝えます。町の中を流れる用水 «家中川（かちゅうがわ）» のせせらぎに耳をすませば、城下町の暮らしの音が聞こえてくるようです。"],"tl":[["戦国時代","小山田氏が谷村に館を構えたといわれる"],["1582年","小山田信茂が武田勝頼を受け入れず、武田氏滅亡"],["1633年","秋元泰朝が谷村の領主となる"],["1683年","松尾芭蕉が谷村に滞在する"],["1704年","秋元氏が川越へ移り、谷村は幕府領に"],["江戸時代中期以降","谷村陣屋が置かれ、郡内を治める拠点となる"]],"who":[["小山田信茂","戦国時代の郡内の領主。最後に勝頼を見放した"],["秋元泰朝","谷村の初代秋元家当主。郡内の開発を進めた"],["松尾芭蕉","江戸の大火のあと谷村に身を寄せた俳人"],["高山麋塒","秋元家の家老で芭蕉の弟子。芭蕉を谷村にまねいた"]],"deep":["«郡内» は甲斐国都留郡のこと。国中とは笹子峠や御坂峠でへだてられ、江戸との結びつきが強い地域でした。","秋元氏が開いたと伝わる用水は «家中川» と呼ばれ、今も市街地を流れています。水車の動力としても使われ、織物業をささえました。","谷村城には天守や高い石垣はなく、館を中心とした平城でした。郡内の城としては、勝頼が頼ろうとした大月の岩殿城のほうが «要害» として有名です。","芭蕉の谷村滞在の期間は数か月とされますが、細かい日付は確かではありません。この経験が、のちの旅の俳諧につながったと考える人もいます。","秋元氏はその後、川越・山形・館林と移りましたが、谷村での経験は «殖産興業の藩» としての性格を育てたともいわれます。"],"look":["谷村城跡の碑","町を流れる家中川","芭蕉ゆかりの碑","都留市郷土資料館の展示"],"q":["江戸の大火で家を失い、1683年に谷村に身を寄せた俳人は？","松尾芭蕉。秋元家の家老で弟子の高山麋塒をたよりました。"],"koji":[],"myth":"秋元氏の織物奨励や家中川開削は伝承的要素を含む。芭蕉の滞在期間は諸説。","img":["秋元泰朝","松尾芭蕉","小山田信茂"],"wp":"谷村城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:d/d4/Akimoto_Yasutomo.JPG",2892,5340,"秋元泰朝"],["c:c/ca/Basho_by_Morikawa_Kyoriku_%281656-1715%29.jpg",512,854,"松尾芭蕉"]]},{"id":"19_katsunuma_yakata","n":"勝沼氏館（武田一族の館跡）","yomi":"かつぬましやかた","cat":"大名屋敷","rank":"A","y":1535,"era":["muromachi"],"sh":"国指定史跡","ad":"甲州市勝沼町勝沼","st":"JR勝沼ぶどう郷駅から車で約10分","la":35.6627,"lo":138.7355,"hook":"ぶどう畑の中に、武田一族の館がまるごと眠っていた。主人は信玄のおじ、そしてその子は信玄に討たれた。","lead":"甲州市勝沼の日川（ひかわ）の崖の上にある、戦国時代の武田一族・勝沼氏の館あとです。堀や土塁、門のあとがよく残り、1981年に国の史跡になりました。館の主は武田信虎の弟・勝沼信友と、その子の信元です。","story":["甲州市勝沼の町は、ぶどう畑に囲まれています。その一角、日川の深い谷に面した崖の上に、ひっそりと館のあとが広がっています。ここはかつて、武田家の一族 «勝沼氏» の屋敷でした。甲府盆地の東の入口をおさえる、大切な場所です。","館を構えたのは、武田信虎の弟・勝沼信友でした。信友は兄の信虎をささえ、甲斐の東の守りをまかされていました。けれど1535年、北条氏との戦いで命を落とします。館を継いだのは子の信元。信元にとって信玄は «いとこ» にあたります。","1560年、事件が起こります。信元が、敵である上杉方と通じていたという疑いをかけられ、信玄によって討たれたのです。«一族なのに、なぜ?» 戦国時代、身内の裏切りは家をほろぼす一番の危険でした。信玄は疑いが出た時点で、きびしく処分したのです。勝沼氏の館は、この事件のあと主を失いました。","それから400年以上、館のあとは畑の下に眠っていました。昭和の後半、ここに施設をつくる計画が持ち上がり、事前の発掘調査が行われます。すると、堀や土塁、建物の礎石、井戸、そして生活の道具が次々と見つかりました。«これは残すべきだ» という声が高まり、計画は変わって、館は国の史跡として守られることになりました。","今、館あとは復元された門や土塁とともに公開されています。内側の «内郭» には建物の配置が示され、戦国の武家の暮らしを思い描くことができます。すぐ外には、ぶどう畑。500年前の悲劇と、今の豊かな実りが、同じ土地の上に重なっています。"],"tl":[["16世紀初め","勝沼信友が勝沼に館を構える"],["1535年","勝沼信友が北条氏との戦いで戦死"],["1560年","勝沼信元が上杉方と通じた疑いで信玄に討たれる"],["昭和40年代後半","施設建設の計画にともなう発掘で館の遺構が見つかる"],["1981年","国指定史跡になる"],["その後","門や土塁が復元され、史跡公園として公開"]],"who":[["勝沼信友","武田信虎の弟。館を構え、甲斐の東を守った"],["勝沼信元","信友の子。信玄に討たれた"],["武田信玄","いとこの信元を謀反の疑いで処罰した"],["武田信虎","信友の兄。信玄の父"]],"deep":["館は日川の崖を背にし、残る三方を堀と土塁で囲んだ «方形館» に近い形です。内郭と外郭に分かれ、内郭からは主殿や台所と考えられる建物跡が見つかっています。","出土品には陶磁器や鍛冶・金属加工の道具などがあり、館の中で生活と生産の両方が営まれていたことがわかりました。","勝沼信元の処罰の理由は、上杉氏との内通とされますが、くわしい事情はよくわかっていません。『甲陽軍鑑』などの記述は後世の編さんで、注意して読む必要があります。","信元の処罰後、勝沼の地は武田氏の直轄に近い形になったと考えられ、館の一部は改修されて使われ続けた可能性があります。","勝沼は甲州街道の宿場でもあり、館は街道と甲府盆地の東の出入口をおさえる位置にあります。のちの柏尾の戦いの場所もすぐ近くです。"],"look":["復元された門と土塁","内郭の建物配置の表示","日川の崖（館の守りの要）","周辺のぶどう畑と勝沼宿"],"q":["勝沼氏館の主・勝沼信友は、武田信玄から見てどんな関係？","おじ（父・信虎の弟）です。その子の信元は信玄のいとこでした。"],"koji":[],"myth":"信元処罰の理由は諸説。発掘のきっかけとなった計画の詳細は確認を推奨。","img":["勝沼信友","武田信虎","甲州市"],"wp":"勝沼氏館","rel":{"ev":[],"grave":[]},"ph":[["c:4/42/Katsunumashi_yakataato-1.jpg",4496,3000,"勝沼氏館"],["c:0/0d/Katsunumashi_yakataato-4.jpg",4496,3000],["c:2/28/Katsunumashi_yakataato-3.jpg",4496,3000],["c:4/4a/Katsunumashi_yakataato-2.jpg",4496,3000],["c:f/fe/%E5%8B%9D%E6%B2%BC%E6%B0%8F%E9%A4%A8.jpg",1280,960],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:f/fc/Takeda_Nobutora_by_Takeda_Nobukado_%28Daisenji_Kofu%29.jpg",358,864,"武田信虎"],["c:1/1e/Marufuji_Winery_190907f.jpg",4496,3000,"甲州市"]]},{"id":"19_kofu_kinban","n":"甲府勤番（旗本の「山流し」）","yomi":"こうふきんばん","cat":"大名屋敷","rank":"A","y":1724,"era":["edo"],"sh":"国指定史跡（甲府城跡）","ad":"甲府市丸の内（甲府城跡・舞鶴城公園）","st":"JR甲府駅から歩いて約5分","la":35.6627,"lo":138.5692,"hook":"«甲府行きを命ず» ——江戸の旗本たちが恐れた «山流し»。けれど彼らは、この山国に学問と記録を残していった。","lead":"江戸時代の中ごろから幕末まで、幕府の直接の領地になった甲府を守るために置かれた役職と、その組織が «甲府勤番» です。江戸から旗本たちが送られ、甲府城に勤めました。«山流し» と呼ばれて嫌われましたが、学問所や地誌など大きな文化も生みました。","story":["1724年、甲府の殿さまだった柳沢吉里（柳沢吉保の子）が、大和郡山（奈良県）へ移ることになりました。甲斐国は幕府が直接治める土地になります。江戸から近く、西の守りでもある甲府城。幕府はここに旗本を送りこみ、城と町を守らせることにしました。これが «甲府勤番» の始まりです。","ところが、この仕事は江戸の旗本たちにとても不人気でした。«甲府勤番を命ず» と言われると、«ああ、山流しか» とため息をついたといいます。江戸のにぎやかな暮らしから、山に囲まれた甲府へ。しかも一度行くと、なかなか江戸へもどれません。«素行の悪い旗本が送られる» といううわさまで立ちました。","けれど、ここで腐らなかった人々もいます。勤番士の野田成方は、甲府の風俗や伝説を書きとめた『裏見寒話』を著しました。«山流し» で見た甲斐の暮らしを、好奇心いっぱいに記録したのです。«せっかく来たのなら、この国をよく知ってやろう»。そんな気持ちが伝わってきます。","江戸時代の後半には、甲府勤番の役人たちの手で学問所 «徽典館» が開かれ、甲斐の若者たちも学ぶようになりました。さらに勤番のトップ（勤番支配）だった松平定能は、甲斐国の歴史・地理・寺社・人物をまとめた大著『甲斐国志』を編みました。今も山梨の歴史研究に欠かせない本です。","1868年、新政府軍が甲府城に入り、甲府勤番の歴史は終わりました。城は明治以降に多くの建物を失いましたが、石垣は今も見事に残り、稲荷櫓などが復元されています。天守台に登って甲府の町を見下ろせば、«山流し» の旗本たちが見た景色と、彼らが残した文化の重みを感じられるでしょう。"],"tl":[["1704年","柳沢吉保が甲府藩主となる"],["1724年","柳沢吉里が大和郡山へ移り、甲斐は幕府領に。甲府勤番が置かれる"],["18世紀中ごろ","勤番士・野田成方が『裏見寒話』を著す"],["1796年","甲府に学問所がつくられる（のちの徽典館）"],["1814年","勤番支配・松平定能らによる『甲斐国志』が完成"],["1868年","新政府軍が甲府城に入り、甲府勤番の時代が終わる"]],"who":[["柳沢吉里","甲府最後の藩主。大和郡山へ移った"],["野田成方","甲府勤番士。『裏見寒話』の著者"],["松平定能","甲府勤番支配。『甲斐国志』の編さんを進めた"],["板垣退助","1868年、新政府軍をひきいて甲府城に入った"]],"deep":["甲府勤番は «勤番支配» 2人をトップに、大手組・山手組の2組に分かれ、それぞれに組頭や勤番士が所属したとされます。人数は時期によってちがいます。","«山流し» は旗本の間の俗なことばで、実際に左遷や懲罰の意味で任命された例もあったといわれますが、全員がそうだったわけではありません。","『甲斐国志』は全120巻余りにおよぶ地誌で、村ごとの記録や古文書の写しを含み、甲斐の歴史を知る基本史料です。","1836年の天保騒動では、一揆の群衆が甲府に迫り、甲府勤番は十分に鎮めることができず、近隣の藩の出兵をあおぎました。幕府の支配の弱さが表れた事件です。","甲府城跡は2019年に国の史跡に指定されました。石垣は豊臣政権期の築城にさかのぼる部分があるとされ、野面積みの古い石垣も見られます。"],"look":["甲府城の天守台と石垣","復元された稲荷櫓と山手門","城の周りの «丸の内» の地名（武家地のなごり）","県立博物館などで『甲斐国志』関連の展示"],"q":["甲府勤番支配・松平定能らがまとめた、甲斐国の大きな地誌の名前は？","『甲斐国志』。1814年に完成し、今も山梨の歴史研究に欠かせません。"],"koji":[{"w":"山流し","m":"江戸の旗本が甲府勤番を命じられること。都から遠い山国へ送られることを嘆いたことば"}],"myth":"«素行の悪い旗本が送られた» というのは一面の話で、うわさも含む。","img":["甲府城","甲斐国志","柳沢吉里"],"wp":"甲府勤番","rel":{"ev":["k_koshu"],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:3/3b/Koufu_Castle_%284936837377%29.jpg",1280,853,"甲府城"],["c:9/95/Lake_Kawaguchiko_Sakura_Mount_Fuji_3.JPG",3872,2592,"近く: 山梨県"],["c:1/17/Kofu_montage.jpg",1186,1568,"近く: 甲府市"],["c:7/73/Kofu_district_court.JPG",4000,3000,"近く: 甲府地方裁判所"],["c:c/cf/Okajima_20240630.png",2560,1920,"近く: 岡島 (百貨店)"],["c:4/4a/KOKORI_at_Kofu_city.JPG",3000,4000,"近く: 山梨県立宝石美術専門学校"],["c:f/ff/Kofu_Police_Station_20241130.jpg",3024,2271,"近く: 甲府警察署"]]},{"id":"19_tenpo_sodo","n":"天保騒動（甲州一揆・犬目の兵助）","yomi":"てんぽうそうどう","cat":"事件","rank":"A","y":1836,"era":["edo"],"sh":"","ad":"上野原市犬目（兵助ゆかりの地）ほか甲斐国各地","st":"JR四方津駅または鳥沢駅から車で約10分（犬目）","la":35.6285,"lo":139.0125,"hook":"米が買えない。子どもが飢える。郡内の百姓たちが立ち上がった一揆は、やがて甲斐一国をゆるがす大騒動になった。","lead":"1836年（天保7年）、ききんで米の値段がはね上がる中、甲斐国の郡内地方の百姓たちが起こした一揆です。はじめは米の安売りを求める行動でしたが、甲府盆地に広がると大きな打ちこわしになり、甲府にまでせまりました。リーダーの一人が犬目村の兵助です。","story":["天保のききんは、日本中を苦しめました。冷たい夏が続き、米がとれません。山あいで田んぼの少ない郡内の人々は、甲府盆地などから米を買って暮らしていました。ところが米の値段はどんどん上がり、しかも一部の商人が米を買い占めている、といううわさが流れます。«このままでは、みんな飢え死にだ»。","1836年8月、郡内の下和田村の武七と、犬目村の兵助らが中心となって人々が立ち上がりました。めざしたのは、笹子峠をこえた国中にいる米商人です。«米を安く売ってくれ»。はじめは、あくまで話し合いと要求のための行動でした。","ところが、峠をこえて甲府盆地に入ると、様子が変わります。盆地の村々から加わった人々が増え、群衆はふくれあがりました。数は数万ともいわれます。商家や豪農の家が次々と打ちこわされ、郡内の指導者たちにも止められなくなりました。武七は郡内へ引き返したといわれますが、群衆は甲府へとなだれこんでいきました。","甲府勤番の力だけではおさえきれず、周りの藩からも兵が出て、ようやく騒動はしずまりました。そのあと、きびしい取り調べが行われ、多くの人が罰を受けました。武七は捕らえられ、獄中で亡くなったと伝わります。兵助は村を逃れ、各地を転々と旅して生きのびたといわれます。","«なぜ、兵助は生きのびられたのか?» 逃亡の旅をしながら、兵助は各地で世話になり、晩年はひそかに犬目にもどって亡くなったと伝わります。犬目には兵助の墓がのこり、郷土の人々は今も «義民» としてしのんでいます。飢えに苦しんだ人々と、騒動で被害を受けた人々、その両方を心にとめて訪ねたい場所です。"],"tl":[["1833年ごろ〜","天保のききんが始まり、米の値段が上がる"],["1836年8月","郡内の武七・兵助らを中心に一揆が起こる"],["1836年8月","笹子峠をこえて国中へ。打ちこわしが広がり甲府にせまる"],["1836年8月末","近隣の藩の出兵などで騒動がしずまる"],["1837年","大坂で大塩平八郎の乱。天保期の社会不安が各地で表面化"],["その後","兵助は逃亡生活ののち、晩年に犬目へもどったと伝わる"]],"who":[["犬目の兵助","一揆のリーダーの一人。逃亡して生きのびたと伝わる"],["下和田の武七","一揆のリーダーの一人。捕らえられ獄中で亡くなったと伝わる"],["甲府勤番","幕府の役人。騒動をおさえきれなかった"],["郡内・国中の百姓たち","ききんに苦しみ、一揆に加わった人々"]],"deep":["天保騒動は «郡内騒動» «甲州一揆» とも呼ばれ、江戸時代の百姓一揆の中でも最大級のものの一つとされます。","はじめに目標とされたのは熊野堂村（今の笛吹市）の米商人だったとされ、米の買い占めへの怒りが一揆のきっかけでした。","郡内勢の «要求型» の行動が、国中で «打ちこわし型» の暴動へ変わっていった過程は、一揆研究で重要なテーマです。指導者が群衆をおさえきれなくなる様子が記録から読みとれます。","幕府直轄の甲斐で大騒動をおさえられなかったことは、幕府の支配力の弱まりを示す出来事と受けとめられ、翌年の大塩平八郎の乱とあわせて天保の改革の背景になったと考えられています。","兵助の逃亡中の足取りについては、本人の記録とされる旅日記があると伝わりますが、内容の信頼性については検討が必要です。"],"look":["犬目に残る兵助の墓と碑","旧甲州街道・犬目宿の町並み","一揆勢がこえた笹子峠","山梨県立博物館の関連展示"],"q":["天保騒動のきっかけになった、人々の一番の苦しみは何？","ききんによる米の値段の高騰と、米の買い占めへの怒りです。"],"koji":[],"myth":"武七の最期、兵助の逃亡と晩年、参加人数は伝承・諸説を含む。","img":["天保の大飢饉","犬目宿","甲府勤番"],"wp":"天保騒動","rel":{"ev":[],"grave":[]},"ph":[["c:7/74/Autoportrait_of_EGAWA_Hidetatsu.jpg",1500,2078],["c:a/a6/%E5%A4%A9%E4%BF%9D%E3%81%AE%E5%A4%A7%E9%A3%A2%E9%A5%89.jpg",700,525,"天保の大飢饉"],["c:f/fb/Koshu_kaido_inume-juku_P1010052.jpg",1280,957,"犬目宿"]]},{"id":"19_inume","n":"犬目宿（北斎・広重が描いた宿）","yomi":"いぬめじゅく","cat":"街道","rank":"A","y":1830,"era":["edo"],"sh":"","ad":"上野原市犬目","st":"JR四方津駅または鳥沢駅から車で約10分。旧甲州街道を歩くなら野田尻宿から約1時間","la":35.629,"lo":139.012,"hook":"山の尾根の上の小さな宿場から、ふいに富士山があらわれる。北斎が «富嶽三十六景» の一枚に選んだ景色。","lead":"上野原市の山の尾根の上にある、甲州街道の宿場のあとです。江戸から甲府へ向かう旅人が、ここで富士山をながめました。葛飾北斎は «富嶽三十六景» に «甲州犬目峠» を描き、歌川広重も旅の途中でこの地を通っています。","story":["江戸から甲州街道を西へ。相模川の谷をぬけて甲斐に入ると、道は山また山の中へ入っていきます。上野原、鶴川、野田尻……。いくつもの坂を上り下りして、尾根の上にたどりつくと、そこが犬目宿です。標高は約500m。甲州街道の宿場の中でも、とても高いところにあります。","この宿場が有名なのは、なんといっても富士山のながめです。山にかくれて見えなかった富士が、ここで突然、南の空に姿をあらわします。«おお、富士だ!» 旅人たちは足を止め、疲れを忘れて見入ったことでしょう。江戸の人々にとって、富士山は信仰の山でもありました。","葛飾北斎は «富嶽三十六景» の中に «甲州犬目峠» を描きました。急な坂道を旅人と馬が行き、その向こうに大きな富士がそびえる構図です。北斎が実際にここに来て描いたかどうかは、よくわかっていません。それでも、この一枚で犬目の名は江戸中に知られるようになりました。","歌川広重も1841年ごろ、甲府へ向かう旅の途中にこの道を通り、旅の日記に風景を書きとめたといわれます。広重はのちに犬目峠から見た富士も描いています。«二人の天才が、同じ峠の富士を描いた»。そう思うと、この小さな宿場がとても特別に見えてきます。","犬目は、1836年の天保騒動のリーダー・兵助のふるさとでもあります。宿場の家々は火事などで建て替えられましたが、道の幅や家の並びに宿場の面影が残ります。今は静かな山里ですが、晴れた日には、北斎や広重が見たのと同じ富士が、変わらずに旅人をむかえてくれます。"],"tl":[["17世紀初め","甲州街道が整備され、宿場が置かれる"],["1830年代前半","葛飾北斎の «富嶽三十六景 甲州犬目峠» が出版される"],["1836年","犬目村の兵助らが天保騒動を起こす"],["1841年ごろ","歌川広重が甲州への旅でこの地を通ったといわれる"],["明治時代","鉄道の開通で街道の旅人が減り、宿場としての役目を終える"]],"who":[["葛飾北斎","«富嶽三十六景» で «甲州犬目峠» を描いた"],["歌川広重","甲州への旅の途中に通り、犬目峠の富士を描いた"],["犬目の兵助","天保騒動のリーダーの一人。犬目村の出身"]],"deep":["犬目宿は江戸から数えて甲州街道の20番目前後の宿場とされ、野田尻宿と下鳥沢宿の間にあります。宿場の数え方は資料によって少しちがいます。","北斎の «甲州犬目峠» は、実際の地形より坂を急に描き、富士を大きく見せる工夫がされています。現地の風景と比べると、北斎の «演出» がよくわかります。","広重の甲州の旅は、甲府の町の人々に頼まれて祭りの幕絵を描くためだったといわれ、その道中を書いた日記が伝わっています。","甲州街道の郡内の宿場は、人馬の負担が大きい割に宿泊客が少なく、宿場の経営は楽ではなかったと考えられています。","犬目には兵助の生家とされる場所や墓があり、天保騒動と宿場の歴史を同時にたどることができます。"],"look":["宿場の中から南に見える富士山","旧甲州街道の道筋と家並み","兵助の墓・ゆかりの碑","野田尻宿〜犬目宿の山道歩き"],"q":["葛飾北斎が «富嶽三十六景» に描いた、犬目宿ゆかりの作品名は？","«甲州犬目峠»。坂道を行く旅人の向こうに大きな富士が描かれています。"],"koji":[],"myth":"北斎が実地で描いたかは不明。広重の旅の目的や日記の詳細は伝承を含む。","img":["富嶽三十六景","葛飾北斎","甲州街道"],"wp":"犬目宿","rel":{"ev":[],"grave":[]},"ph":[["c:f/fb/Koshu_kaido_inume-juku_P1010052.jpg",1280,957,"犬目宿"],["c:9/9b/Hokusai41_inume-pass.jpg",3100,2110],["c:0/0a/The_Great_Wave_off_Kanagawa.jpg",4335,2990,"富嶽三十六景"],["c:d/d4/Hokusai_portrait.jpg",680,1284,"葛飾北斎"],["c:a/a3/100_views_edo_086.jpg",793,1200,"甲州街道"]]},{"id":"19_daigahara","n":"台ヶ原宿（甲州街道の古い町並み）","yomi":"だいがはらじゅく","cat":"街道","rank":"A","y":1750,"era":["edo","meiji"],"sh":"","ad":"北杜市白州町台ヶ原","st":"JR長坂駅または日野春駅から車で約10〜15分","la":35.8095,"lo":138.3195,"hook":"南アルプスの水でつくる酒蔵と、老舗の和菓子屋。明治天皇も泊まった甲州街道の宿場に、江戸の空気が残る。","lead":"北杜市白州町にある、甲州街道の宿場町です。古い商家や酒蔵が道沿いに並び、«日本の道百選» にも選ばれています。1750年創業と伝わる酒蔵は、明治天皇が巡幸のときに泊まった家でもあります。","story":["甲府から甲州街道を北西へ。八ヶ岳と南アルプスにはさまれた谷を進むと、やがて信濃（長野県）との境が近づいてきます。その手前にあるのが台ヶ原宿です。旅人はここで一息つき、信濃への最後の道のりに備えました。","宿場の通りを歩くと、太い梁と格子戸の家々が目に入ります。とくに目をひくのが、大きな酒蔵。1750年創業と伝わるこの蔵は、南アルプスの山からわき出るきれいな水を使って酒を造ってきました。«水がいいから、いい酒ができる»。このあたりの人々の自慢です。","1880年、明治天皇が山梨県や長野県をめぐる旅（巡幸）に出たとき、この酒蔵の家が «行在所（あんざいしょ）»、つまり天皇のお泊まりどころになりました。家には «竹林の七賢» を彫った立派な欄間があったといわれ、のちにそれにちなんだ名前の酒が生まれたと伝わります。","通りの向かいには、明治時代から続く和菓子屋があります。名物は、きなこと黒蜜をかけて食べるお菓子。«信玄餅» と呼ばれる甲州の味をたのしめます。«宿場町で、甘いものを片手にひと休み»。江戸の旅人も、きっと同じように茶店で一服したのでしょう。","台ヶ原の町並みは、1986年に «日本の道百選» に選ばれました。近くには尾白川の渓谷や、名水をいかしたウイスキーの蒸溜所もあり、«水の町» としても知られています。山の水がめぐりめぐって、酒になり、町の暮らしをささえてきた。台ヶ原は、そんな水の物語の町でもあるのです。"],"tl":[["17世紀初め","甲州街道の宿場として整えられる"],["1750年","宿場の酒蔵が創業したと伝わる"],["江戸時代","信濃との国境に近い宿場としてにぎわう"],["1880年","明治天皇の巡幸で、酒蔵の家が行在所となる"],["1986年","甲州街道台ヶ原宿として «日本の道百選» に選ばれる"]],"who":[["明治天皇","1880年の巡幸で台ヶ原に泊まった"],["宿場の酒造家","南アルプスの水で酒を造り、宿場をささえた"],["甲州街道の旅人","江戸と信濃・甲府を行き来した人々"]],"deep":["台ヶ原宿は、甲州街道で甲府より西の宿場（韮崎・台ヶ原・教来石・蔦木など）の一つ。蔦木宿の先はもう信濃国でした。","明治天皇の1880年の巡幸は、山梨・長野・三重・京都などを回る大きな旅で、各地の旧家が行在所や休憩所になりました。","«竹林の七賢» は中国の晋の時代、俗世をはなれて竹林で語り合ったという7人の賢者。欄間の図柄が酒の名につながったと伝わります。","白州一帯は南アルプスの花崗岩をくぐった軟水がわき、酒造・ウイスキー・ミネラルウォーターの産地として知られます。","宿場の町割りは、道の両側に間口のせまい奥行きの長い敷地が並ぶ、典型的な宿場の形をよく残しています。"],"look":["道沿いの酒蔵と古い商家","行在所となった家の建物（外観）","老舗和菓子屋の店構え","近くの尾白川渓谷"],"q":["1880年、台ヶ原宿に泊まった人物はだれ？","明治天皇。巡幸の途中、酒蔵の家が行在所になりました。"],"koji":[{"w":"竹林の七賢","m":"中国・晋の時代に、世の中からはなれて竹林で語り合ったという7人の賢者"}],"myth":"酒蔵の創業年や欄間と酒名の由来は伝承を含む。","img":["甲州街道","明治天皇","竹林の七賢"],"wp":"台ヶ原宿","rel":{"ev":[],"grave":[]},"ph":[["c:c/ce/Daigahara-juku_%28Hokuto_City%2C_Yamanashi_Prefecture%29_April_29%2C_2026_08.jpg",5568,3712,"台ヶ原宿"],["c:7/73/Daigahara-juku_%28Hokuto_City%2C_Yamanashi_Prefecture%29_April_29%2C_2026_09.jpg",5568,3712],["c:2/24/Daigahara-juku_%28Hokuto_City%2C_Yamanashi_Prefecture%29_April_29%2C_2026_07.jpg",5568,3712],["c:3/38/Daigahara-juku_%28Hokuto_City%2C_Yamanashi_Prefecture%29_April_29%2C_2026_06.jpg",5568,3712],["c:c/c5/Daigahara-juku_%28Hokuto_City%2C_Yamanashi_Prefecture%29_April_29%2C_2026_04.jpg",5568,3712],["c:1/1a/Daigahara-juku_%28Hokuto_City%2C_Yamanashi_Prefecture%29_April_29%2C_2026_02.jpg",5568,3712],["c:a/a3/100_views_edo_086.jpg",793,1200,"甲州街道"],["c:0/0a/Emperor_Meiji_in_1873.jpg",960,1360,"明治天皇"]]},{"id":"19_katsunuma_juku","n":"勝沼宿（甲州街道とぶどうの町）","yomi":"かつぬまじゅく","cat":"街道","rank":"A","y":1868,"era":["edo","meiji"],"sh":"","ad":"甲州市勝沼町勝沼","st":"JR勝沼ぶどう郷駅から車で約5分（歩いて約30分）","la":35.664,"lo":138.7285,"hook":"ぶどうの町の宿場で、幕末最後の戦いの一つが起きた。近藤勇が «大久保剛» と名を変えて向かった甲州の道。","lead":"甲州市勝沼にある甲州街道の宿場です。江戸時代から «甲州ぶどう» の名産地で、旅人のみやげとしても人気でした。1868年には、近くの柏尾で近藤勇の甲陽鎮撫隊と新政府軍が戦っています。","story":["笹子峠をこえ、甲府盆地に下りてきた旅人が最初に出会う大きな宿場、それが勝沼宿でした。盆地を見下ろす坂の町で、目の前には一面のぶどう畑が広がります。«甲斐に来た» と実感する場所だったのでしょう。","勝沼のぶどうの歴史はとても古く、奈良時代の僧・行基が薬師如来のおつげでぶどうを伝えたとか、鎌倉時代に雨宮勘解由という人が山で見つけたとか、いくつもの言い伝えがあります。近くの大善寺の薬師如来は、手にぶどうを持った姿で «ぶどう薬師» と呼ばれます。江戸時代には、ぶどうは甲州の名物として江戸にも運ばれました。","1868年の春、この静かな宿場に緊張が走ります。新選組の近藤勇が «大久保剛» と名を変え、«甲陽鎮撫隊» をひきいて甲府城をめざしてやって来たのです。«甲府城を先に押さえれば、新政府軍を止められる!» しかし、板垣退助の新政府軍が一足先に甲府城に入っていました。","両軍は勝沼宿の東、柏尾のあたりでぶつかりました。数と武器でまさる新政府軍の前に、鎮撫隊は短い時間で敗れ、散り散りになって江戸方面へ退きました。«甲州勝沼の戦い» «柏尾の戦い» と呼ばれるこの戦いは、戊辰戦争の一場面です。宿場の近くには、この戦いを伝える碑や近藤勇の像があります。","明治になると、勝沼ではぶどうからワインを造る挑戦が始まり、日本のワインのふるさとになっていきます。宿場の通りには、明治時代の銀行の建物や本陣のあとの碑が残ります。坂道を歩けば、旅人とぶどうと戦いの記憶が、ゆっくりと重なって見えてきます。"],"tl":[["718年","行基がぶどうを伝えたとする言い伝え（伝承）"],["1186年","雨宮勘解由が甲州ぶどうを見つけたとする言い伝え（伝承）"],["17世紀初め","甲州街道の宿場として整えられる"],["江戸時代","甲州ぶどうが名産として江戸へ運ばれる"],["1868年3月","柏尾の戦いで甲陽鎮撫隊が新政府軍に敗れる"],["1877年","勝沼（祝村）でワイン会社が設立され、2人の若者がフランスへ"]],"who":[["近藤勇","新選組局長。«大久保剛» と名乗り甲陽鎮撫隊をひきいた"],["板垣退助","新政府軍をひきい、甲府城に先に入った"],["行基","奈良時代の僧。ぶどうを伝えたと伝わる"],["雨宮勘解由","甲州ぶどうを見つけたと伝わる人物"]],"deep":["近藤勇が名乗った «大久保剛» の名は、幕府から与えられた身分にもとづくといわれます。甲陽鎮撫隊には土方歳三・永倉新八・原田左之助らも加わっていました。","柏尾の戦いは短時間で決着したとされますが、戦死者の数や戦闘の細かい経過は史料によって異なります。","大善寺の本堂（薬師堂）は鎌倉時代の建物で国宝。«ぶどう寺» として勝沼のぶどうの歴史を象徴する存在です。","甲州ぶどうはヨーロッパ系のぶどうの流れをくむことが、遺伝子の研究で示されています。シルクロードを通って伝わった可能性が語られています。","宿場の通りに残る旧田中銀行の建物は明治時代の洋風建築で、ぶどう・養蚕でうるおった勝沼の経済力を物語ります。"],"look":["本陣のあとの碑と宿場の通り","旧田中銀行などの明治の建物","柏尾古戦場の碑と近藤勇の像","ぶどう寺・大善寺の本堂"],"q":["甲陽鎮撫隊をひきいたとき、近藤勇はどんな名前を名乗っていた？","«大久保剛»。新政府軍に敗れ、江戸方面へ退きました。"],"koji":[],"myth":"ぶどうの起源（行基説・雨宮勘解由説）はどちらも伝承。","img":["勝沼宿","甲州勝沼の戦い","大善寺 (甲州市)"],"wp":"勝沼町","rel":{"ev":[],"grave":[]},"ph":[["c:1/1e/Marufuji_Winery_190907f.jpg",4496,3000,"勝沼町"],["c:9/93/Norobasi-1.jpg",4496,3000],["c:4/42/Katsunumashi_yakataato-1.jpg",4496,3000],["c:2/21/Daizen-ji-4a.jpg",4496,3000],["c:e/ee/KatsunumaTown-YamanashiPref.png",600,500],["c:e/e1/KatsunumaSt.jpg",600,445],["c:b/b1/KoshuKatsunuma.jpg",1600,766,"甲州勝沼の戦い"]]},{"id":"19_daibosatsu","n":"大菩薩峠（青梅街道の難所）","yomi":"だいぼさつとうげ","cat":"街道","rank":"A","y":1913,"era":["heian","edo","taisho"],"sh":"","ad":"甲州市塩山上萩原・北都留郡小菅村","st":"JR塩山駅からバスで上日川峠（季節運行・本数少）、そこから歩いて約1時間","la":35.747,"lo":138.8445,"hook":"標高1897m、雲の上の峠。一人の作家がここを舞台に、日本一長いといわれる時代小説を書き始めた。","lead":"甲州市と小菅村の境にある、標高1897mの峠です。昔は甲斐と武蔵をむすぶ青梅街道の難所でした。中里介山の長編小説『大菩薩峠』の舞台として、全国にその名を知られています。","story":["甲府盆地の東にそびえる大菩薩嶺。その肩にあたる大菩薩峠は、標高1897m。かつて甲斐と武蔵（東京都）を結ぶ青梅街道は、この高い峠をこえていました。«なぜ、わざわざこんな高い所を?» 甲州街道の谷道にくらべて距離が短く、塩や炭、絹などの荷物を運ぶ人々が通ったのです。","峠の名前には言い伝えがあります。平安時代の終わり、甲斐源氏の祖・新羅三郎義光が道に迷ったとき、«八幡大菩薩» と神に祈ると、道案内があらわれ、無事に峠をこえられたというのです。本当かどうかはわかりませんが、それほど道の険しい、神だのみの峠だったのでしょう。","1913年、東京の新聞で、ひとつの小説の連載が始まりました。中里介山の『大菩薩峠』です。物語は、この峠の上で、剣客・机竜之助がひとりの老巡礼を理由もなく斬る場面から始まります。«音無しの構え» を使う虚無的な剣士の物語は、多くの読者をひきつけ、映画にも何度もなりました。","介山はこの小説を30年近く書き続けましたが、ついに完成しないまま1944年に亡くなりました。«世界一長い小説» と呼ばれることもあるほどの大作です。峠のそばには介山の文学碑が立ち、今も文学好きの登山者が足を止めます。","今の大菩薩峠は、首都圏から日帰りできる人気の山歩きコースです。峠からは、晴れていれば富士山や南アルプス、大菩薩湖が見わたせます。荷をかついだ旅人、机竜之助、そして今の登山者。同じ峠に立った人々の思いを重ねてみると、雲の上の景色がいっそう深く見えてきます。"],"tl":[["平安時代後期","新羅三郎義光が «八幡大菩薩» と祈ったのが峠の名の由来と伝わる"],["江戸時代","青梅街道（甲州裏街道）の峠として人や荷が行き交う"],["明治時代","柳沢峠の新道が開かれ、大菩薩峠を通る人が減る"],["1913年","中里介山が『大菩薩峠』の連載を始める"],["1944年","介山が死去。『大菩薩峠』は未完に"],["現在","人気の登山コース。峠に山小屋と文学碑"]],"who":[["中里介山","小説『大菩薩峠』の作者"],["机竜之助","小説の主人公（架空の人物）。虚無の剣士"],["新羅三郎義光（源義光）","峠の名の由来の伝説に登場する武将"]],"deep":["現在の大菩薩峠は、江戸時代の峠道の位置から移っているといわれ、もとの峠は少し北の «賽ノ河原» 付近だったという説があります。","青梅街道は、江戸と甲府を結ぶ甲州街道の «裏» のルートとして «甲州裏街道» とも呼ばれました。距離は短いものの、高い峠をこえる厳しい道でした。","『大菩薩峠』は新聞・雑誌をまたいで連載され、全41巻ともいわれる分量になります。巻数の数え方は版によってちがいます。","机竜之助は架空の人物で、物語の出来事は創作です。ただし幕末の甲州や江戸の風俗は、介山がよく調べて描いたと評価されています。","峠の近くの山小屋・福ちゃん荘は、1969年に過激派の学生グループが軍事訓練のために集まり、一斉に逮捕された «大菩薩峠事件» の現場としても記録されています。"],"look":["峠の標柱と山小屋","中里介山の文学碑","峠から見る富士山と大菩薩湖","大菩薩嶺（標高2057m）への稜線歩き"],"q":["小説『大菩薩峠』の主人公の剣士の名前は？","机竜之助。«音無しの構え» で知られる架空の剣士です。"],"koji":[],"myth":"峠の名の由来（義光の祈り）は伝承。小説の人物・出来事は創作。旧峠の位置は諸説。","img":["大菩薩峠 (小説)","中里介山","青梅街道"],"wp":"大菩薩峠","rel":{"ev":[],"grave":[]},"ph":[["c:9/9b/Daibosatsu_touge.jpg",2592,1944,"大菩薩峠"],["c:0/06/View_from_Daibosatsu-Pass_01.jpg",9300,1490],["c:3/33/Daibosatsurei_%26_Kamihikawa_Dam_2012-11-02.jpg",1386,924],["c:e/e6/Nakazato_Kaisan.JPG",499,719,"中里介山"]]},{"id":"19_sasago_toge","n":"笹子峠（甲州街道最大の難所）","yomi":"ささごとうげ","cat":"街道","rank":"A","y":1938,"era":["edo","meiji","showa"],"sh":"国の登録有形文化財（笹子隧道）","ad":"大月市笹子町黒野田・甲州市大和町","st":"JR笹子駅から歩いて約2時間（旧道を歩く場合）。車なら県道で笹子隧道の近くまで行ける","la":35.6095,"lo":138.8215,"hook":"江戸から甲府へ、旅人がいちばん苦しんだ山道。峠の下には、今も昭和のれんが造りのトンネルが口をあけている。","lead":"大月市と甲州市の境にある、標高1096mの峠です。甲州街道でいちばんの難所といわれ、郡内と国中を分ける «境» でもありました。明治には鉄道の長いトンネル、昭和には車のトンネルがほられ、峠の歴史は «トンネルの歴史» でもあります。","story":["江戸を出て甲州街道を歩いてきた旅人にとって、最後で最大の関門が笹子峠でした。大月の先、笹子の集落から、道は急な坂をぐんぐん上っていきます。石ころだらけの山道、深い杉の森。«この峠さえこえれば、甲府盆地だ» と、旅人は自分をはげましながら歩いたのでしょう。","峠の手前には、巨大な杉の木 «矢立の杉» がそびえています。戦に出る武士たちが、この杉に矢を射立てて勝利を祈ったと伝わります。幹の中は空洞になっていますが、今も天に向かってまっすぐ立ち、旅人を見守っています。","明治時代、この険しい峠の下に鉄道を通す大工事が行われました。中央本線の笹子トンネルは、長さ4.6km余り。完成した当時は日本で一番長い鉄道トンネルでした。«山の下を汽車が走る!» それは、何日もかけて峠をこえていた人々にとって、夢のような出来事でした。","昭和に入ると、自動車のためのトンネルも作られます。1938年に完成した笹子隧道は、入り口をれんがや石で美しく飾った、どっしりしたトンネルです。今は国の登録有形文化財になり、古い峠道を歩く人々の目を楽しませています。その後、さらに下に国道や高速道路のトンネルが通りました。","笹子の高速道路のトンネルでは、2012年に天井板が崩れ落ちる事故が起き、9人の方が亡くなりました。便利さの裏にある安全の大切さを、私たちに問いかけた出来事です。峠道を歩き、れんがのトンネルの前に立つとき、ここを行き来した多くの人々のことを静かに思い浮かべたい場所です。"],"tl":[["江戸時代","甲州街道最大の難所として旅人が行き交う"],["1836年","天保騒動の一揆勢が笹子峠をこえて国中へ向かう"],["1903年","中央本線の笹子トンネルが開通（当時日本最長の鉄道トンネル）"],["1938年","自動車用の笹子隧道が完成"],["1977年","中央自動車道の笹子トンネルが開通"],["2012年","中央道笹子トンネルで天井板の崩落事故が起き、9人が亡くなる"]],"who":[["甲州街道の旅人たち","峠をこえて江戸と甲府を行き来した人々"],["中央本線の工事にたずさわった人々","長いトンネルをほりぬいた"],["天保騒動の一揆勢","峠をこえて国中へ向かった郡内の人々"]],"deep":["峠の東の黒野田宿、西の駒飼宿は、峠をこえる前後の休み場として機能しました。峠の上には茶屋があったと伝わります。","中央本線の笹子トンネル（初代）は長さ約4,656mで、完成時は国内最長の鉄道トンネルでした。工事には最新の技術と多くの労働力が注がれました。","笹子隧道は長さ約239mの道路トンネルで、坑門の装飾は昭和初期の土木デザインの特徴を示し、国の登録有形文化財になっています。","矢立の杉は県の天然記念物。«矢立» の伝承は各地にありますが、ここでは出陣の武士が矢を射立てたと語られます。","笹子峠は «国中» と «郡内» を分ける分水嶺で、峠の東の水は相模川へ、西の水は笛吹川・富士川へ流れます。"],"look":["旧笹子隧道の坑門（れんが・石積みの飾り）","矢立の杉","旧甲州街道の峠道","笹子駅周辺の名物・笹子餅"],"q":["明治時代に笹子峠の下に開通した中央本線の笹子トンネルは、完成当時どんな記録を持っていた？","日本で一番長い鉄道トンネル。長さは約4.6kmでした。"],"koji":[],"myth":"矢立の杉の由来は伝承。","img":["笹子隧道","中央本線","甲州街道"],"wp":"笹子峠","rel":{"ev":[],"grave":[]},"ph":[["c:9/9f/Sasagotouge.JPG",240,320,"笹子峠"],["c:3/36/Aerial_view_several_tunnels_Sasagotoge_pass._West_entrance_side.jpg",2461,1780],["c:9/9f/Aerial_view_several_tunnels_Sasagotoge_pass._East_entrance_side.jpg",2456,1771],["c:c/c1/Hiroshige_II_K%C5%8Dsh%C5%AB_Yatatesugi.jpg",1033,1536],["c:a/a1/Sasago_Pass_01-2.jpg",3646,2431,"笹子隧道"],["c:e/e3/JRE_Chuo-Main-Line_Multiple-lines.jpg",2736,1824,"中央本線"],["c:a/a3/100_views_edo_086.jpg",793,1200,"甲州街道"]]},{"id":"19_mutsuzawa","n":"旧睦沢学校校舎（藤村式の擬洋風建築）","yomi":"きゅうむつざわがっこうこうしゃ","cat":"近代","rank":"A","y":1875,"era":["meiji"],"sh":"国の重要文化財","ad":"甲府市北口（甲府市藤村記念館）","st":"JR甲府駅北口から歩いてすぐ","la":35.6674,"lo":138.5691,"hook":"«学校こそ文明の入口だ» ——県令の号令で村の大工が挑んだ、ちょっと不思議な «洋風» 校舎。","lead":"明治のはじめ、1875年に今の甲斐市に建てられた小学校の校舎です。当時の山梨県令・藤村紫朗がすすめた «藤村式» と呼ばれる洋風の建物で、国の重要文化財。今は甲府駅北口に移され «甲府市藤村記念館» として公開されています。","story":["明治維新から数年後、日本中で «学校をつくろう» という動きが始まりました。1872年に «学制» が出され、すべての子どもが学ぶ時代がやってきたのです。山梨県でそれを強くおしすすめたのが、県令（今の知事）の藤村紫朗でした。","藤村は «これからは西洋に学ぶ時代だ» と考え、学校や役所の建物を洋風にすることをすすめました。けれど、村の大工たちは本物の西洋建築を見たことがありません。«洋風って、どうつくればいいんだ?» 彼らは東京や横浜の写真や絵を手がかりに、日本の技術で «洋風らしく» 見える建物をつくりました。こうした建物を «擬洋風建築» と呼びます。","1875年、巨摩郡睦沢村（今の甲斐市亀沢）にできた睦沢学校もそのひとつです。白いしっくいの壁、2階のベランダ、屋根の上には時を知らせる太鼓を置いた塔。ところが窓のまわりや軒の飾りをよく見ると、日本のお寺や蔵の技も使われています。«和と洋のまぜごはん» のようなおもしろさが、藤村式の魅力です。","村の人々は、この校舎をとても誇りにしました。子どもたちはここで読み書きや算数を学び、新しい時代の知識を身につけていきました。学校は、村に «文明開化» を運んできた窓口だったのです。","校舎はその後、役目を終えて甲府へ移され、1967年に国の重要文化財に指定されました。さらに2010年、甲府駅の北口に移り、今は記念館として無料で見学できます。駅を降りてすぐのところで、明治の子どもたちが見上げた «夢の校舎» に出会えるのです。"],"tl":[["1872年","学制が出され、全国で学校づくりが始まる"],["1873年","藤村紫朗が山梨県に着任し、学校などの洋風建築をすすめる"],["1875年","睦沢村に睦沢学校の校舎が完成"],["昭和時代","校舎が役目を終え、甲府市内へ移築される"],["1967年","国の重要文化財に指定"],["2010年","甲府駅北口に移築され、甲府市藤村記念館として公開"]],"who":[["藤村紫朗","山梨県令。藤村式建築をすすめた"],["睦沢村の人々","お金を出し合い、学校を建てた"],["地元の大工棟梁","見よう見まねで洋風の校舎をつくった"]],"deep":["藤村式建築の現存例には、旧睦沢学校のほか、北杜市の旧津金学校、都留市の旧尾県学校などがあり、山梨県内に «明治の学校» がまとまって残っています。","屋根の上の塔（太鼓楼）には太鼓が置かれ、授業の始まりなどを知らせたといわれます。時計がまだ高価だった時代の工夫です。","擬洋風建築は、長野県の旧開智学校（国宝）などと同じ流れにあり、地方の大工が西洋建築をどう理解し表現したかを知る貴重な資料です。","校舎の建設費の多くは地域の人々の寄付でまかなわれたとされ、明治の人々の教育への熱意がうかがえます。","藤村紫朗は学校だけでなく、道路や役所の建設もおしすすめ、«藤村式» の建物は山梨の近代化の象徴とされますが、住民の負担が重かったという見方もあります。"],"look":["2階のベランダと屋根の上の太鼓楼","窓まわりの和洋が混ざった装飾","館内の明治の教室の展示","甲府駅北口の «よっちゃばれ広場» とあわせて"],"q":["明治の地方の大工たちが、見よう見まねでつくった洋風の建物を何と呼ぶ？","擬洋風建築。山梨では県令の名前から «藤村式» と呼ばれます。"],"koji":[{"w":"文明開化","m":"明治のはじめ、西洋の文化や技術を取り入れて社会が大きく変わったこと"}],"myth":"移築の経緯と年は確認を推奨。建設費の負担割合は諸説。","img":["藤村紫朗","擬洋風建築","旧開智学校"],"wp":"甲府市藤村記念館","rel":{"ev":[],"grave":[]},"ph":[["c:a/a1/Fujimura_Memorial_Hall._Nov._2016.jpg",6000,4000,"甲府市藤村記念館"],["c:3/35/Takeda_Nobutora_2019a.jpg",4496,3000],["c:f/f8/Fujimura_Memorial-3.jpg",3216,2136],["c:1/11/Fujimura_Memorial-2.jpg",3216,2136],["c:7/71/Fujimura_Memorial-1.jpg",3216,2136],["c:f/f7/Fujimura_Shiro.jpg",960,1280,"藤村紫朗"],["c:8/88/Former_Kaichi_School03_1024.jpg",1536,2048,"擬洋風建築"],["c:5/59/View_of_Former_Kaichi_School%2C_Kaichi_Matsumoto_City_2026.jpg",1500,1000,"旧開智学校"]]},{"id":"19_kikoten","n":"徽典館（甲府の学問所）","yomi":"きてんかん","cat":"学び","rank":"A","y":1796,"era":["edo","meiji"],"sh":"","ad":"甲府市丸の内付近（甲府城の近くにあったとされる）","st":"JR甲府駅から歩いて約5〜10分","la":35.662,"lo":138.567,"hook":"«山流し» の役人たちが、山国の若者のために開いた学びの場。その灯は、今の山梨大学へとつながっている。","lead":"江戸時代の後半、甲府勤番の役人たちの手で甲府城の近くに開かれた学問所です。はじめは «甲府学問所» と呼ばれ、のちに «徽典館» と名づけられました。幕府の学問所から先生が送られ、甲斐の若者も学びました。山梨大学の源流の一つとされます。","story":["18世紀の終わり、甲府の町では、江戸から来た甲府勤番の武士たちが暮らしていました。«山流し» とうわさされたこの仕事。けれど、子どもたちの教育はおろそかにできません。«江戸にもどったとき、わが子が学問で遅れをとってはいけない»。そんな思いもあって、1796年、甲府に学問所がつくられました。","学問所で学ぶのは、主に «儒学»。中国の孔子の教えをもとに、人としての正しい生き方や、国の治め方を考える学問です。先生たちは、読み書きや漢文の素読（声に出して読むこと）を通して、子どもたちをきたえました。«子曰く……»。甲府の町に、若い声がひびきました。","やがて学問所には «徽典館（きてんかん）» という名がつけられます。«徽» は «よい»、«典» は «教え・手本» という意味。名付けたのは、幕府の学問の元締めである林家だと伝わります。さらに、江戸の昌平坂学問所から、優秀な学者が交代で送られてくるようになりました。«山国で、江戸と同じ学問が学べる»。これは大きなことでした。","徽典館で学んだのは、勤番の子どもたちだけではありませんでした。甲斐の町人や村の有力者の子どもたちにも門が開かれ、ここで学んだ若者たちが、のちの山梨の近代化をささえていきます。«学ぶことで、身分をこえた仲間ができる» ——徽典館は、そんな場でもあったのです。","明治維新のあと、徽典館の流れは教員を育てる学校へと引きつがれ、やがて今の山梨大学につながったとされます。建物は残っていませんが、«徽典館» の名は今も山梨大学の中で大切に受けつがれています。甲府城のまわりを歩くとき、江戸の若者たちの素読の声を思い浮かべてみてください。"],"tl":[["1724年","甲斐が幕府領となり、甲府勤番が置かれる"],["1796年","甲府に学問所がつくられる"],["19世紀前半","«徽典館» と名づけられ、昌平坂学問所から学者が送られるようになる"],["江戸時代後期","町人や村の有力者の子弟にも門が開かれる"],["1868年","明治維新。甲府勤番の廃止とともに新しい学校制度へ"],["明治時代","教員養成の学校に引きつがれ、のちの山梨大学の源流の一つとなる"]],"who":[["甲府勤番の武士たち","学問所を開き、子どもたちを学ばせた"],["林家","幕府の学問をつかさどった家。徽典館の名付けに関わったと伝わる"],["昌平坂学問所の学者たち","江戸から派遣され、甲府で教えた"]],"deep":["昌平坂学問所（昌平黌）は幕府直轄の最高学府。そこから学頭が派遣されたことは、徽典館が «幕府公認の地方学問所» だったことを示します。","甲府のほかにも、幕府領の要地には似た学問所がつくられた例があり、徽典館は «幕府直轄地の教育機関» の代表例として研究されています。","徽典館の名付けの年や名付け親については、史料によって記述がちがい、はっきりしない点があります。","ここで学んだ人々の中には、明治以降に山梨の教育や行政、産業で活躍した人が多いといわれ、近代山梨の人材の土台になったと評価されています。","山梨大学は徽典館を大学のルーツと位置づけており、大学の施設や記念事業にその名が使われています。"],"look":["甲府城跡（徽典館があった界隈）","甲府城の石垣と天守台","山梨県立博物館などの関連展示","山梨大学の «徽典館» ゆかりの展示（公開時）"],"q":["徽典館の先生として、江戸のどこから学者が送られてきた？","幕府の学問所・昌平坂学問所です。山国の甲府でも江戸と同じ学問が学べました。"],"koji":[{"w":"子曰く","m":"«先生（孔子）がおっしゃるには» という意味。『論語』の多くの文はこのことばで始まる"}],"myth":"跡地の正確な位置、名付けの年と名付け親は諸説。","img":["昌平坂学問所","甲府勤番","山梨大学"],"wp":"徽典館","rel":{"ev":[],"grave":[]},"ph":[["c:9/97/Monument_of_Kitenkan_Kofu_City.JPG",4608,3072],["c:1/11/Kitenkan_Yamanashi_prefecture_normal_school_1884.JPG",2035,2939],["c:6/6c/%E5%B1%B1%E6%A2%A8%E5%A4%A7%E5%AD%A6%E7%94%B2%E5%BA%9C%E8%A5%BF%E3%82%AD%E3%83%A3%E3%83%B3%E3%83%91%E3%82%B9%282026%29.jpg",6000,4000,"山梨大学"]]},{"id":"19_miyakoen","n":"宮光園（日本ワインの草創期）","yomi":"みやこうえん","cat":"産業","rank":"A","y":1877,"era":["meiji","taisho","showa"],"sh":"","ad":"甲州市勝沼町下岩崎","st":"JR勝沼ぶどう郷駅から車で約10分","la":35.66,"lo":138.727,"hook":"«日本でもワインを» ——明治の若者たちの夢は一度くじけた。それを引きついだ男の家が、日本ワインのふるさとに残る。","lead":"甲州市勝沼にある、明治時代のワイン造りの先駆者・宮崎光太郎の家とワイン醸造所のあとです。日本で最初期のワイン会社の流れを受けつぎ、観光ぶどう園の先がけにもなりました。今は資料館として公開されています。","story":["明治のはじめ、日本はなんでも西洋に学ぼうとしていました。ワインもそのひとつです。«ぶどうの名産地・勝沼なら、ワインが造れるはずだ»。1877年、勝沼の祝村（いわいむら）に «大日本山梨葡萄酒会社» がつくられました。日本で最も早い民間のワイン会社の一つです。","会社は、村の若者二人をフランスへ送りました。高野正誠と土屋龍憲です。言葉もわからない異国で、二人は必死にぶどうの育て方とワインの造り方を学び、1年半ほどで帰国しました。«これで、日本のワインが造れる!» 村じゅうが期待に胸をふくらませました。","ところが現実はきびしいものでした。日本人の口にワインの味はなかなか合わず、売れ行きはのびません。数年で会社は解散してしまいます。«夢は、ここで終わるのか?» そのとき、あきらめなかったのが、会社に関わっていた宮崎光太郎でした。","光太郎は東京に店を開き、自分たちのワインを売りこみました。甘みを加えて日本人の好みに合わせるなど、工夫をこらしたといわれます。やがて «大黒天印» のワインは広く知られるようになりました。光太郎の事業は、のちに日本の大手ワインメーカーの源流の一つになっていきます。","勝沼の本拠地 «宮光園» には、醸造所や貯蔵庫、住まいが並び、ぶどう狩りを楽しむ人々もむかえました。今の «観光ぶどう園» の先がけです。宮光園からは、大正から昭和のはじめのぶどう畑やワイン造りを撮影した貴重な映像フィルムも見つかっています。一度は消えかけた夢が、ここで花開いたのです。"],"tl":[["1877年","祝村に大日本山梨葡萄酒会社が設立され、高野正誠・土屋龍憲がフランスへ"],["1879年","二人が帰国し、ワイン造りが本格化"],["1886年","大日本山梨葡萄酒会社が解散"],["明治20年代","宮崎光太郎が東京で販売を広げ、«大黒天印» ワインが知られるようになる"],["大正〜昭和初期","宮光園で観光ぶどう園を営み、ワイン造りの様子を映像に残す"],["平成以降","建物が修復され、資料館として公開される"]],"who":[["宮崎光太郎","宮光園の主。ワイン事業を引きつぎ発展させた"],["高野正誠","フランスでワイン造りを学んだ若者"],["土屋龍憲","高野とともにフランスで学んだ若者"]],"deep":["大日本山梨葡萄酒会社は、地元の有力者が出資してつくられた会社で、«祝村葡萄酒会社» とも呼ばれます。祝村は今の甲州市勝沼町下岩崎などにあたります。","高野・土屋のフランス留学は、ブドウ栽培と醸造を実地で学ぶためのもので、帰国後に彼らが持ち帰った知識が日本のワイン造りの出発点になりました。","明治のワインは、甘いワイン（甘味ぶどう酒）が主流でした。日本人の好みに合わせた «甘口» が普及の決め手になったと考えられています。","宮光園で見つかった映像フィルムは、戦前のぶどう栽培やワイン醸造のようすを伝える産業史・映像史の貴重な資料です。","近くには土屋龍憲が使ったとされるワイン貯蔵庫（龍憲セラー）も残り、明治のワイン造りの跡をあわせて見学できます。"],"look":["主屋と白壁の蔵（醸造・貯蔵の建物）","宮光園で見つかった映像資料の上映・展示","明治のワインのびんやラベル","周辺のワイナリーとぶどう畑"],"q":["1877年、ワイン造りを学ぶためにフランスへ送られた勝沼の若者二人はだれ？","高野正誠と土屋龍憲。帰国後、日本のワイン造りの土台を築きました。"],"koji":[],"myth":"宮崎光太郎の販売上の工夫の細部は伝承を含む。文化財指定の区分は確認を推奨。","img":["メルシャン","勝沼町","日本ワイン"],"wp":"宮光園","rel":{"ev":[],"grave":[]},"ph":[["c:e/e6/Miyakoen_main_building_ac_%281%29.jpg",5981,3977,"宮光園"],["c:7/77/Miyazaki_Kotaro_monument_ac_%282%29.jpg",4005,3004],["c:e/ed/Miyakoen_monument_ac_%281%29.jpg",5333,4000],["c:6/67/Miyakoen_main_building_ac_%282%29.jpg",5930,3943],["c:4/42/Miyakoen_kura_ac_%281%29.jpg",5939,3949],["c:6/68/Miyakoen_hanarezashiki_ac_%282%29.jpg",5999,3988],["c:2/2f/Miyakoen_gate_ac_%283%29.jpg",5981,3977],["c:9/99/Miyakoen_gate_ac_%281%29.jpg",5850,3889]]},{"id":"19_kaiki","n":"甲斐絹の里・郡内（織物の産地）","yomi":"かいきのさと・ぐんない","cat":"産業","rank":"A","y":1700,"era":["edo","meiji","showa"],"sh":"","ad":"富士吉田市下吉田・都留市・西桂町ほか","st":"富士急行下吉田駅・月江寺駅から歩いてすぐ（富士吉田の織物の町）","la":35.49,"lo":138.803,"hook":"羽織を脱いだときにだけ見える、光る裏地。江戸っ子の «粋» をささえたのは、富士山のふもとの機織りの音だった。","lead":"富士山の北東の «郡内» 地方（今の富士吉田市・都留市・西桂町など）は、昔から絹織物の産地です。細い絹糸を先に染めてから織る «甲斐絹（かいき）» は、羽織の裏地として江戸や東京で大人気でした。今も «ハタオリの町» として織物が続いています。","story":["富士山のふもとの郡内は、寒くて土地がやせ、米がたくさんとれる場所ではありませんでした。そこで人々は、蚕を育てて糸をとり、布を織って暮らしを立てました。富士山からわき出るきれいな水は、糸を染めるのにもぴったりでした。家々からは «トントン、カラリ» と機織りの音がひびいたといいます。","江戸時代、郡内で織られた絹は «郡内織» «郡内縞» と呼ばれ、江戸の人々に愛されました。郡内から江戸までは、甲州街道で何日かの道のり。商人たちは反物を背負って峠をこえ、江戸の呉服屋に届けたのです。郡内の殿さまだった秋元氏も、この織物を大切にすすめたと伝わります。","明治時代になると、この織物は «甲斐絹（かいき）» と呼ばれるようになります。細い糸を先に染めて、ぎっしりと密に織るので、布はうすくて強く、つやつやと光ります。こすると «キュッ» と鳴る «絹鳴り» も特徴でした。«見えない所にこそ、いいものを» ——江戸・東京の人々は、羽織の裏地に甲斐絹を使い、脱いだときにちらりと見えるおしゃれを楽しんだのです。","甲斐絹の裏地には、風景や動物などの絵を織り出したり、染めで表したりしたものもありました。«羽織の裏に富士山が!» そんな遊び心は、表向きは地味にしながら裏で凝るという、江戸っ子の «粋» そのものでした。","戦後、着物を着る人が減ると、甲斐絹の生産はしだいに少なくなりました。けれど郡内の機屋（はたや）は、その技をいかしてネクタイ、傘、洋服の生地、インテリアの布などを作り続けています。富士吉田の古い商店街を歩くと、今も機織りの音が聞こえることがあります。富士山のふもとの «糸の物語» は、形を変えて続いているのです。"],"tl":[["江戸時代前期","郡内で絹織物がさかんになる。秋元氏が奨励したと伝わる"],["江戸時代","«郡内織» «郡内縞» が江戸で人気に"],["明治時代","«甲斐絹» の名で羽裏（羽織の裏地）として全国に広まる"],["大正〜昭和初期","甲斐絹の生産が最盛期をむかえる"],["戦後","着物離れとともに甲斐絹は減り、ネクタイや傘地などへ転換"],["現在","富士吉田・西桂などで織物産業が続く"]],"who":[["郡内の機屋と織り手たち","蚕を育て、糸を染め、布を織ってきた人々"],["秋元泰朝","谷村の領主。織物をすすめたと伝わる"],["江戸・東京の粋人たち","甲斐絹の裏地をこよなく愛した人々"]],"deep":["«かいき» の語源には、外国から伝わった «海気（かいき）» という絹織物の名にちなむという説があり、明治以降に «甲斐絹» の字が当てられたとされます。","甲斐絹は «先染め» の平織物で、たて糸とよこ糸に細い糸を密に打ちこむため、薄くて張りがあり、独特の光沢が出ます。","羽裏は人に見せない部分だからこそ凝るという美意識は、江戸時代にぜいたくを禁じた «奢侈禁止令» への反発から育ったともいわれます。","郡内の織物は、江戸時代から江戸の問屋との取引で成り立ち、甲府盆地の国中よりも江戸との経済的な結びつきが強い地域でした。","富士吉田では、織物の町の歴史と富士山の景色をいかしたまちづくりが進み、古い機屋や商店街が観光の舞台にもなっています。"],"look":["富士吉田の本町通りから見る富士山","機屋の見学やオープンファクトリー（開催時）","ふじさんミュージアムの織物の展示","西桂町・都留市の織物の町並み"],"q":["甲斐絹が江戸・東京で人気だったのは、着物のどの部分に使われたから？","羽織の裏地（羽裏）。脱いだときにだけ見える «粋» なおしゃれでした。"],"koji":[{"w":"粋（いき）","m":"見た目は控えめでも、気のきいた洗練された美しさがあること。江戸っ子が大切にした美意識"}],"myth":"秋元氏の奨励、«海気» 語源説は伝承・諸説。","img":["甲斐絹","富士吉田市","羽織"],"wp":"郡内地方","rel":{"ev":[],"grave":[]},"ph":[["c:6/6e/Fujiyoshida_montage.jpg",2870,3168,"富士吉田市"],["c:9/97/%E9%BB%92%E5%B9%B3%E7%B5%B9%E5%9C%B0%E5%AF%8C%E5%A3%AB%E5%9B%B3%E7%BE%BD%E7%B9%94_%E7%94%B7%E7%89%A9-Man%27s_Formal_Jacket_%28Haori%29_MET_DP330781.jpg",2911,3880,"羽織"],["c:7/72/Fujikyuko_Shimoyoshida_Sta_20161026.jpg",3264,1836,"近く: 下吉田駅"],["c:b/b0/%E6%9C%88%E6%B1%9F%E5%AF%BA%E9%A7%85_-_panoramio_%281%29.jpg",4752,3168,"近く: 月江寺駅"],["c:8/8b/Fujisan_sta.jpg",2048,1536,"近く: 富士山駅"],["c:d/de/Yamanashi_pref_Yoshida_highschool.jpg",1555,1166,"近く: 山梨県立吉田高等学校"],["c:9/9c/Fujisan_Shimomiya_Omuro_Sengen_jinja_torii_%E2%80%94_2021.jpg",4032,3024,"近く: 冨士山下宮小室浅間神社"]]},{"id":"19_togawa_ke","n":"旧外川家住宅（富士講の御師の家）","yomi":"きゅうとがわけじゅうたく","cat":"町","rank":"A","y":1768,"era":["edo"],"sh":"国の重要文化財・世界文化遺産「富士山」の構成資産","ad":"富士吉田市上吉田","st":"富士急行富士山駅から歩いて約10〜15分","la":35.4822,"lo":138.8012,"hook":"富士山に登る江戸の人々を泊め、祈りを案内した «御師»。その家が、250年前の姿のまま富士吉田の町に残る。","lead":"富士吉田市上吉田に残る、江戸時代の «御師（おし）» の家です。御師は、富士山に登る人々を泊め、お祈りをして登山の世話をした人たちでした。1768年に建てられた主屋が残り、国の重要文化財で、世界文化遺産「富士山」の一部でもあります。","story":["江戸時代の後半、江戸では «富士講» がブームになりました。富士山を信じる人々が «講» というグループをつくり、お金を出し合って、代表が富士山に登るのです。«一生に一度は、お山に登りたい»。江戸から富士吉田まで数日。白い装束の人々が、鈴を鳴らしながら甲州街道を歩きました。","富士吉田の上吉田に着くと、講の人々をむかえるのが «御師» です。御師は、自分の家に講の人々を泊め、神前でお祈りをし、登山の道案内の手配までしてくれました。御師と講は «師と檀家» のような深い関係で、毎年同じ御師の家に泊まるのが決まりでした。","旧外川家住宅は、1768年に建てられた御師の家です。通りから細い参道を入った奥にあり、その参道は «タツミチ» と呼ばれます。家の中には、お祈りをするための «御神前» の部屋があり、そのまわりに講の人々が泊まる部屋が並びます。«家の中に神社がある!» と驚く人も多いでしょう。","家の横には小さな川が流れています。講の人々はこの水で身を清めてから、お山へ向かったといわれます。登山の前の晩、御神前でお祈りをし、ろうそくのゆれる部屋で «明日はいよいよお山だ» と、胸を高鳴らせたことでしょう。","江戸時代の後半には、上吉田に数十軒もの御師の家が並んでいたといわれます。明治以降、富士講はしだいにおとろえ、御師の家もその多くが姿を消しました。旧外川家住宅は、その暮らしを今に伝える数少ない一軒です。2013年、富士山とともに世界文化遺産の一部になりました。"],"tl":[["1733年","富士講の行者・食行身禄が富士山で断食し、入定する。以後、富士講が広まる"],["1768年","外川家の主屋が建てられる"],["江戸時代後期","江戸で富士講が大流行し、上吉田の御師町がにぎわう"],["幕末ごろ","主屋の奥に裏座敷が増築されたとされる"],["明治以降","富士講がおとろえ、御師の家が減っていく"],["2013年","世界文化遺産「富士山」の構成資産に"]],"who":[["外川家の御師","富士講の人々を泊め、祈りと登山の世話をした"],["食行身禄","富士講を広めた行者。江戸の庶民に大きな影響を与えた"],["江戸の富士講の人々","講を組んで富士山に登った庶民"]],"deep":["«御師» は «御祈祷師» の略とされ、伊勢神宮などにもいた宗教者です。富士山の北口では、上吉田・河口などに御師町が形成されました。","上吉田の御師の家は、通りから奥まった場所に建ち、«タツミチ» と呼ばれる細い参道で結ばれるのが特徴です。家の敷地の «奥行き» が信仰の空間をつくっています。","旧外川家住宅には、講の人々が残した «まねき» （講の名や紋を染めた旗）などの資料が伝わり、どの地域の講が泊まったかがわかります。","食行身禄は1733年に富士山の烏帽子岩で断食して亡くなり、その教えが江戸の町人に広がって «江戸八百八講» と呼ばれるほど富士講が増えたといわれます。","富士吉田の御師の家で公開されているのは旧外川家住宅など少数で、ほかの多くは今も住まいとして使われ、非公開です。"],"look":["通りから奥へのびる «タツミチ»","主屋の御神前の部屋","講の人々が残した資料や «まねき»","家の横を流れる水路（禊の場とされる）"],"q":["富士講の人々を自分の家に泊め、お祈りや登山の世話をした人たちを何と呼ぶ？","御師（おし）。上吉田には御師の家が立ち並んでいました。"],"koji":[],"myth":"御師の家の数や水路での禊の話は伝承・推定を含む。","img":["御師","富士講","北口本宮冨士浅間神社"],"wp":"旧外川家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:7/79/The_former-Togawa_family_house.JPG",4000,3000,"旧外川家住宅"],["c:2/24/Fujinomiya_Hongu_Sengen_Taisha_Honden.jpg",2816,2112],["c:d/d9/Kodaki_fuji_frm_shojinko.jpg",1530,1024],["c:7/7a/Oshi_20190826a.jpg",4454,2927,"御師"],["c:5/5a/Monks_walk_through_the_approach_of_Northern_Fuji_Sengen_Shrine.JPG",2126,1595,"富士講"],["c:8/87/Kitaguchi_Hongu_Fuji_Sengen_jinja_Torii.jpg",4480,2980,"北口本宮冨士浅間神社"]]},{"id":"19_yoshida_hi","n":"吉田の火祭り（北口本宮の鎮火祭）","yomi":"よしだのひまつり","cat":"伝承","rank":"A","y":1700,"era":["edo"],"sh":"国の重要無形民俗文化財","ad":"富士吉田市上吉田（北口本宮冨士浅間神社・諏訪神社と周辺の町）","st":"富士急行富士山駅から歩いて約20分。祭りの日は交通規制あり","la":35.4757,"lo":138.7937,"hook":"夏の終わりの夜、町じゅうの大松明に火がともる。富士山の «山じまい» を告げる、日本三奇祭のひとつ。","lead":"毎年8月26日・27日に、富士吉田市の北口本宮冨士浅間神社と諏訪神社で行われる祭りです。町の通りに並べた高さ約3mの大松明に次々と火がつけられ、夜の町が炎に包まれます。富士山の夏山シーズンの終わりを告げる祭りで、国の重要無形民俗文化財です。","story":["8月26日の夕方、富士吉田の町に神輿のかけ声がひびきます。北口本宮冨士浅間神社の境内から、二基の神輿が町へくり出すのです。ひとつはふつうの神輿、もうひとつは富士山の形をした真っ赤な神輿 «御山さん»。重さは1トンほどともいわれ、担ぎ手たちは地面にたたきつけるようにして進みます。","日が暮れると、いよいよ火祭りの始まりです。町の通りにずらりと並んだ大松明に、次々と火がつけられていきます。高さは約3m。その数は数十本にもなります。家々の前でも井桁に組んだ薪が燃やされ、町全体が炎の川のようになります。«熱い! まぶしい!» 夜空が赤くそまり、火の粉が舞い上がります。","«なぜ、こんなに火を燃やすの?» この祭りは、もともと «鎮火祭» と呼ばれます。富士山の神・木花開耶姫は、燃えさかる産屋の中で無事に子どもを生んだという神話があり、火の中でも身を守る神とされました。火を燃やして神を祭り、噴火や火事をしずめる願いがこめられているのです。","この祭りは、富士山の «山じまい» の祭りでもあります。江戸時代、富士山に登れるのは夏の間だけ。多くの富士講の人々が御師の家に泊まり、お山に登りました。祭りの炎は «今年もみんな無事に登れました、ありがとう» という感謝のしるしでもあったのです。","翌27日には、«すすき祭り» と呼ばれる行事があり、すすきの穂を持った人々が神輿をむかえます。2012年、この祭りは国の重要無形民俗文化財になりました。富士山の麓で、火を恐れ、火を祭ってきた人々の祈り。その熱さを肌で感じられる、忘れられない一夜です。"],"tl":[["伝・古代","富士山の神をまつる祭りとして始まったと伝わる"],["江戸時代","富士講の隆盛とともに «山じまい» の祭りとして盛大に"],["1733年","食行身禄の入定を機に、江戸で富士講が広まる"],["毎年8月26日","鎮火祭。神輿の渡御と大松明の点火"],["毎年8月27日","すすき祭り"],["2012年","«吉田の火祭り» が国の重要無形民俗文化財に"]],"who":[["木花開耶姫命","北口本宮冨士浅間神社の祭神。火の中で子を生んだ神話をもつ"],["上吉田の氏子たち","神輿をかつぎ、松明を立てて祭りをささえる"],["富士講の人々","夏の登山を終え、祭りで感謝をささげた"]],"deep":["«吉田の火祭り» は北口本宮冨士浅間神社と、その境内にある諏訪神社の両社の祭りです。もとは諏訪神社の祭りだったという見方もあり、成り立ちには諸説あります。","«御山さん» は富士山をかたどった赤い神輿で、担ぎ手が «御旅所» に着くと、地面に何度もおろす所作が見どころです。重さは1トン前後といわれます。","大松明は、上吉田の各町内がそれぞれ用意して立てるもので、町の人々の協力で祭りが成り立っています。","«日本三奇祭» の一つに数えられることがありますが、どの祭りを三奇祭とするかは諸説あり、決まったものではありません。","北口本宮冨士浅間神社の本殿は江戸時代初めの建物で国の重要文化財。境内の大鳥居は «富士山大鳥居» と呼ばれ、木造の鳥居として大きなものです。"],"look":["赤い富士山形の神輿 «御山さん»","通りに並ぶ大松明の点火（26日夕方〜夜）","北口本宮冨士浅間神社の本殿と大鳥居","翌日のすすき祭り"],"q":["吉田の火祭りで町を進む、富士山の形をした赤い神輿の呼び名は？","«御山さん»。重さは1トンほどといわれ、担ぎ手が勢いよく地面におろします。"],"koji":[],"myth":"祭りの起源、日本三奇祭の数え方、御山さんの重さは諸説・伝承。","img":["北口本宮冨士浅間神社","富士講","木花咲耶姫"],"wp":"吉田の火祭","rel":{"ev":[],"grave":[]},"ph":[["c:d/d2/Yoshida_Fire_Festival_20190826b.jpg",3457,2956,"吉田の火祭"],["c:5/59/Yoshida_Fire_Festival_to_be_prepared_on_the_road.JPG",4000,3000],["c:3/31/Yoshida_Fire_Festival_large_torches_placed_on_the_sidewalk_B.JPG",4000,3000],["c:f/fd/Yoshida_Fire_Festival_Myojin-Mikoshi.JPG",4000,3000],["c:6/6d/Yoshida_Fire_Festival_Igeta_torches.JPG",4000,3000],["c:4/4a/Torches_burning_Yoshida_Fire_Festival_B.JPG",4000,3000],["c:8/82/Torches_burning_Yoshida_Fire_Festival_A.JPG",4000,3000],["c:7/79/The_former-Togawa_family_house.JPG",4000,3000]]},{"id":"19_oshino","n":"忍野八海（富士講の巡礼霊場）","yomi":"おしのはっかい","cat":"伝承","rank":"A","y":1843,"era":["edo"],"sh":"国の天然記念物","ad":"南都留郡忍野村忍草","st":"富士急行線 富士山駅からバスで約20分、«忍野八海»下車すぐ","la":35.4602,"lo":138.833,"hook":"富士山に降った雪と雨が、長い年月をかけて地下をくぐり、ここで青く澄んだ泉になって湧き出す。江戸の人々はその泉を «神さまの池» として巡った。","lead":"忍野八海は、富士山のふもとの忍野村にある8つの湧き水の池です。江戸時代には富士山にお参りする «富士講» の人たちが、登山の前に身を清める «霊場» として巡りました。いまは世界文化遺産 «富士山» の構成資産にもなっています。","story":["朝の忍野村。池をのぞきこむと、水があまりに透きとおっていて、底の水草が風にゆれるように見えます。«この水はどこから来たの?» 答えは富士山です。山に降った雪や雨が溶岩のすきまにしみこみ、長い時間をかけて地下を流れ、ここで湧き出しているのです。何十年もかかるといわれますが、正確な年数は研究によって見方が分かれます。","むかし、このあたりには大きな湖があったと伝わります。富士山の噴火で流れ出た溶岩が川をせき止めてできた湖で、やがて水が抜けて盆地になり、湧き水の池だけが残った――そんな成り立ちが語られています。«宇津湖（うつこ）» という名前で呼ばれることもありますが、細かい時期などは諸説あります。","江戸時代、富士山は «登って拝む山» でした。江戸の町には «富士講» という信者のグループがたくさん生まれ、夏になると白い行衣（ぎょうい）を着て富士をめざしました。«山に登る前に、心も体も清めねば» ――その清めの場の一つが忍野の池でした。","天保14年（1843年）、富士講の人々は、忍野の8つの池を «元八湖（もとはっこ）» と呼ばれる霊場として整えたといわれます。池それぞれに八大竜王がまつられ、和歌も詠まれました。出口池、お釜池、底抜池、銚子池、湧池、濁池、鏡池、菖蒲池。巡礼者はひとつずつ池をまわり、水を浴びたり手を合わせたりしながら進みました。","いまの忍野八海は、国内外からの旅行者でにぎわう観光地です。でも池のほとりに立つ小さな石碑や祠に目を向けると、«富士山を拝むための聖地» だったころの姿が見えてきます。にぎやかな売店の向こうに、静かな信仰の歴史が眠っているのです。"],"tl":[["約1万年前以降","富士山の噴火と溶岩流で、忍野の地形ができていったとされる"],["1843年（天保14年）","富士講の人々が8つの池を霊場として整えたといわれる"],["1934年","«忍野八海» が国の天然記念物に指定"],["1985年","環境庁（当時）の «名水百選» に選ばれる"],["2013年","世界文化遺産 «富士山―信仰の対象と芸術の源泉» の構成資産に"]],"who":[["富士講の人々","江戸を中心に広がった富士山信仰の集団。池を巡って身を清めた"],["忍草の村人","湧き水を暮らしと田畑に使い、池を守ってきた"],["八大竜王","池ごとにまつられた水の神々（信仰上の存在）"]],"deep":["«八海» の名は、富士山のまわりの湖を巡る «外八海»、山頂近くの池などを巡る «内八海» という富士講の巡礼に由来します。忍野の池はそれにならった霊場だと説明されます。","8つの池のうち «お釜池» はいちばん小さな池ですが、湧く水の量は多いといわれます。池ごとに大きさも深さも色もちがうので、見比べると楽しいです。","«底抜池» は、観光客の多い場所から少し離れた私有の敷地（有料の資料館の中）にあります。8つすべてを巡るなら事前に場所を確かめておきましょう。","湧き水の温度は一年を通してほぼ一定（10℃台前半ほど）といわれ、冬でも凍りにくく、夏はひんやり冷たく感じます。","世界遺産の構成資産としては «忍野八海» の8つの池がまとめて登録されています。信仰の場としての価値が認められた点が大事です。","忍野の «湧池» は、富士講の巡礼で重要な池の一つとされ、水の青さで特に人気があります。"],"look":["«湧池» の底までのぞける青い水","池ごとの石碑（八大竜王の名や和歌が刻まれたもの）","«出口池»（少し離れていて静か）","富士山と池がいっしょに見える場所","中池（あとから作られた池で、八海には入らない）"],"q":["忍野八海の水は、もともとどこに降った雨や雪？","富士山です。溶岩のすきまを長い時間かけて流れ、忍野で湧き出しています。"],"koji":[{"w":"六根清浄","m":"目・耳・鼻・舌・身・心を清らかにすること。富士講の人々が山に登るときに唱えたことば"}],"myth":"湖があったという成り立ち、水が湧き出すまでの年数、1843年の霊場整備の細部には諸説ある。","img":["富士講","富士山","忍野村","湧池"],"wp":"忍野八海","rel":{"ev":[],"grave":[]},"ph":[["c:2/22/231028_Waku-ike_Oshino_Hakkai_springs_Oshino_Yamanashi_pref_Japan01s3.jpg",5472,3648,"忍野八海"],["c:2/22/%E5%BF%8D%E9%87%8E%E5%85%AB%E6%B5%B7_-_panoramio_%282%29.jpg",5184,3456],["c:1/1b/%E5%BF%8D%E9%87%8E%E5%85%AB%E6%B5%B7_-_panoramio_%281%29.jpg",5184,3456],["c:f/fd/Oshino-Hakkai-Nakaike.jpg",5472,3648],["c:9/94/231028_Nigori-ike_Oshino_Hakkai_springs_Oshino_Yamanashi_pref_Japan02s3.jpg",5472,3648],["c:5/53/231028_Naka-ike_Oshino_Hakkai_springs_Oshino_Yamanashi_pref_Japan01s3.jpg",5472,3648],["c:a/a0/231028_Deguchi-ike_Oshino_Hakkai_springs_Oshino_Yamanashi_pref_Japan05s3.jpg",5472,3648],["c:1/1b/080103_hakkai_fuji.jpg",3872,2592]]},{"id":"19_funatsu","n":"船津胎内樹型（富士講の胎内くぐり）","yomi":"ふなつたいないじゅけい","cat":"伝承","rank":"A","y":1800,"era":["heian","edo"],"sh":"国の天然記念物","ad":"南都留郡富士河口湖町船津","st":"富士急行線 河口湖駅から周遊バスで約20分、«河口湖フィールドセンター» 下車","la":35.4697,"lo":138.7392,"hook":"溶岩の洞窟にもぐると、天井に «あばら骨» のような模様。江戸の人々はここを «富士山の母のおなか» だと信じ、くぐって生まれ変わろうとした。","lead":"船津胎内樹型は、富士山の溶岩が大きな木を包みこみ、木が焼けてなくなったあとにできた洞窟です。中が人の体の内側のように見えることから «胎内（おなかの中）» と呼ばれ、富士講の人々が «胎内くぐり» をする聖地になりました。","story":["むかし、富士山が火をふいたとき、真っ赤な溶岩が森の中へ流れこみました。溶岩は大きな木々をぐるりと包み、そのまま冷えて固まります。中の木は燃えたり腐ったりして、あとには木の形の «穴» だけが残りました。これが «溶岩樹型（じゅけい）» です。","船津の樹型はいくつもの穴がつながっていて、人がやっとはって進めるほどのトンネルになっています。内側の壁には、溶岩が冷えるときにできたしわや、ろっ骨のような筋が見られます。«まるで人のおなかの中のようだ» ――そう感じた人々は、ここを «母の胎内» と呼びました。","江戸時代、富士山を拝む富士講の人々は、山そのものを神さまだと考えていました。«富士の胎内をくぐれば、一度死んで清らかに生まれ変われる» 。暗い穴にもぐり、体をかがめて進み、また光の下に出てくる。それは、生まれ直しの儀式だったのです。","洞窟の入口には «無戸室浅間神社（うつむろせんげんじんじゃ）» がまつられています。«無戸室» とは、戸のない部屋のこと。神話で、木花開耶姫（このはなのさくやびめ）が戸のない産屋にこもり、火を放って子を産んだという話に重ねた名だといわれます。富士山の神さまとされる姫と «安産» が、ここで結びついているのです。","いまでは見学ルートが整えられ、ヘルメットをかぶって中に入れます（季節や時間に注意）。低い天井に頭を下げ、ひんやりした空気の中を進むと、江戸の巡礼者たちがなぜここを特別な場所だと思ったのか、体で感じられるはずです。"],"tl":[["平安時代ごろ","富士山の噴火による溶岩流（剣丸尾溶岩流とされる）が流れ、樹型ができたと考えられる"],["江戸時代","富士講の人々が «胎内» として信仰し、胎内くぐりを行う"],["1929年","«船津胎内樹型» が国の天然記念物に指定"],["2013年","世界文化遺産 «富士山» の構成資産に登録"]],"who":[["富士講の人々","洞窟を «胎内» として巡り、生まれ変わりを願った"],["木花開耶姫","富士山の神とされる女神。無戸室浅間神社の神話と結びつく"],["長谷川角行","富士講の祖とされる行者。胎内の信仰と結びつけて語られることがある"]],"deep":["樹型ができたもとの溶岩流は «剣丸尾（けんまるび）溶岩流» と説明されることが多く、平安時代の噴火によるものとされます。年代については研究によって見方があります。","富士山周辺には «吉田胎内樹型» もあり、こちらも国の天然記念物で世界遺産の構成資産です。ただし吉田胎内はふだん非公開で、年に一度の祭りの日などに限って公開されることが知られています。","内部には «肋骨»«乳房» などに見立てられた部分があり、信者は体の各部に見立てた場所を拝みながら進んだといわれます。","«胎内くぐり» は富士山だけでなく、各地の岩屋や仏像の胎内でも行われた «擬死再生（一度死んで生まれ変わる）» の儀礼の一つと考えられています。","入口の «無戸室浅間神社» は、樹型そのものを御神体のように扱う、洞窟と一体の小さな社です。","見学は河口湖フィールドセンター側で受け付けています。内部は狭く、しゃがんで進む場所もあるので、動きやすい服装がおすすめです。"],"look":["無戸室浅間神社（洞窟の入口）","天井や壁の «あばら骨» のような溶岩のしわ","体をかがめて通る狭いトンネル","周辺の青木ヶ原の溶岩の上の森"],"q":["«胎内くぐり» をした富士講の人々は、何を願ったでしょう？","一度 «母の胎内» にもどり、清らかな体で生まれ変わることを願いました。"],"koji":[],"myth":"発見のいきさつや年代、長谷川角行との結びつきは伝承による部分が大きい。","img":["富士講","吉田胎内樹型","木花咲耶姫","青木ヶ原"],"wp":"船津胎内樹型","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/%E3%80%8E%E8%88%B9%E6%B4%A5%E8%83%8E%E5%86%85%E7%A5%9E%E7%A4%BE%E3%80%8F_%E5%AF%8C%E5%A3%AB%E5%B1%B1%E3%83%91%E3%83%AF%E3%83%BC%E3%82%B9%E3%83%9D%E3%83%83%E3%83%88%E3%81%AE%E6%B4%9E%E7%AA%9F%E8%83%8E%E5%86%85%E5%B7%A1%E3%82%8A_-_panoramio.jpg",4896,2752,"船津胎内樹型"],["c:d/d9/Kodaki_fuji_frm_shojinko.jpg",1530,1024],["c:5/5a/Monks_walk_through_the_approach_of_Northern_Fuji_Sengen_Shrine.JPG",2126,1595,"富士講"],["c:a/a2/Yoshida_Tainai_Lava_Tree_Molds.jpg",4032,3024,"吉田胎内樹型"],["c:b/b3/Women_of_Japan_in_art_detail%2C_from-_MET_JIB18_003_%28cropped%29.jpg",1461,2121,"木花咲耶姫"],["c:d/d3/Mount_Ashiwada_and_Mount_Fuji.jpg",5184,3456,"青木ヶ原"]]},{"id":"19_shichimenzan","n":"七面山（身延の奥の院・敬慎院）","yomi":"しちめんざん","cat":"寺社","rank":"A","y":1297,"era":["kamakura","edo"],"sh":"","ad":"南巨摩郡早川町・身延町（山頂近くに敬慎院）","st":"JR身延線 身延駅からバス・車で表参道の登山口へ。登山口から敬慎院まで歩いて4〜5時間ほど","la":35.376,"lo":138.362,"hook":"春分と秋分の朝、この山の上からは、富士山のてっぺんからまっすぐ太陽がのぼる。それを拝むため、人々は夜明け前の山道を登り続けてきた。","lead":"七面山は、日蓮宗の総本山・身延山久遠寺の西にそびえる標高1989mの山です。山頂近くには七面大明神をまつる «敬慎院（けいしんいん）» があり、身延山の «奥の院» のような聖地として、今も多くの人が登っています。","story":["鎌倉時代、日蓮が身延山で教えを説いていたときのことだと伝わります。聴きに来た人々の中に、見なれない美しい女性がいました。«あなたはどなたですか?» と日蓮がたずねると、女性は «七面山に住む者です» と答えたといいます。日蓮が花瓶の水をそそぐと、女性はたちまち竜の姿になり、西の山へ飛び去った――。","この女性こそ、法華経を守る神 «七面大明神（七面天女）» だとされました。日蓮の没後、弟子の日朗と、身延山の土地を寄進した地頭・波木井実長（はきいさねなが）が七面山に登り、大明神をまつったと伝わります。永仁5年（1297年）のことだといわれています。","«なぜ女性が主人公なのに、長いあいだ女性は登れなかったの?» 七面山は古くから女人禁制の山でした。この禁を最初に破ったのが、徳川家康の側室で熱心な日蓮宗の信者だった «お万の方（養珠院）» と伝わります。お万の方はふもとの滝に打たれて身を清め、堂々と山に登ったといわれ、それをきっかけに女性の参詣が認められていったと語られています。","表参道には «一丁目» から «五十丁目» まで、道のりを示す丁目石が立っています。一歩一歩、息を切らしながら登る信者たちは «南無妙法蓮華経» と唱え、励まし合いました。敬慎院には宿坊があり、多くの人が泊まって夜明けを待ちます。","そして春分・秋分のころ。敬慎院の前から東を見ると、遠くの富士山の山頂から太陽が顔を出す «ご来光» が見られることがあります。身延山、そして富士山。山と山がつながる不思議な景色に、人々は昔も今も手を合わせるのです。"],"tl":[["1274年","日蓮が身延山に入る"],["1297年（永仁5年）","日朗と波木井実長が七面山を開いたと伝わる"],["江戸時代初め","お万の方（養珠院）が女性として初めて登ったと伝わる"],["江戸時代","身延山と七面山を結ぶ参詣が盛んになり、講中宿（赤沢宿など）が栄える"],["現在","敬慎院には宿坊があり、ご来光を拝む参拝者が訪れる"]],"who":[["日蓮","日蓮宗の開祖。七面大明神の伝説の中心人物"],["日朗","日蓮の高弟。七面山を開いたと伝わる"],["波木井実長","身延の地頭。身延山を寄進し、七面山開山にもかかわったとされる"],["お万の方（養珠院）","徳川家康の側室。女人禁制を破って登ったと伝わる"]],"deep":["七面山の名は、山が «七つの面（八方に開けた姿）» をもつことに由来する、などの説があり、はっきりしません。","山頂近くの «ナナイタガレ» と呼ばれる大きな崩れは、長い年月をかけて崩れ続けている斜面で、山の荒々しさを物語ります。","春分・秋分に富士山頂から日が昇るのは、七面山と富士山がほぼ東西に並んでいるためです。天気や時期によっては見られないこともあります。","表参道の丁目石は、麓からの道のりを示す目印で、昔の参詣者はこれを数えながら登りました。裏参道もあります。","七面大明神の信仰は七面山だけでなく、全国の日蓮宗寺院に «七面堂» として広まりました。","お万の方がこもったとされる滝は «白糸の滝» と呼ばれ、ふもとの羽衣（はごろも）あたりにあります。"],"look":["表参道の丁目石（数えながら登る）","敬慎院の本堂と宿坊","富士山を正面に望む遥拝所（ご来光）","ふもとの白糸の滝（お万の方の伝説）","山の崩壊地 «ナナイタガレ»（安全な場所から）"],"q":["七面山から、春分・秋分の朝に見られる特別な景色は？","富士山の山頂から太陽がのぼる «ご来光» です。"],"koji":[{"w":"南無妙法蓮華経","m":"法華経に心から帰依しますという意味の題目。日蓮宗の信者が唱える"}],"myth":"七面大明神の出現、1297年の開山、お万の方の初登山はいずれも寺の伝承によるもので、細部には諸説ある。","img":["身延山久遠寺","日蓮","養珠院","日朗"],"wp":"七面山","rel":{"ev":[],"grave":[]},"ph":[["c:9/9a/Mount_Shichimensan.jpg",2048,1536,"七面山"],["c:f/f0/Keishinin-1jpg.jpg",3813,2982],["c:c/c5/Keishinin_trailhead.jpg",3648,2736],["c:6/64/MtShichimen_StoneSteps.jpg",3072,2304],["c:e/e1/MtShichimen_MainTemple_KeiShinIn.jpg",3072,2304],["c:d/d8/MtShichimen_BigKettle.jpg",2304,3072],["c:c/cc/MtShichimen_BigBell.jpg",3072,2304],["c:6/65/MtShichimen_2ndGate.jpg",3072,2304]]},{"id":"19_akasawa","n":"赤沢宿（身延・七面山の講中宿）","yomi":"あかさわじゅく","cat":"町","rank":"A","y":1800,"era":["edo","meiji"],"sh":"国の重要伝統的建造物群保存地区","ad":"南巨摩郡早川町赤沢","st":"JR身延線 下部温泉駅・身延駅方面から車で約40分前後。公共交通は本数が少なく、車が便利","la":35.3905,"lo":138.396,"hook":"山の尾根にへばりつくように並ぶ古い宿。軒先には、泊まった講中が残した木の札がずらりと並ぶ。«信仰の旅人の宿場» が、ほぼそのまま残っている。","lead":"赤沢宿は、身延山と七面山を行き来する参詣者が泊まった «講中宿（こうじゅうやど）» の集落です。山の斜面に古い旅館の建物が並び、国の重要伝統的建造物群保存地区に選ばれています。","story":["江戸時代、日蓮宗を信じる人々は «身延山にお参りしたら、七面山にも登らなければ» と考えました。身延山から七面山へ向かう山道の途中、ひと休みにちょうどよい場所にあったのが赤沢です。«今夜はここで泊まって、明日の朝に山へ» ――そうして赤沢は、参詣者の宿の集落として栄えました。","«講中» とは、同じ信仰をもつ仲間のグループのことです。村や町ごとに講をつくり、お金を積み立てて、みんなで旅に出ました。宿に泊まると、講の名前を書いた木の札 «まねき» を軒先にかけていきました。«うちの講はここに泊まったぞ» という目印であり、次の年もよろしくという約束でもありました。","集落は急な斜面に石垣を積み、その上に家を建てています。道は細い石畳の坂道で、車の通れない昔の参道の雰囲気が残っています。大きな宿の建物は、二階に広い座敷があり、たくさんの参詣者がいっしょに泊まれるようにつくられていました。","明治・大正・昭和と、赤沢は参詣者でにぎわいました。ところが、ふもとから七面山の登山口まで車で行けるようになると、わざわざ赤沢を通る人は減っていきます。«宿の役目が終わってしまった» ――集落は静かになりました。","けれども、その静けさのおかげで古い町並みが残りました。平成5年（1993年）、赤沢は国の重要伝統的建造物群保存地区に選ばれます。軒先の «まねき» を一枚一枚見ていくと、遠くの町から来た講の名前が読み取れ、かつてこの坂道を歩いた大勢の人の足音が聞こえてくるようです。"],"tl":[["江戸時代","身延山と七面山を結ぶ参詣路の宿として栄える"],["明治〜昭和前期","講中の参詣でにぎわい、大きな宿の建物が建てられる"],["昭和後期","登山口まで車で行けるようになり、宿泊客が減る"],["1993年","国の重要伝統的建造物群保存地区に選定"]],"who":[["身延山・七面山の参詣者","講をつくって旅をし、赤沢に泊まった"],["宿を営んだ赤沢の人々","斜面に宿を建て、参詣者をもてなした"],["日蓮","身延山の開祖。この道をたどる信仰のみなもと"]],"deep":["重要伝統的建造物群保存地区の中でも、赤沢は «山村・講中宿» という性格で選ばれた珍しい例として知られています。","軒先の木札 «まねき» には、講の名前や出身地が書かれ、どこから人が来ていたかを知る手がかりになります。関東や東海などの地名が見られます。","宿の建物の多くは、江戸末期から明治以降に建てられたり建て直されたりしたものと考えられています。細かい建築年代は建物ごとに異なります。","斜面の集落なので、敷地は石垣でつくった段々の上にあります。石垣の積み方も見どころの一つです。","赤沢から七面山、身延山への古い参道は、今もハイキング道として歩けるところがあります（道の状況は事前確認を）。","集落の中には今も人が暮らしています。家の中や私有地には勝手に入らず、静かに見学するのがマナーです。"],"look":["軒先にずらりと並ぶ講中札 «まねき»","石畳の坂道と石垣","二階建ての大きな旧宿の建物","集落から見る山並み"],"q":["講中宿の軒先にかけられた、講の名前を書いた木の札を何と呼ぶ？","«まねき» です。泊まった講の目印でした。"],"koji":[],"myth":"","img":["身延山久遠寺","七面山","早川町","重要伝統的建造物群保存地区"],"wp":"赤沢","rel":{"ev":[],"grave":[]},"ph":[["c:0/00/Mt.Shichimen-san_to_look_up_at_from_Akasawa.JPG",4000,3000,"赤沢"],["c:6/64/The_house_of_Akasawa_district_and_Japanese_traditional_umbrella.JPG",4000,3000],["c:f/fd/Stone_pavement_of_Akasawa.JPG",4000,3000],["c:f/f7/Scenery_of_the_Akasawa_district.JPG",4000,3000],["c:4/4f/Old_accommodations_Osakaya_in_Akasawa_and_Mt.Shichimen-san.JPG",4000,3000],["c:0/08/Old_accommodations_Osakaya_in_Akasawa.JPG",4000,3000],["c:e/e7/Old_accommodations_Edoya_in_Akasawa.JPG",4000,3000],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944]]},{"id":"19_takano_ke","n":"旧高野家住宅（甘草屋敷）","yomi":"きゅうたかのけじゅうたく（かんぞうやしき）","cat":"町","rank":"A","y":1830,"era":["edo"],"sh":"国の重要文化財","ad":"甲州市塩山上於曽","st":"JR中央本線 塩山駅北口から歩いて約1分","la":35.7078,"lo":138.73,"hook":"屋根の真ん中がぽこんと持ち上がった大きな家。ここは江戸幕府に «薬の草» を納めていた、甲州の名家の屋敷だった。","lead":"旧高野家住宅は、江戸時代に薬草の «甘草（かんぞう）» を育てて幕府に納めていた高野家の家です。そこから «甘草屋敷» と呼ばれます。甲州の民家らしい «突き上げ屋根» が見どころで、国の重要文化財です。","story":["塩山駅の北口を出ると、すぐ目の前に、屋根の大きな古い屋敷が見えてきます。«駅前にこんな家が?» と驚く人も多い、それが甘草屋敷です。","«甘草» とは、根っこが甘い薬草です。せきを止めたり、ほかの薬の味をととのえたりするため、漢方薬によく使われました。江戸時代、甘草はとても大切な薬でした。高野家はこの甘草を育て、幕府に納める役目を任されていたと伝わります。","とくに8代将軍・徳川吉宗のころ、幕府は国内で薬草を育てることに力を入れました。«外国からの輸入に頼らず、薬を自分たちで» という考えです。高野家の甘草は、幕府の役人が見に来るほど大切にされたといわれます。","この家のもう一つの特徴は屋根です。切妻屋根の真ん中を持ち上げたような «突き上げ屋根» 。«なぜこんな形に?» じつは、屋根裏で蚕（かいこ）を育てる養蚕のために、光と風を取り入れる工夫だと考えられています。甲州の山あいの村に多い形です。","いま屋敷の中に入ると、広い土間、大きな囲炉裏、何段にも分かれた屋根裏が見学できます。ひな人形の季節には、たくさんのおひなさまが飾られることでも知られます。薬と絹――甲州の暮らしを支えた二つの産業が、一軒の家に詰まっているのです。"],"tl":[["江戸時代前期ごろ","高野家が甘草の栽培にかかわるようになったと伝わる"],["18世紀前半","8代将軍吉宗のもとで、幕府が国産の薬草づくりを進める"],["19世紀前半","現在の主屋が建てられたとされる"],["昭和時代","国の重要文化財に指定される"],["現在","甲州市が管理し、一般公開されている"]],"who":[["高野家","甘草を育てて幕府に納めた家。屋敷の持ち主"],["徳川吉宗","8代将軍。薬草の国産化を進めた"],["養蚕に励んだ人々","屋根裏で蚕を育て、甲州の絹を支えた"]],"deep":["«甘草屋敷» の名は、高野家が幕府の御用として甘草を栽培していたことに由来します。敷地の近くには甘草を植えた園もあったと伝わります。","主屋は19世紀前半の建築とされ、切妻造の中央を一段高くした «突き上げ屋根» が特色です。甲州民家の代表例として重要文化財に指定されています。","屋根裏は何層かに分かれ、養蚕の作業場として使われたと考えられています。見学時に屋根裏へ上がれる場合があります。","主屋のほか、蔵などの付属建物も文化財に含まれています。屋敷全体で、甲州の名家の暮らしが分かります。","甲州市塩山は、武田信玄の墓がある恵林寺や、放光寺、向嶽寺にも近く、寺巡りと合わせて歩けます。","甘草は «マメ科» の植物で、根をかむと甘みがあります。現在でも漢方薬の材料として使われています。"],"look":["«突き上げ屋根» の外観（離れて全体を見る）","広い土間と囲炉裏","何段にも分かれた屋根裏（養蚕の場）","季節の展示（ひな飾りなど）"],"q":["甘草屋敷の屋根が真ん中だけ持ち上がっているのはなぜ？","屋根裏で蚕を育てるため、光と風を取り入れる工夫だと考えられています。"],"koji":[],"myth":"甘草栽培の始まりの時期や幕府とのかかわりの細部は家の伝承による部分がある。","img":["甲州市","甘草","塩山駅","恵林寺"],"wp":"甘草屋敷","rel":{"ev":[],"grave":[]},"ph":[["c:5/5a/Old_Takano_House.jpg",2358,1572,"甘草屋敷"],["c:f/f2/Kanzoyashiki_Bunkogura.JPG",4000,3000],["c:7/72/Kanzo-yashiki-umaya.JPG",4000,3000],["c:7/71/Kanzo-yashiki-tatsumigura.JPG",4000,3000],["c:5/5d/Kanzo-yashiki-jimidana.JPG",4000,3000],["c:f/fe/Kanzo-yashiki-doma.JPG",4000,3000],["c:1/19/Dry_persimmon_light_and_shadow.JPG",4000,3000],["c:6/68/Kanzo-Yashiki_Tsurushibina.A.JPG",4000,2250]]},{"id":"19_ando_ke","n":"安藤家住宅（江戸の名主の家）","yomi":"あんどうけじゅうたく","cat":"町","rank":"A","y":1705,"era":["edo"],"sh":"国の重要文化財","ad":"南アルプス市西南湖","st":"JR甲府駅から車で約30分。バスは本数が少なく、車が便利","la":35.6205,"lo":138.493,"hook":"300年以上前に建てられたかやぶきの大屋根。この家の主は、村のもめごとも年貢の取りまとめも引き受ける «村のリーダー» だった。","lead":"安藤家住宅は、江戸時代に西南湖村（にしなんごむら）の «名主（なぬし）» をつとめた安藤家の家です。主屋は江戸時代の中ごろに建てられたとされ、長屋門や蔵とともに国の重要文化財になっています。","story":["甲府盆地の西、釜無川に近い田んぼの中に、大きなかやぶき屋根の屋敷があります。門をくぐると、まるで時代劇の中に入りこんだよう。«ここにはどんな人が住んでいたの?» ――答えは、村をまとめる «名主» の一家です。","江戸時代の村では、殿さまや代官が一人ひとりの百姓と直接やりとりするわけではありませんでした。あいだに立つのが名主です。年貢を集めて納める、村の決まりを伝える、けんかの仲裁をする、水争いの話し合いをする……。名主の家は、村の役場のような場所でもあったのです。","安藤家の主屋は、宝永2年（1705年）ごろに建てられたとされます。«宝永» といえば、富士山の宝永大噴火（1707年）の少し前。村の人々は、この家の広い座敷に集まって相談をしたのでしょう。«今年の米のでき具合はどうだ»«川の堤を直さねば» ――そんな声が聞こえてきそうです。","釜無川の近くは、昔から洪水に悩まされた土地でした。武田信玄がつくったと伝わる «信玄堤» も、この川の水から人々を守るためのものです。名主の家にとって、川と水の管理は大きな仕事だったと考えられます。","いま、安藤家住宅は南アルプス市が公開しています。土間に立つと、太い柱や梁（はり）が屋根を支えているのがよく見えます。季節ごとに、ひな飾りなど昔の暮らしを伝える展示が行われることもあります。"],"tl":[["江戸時代","安藤家が西南湖村の名主をつとめる"],["1705年（宝永2年）ごろ","現在の主屋が建てられたとされる"],["江戸時代後期","長屋門や蔵などが整えられていく"],["昭和時代","国の重要文化財に指定される"],["現在","南アルプス市が管理し、一般公開"]],"who":[["安藤家","西南湖村の名主をつとめた家"],["西南湖村の百姓たち","名主の家に集まり、村のことを話し合った"],["武田信玄","釜無川の治水（信玄堤）と結びつけて語られる戦国大名"]],"deep":["«名主» は関東などでの呼び名で、関西では «庄屋» と呼ぶことが多い村役人です。甲斐国では名主の呼び名が使われました。","主屋の建築年代は、残された資料などから18世紀初めとされます。かやぶきの大屋根と、広い土間・座敷の間取りが特徴です。","主屋のほか、長屋門や蔵なども重要文化財の指定に含まれ、屋敷構え全体で名主の家の姿を伝えています。","屋敷のまわりには堀や生け垣が残り、洪水や外からの侵入に備えた屋敷の構えがうかがえます。","南アルプス市には、古い水路や堤防の跡も多く、水とたたかってきた土地の歴史を歩いて確かめられます。","甲斐国の多くは江戸時代に幕府の直轄地（天領）となった時期が長く、代官のもとで名主が村を治めました。"],"look":["かやぶきの大屋根","太い柱と梁が見える土間","名主が客を迎えた座敷","長屋門と蔵","屋敷を囲む堀や生け垣"],"q":["江戸時代、年貢を取りまとめたり村のもめごとを収めたりした村の役人を何という？","«名主» です。関西では «庄屋» と呼ぶことが多いです。"],"koji":[],"myth":"主屋の建築年は伝わる年代で、細部は資料による。","img":["南アルプス市","名主","信玄堤"],"wp":"安藤家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:b/bb/A_main_building_Ando-_house_Cultural_Properties_of_Japan.JPG",4000,3000,"安藤家住宅"],["c:d/dd/The_gate_of_Ando-house_Cultural_Properties_of_Japan.JPG",4000,3000],["c:f/ff/Mountain_hut_Kita_and_Mount_Kita_2001-10-03.jpg",1600,1024,"南アルプス市"],["c:3/30/Ichinoe_house_of_the_village_headman_edogawa_tokyo_2015.jpg",3389,3193,"名主"],["c:3/38/Outside_of_Shingen_embankment.JPG",4000,3000,"信玄堤"]]},{"id":"19_kofu_kushu","n":"甲府空襲（七夕空襲）","yomi":"こうふくうしゅう","cat":"昭和","rank":"A","y":1945,"era":["showa"],"sh":"","ad":"甲府市中心部（甲府駅周辺・舞鶴城公園の南一帯など）","st":"JR甲府駅周辺。平和について学べる施設は «山梨平和ミュージアム» など","la":35.664,"lo":138.569,"hook":"七夕の夜、短冊に願いを書いた子どもたちの頭上に、焼夷弾の雨が降った。甲府の町の大部分が一夜で焼けた。","lead":"1945年7月6日の深夜から7日にかけて、アメリカ軍のB29爆撃機が甲府の町を空襲しました。七夕の日に重なったため «七夕空襲» とも呼ばれます。町の大部分が焼け、1000人をこえる人が亡くなりました。","story":["1945年の夏。戦争は長引き、日本の各地の都市が次々と空襲を受けていました。«甲府は山に囲まれているから、大丈夫だろう» ――そう思っていた人もいたといわれます。けれども7月6日の夜、空襲警報が鳴りひびきました。","真夜中近く、B29の大編隊が甲府の上空にあらわれます。落とされたのは、建物を燃やすための «焼夷弾»。木造の家が多い町は、あっという間に炎に包まれました。人々は防空頭巾をかぶり、子どもの手を引いて、川の方へ、畑の方へと逃げました。","夜が明けて7月7日。七夕の朝、町の景色は一変していました。市街地の大半が焼け野原になり、多くの家族が家を失いました。亡くなった方は1000人をこえ、けがをした人、焼け出された人は数えきれないほどでした。«今日は七夕なのに――» 。この日の記憶は、甲府の人々に長く刻まれることになります。","«なぜ地方の町まで?» 当時、アメリカ軍は大都市だけでなく、全国の中小の都市にも次々と空襲を行っていました。甲府もその一つとして選ばれたのです。空襲から約1か月後の8月15日、戦争は終わりました。","いま、甲府の中心街には当時の面影はほとんど残っていません。けれども毎年の慰霊の行事や、体験を語り継ぐ活動、平和を学ぶ施設での展示を通して、あの夜のことは伝えられています。町を歩くとき、ここで命を落とした人々のことを、そっと思い出してみてください。"],"tl":[["1941年12月","太平洋戦争が始まる"],["1945年3月〜","東京大空襲をはじめ、全国の都市への空襲が激しくなる"],["1945年7月6日深夜〜7日","甲府空襲。市街地の大部分が焼失"],["1945年8月15日","戦争が終わる"],["戦後","焼け跡から町の復興が進み、空襲の記憶を伝える活動が続く"]],"who":[["甲府の市民","空襲で家や家族を失った人々"],["語り部の人々","空襲の体験を次の世代に伝えてきた"],["石橋湛山","戦前から戦争の拡大を批判した言論人。のち首相。山梨にゆかりがあり、平和ミュージアムの名にも残る"]],"deep":["空襲に来たB29は約130機といわれ、大量の焼夷弾が落とされました。機数や弾の量は資料によって数字に差があります。","亡くなった人の数は、甲府市などのまとめで1100人余りとされることが多いですが、調査によって数字が異なります。","市街地の焼失は約7割以上にのぼるとされ、県庁のまわりや商店街など町の中心がほぼ焼けたといわれます。","«七夕空襲» という呼び名は、7月7日の七夕に重なったことから広まりました。甲府では毎年この時期に、犠牲者をしのぶ行事が行われます。","甲府にはかつて陸軍の歩兵連隊が置かれていました。ただし空襲の目的は、軍の施設だけでなく町そのものを焼くことにあったと考えられています。","«山梨平和ミュージアム―石橋湛山記念館―» では、甲府空襲の資料や証言にふれることができます。"],"look":["甲府駅周辺から舞鶴城公園にかけての中心市街（焼けた範囲を想像しながら歩く）","慰霊碑や記念碑","山梨平和ミュージアムの展示（開館日を確認）"],"q":["甲府空襲が «七夕空襲» と呼ばれるのはなぜ？","空襲が1945年7月6日の深夜から7月7日（七夕）にかけて行われたからです。"],"koji":[],"myth":"機数・死者数・焼失率は資料によって数字が異なる。","img":["日本本土空襲","B-29 (航空機)","甲府市","石橋湛山"],"wp":"甲府空襲","rel":{"ev":[],"grave":[]},"ph":[["c:8/8c/Air_raid_Kofu-City.jpg",2474,1807,"甲府空襲"],["c:6/60/Aerial_photograph_of_Kofu_city_Mount_Atago.jpg",3428,2571],["c:c/c6/B-29s_dropping_bombs.jpg",576,896,"日本本土空襲"],["c:8/8c/B-29_Bomber_on_a_long_range_mission_in_late_1945.jpg",2048,1492,"B-29 (航空機)"],["c:1/17/Kofu_montage.jpg",1186,1568,"甲府市"],["c:1/11/Tanzan_Ishibashi.jpg",1080,1408,"石橋湛山"]]},{"id":"19_sasago_tunnel","n":"笹子トンネル（明治の中央本線の難工事）","yomi":"ささごとんねる","cat":"近代","rank":"A","y":1903,"era":["meiji"],"sh":"","ad":"大月市笹子町〜甲州市大和町","st":"JR中央本線 笹子駅が東口に近い（坑口は線路内のため近づけない。安全な場所から見る）","la":35.604,"lo":138.82,"hook":"甲州街道いちばんの難所・笹子峠。その山の下を、明治の人々は4.6kmものトンネルで掘り抜いた。«汽車で甲府へ» の夢はここで実現した。","lead":"笹子トンネルは、明治時代に中央本線のために掘られた鉄道トンネルです。長さは約4.6kmで、完成した当時は日本でいちばん長い鉄道トンネルでした。この開通で、東京と甲府が汽車で結ばれました。","story":["江戸時代、甲州街道を歩く旅人にとって、笹子峠は «いちばんきつい峠» でした。急な坂道を何時間も登り、また下る。荷物を運ぶ馬も人もへとへとです。«山をくぐって行けたら、どんなに楽だろう» 。","明治時代、鉄道が日本中に広がりはじめると、東京と甲府・長野方面を結ぶ «中央線» の計画が進みました。最大の壁が、この笹子峠の山です。そこで、山の下にトンネルを掘ることになりました。明治29年（1896年）に工事が始まります。","工事は東と西の両側から掘り進められました。固い岩、わき出す水、たまる煙。今のような大型の機械はなく、多くの作業員がつるはしや発破（ダイナマイト）を使って少しずつ掘りました。事故で命を落とした人もいたと伝えられています。","そして明治35年（1902年）、ついに東と西の穴がつながりました。«貫通だ!» 。翌明治36年（1903年）、中央本線が甲府まで開通し、汽車がこのトンネルを通るようになりました。東京から甲府への旅は、何日もかかる徒歩の旅から、半日ほどの汽車の旅へと変わったのです。","トンネルの入口には、明治の政治家が書いた言葉の額（扁額）がかかげられました。東口は伊藤博文の «因地利（地の利による）»、西口は山県有朋の «代天工（天の工に代わる）» 。自然の山に人の力で道を開いた誇りが、この言葉にこめられています。"],"tl":[["江戸時代","笹子峠は甲州街道最大の難所として知られる"],["1896年（明治29年）","笹子トンネルの工事が始まる"],["1902年（明治35年）","トンネルが貫通"],["1903年（明治36年）","中央本線が甲府まで開通し、トンネルの使用が始まる"],["昭和時代","複線化のため新しいトンネルが掘られ、上り・下りで別々のトンネルを使うように"],["2012年12月","並行する中央自動車道の笹子トンネル（道路）で天井板が落ち、9人が亡くなる事故"]],"who":[["伊藤博文","東口の扁額 «因地利» を書いたとされる"],["山県有朋","西口の扁額 «代天工» を書いたとされる"],["工事にかかわった人々","固い岩と水にいどみ、トンネルを掘り抜いた"]],"deep":["長さは約4,656m。当時の日本の鉄道トンネルで最長で、のちに清水トンネル（1931年）などに抜かれるまで長く上位にありました。","扁額 «因地利» と «代天工» は、トンネル工事への思いを表す言葉として知られます。明治の長いトンネルには、有力者が書いた扁額をかかげることがよくありました。","工事では、トンネルの中で機械を動かしたり明かりをつけたりするために電気が使われたといわれ、明治の工事技術の見本の一つでした。","複線化のあと、上り線と下り線で別々のトンネルを使うようになりました。明治のトンネルは今も使われています。","同じ名前の «笹子トンネル» は中央自動車道にもあり、2012年の天井板落下事故はそちらで起きました。鉄道トンネルとは別のものです。亡くなった方々への慰霊が今も続けられています。","トンネルの上の笹子峠には、昭和13年（1938年）に完成した道路の «笹子隧道» もあり、こちらは国の登録有形文化財です。"],"look":["東口の坑口と扁額（安全な場所から）","笹子駅周辺の山あいの景色","笹子峠の旧道と «笹子隧道»（車・徒歩、状況を確認）","近くの «矢立の杉»"],"q":["笹子トンネルの東口にかかげられた扁額の言葉は？","«因地利» です。伊藤博文が書いたとされます。西口は山県有朋の «代天工»。"],"koji":[],"myth":"工事中の犠牲者の数や電気の使い方の細部ははっきりしない。","img":["中央本線","笹子駅","笹子峠","伊藤博文"],"wp":"笹子トンネル","rel":{"ev":[],"grave":[]},"ph":[["c:3/36/Aerial_view_several_tunnels_Sasagotoge_pass._West_entrance_side.jpg",2461,1780,"笹子トンネル"],["c:9/9f/Aerial_view_several_tunnels_Sasagotoge_pass._East_entrance_side.jpg",2456,1771],["c:e/e3/JRE_Chuo-Main-Line_Multiple-lines.jpg",2736,1824,"中央本線"],["c:f/fe/JR_Chuo-Main-Line_Sasago_Station_building.jpg",4308,2495,"笹子駅"],["c:9/9f/Sasagotouge.JPG",240,320,"笹子峠"],["c:7/7d/IT%C5%8C_Hirobumi.jpg",1024,1392,"伊藤博文"]]},{"id":"19_nanbu","n":"南部氏発祥の地（南部町）","yomi":"なんぶしはっしょうのち","cat":"伝承","rank":"A","y":1189,"era":["kamakura"],"sh":"","ad":"南巨摩郡南部町南部","st":"JR身延線 内船駅から車で。町内の史跡巡りは車が便利","la":35.287,"lo":138.452,"hook":"青森・岩手をおさめた大名 «南部氏»。そのふるさとは、はるか南の山梨県・富士川のほとりにあった。","lead":"江戸時代に盛岡藩や八戸藩をおさめた南部氏は、もともと甲斐国（山梨県）の武士でした。先祖の南部光行が、甲斐国の «南部» という土地をおさめたことから南部氏を名乗ったといわれます。いまの南部町は、その発祥の地とされています。","story":["平安時代の終わり、甲斐国には «甲斐源氏» と呼ばれる武士の一族が広がっていました。その中の加賀美遠光（かがみとおみつ）の子・光行が、富士川沿いの南部の地をおさめ、«南部三郎光行» と名乗ったと伝わります。これが南部氏の始まりです。","1189年、源頼朝は奥州藤原氏をほろぼす戦い（奥州合戦）を起こしました。光行もこの戦いに加わり、手柄を立てて、はるか北の «糠部（ぬかのぶ）» の土地をもらったといわれます。今の青森県東部から岩手県北部にかけての地域です。","«なぜ山梨の武士が東北に?» 鎌倉時代には、手柄を立てた武士が遠い土地をもらうことがよくありました。南部氏の一族は少しずつ北へ移り、やがて東北の大きな大名へと成長していきます。江戸時代には盛岡藩、八戸藩などをおさめました。","一方、甲斐に残った一族もいました。光行の子の一人とされる南部（波木井）実長は、身延の地をおさめ、日蓮をむかえて身延山久遠寺のもとをひらいた人物として知られます。«南部» の名は、山梨と東北、そして日蓮宗の歴史をつないでいるのです。","いまの南部町には、南部氏ゆかりと伝わる寺や史跡があり、東北の南部氏ゆかりの町との交流も行われています。富士川の流れを見ながら、この小さな町から東北の大名が生まれたことを思うと、歴史のスケールの大きさに驚かされます。"],"tl":[["平安時代末","甲斐源氏の加賀美遠光の子・光行が南部の地をおさめたと伝わる"],["1189年","奥州合戦。光行が手柄を立て糠部の地を得たといわれる"],["1274年","南部（波木井）実長のもとに日蓮が身延に入る"],["鎌倉〜室町時代","南部氏の本拠がしだいに東北へ移る"],["江戸時代","南部氏が盛岡藩・八戸藩などの大名となる"]],"who":[["南部光行","南部氏の祖とされる人物。甲斐国南部の地をおさめた"],["加賀美遠光","光行の父。甲斐源氏の一族"],["南部（波木井）実長","光行の子とされる。身延に日蓮をむかえた"],["源頼朝","奥州合戦を起こし、功のあった武士に土地を与えた"]],"deep":["南部光行が東北へ本格的に移った時期や、本当に本人が東北へ下ったのかについては諸説があり、はっきりしません。","南部氏は新羅三郎義光を祖とする甲斐源氏の一族で、武田氏とは遠い親戚にあたります。","波木井実長は日蓮の有力な支援者で、身延山久遠寺の開基とされます。のちに日蓮の弟子の間の対立にもかかわりました。","盛岡藩の南部氏は、江戸時代を通して東北の大藩として続きました。家紋 «向鶴（むかいづる）» はよく知られています。","青森県の三戸町や八戸市などには南部氏の本拠地があり、山梨の南部町とのゆかりが語られています。","«南部» という地名は、甲斐国の南の端に近い場所であったことにちなむとも考えられています。"],"look":["富士川と南部の町並み","南部氏ゆかりと伝わる寺院","身延山久遠寺（波木井実長ゆかり、車で移動）"],"q":["南部氏が江戸時代におさめたのは、今の何県あたり？","岩手県・青森県のあたりです（盛岡藩・八戸藩など）。"],"koji":[],"myth":"光行の東北下向の時期、南部町の史跡と南部氏の結びつきには伝承が多く、諸説ある。","img":["南部光行","盛岡藩","波木井実長"],"wp":"南部氏","rel":{"ev":[],"grave":[]},"ph":[["c:2/20/Nanbu_Mitsuyuki.jpg",3977,2433,"南部光行"],["c:3/31/Nanbu_sanenaga.jpg",1386,1811,"波木井実長"],["c:e/eb/JR_Central_Utsubuna_Station_building.jpg",5328,4000,"近く: 内船駅"],["c:4/41/Yamanashi-nanbu3.JPG",2048,1536,"近く: アルカディア南部総合公園"],["c:e/e6/%E5%8D%97%E9%83%A8%E8%AD%A6%E5%AF%9F%E7%BD%B2_-_panoramio.jpg",1600,1200,"近く: 南部警察署"],["c:4/46/%E5%8D%97%E9%83%A8%E4%B8%AD%E5%AD%A6%E6%A0%A1_-_panoramio.jpg",1600,1200,"近く: 南部町立南部中学校 (山梨県)"],["c:c/cf/Naisenji03.jpg",4096,2304,"近く: 内船寺"],["c:9/92/%E5%85%AB%E6%B4%A5%E5%BE%A1%E5%B6%BD%E7%A5%9E%E7%A4%BE_-_panoramio.jpg",1600,1200,"近く: 宝生教"]]},{"id":"19_kai_kuroma","n":"甲斐の黒駒（聖徳太子の愛馬伝説）","yomi":"かいのくろこま","cat":"伝承","rank":"A","y":598,"era":["kofun","asuka","heian"],"sh":"","ad":"笛吹市御坂町上黒駒・下黒駒","st":"JR中央本線 石和温泉駅から車で約15分","la":35.595,"lo":138.688,"hook":"聖徳太子は、甲斐国から贈られた黒い馬に乗って空をかけ、富士山を越えたという。その馬の名を、今も山梨の地名が伝えている。","lead":"«甲斐の黒駒» は、昔の甲斐国（山梨県）で育てられたすばらしい黒い馬のことです。『日本書紀』の歌にも登場し、聖徳太子の愛馬だったという伝説もあります。笛吹市には «黒駒» という地名が残っています。","story":["山梨は、山に囲まれた盆地です。昔から «よい馬が育つ国» として知られていました。広い草原と冷たい水、きびしい冬。その中で育った馬は、足が強く、たくましかったといわれます。","『日本書紀』には、こんな話があります。雄略天皇のころ、ある大工が失敗をとがめられ、処刑されそうになりました。天皇はあとで思い直し、«死刑をやめよ» という知らせを馬で走らせます。その馬こそ «甲斐の黒駒»。仲間たちは «甲斐の黒駒がいなかったら、命はなかっただろう» と歌ったと記されています。","もっと有名なのが、聖徳太子の伝説です。平安時代にまとめられた『聖徳太子伝暦（でんりゃく）』によると、598年、甲斐国から四本の足だけが白い黒い馬が献上されました。太子がこの馬に乗ると、馬は空へかけあがり、富士山の頂上を越えて、3日で都へもどったといいます。«なんと、空を飛ぶ馬!» 。","もちろん、馬が空を飛ぶことは伝説です。でも、そんな話が生まれるほど、甲斐の馬は都の人々にとって特別な存在でした。平安時代の法律の本『延喜式』には、甲斐国に天皇のための牧場 «御牧（みまき）» が置かれていたことが記されています。","いまの笛吹市御坂町には «上黒駒»«下黒駒» という地名があり、黒駒の伝説と結びつけて語られています。幕末には、この地から «黒駒勝蔵» という侠客も出ました。山あいの静かな里で、空をかける黒い馬の姿を想像してみてください。"],"tl":[["雄略天皇のころ（5世紀後半とされる）","『日本書紀』に «甲斐の黒駒» の歌が記される"],["598年（推古6年）","甲斐国から黒駒が聖徳太子に献上されたと『聖徳太子伝暦』は伝える"],["平安時代","『延喜式』に甲斐国の御牧（天皇の牧場）が記される"],["幕末","上黒駒出身の黒駒勝蔵が活動"]],"who":[["聖徳太子","黒駒に乗って富士山を越えたと伝わる"],["雄略天皇","『日本書紀』の黒駒の歌の場面に登場する天皇"],["黒駒勝蔵","幕末の侠客。上黒駒の出身"]],"deep":["『日本書紀』雄略天皇13年の条には、大工の猪名部真根（いなべのまね）が処刑されかけ、使者が甲斐の黒駒で走って赦免を伝えた話と、黒駒をたたえる歌が載っています。","『聖徳太子伝暦』は平安時代に書かれた太子の伝記で、多くの不思議な話を含みます。黒駒の話もその一つで、史実とは考えられていません。","『延喜式』では、甲斐国に «柏前牧»«真衣野牧»«穂坂牧» の3つの御牧が記され、毎年都に馬を送っていました。","聖徳太子が黒駒に乗って富士山を越える場面は、鎌倉時代などの絵巻や絵伝にもくり返し描かれました。","甲府盆地では古墳時代の遺跡から馬具や馬の骨が見つかっており、古くから馬が飼われていたことがわかります。","«黒駒» の地名と太子伝説を結びつける話は地元で語り継がれていますが、どこまでさかのぼれるかははっきりしません。"],"look":["«上黒駒»«下黒駒» の地名が残る里の風景","御坂の山並み（黒駒が越えたと伝わる富士山の方角）","周辺の古墳や神社"],"q":["聖徳太子の黒駒は、どんな見た目だったと伝わる？","体は黒く、四本の足だけが白かったと伝わります。"],"koji":[],"myth":"聖徳太子の黒駒の話は『聖徳太子伝暦』などの伝説であり、史実ではない。地名との結びつきも伝承。","img":["聖徳太子","延喜式","黒駒勝蔵","御牧"],"wp":"甲斐の黒駒","rel":{"ev":[],"grave":[]},"ph":[["c:a/a5/Misaki-uma.jpg",1280,960,"甲斐の黒駒"],["c:3/30/Kai-Choshizuka-kofun_%E2%84%961.JPG",4000,3000],["c:e/e0/Hokkaido_Pony.jpg",3648,2736],["c:9/96/Ofuneishi_Kofun_Shida_Kai_City.jpg",2581,1881],["c:9/9e/Prince_Shotoku_with_Two_Princes_by_Kano_Osanobu_1842.png",1113,1495],["c:4/45/Sh%C5%8Dtoku_Taishi_Sh%C5%8Dmanky%C5%8D_K%C5%8Dsan.jpg",1083,1518,"聖徳太子"],["c:b/bb/Engishiki_Kujo_edition.jpg",1001,527,"延喜式"]]},{"id":"19_shiroyama","n":"白山城（武田氏発祥の地の山城）","yomi":"しろやまじょう（はくさんじょう）","cat":"城","rank":"B","y":1570,"era":["heian","muromachi","azuchi"],"sh":"国指定史跡","ad":"韮崎市神山町鍋山","st":"JR中央本線 韮崎駅から車で約15分。武田八幡宮の近くから山道を歩いて登る","la":35.698,"lo":138.43,"hook":"«武田» という名字が生まれた里。その背後の山の上に、戦国の堀と土塁が、ほとんど手つかずのまま眠っている。","lead":"白山城は、韮崎市神山町の山の上にあった山城の跡です。ふもとの «武田» の地は、武田氏の名字のもとになった場所とされ、武田信義の館があったと伝わります。山の上には戦国時代の堀や土塁がよく残り、国の史跡になっています。","story":["平安時代の終わり、甲斐源氏の一人・源信義は、韮崎の «武田» という土地に住み、«武田信義» と名乗ったと伝わります。これが、のちに戦国大名・武田信玄へと続く武田氏の始まりとされています。ふもとには武田氏の氏神・武田八幡宮があり、今も大切に守られています。","その武田八幡宮の裏手、南にのびる尾根の先にあるのが白山城です。«信義がこの山に城を築いたのでは?» といわれてきましたが、はっきりした証拠はありません。いま山の上に残っている堀や土塁は、戦国時代の山城の特徴をもっているため、戦国時代に手が加えられたものと考えられています。","山道を登って頂上に着くと、平らにならされた «主郭（しゅかく）» があります。そのまわりを土の壁（土塁）が囲み、尾根を断ち切る深い堀（堀切）や、斜面をたてに走る堀（竪堀）が刻まれています。«敵がここを登ってきたら、上から矢を射かけられる» ――城の仕組みを体で感じられます。","城の役目は、甲府盆地の西の入口、釜無川の流れと、信濃へ向かう道を見張ることだったと考えられています。武田氏の家臣が守ったとも伝わりますが、城主については諸説あります。","«武田のふるさと» は、にぎやかな観光地ではありません。でも、静かな山の上で土の城の形をたどると、武田氏がどこから来て、どう戦国の世を生きたのかが、少しずつ見えてきます。"],"tl":[["平安時代末","武田信義が韮崎の武田の地を本拠にしたと伝わる"],["1541年（天文10年）","武田晴信（信玄）が武田八幡宮の本殿を再建したとされる"],["戦国時代","白山城が見張りの城として整えられたと考えられる"],["1582年","武田氏がほろびる"],["平成時代","«白山城跡» が国の史跡に指定"]],"who":[["武田信義","甲斐源氏の武将。武田の地で武田氏を名乗ったと伝わる"],["武田信玄","武田八幡宮の本殿を再建したとされる戦国大名"],["城を守った武田家臣","城主については諸説がある"]],"deep":["«白山城» の名は、城のある山に白山権現をまつっていたことにちなむと考えられています。«しろやまじょう»«はくさんじょう» の両方の読みが使われます。","遺構は、主郭を中心に土塁・堀切・竪堀・虎口がまとまって残り、戦国期の武田氏の山城の造り方を知るうえで貴重とされます。","ふもとの武田八幡宮の本殿は国の重要文化財で、戦国時代の建物です。城と神社をセットで見ると、武田氏と «武田» の地の結びつきがよくわかります。","武田信義の館があったとされる場所は、白山城のふもとの武田の集落にあたるといわれますが、正確な場所は確かめられていません。","城から見下ろすと、釜無川と甲府盆地の西側が見渡せます。新府城や能見城など、武田氏末期の城との位置関係も確かめられます。","山道は整備されていますが、急な所もあります。歩きやすい靴で、季節によってはクマや虫への備えもしましょう。"],"look":["主郭を囲む土塁","尾根を断ち切る堀切","斜面の竪堀と虎口（城の出入口）","ふもとの武田八幡宮","山上からの釜無川と甲府盆地の眺め"],"q":["«武田» という名字のもとになった土地は、今のどこ？","山梨県韮崎市の神山町武田あたりとされます。武田信義がここで武田氏を名乗ったと伝わります。"],"koji":[],"myth":"武田信義が白山城を築いたという話や城主については諸説あり、確かな史料はない。","img":["武田八幡宮","武田信義","甲斐源氏","韮崎市"],"wp":"白山城","rel":{"ev":[],"grave":[]},"ph":[["c:5/50/TakedahatimanguuDVC00241.JPG",240,400,"武田八幡宮"],["c:8/84/Takeda_Nobuyoshi.jpg",1214,1467,"武田信義"],["c:4/4a/%E6%AD%A6%E7%94%B0%E5%85%AB%E5%B9%A1%E5%AE%AE.jpg",4000,3000,"韮崎市"]]},{"id":"19_nomi_jo","n":"能見城（新府城を守る砦）","yomi":"のうけんじょう","cat":"城","rank":"B","y":1582,"era":["azuchi"],"sh":"","ad":"韮崎市穴山町","st":"JR中央本線 穴山駅から歩いて約20〜30分（目安）","la":35.726,"lo":138.453,"hook":"武田氏がほろびたあと、主を失った甲斐をめぐって徳川と北条がにらみ合った。その最前線にのびた «土の壁» が能見城だ。","lead":"能見城は、韮崎市の七里岩（しちりいわ）と呼ばれる崖の上にあった砦の跡です。すぐ南には武田勝頼が築いた新府城があります。武田氏がほろびた1582年、甲斐をめぐって徳川家康と北条氏が争ったとき、徳川方の守りの拠点になったと考えられています。","story":["1582年の春、織田信長の軍が甲斐に攻めこみ、武田勝頼は完成したばかりの新府城に火をかけて逃れました。やがて勝頼は天目山のふもとで命を落とし、武田氏はほろびます。ところが、その3か月後、信長も本能寺の変でたおれてしまいます。","«甲斐と信濃は、だれのものになるのか?» 。持ち主のいなくなった土地をめぐって、東からは北条氏直の大軍、南からは徳川家康が兵を進めました。これを «天正壬午の乱（てんしょうじんごのらん）» といいます。","家康は新府城に陣を置き、北条軍は北の若神子（わかみこ）に陣を置いて、にらみ合いました。その間にあったのが能見城です。徳川方は、七里岩の台地を横切るように土塁や堀をつくって守りを固めたと考えられています。数では北条軍が上回っていたといわれますが、家康はねばり強く守りました。","にらみ合いは長く続きましたが、やがて両者は和議を結びます。甲斐と信濃の多くは徳川のものになり、家康は大きく勢力を広げました。«もし能見城の守りが破られていたら――» 。家康ののちの天下取りは、ここでの踏ん張りがあってこそだったのかもしれません。","いま能見城のあたりは、畑や林の中に土塁の高まりが残る静かな場所です。案内板を頼りに土の盛り上がりをたどると、400年以上前、兵士たちがここで北をにらんでいた姿が浮かんできます。"],"tl":[["1581年","武田勝頼が新府城を築き、本拠を移す"],["1582年3月","織田軍の侵攻。勝頼が新府城を焼いて逃れ、武田氏滅亡"],["1582年6月","本能寺の変で織田信長が死去"],["1582年夏〜秋","天正壬午の乱。徳川家康が新府城、北条氏直が若神子に陣を置き対峙"],["1582年10月ごろ","徳川と北条が和議を結ぶ"]],"who":[["徳川家康","新府城に陣を置き、北条軍と対峙した"],["北条氏直","北条氏の当主。若神子に陣を置いた"],["武田勝頼","新府城を築いた武田氏最後の当主"]],"deep":["能見城は、新府城の北側を守るための砦として武田勝頼の時代に築かれたという説と、天正壬午の乱で徳川方が築いた・手を加えたという説があります。","遺構は、七里岩の台地を東西に横切るように続く土塁と堀が特徴で、«能見城防塁» と呼ばれることもあります。","七里岩は、八ヶ岳の大昔の山崩れでできた地形が、釜無川と塩川にけずられてできた長い崖です。天然の堀の役割を果たしました。","天正壬午の乱では、家康方の兵は北条方よりずっと少なかったといわれますが、数は資料によって差があります。","新府城跡は国の史跡で、能見城とあわせて歩くと、七里岩の上に城と砦が並ぶ防衛の考え方がよくわかります。","戦いの後、徳川と北条は和議の条件として、家康の娘・督姫を北条氏直にとつがせることを決めました。"],"look":["台地を横切る土塁と堀の跡","七里岩の上からの眺め（釜無川側）","南の新府城跡とのつながり","案内板（位置を確かめながら歩く）"],"q":["1582年、武田氏がほろんだあと、甲斐・信濃をめぐって起きた徳川と北条の争いを何という？","«天正壬午の乱» です。能見城は徳川方の守りの拠点になったと考えられています。"],"koji":[],"myth":"築城者（武田か徳川か）や具体的な戦いの様子には諸説がある。","img":["新府城","天正壬午の乱","七里岩","若神子城"],"wp":"能見城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:7/7e/Shinpu_Castle.jpg",2048,1536,"新府城"],["c:3/37/Shichiri_rock_plateau_Nirasaki_Aerial_photograph.jpg",2355,3139,"七里岩"],["c:4/44/Wakamiko_castle_01.jpg",5184,3456,"若神子城"]]},{"id":"19_misaka_toge","n":"御坂峠（鎌倉往還・御坂城）","yomi":"みさかとうげ","cat":"街道","rank":"B","y":1582,"era":["nara","azuchi","showa"],"sh":"","ad":"笛吹市御坂町〜南都留郡富士河口湖町","st":"富士急行線 河口湖駅から車で約20分（旧道の峠付近）。峠の城跡へは山道を歩く","la":35.536,"lo":138.748,"hook":"甲府盆地と富士山のあいだに立ちはだかる峠。古代の都の道が通り、戦国の城が築かれ、昭和の文豪は «富士には月見草がよく似合ふ» と書いた。","lead":"御坂峠は、甲府盆地から河口湖へ山をこえる峠です。古代から甲斐と駿河・相模を結ぶ大事な道 «鎌倉往還（御坂路）» が通り、戦国時代には北条氏が «御坂城» を築きました。昭和には作家の太宰治が峠の茶屋に滞在しました。","story":["奈良・平安の時代、都から甲斐の国府へ向かう公の道は、駿河から富士山の北側をまわって、この御坂の峠をこえていたと考えられています。«みさか» は «神の坂» とも解され、峠は神の住む場所として、旅人が手を合わせる所でした。","鎌倉時代になると、この道は鎌倉と甲斐を結ぶ «鎌倉往還» として使われました。武士や商人、僧侶たちが、荷を背負って峠をこえていきました。","1582年、武田氏がほろび、信長も本能寺の変でたおれると、甲斐をめぐって徳川と北条が争いました（天正壬午の乱）。北条氏は相模から甲斐へ攻め入る道を確保するため、峠の上に «御坂城» を築きました。«ここを押さえれば、甲府盆地へ一気に下りられる» ――峠の城は、攻めるための足場だったのです。","時は流れて昭和13年（1938年）。作家の太宰治は、師の井伏鱒二をたよって、峠の茶屋 «天下茶屋» にしばらく滞在しました。毎日、目の前にそびえる富士山を見ながら、心をととのえて書いたのが『富嶽百景』です。その中の «富士には月見草がよく似合ふ» ということばは、とても有名になりました。","いまは下にトンネルが通り、車で峠をこえる人はほとんどいません。けれども旧道の峠に立てば、目の前に河口湖と富士山、ふりかえれば甲府盆地。古代の旅人、戦国の兵、昭和の文豪が見た景色が、そこにあります。"],"tl":[["奈良・平安時代","都と甲斐の国府を結ぶ道が御坂を通ったと考えられる"],["鎌倉時代","鎌倉往還として使われる"],["1582年（天正10年）","天正壬午の乱。北条氏が御坂城を築く"],["1938年（昭和13年）","太宰治が天下茶屋に滞在"],["1939年","『富嶽百景』が発表される"]],"who":[["北条氏","天正壬午の乱で御坂城を築いた"],["太宰治","天下茶屋に滞在し『富嶽百景』を書いた作家"],["井伏鱒二","太宰の師。天下茶屋に滞在していた"],["鎌倉往還の旅人たち","武士や商人、僧侶が峠をこえた"]],"deep":["平安時代の『延喜式』には、甲斐国の駅として «水市»«河口»«加吉» が記され、御坂峠をこえる道筋と考えられています。駅の正確な場所には諸説があります。","御坂城は峠の尾根の上に築かれ、土塁や堀、虎口（出入口）などの遺構が残るとされます。北条氏らしい大きな堀の造りが特徴といわれます。","峠の河口湖側にある河口浅間神社は、平安時代の富士山噴火のあとにまつられたと伝わり、世界遺産 «富士山» の構成資産です。","天下茶屋には太宰治の記念室があり、峠には «富士には月見草がよく似合ふ» の文学碑が建てられています。","峠の標高は約1500mで、冬は雪や凍結で旧道が通れなくなる時期があります。","御坂峠からの富士山の眺めは、明治以降の写真家や画家にも愛され、«富士見の名所» として知られます。"],"look":["旧道の峠からの河口湖と富士山","天下茶屋と太宰治ゆかりの展示","文学碑 «富士には月見草がよく似合ふ»","尾根上の御坂城跡（山歩きの装備で）"],"q":["太宰治が御坂峠の天下茶屋に滞在して書いた作品は？","『富嶽百景』です。«富士には月見草がよく似合ふ» の一節で知られます。"],"koji":[{"w":"富士には月見草がよく似合ふ","m":"太宰治『富嶽百景』の一節。雄大な富士と、けなげに咲く月見草の対比をえがいた"}],"myth":"古代の官道の正確な経路や、峠名の由来には諸説ある。","img":["太宰治","富嶽百景","天正壬午の乱","河口浅間神社"],"wp":"御坂峠","rel":{"ev":[],"grave":[]},"ph":[["c:3/30/Mt._Fuji_from_Misaka_Pass_%282nd_gen.%29.JPG",1280,960,"御坂峠"],["c:b/b3/Hiroshige_Mt_fuji_4.jpg",2001,3021],["c:4/4b/The_Fuji_reflects_in_Lake_Kawaguchi%2C_seen_from_the_Misaka_pass_in_the_Kai_province.jpg",1024,689],["c:c/c4/Former_Misaka_Tunnel.JPG",640,480],["c:7/77/Osamu_Dazai.jpg",815,1220,"太宰治"],["c:d/d6/Kawaguchi-asama-jinja_haiden_and_sugi_%281%29.JPG",6016,4000,"河口浅間神社"]]},{"id":"19_bodo","n":"棒道（信玄の軍用道）","yomi":"ぼうみち","cat":"街道","rank":"B","y":1552,"era":["muromachi"],"sh":"","ad":"北杜市小淵沢町・長坂町・高根町など","st":"JR中央本線 小淵沢駅から車で約10分（上の棒道の散策路付近）","la":35.883,"lo":138.335,"hook":"八ヶ岳のすそ野の森を、定規で引いたようにまっすぐ北へのびる古道。武田信玄が信濃へ兵を送るために通したと伝わる «戦国の高速道路»。","lead":"棒道は、武田信玄が信濃（長野県）へ軍を早く進めるためにつくったと伝わる道です。«棒のようにまっすぐ» なことから棒道と呼ばれます。八ヶ岳の南のふもと、北杜市に «上の棒道»«中の棒道»«下の棒道» の跡が伝わっています。","story":["戦国時代、甲斐の武田信玄は、北の信濃へと勢力を広げていきました。諏訪、佐久、そして川中島。何度も大軍を動かすには、«早く、たくさんの兵を運べる道» が必要でした。","«山を回りこむ道では遅い。まっすぐ行ける道をつくれ» ――そう考えたかどうかはわかりませんが、八ヶ岳のなだらかなすそ野には、ほぼ一直線にのびる道が通されたと伝わります。これが棒道です。高低差の少ない高原を選び、兵や馬、荷物を運びやすくしたといわれます。","棒道は1本ではなく、«上»«中»«下» の3本があったといわれます。それぞれ少しずつちがう道筋で信濃の方へ向かっていました。«どうしてそんなに道が必要なの?» 。敵の動きや季節に合わせて道を使い分けたとも、兵を分けて進めたとも考えられますが、確かなことはわかっていません。","江戸時代になると、棒道は地元の人々の生活の道や、信仰の道として使われました。小淵沢の «上の棒道» 沿いには、たくさんの観音さまの石像が並べられ、今もその一部を森の中で見ることができます。","いま棒道の一部は、森の中の散策路になっています。木もれ日の中、落ち葉を踏みながら歩いていると、ふと、甲冑の音と馬のひづめの音が聞こえてくるような気がします。"],"tl":[["1540年代","武田晴信（信玄）が信濃への侵攻を本格化する"],["1550年代","棒道が整えられたといわれる（時期は諸説）"],["1553〜1564年","川中島の戦い（5回とされる）"],["江戸時代","上の棒道沿いに観音の石像が置かれる"],["現在","一部が散策路として歩ける"]],"who":[["武田信玄","棒道をつくらせたと伝わる戦国大名"],["武田軍の兵たち","棒道を通って信濃へ向かったと考えられる"],["江戸時代の村人","道沿いに観音像を置き、信仰の道とした"]],"deep":["棒道を信玄がつくったことをはっきり示す同時代の史料は少なく、武田家臣の記録『高白斎記』の記事などが手がかりとして紹介されることがあります。解釈には諸説あります。","«上の棒道» は小淵沢から信濃方面へ向かう道筋が比較的よくたどれるとされ、散策路として整備されています。","«中の棒道»«下の棒道» の正確な道筋ははっきりしない部分が多く、研究者によって想定が異なります。","上の棒道沿いの石仏は、西国三十三所や坂東・秩父などの観音霊場になぞらえて置かれたものと考えられています。","八ヶ岳南麓は火山のすそ野で傾斜がゆるく、まっすぐな道を通しやすい地形でした。","信玄の軍用道として «棒道» のほか、各地に «信玄道» と呼ばれる道が伝わっていますが、多くは後世の伝承です。","棒道の行き先は信濃の諏訪・佐久方面とされ、信玄が北信濃の川中島へ兵を送るときにも使われたと語られます。ただし、実際にどの戦いでどの道を通ったかを示す確かな記録は多くありません。"],"look":["森の中をまっすぐのびる上の棒道の散策路","道沿いの観音石像","八ヶ岳のすそ野の地形","小淵沢周辺の案内板"],"q":["棒道はなぜ «棒» 道と呼ばれる？","棒のようにまっすぐな道だからといわれます。"],"koji":[{"w":"疾きこと風の如く","m":"«風林火山» の一句。軍を風のように速く動かせという意味。棒道はまさにそのための道とされる"}],"myth":"信玄がつくったという話、3本の道筋、完成時期はいずれも伝承や推定を含み、諸説ある。","img":["武田信玄","八ヶ岳","小淵沢町","川中島の戦い"],"wp":"北杜市","rel":{"ev":[],"grave":[]},"ph":[["c:a/a8/150719_KEEP_Hokuto_Yamanashi_pref_Japan11n.jpg",6000,4000,"北杜市"],["c:4/44/Wakamiko_castle_01.jpg",5184,3456],["c:d/df/Shinden-no_Oitozakura.JPG",4000,3000],["c:4/49/Mus%C3%A9e_Kiyoharu_Shirakaba_A.JPG",4000,3000],["c:0/00/Makibakoen_mtfuji.jpg",4160,3120],["c:1/17/Hokuto_police_station.JPG",4128,3096],["c:7/73/Akeno_village_sunflower_field.JPG",4000,3000],["c:0/01/150719_KEEP_Hokuto_Yamanashi_pref_Japan17bs5.jpg",6000,4000]]},{"id":"19_tsuru_se","n":"鶴瀬宿（甲州街道の関所の宿）","yomi":"つるせじゅく","cat":"街道","rank":"B","y":1700,"era":["edo","azuchi"],"sh":"","ad":"甲州市大和町鶴瀬","st":"JR中央本線 甲斐大和駅から歩いて約20〜30分","la":35.648,"lo":138.773,"hook":"笹子峠を下りきった谷間の小さな宿場。ここには旅人を調べる «関所» があり、すぐ近くでは武田家最後の悲劇が起きていた。","lead":"鶴瀬宿は、江戸と甲府を結ぶ甲州街道の宿場の一つです。笹子峠を越えて甲府盆地へ入る手前の谷間にあり、人や荷物を調べる «口留番所（くちどめばんしょ）» が置かれていました。近くには武田勝頼が最期を迎えた田野の地があります。","story":["江戸を出て甲州街道を西へ。笹子峠の長い坂を下りきり、駒飼宿を過ぎると、日川（ひかわ）の谷に小さな宿場があらわれます。それが鶴瀬宿です。«ここを越えれば、もうすぐ甲府盆地だ» 。旅人はほっと息をついたことでしょう。","鶴瀬には «口留番所» がありました。口留番所は、国の出入口で人や荷物を調べる、関所のような役目の番所です。«通行手形を見せよ»«その荷は何だ» ――役人のきびしい声が、谷にひびいていたかもしれません。とくに米や武器、女性の出入りなどが見張られたといわれます。","«なぜこの谷に番所を?» 。鶴瀬のあたりは山がせまり、道が谷底の一本しかない場所でした。ここを押さえれば、甲府盆地の東の出入口をしっかり見張ることができたのです。","じつは、この谷は戦国時代の悲しい歴史の舞台でもあります。1582年、織田軍に追われた武田勝頼は、天目山をめざして日川の谷をさかのぼり、田野の地で妻や子とともに命を落としました。その場所には、のちに徳川家康が勝頼たちの霊をなぐさめるため «景徳院» を建てたと伝わります。","いまの鶴瀬は、国道と鉄道が通る静かな山あいの集落です。番所跡の案内や、古い街道の道筋をたどりながら歩くと、峠をこえてきた江戸の旅人と、谷の奥へ消えていった戦国の武将たち、二つの時代の足音が重なって聞こえてきます。"],"tl":[["1582年3月","武田勝頼が田野（鶴瀬の近く）で自害し、武田氏がほろびる"],["江戸時代初め","甲州街道が整えられ、鶴瀬が宿場となる"],["江戸時代","鶴瀬に口留番所が置かれる"],["明治時代","番所が廃止され、のちに鉄道（中央本線）が近くを通る"]],"who":[["武田勝頼","鶴瀬に近い田野で最期を迎えた武田氏最後の当主"],["徳川家康","勝頼らの霊をなぐさめる景徳院を建てたと伝わる"],["番所の役人","旅人や荷物を調べた"],["甲州街道の旅人","笹子峠を越えて鶴瀬を通った"]],"deep":["甲州街道の宿場では、江戸から数えて鶴瀬は34番目ごろにあたり、東の駒飼宿、西の勝沼宿にはさまれています（数え方は資料による）。","甲斐国の «口留番所» は国境や主要な街道の出入口に置かれた番所で、鶴瀬はその一つでした。","武田勝頼の最期の地・田野には «景徳院» があり、勝頼と夫人、嫡男・信勝の墓とされるものが残っています。","勝頼の家臣・土屋昌恒が、せまい崖道で片手で藤づるにつかまりながら敵を防いだという «片手千人斬り» の伝説が、この谷に伝わっています。","日川の谷は «天目山» へ向かう道で、勝頼は天目山の棲雲寺をめざしていたといわれます。","宿場のころの建物はほとんど残っていませんが、道の曲がり方や家の並びに、宿場の面影を探すことができます。"],"look":["口留番所跡の案内","日川の谷と甲州街道の旧道","近くの景徳院（武田勝頼の最期の地）","笹子峠方面の山並み"],"q":["鶴瀬宿に置かれていた、関所のような役目の番所を何という？","«口留番所» です。人や荷物の出入りを調べました。"],"koji":[],"myth":"勝頼最期の様子や «片手千人斬り» は軍記物などの伝承による。","img":["甲州街道","景徳院","武田勝頼","甲斐大和駅"],"wp":"甲州市","rel":{"ev":["k_koshu"],"grave":[]},"ph":[["c:1/1e/Marufuji_Winery_190907f.jpg",4496,3000,"甲州市"],["c:a/a6/Museums_in_Yamanashi_prefecture-1.jpg",4496,3000],["c:d/d8/Mercian-1.jpg",4496,3000],["c:9/96/Koshushi-4.jpg",4496,3000],["c:5/52/Koshushi-3.jpg",4496,3000],["c:e/e3/Koshushi-2.jpg",4496,3000],["c:4/42/Katsunumashi_yakataato-1.jpg",4496,3000],["c:3/33/Katsunuma_Junior_high_school-1.jpg",4496,3000]]},{"id":"19_uenohara_juku","n":"上野原宿（甲州街道の甲斐側入口）","yomi":"うえのはらじゅく","cat":"街道","rank":"B","y":1700,"era":["edo","muromachi"],"sh":"","ad":"上野原市上野原（本町周辺）","st":"JR中央本線 上野原駅から坂を上って歩いて約15〜20分、またはバスで数分","la":35.631,"lo":139.111,"hook":"相模の国から境川を渡ると、そこは甲斐の国。高い段丘の上に開けた上野原宿は、江戸から来た旅人が最初に出会う «甲州» の町だった。","lead":"上野原宿は、甲州街道で甲斐国（山梨県）に入って最初の宿場です。桂川がつくった高い段丘の上にあり、国境の番所や、にぎやかな市がありました。郡内（ぐんない）と呼ばれた山梨県東部の、東の玄関口です。","story":["江戸の日本橋を出て、甲州街道をひたすら西へ。相模の国（神奈川県）の宿場をいくつも過ぎ、境川という小さな川を渡ると、そこから先が甲斐の国です。«いよいよ甲州に入ったぞ» 。国境の近くには «諏訪番所» があり、旅人の出入りを見張っていました。","番所をぬけて坂を上ると、台地の上に上野原宿の町並みが広がります。«どうして宿場が崖の上に?» 。桂川と鶴川が長い年月をかけて土地をけずり、高い段丘をつくりました。その平らな上に町が開かれたのです。見晴らしがよく、洪水の心配も少ない場所でした。","上野原は、宿場であると同時に «市の町» でした。決まった日に市が立ち、まわりの村から人々が集まって、織物や穀物、炭などを売り買いしました。山梨県東部は、江戸時代から «甲斐絹（かいき）» などの絹織物で知られ、その取引でもにぎわったといわれます。","さかのぼって戦国時代、このあたりは武田氏と、相模の北条氏の勢力がぶつかる国境の地でした。上野原には «上野原城» があり、国境を守る加藤氏の城だったと伝わります。宿場の町の下には、戦国の緊張も眠っているのです。","いまの上野原の中心街は、車の行きかう通りになっています。それでも、ゆるやかに曲がる道や古い商家の建物、町の神社に目を向けると、峠をこえてきた旅人が一息ついた宿場の気配が、ところどころに残っています。"],"tl":[["戦国時代","上野原城が武田方の国境の守りとなったと伝わる"],["江戸時代初め","甲州街道が整備され、上野原が宿場となる"],["江戸時代","諏訪番所が置かれ、市が立ってにぎわう"],["1901年（明治34年）","中央本線が上野原まで開通したとされる"],["現在","上野原市の中心市街地"]],"who":[["加藤氏","戦国時代に上野原城を守ったと伝わる武田方の武将の一族"],["甲州街道の旅人","国境を越えて最初にこの宿場に泊まった"],["郡内の織物商人","市で絹織物などを売り買いした"]],"deep":["甲州街道の宿場を江戸から数えると、上野原宿は17番目ごろにあたり、甲斐国の最初の宿場です（数え方は資料による）。","«郡内» は甲斐国の都留郡のことで、甲府盆地の «国中（くになか）» と対になる呼び名です。文化や経済のつながりは、江戸や相模とも深い地域でした。","諏訪番所は、甲斐国の東の出入口を守る口留番所の一つとされ、近くの諏訪神社にちなんだ名といわれます。","上野原城は宿場の近くにあったとされ、国境の武将・加藤氏の拠点と伝わります。遺構はあまり残っていません。","中央本線の上野原駅は段丘の下にあり、宿場のあった市街とは高さに大きな差があります。宿場と駅の位置関係から、段丘の地形がよくわかります。","郡内の絹織物 «甲斐絹» は、裏地などに使われた高級品として江戸でも人気がありました。"],"look":["段丘の上の旧宿場の通り","古い商家の建物","段丘の崖と桂川の眺め","諏訪番所跡や国境の境川付近"],"q":["甲州街道で、甲斐国に入って最初の宿場はどこ？","上野原宿です。"],"koji":[],"myth":"上野原城と加藤氏のかかわり、番所の細部には伝承を含む。","img":["甲州街道","甲斐絹","郡内"],"wp":"上野原市","rel":{"ev":["k_koshu"],"grave":[]},"ph":[["c:5/57/Uenohara_no_Okeyaki_A.jpg",6000,4000,"上野原市"],["c:7/73/Tukimigaike.jpg",4000,3000],["c:d/d0/Mushono-Dainembutsu_dance.JPG",4000,3000],["c:8/8a/%E8%BB%8D%E5%88%80%E5%88%A9%E7%A5%9E%E7%A4%BE_%E5%A5%A5%E3%81%AE%E9%99%A2.jpg",2976,3968],["c:7/7a/%E3%81%B5%E3%82%8B%E3%81%95%E3%81%A8%E9%95%B7%E5%AF%BF%E9%A4%A8.jpg",3968,2976],["c:0/00/Seidanotamazi.jpg",3968,2976],["c:0/08/Uenohara_city_center_area_Aerial_photograph.1976.jpg",3131,2757],["c:8/82/%E7%A7%8B%E5%B1%B1%E6%B8%A9%E6%B3%89_-_panoramio.jpg",3648,2736]]},{"id":"19_kyoraishi","n":"教来石宿（甲州街道 甲斐最後の宿）","yomi":"きょうらいしじゅく","cat":"街道","rank":"B","y":1700,"era":["edo","muromachi"],"sh":"","ad":"北杜市白州町教来石","st":"JR中央本線 小淵沢駅・長坂駅から車で約15〜20分","la":35.835,"lo":138.307,"hook":"«きょうらいし» ――ふしぎな名前の宿場は、甲州街道で甲斐の国の最後の宿。この先の川を渡れば、もう信濃の国だった。","lead":"教来石宿は、甲州街道の甲斐国（山梨県）側で最後の宿場です。すぐ先は信濃国（長野県）で、国境には «山口の番所» がありました。変わった地名には、日本武尊（やまとたけるのみこと）にまつわる伝説が残っています。","story":["甲府から甲州街道を北西へ。韮崎、台ヶ原と宿場を過ぎ、南アルプスの甲斐駒ヶ岳を左に見ながら進むと、教来石宿に着きます。«次は信濃の蔦木宿。甲斐の国とも、ここでお別れだ» 。","«教来石» という名前はどこから来たのでしょう。むかし、日本武尊が東の国へ遠征した帰り道、この地の大きな石に腰を下ろして休んだ――という伝説が残っています。その石にちなむ名だといわれ、«経て来た石» が変わったなど、いくつかの説が語られています。","宿場の少し先、国境の近くには «山口の口留番所» が置かれていました。甲斐国を出入りする人や荷物をここで調べました。甲斐の東の入口・鶴瀬や諏訪の番所に対して、こちらは北西の出口の番所です。","教来石は、戦国時代の武田家の名将 «馬場信春（ばばのぶはる）» のふるさととしても知られます。はじめは «教来石景政» と名乗っていたといわれ、のちに馬場の名をつぎ、«武田四天王» の一人に数えられるほど活躍しました。1575年の長篠の戦いで、主君・勝頼を逃がして討ち死にしたと伝わります。","いまの白州のあたりは、南アルプスからの清らかな水で知られる里です。宿場の建物はほとんど残っていませんが、街道の道筋や石仏、道しるべをたどりながら歩くと、国境の宿の静かなたたずまいを感じられます。"],"tl":[["伝説の時代","日本武尊が石に腰を下ろしたと伝わる"],["16世紀","教来石の出身とされる馬場信春が武田家臣として活躍"],["1575年","長篠の戦いで馬場信春が討ち死に"],["江戸時代初め","甲州街道が整い、教来石が宿場となる"],["江戸時代","国境近くに山口の口留番所が置かれる"]],"who":[["日本武尊","地名の伝説に登場する古代の英雄"],["馬場信春","教来石出身とされる武田家の名将。はじめ教来石景政と名乗った"],["武田勝頼","長篠の戦いで馬場信春に守られて退いたと伝わる"]],"deep":["甲州街道の宿場を江戸から数えると、教来石は41番目ごろにあたり、次の42番目・蔦木宿は信濃国です（数え方は資料による）。","地名の由来には日本武尊の伝説のほか、«清らかな水が来る石» からという話などがあり、はっきりしません。","馬場信春は武田信玄・勝頼の二代に仕え、多くの合戦で傷を負わなかったという話が軍記物に伝わっています（誇張の可能性あり）。","山口の口留番所は、甲斐国の北西の出入口を守る番所で、旅人は通行手形を見せる必要がありました。","すぐ手前の台ヶ原宿は古い町並みがよく残り、教来石とあわせて歩くと宿場の姿を想像しやすくなります。","白州のあたりは花崗岩の山から流れる水が豊富で、名水の里として知られています。"],"look":["旧甲州街道の道筋と石仏・道しるべ","国境の番所跡付近","甲斐駒ヶ岳の眺め","台ヶ原宿の町並み（近くの宿場）"],"q":["教来石の出身とされる、武田四天王の一人に数えられる武将は？","馬場信春です。はじめは教来石景政と名乗ったといわれます。"],"koji":[],"myth":"地名の由来（日本武尊の伝説など）や馬場信春の逸話は伝承・軍記物による部分が多い。","img":["甲州街道","馬場信春","白州町","台ヶ原宿"],"wp":"教来石宿","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/100_views_edo_086.jpg",793,1200,"甲州街道"],["c:b/bf/Baba_Nobufusa.jpg",832,1268,"馬場信春"],["c:9/94/Suntory-hakushu-distillery.jpg",4000,3000,"白州町"],["c:c/ce/Daigahara-juku_%28Hokuto_City%2C_Yamanashi_Prefecture%29_April_29%2C_2026_08.jpg",5568,3712,"台ヶ原宿"]]},{"id":"19_isawa_juku","n":"石和宿（甲州街道・石和代官所）","yomi":"いさわじゅく","cat":"街道","rank":"B","y":1700,"era":["kamakura","edo","showa"],"sh":"","ad":"笛吹市石和町市部","st":"JR中央本線 石和温泉駅から歩いて約15分","la":35.655,"lo":138.633,"hook":"いまは温泉街として知られる石和。けれど江戸時代、ここには甲斐の村々を治める幕府の代官所があり、さらに昔は武田氏の本拠でもあった。","lead":"石和宿は、甲州街道で甲府の一つ手前にあった宿場です。江戸時代には幕府の «石和代官所» が置かれ、周りの村々を治めました。鎌倉時代には、武田氏がこの地に館を構えていたと伝わります。","story":["鎌倉時代、甲斐源氏の武田信光は «石和五郎» と呼ばれ、この石和に館を構えたと伝わります。武田氏が甲府の躑躅ヶ崎（つつじがさき）に館を移すのは、ずっとのちの戦国時代のこと。それまで、石和は武田氏の大切な拠点の一つでした。町の石和八幡宮は、武田氏ゆかりの神社として伝えられています。","江戸時代になると、甲州街道が整えられ、石和は宿場町になりました。笹子峠を越えてきた旅人は、石和で一泊し、翌日には甲府に入ります。«いよいよ甲府だ» 。旅籠（はたご）や茶屋が並び、町はにぎわいました。","甲斐国の多くは、江戸時代の中ごろから幕府が直接治める土地になりました。そこで石和には «代官所（陣屋）» が置かれ、代官が年貢の取り立てや村々の取り締まりを行いました。石和の代官所は、国中（くになか）の東部の村々を治める «役所» だったのです。","石和にはもう一つ、ふしぎな伝説があります。むかし、石和川で禁じられた鵜飼いをした漁師が罰せられて亡くなり、のちに旅の途中の日蓮がその霊を法華経でなぐさめた――という話です。この伝説は能の «鵜飼» にもなり、町の遠妙寺（おんみょうじ）に伝わっています。","そして昭和36年（1961年）、ぶどう畑から温泉が勢いよくわき出しました。«畑から湯が!» 。これをきっかけに石和は温泉街として発展し、今の姿になりました。温泉の湯けむりの向こうに、武田氏と宿場と代官所の、長い歴史が重なっています。"],"tl":[["鎌倉時代","武田信光（石和五郎）が石和に館を構えたと伝わる"],["江戸時代初め","甲州街道の宿場となる"],["江戸時代中期以降","石和に幕府の代官所（陣屋）が置かれる"],["明治時代","代官所の役目が終わる"],["1961年（昭和36年）","ぶどう畑から温泉がわき、石和温泉が生まれる"]],"who":[["武田信光","鎌倉時代の甲斐源氏の武将。«石和五郎» と呼ばれた"],["石和代官","幕府から派遣され、村々を治めた役人"],["日蓮","鵜飼いの漁師の霊をなぐさめたと伝わる"]],"deep":["甲州街道の宿場を江戸から数えると、石和宿は37番目ごろにあたり、次の甲府柳町宿の一つ手前です（数え方は資料による）。","石和代官所（陣屋）の建物は残っておらず、跡地は町の中の案内などで位置を確かめることになります。","武田信光の石和館の正確な場所は分かっておらず、石和八幡宮の周辺などいくつかの説があります。","能 «鵜飼» は、殺生をした漁師の霊が法華経の力で救われる話で、作者は榎並左衛門五郎、のちに世阿弥が手を加えたとされます。","石和温泉は、1961年にぶどう畑の中の井戸から湯がわき出したことで知られ、当初は露天で入る «青空温泉» が話題になったといわれます。","石和は笛吹川の流れに近く、たびたび洪水の被害を受けた土地でもあります。川の流れも時代によって変わってきました。"],"look":["石和八幡宮（武田氏ゆかり）","遠妙寺（鵜飼の伝説）","代官所跡の案内","甲州街道の旧道筋","石和温泉街"],"q":["石和温泉は、何の畑から温泉がわいたことで生まれた？","ぶどう畑です。1961年（昭和36年）のことでした。"],"koji":[],"myth":"武田信光の館の場所、鵜飼の伝説は伝承。代官所の設置時期の細部は資料による。","img":["石和温泉","武田信光","遠妙寺","鵜飼 (能)"],"wp":"石和町","rel":{"ev":[],"grave":[]},"ph":[["c:9/9f/Isawa_Spa_Town_Aug.2013.JPG",1920,1440,"石和町"],["c:5/56/Onmyouji_Isawatyouichibe_Fuefuki_City.JPG",4608,3072],["c:6/67/Dawn_at_Isawa_in_the_Kai_province.jpg",4539,3014],["c:e/e3/Hattake-Shoin.jpg",2048,1536],["c:3/38/Daizokyouji_temple_Fuefuki-city.JPG",1944,1296],["c:d/dc/Isawaonsen_sta_20080428_01.jpg",800,600],["c:5/5c/IsawaTown-YamanashiPref.png",600,500],["c:3/3e/NDL-DC_9369963-066_Utagawa_Kunisada_crd.jpg",11880,5967,"武田信光"]]},{"id":"19_yatate_sugi","n":"矢立の杉（出陣の矢立の伝承）","yomi":"やたてのすぎ","cat":"伝承","rank":"B","y":1600,"era":["muromachi","edo"],"sh":"県指定天然記念物","ad":"大月市笹子町黒野田（笹子峠の旧道沿い）","st":"JR中央本線 笹子駅から旧道を歩いて1時間以上。車でも旧道は細く、冬は通行止めになることがある","la":35.615,"lo":138.799,"hook":"戦いに向かう武士たちは、峠の大杉に矢を射立てて勝利を祈った。幹の中が空洞になった巨木は、今も甲州街道の峠道に立ち続けている。","lead":"矢立の杉は、甲州街道の笹子峠の近くに立つ杉の巨木です。むかし、出陣する武士たちがこの杉に矢を射立てて戦いの勝利を願ったと伝わり、その名がつきました。山梨県の天然記念物です。","story":["甲州街道でいちばんの難所といわれた笹子峠。江戸側から峠へ向かう山道の途中に、ひときわ太い杉の木がそびえています。見上げると、首が痛くなるほどの高さです。«この木は、いったい何百年ここに立っているの?» 。","この杉には、こんな言い伝えがあります。戦いに向かう武士たちが峠を通るとき、この杉に矢を射立てて、«どうか勝たせたまえ» と祈った――。矢を射立てる、つまり «矢立（やたて）» の杉です。武田氏の兵士たちもここを通ったと語られています。","«なぜ杉に矢を?» 。昔の人は、大きな木には神さまが宿ると考えていました。峠は国と国、里と山の境目で、神さまにあいさつをして通る場所でもありました。そこに立つ巨木に矢をささげることは、神への誓いであり、戦いに向かう覚悟の表れだったのかもしれません。","江戸時代になると、戦の時代は終わり、峠を通るのは旅人や商人、荷を運ぶ馬になりました。旅人たちは、この大杉を見上げて一息つき、峠越えの無事を祈ったことでしょう。杉は、峠の道しるべでもありました。","長い年月のあいだに、幹の中は空洞になりました。それでも杉は枝を広げ、緑の葉をしげらせています。峠道をたどってこの木の前に立つと、弓を引いた武士や、汗をふく旅人たちの姿が、木の影の中に浮かんでくるようです。"],"tl":[["戦国時代ごろ","出陣の武士が矢を射立てたと伝わる"],["江戸時代","甲州街道の笹子峠越えの目印として知られる"],["1903年（明治36年）","鉄道の笹子トンネルが開通し、峠を歩いて越える人は減っていく"],["1938年（昭和13年）","峠の下に道路の «笹子隧道» が完成"],["現在","山梨県の天然記念物として保護されている"]],"who":[["出陣の武士たち","杉に矢を射立てて勝利を祈ったと伝わる"],["甲州街道の旅人","峠越えの途中で大杉を目印にした"],["笹子の人々","峠のふもとで旅人を迎え、杉を守ってきた"]],"deep":["«矢立» の名は、矢を射立てる風習からとされますが、いつ、だれが始めたかを示す確かな史料はありません。","幹の太さはおとな数人が手をつないでもかかえきれないほどで、根元近くの幹は大きな空洞になっています。","笹子峠は標高約1000mあまりで、江戸時代の甲州街道で最大の難所とされました。峠の東側に黒野田宿、西側に駒飼宿がありました。","峠の下を通る道路の «笹子隧道»（昭和13年完成）は、石造りの装飾がある坑口で、国の登録有形文化財です。","矢を木に射立てて祈る風習は、ほかの峠や神社の巨木にも伝わっており、峠の神への祈りと結びついたものと考えられています。","杉のまわりは保護のため柵で囲われていることがあります。根を踏まないよう、決められた場所から見学しましょう。"],"look":["空洞になった巨大な幹","見上げるほどの樹高","笹子峠の旧道の石畳や道しるべ","峠の笹子隧道（車・徒歩、状況を確認）"],"q":["«矢立の杉» の名前の由来は？","出陣する武士がこの杉に矢を射立てて勝利を祈ったという言い伝えからです。"],"koji":[],"myth":"矢を射立てた武士が誰だったか、武田氏とのかかわりは伝承による。","img":["甲州街道","大月市","笹子駅"],"wp":"笹子峠","rel":{"ev":[],"grave":[]},"ph":[["c:9/9f/Sasagotouge.JPG",240,320,"笹子峠"],["c:3/36/Aerial_view_several_tunnels_Sasagotoge_pass._West_entrance_side.jpg",2461,1780],["c:9/9f/Aerial_view_several_tunnels_Sasagotoge_pass._East_entrance_side.jpg",2456,1771],["c:c/c1/Hiroshige_II_K%C5%8Dsh%C5%AB_Yatatesugi.jpg",1033,1536],["c:a/a3/100_views_edo_086.jpg",793,1200,"甲州街道"],["c:1/15/Saru_hashi-1a.jpg",4233,2781,"大月市"],["c:f/fe/JR_Chuo-Main-Line_Sasago_Station_building.jpg",4308,2495,"笹子駅"]]},{"id":"19_renpo","n":"連方屋敷（戦国の方形館跡）","yomi":"れんぽうやしき","cat":"大名屋敷","rank":"B","y":1500,"era":["muromachi"],"sh":"県指定史跡","ad":"山梨市三ケ所","st":"JR中央本線 山梨市駅から車で約10分","la":35.702,"lo":138.692,"hook":"畑の中に、四角く囲まれた土の壁と堀。ここに誰が住んでいたのか、はっきりとはわからない。謎を残したまま、中世の館のかたちだけが残っている。","lead":"連方屋敷は、山梨市にある中世（室町〜戦国時代ごろ）の館の跡です。四角い敷地を土塁（土の壁）と堀で囲む «方形館（ほうけいかん）» の姿がよく残り、山梨県の史跡になっています。誰の館だったかは諸説あります。","story":["山梨市の住宅や畑のあいだに、こんもりとした土手が四角く続いている場所があります。近づいてみると、土手の外側にはくぼんだ堀のあと。«ここは何だろう?» ――それが連方屋敷です。","中世の武士の家は、今の «お城» のイメージとはちがいます。平らな土地を四角く区切り、まわりに土を盛って壁にし、その外に堀をめぐらせました。これを «方形館» といいます。中には主人の住まいや倉、馬小屋などがあったと考えられています。","連方屋敷は、一辺100mほどの四角い敷地で、土塁と堀が比較的よく残っています。甲斐国では、武田氏の館だった甲府の躑躅ヶ崎館（つつじがさきやかた）も、もとはこうした方形館の形をしていました。«武士の館の基本形» を、ここで見ることができるのです。","«いったい誰の館?» 。武田氏の一族や、その家臣の屋敷だったという説、あるいは別の武士の館だったという説など、いろいろな考えがあります。«連方» という変わった名前の由来も、はっきりわかっていません。","大きな天守も石垣もない、土だけの館跡。でも、土塁の上に立って四角い敷地を見わたすと、中世の武士たちが、家族や家来と共に暮らしながら、戦いにそなえていた様子が想像できます。謎が多いからこそ、想像がふくらむ史跡です。"],"tl":[["室町時代〜戦国時代ごろ","方形館がつくられ、使われたと考えられる"],["1519年","武田信虎が甲府に躑躅ヶ崎館を構える（同じ方形館の例）"],["1582年","武田氏がほろびる"],["昭和時代以降","山梨県の史跡に指定され、保存される"]],"who":[["館の主（不明）","武田氏の一族や家臣など諸説がある"],["武田信虎","甲府に躑躅ヶ崎館を築いた戦国大名。同時代の方形館の代表例をつくった"],["館で暮らした人々","主人の家族や家来、使用人など"]],"deep":["方形館は、鎌倉〜戦国時代の武士の館によく見られる形で、一辺100m前後（約1町四方）のものが多いとされます。連方屋敷もその規模に近いとされます。","土塁は敷地の四方をめぐり、外側に堀が残る部分があります。出入口（虎口）の位置も、館の使い方を考えるうえで注目されています。","館の主については、武田氏の一族とする説のほか、在地の武士の館とする説があり、確かな史料は見つかっていません。","«連方» の名の意味ははっきりせず、由来を記した確かな史料はありません。地名の成り立ちもふくめて、今後の研究が待たれます。","山梨県内には、甲府の躑躅ヶ崎館（武田氏館跡、国史跡）や、勝沼氏館跡（甲州市）など、方形館の遺構が各地に残っています。見比べると面白いです。","敷地の中や周辺は私有地や住宅が多いところもあります。見学は道路や案内板のある場所から行いましょう。"],"look":["敷地を四角く囲む土塁","土塁の外側の堀のあと","館の出入口（虎口）とされる場所","案内板と館全体の配置"],"q":["土塁と堀で四角く囲んだ、中世の武士の館の形を何という？","«方形館» です。武田氏の躑躅ヶ崎館も、もとはこの形でした。"],"koji":[],"myth":"館の主と «連方» の名の由来は不明で、諸説ある。","img":["方形館","武田氏館","勝沼氏館","山梨市"],"wp":"連方屋敷","rel":{"ev":[],"grave":[]},"ph":[["c:9/9b/Renpo_Yashiki_stone_monument_of_historic_sites.JPG",4000,3000],["c:2/24/Renpo_Yashiki_Views_of_west_side_direction.JPG",4000,3000],["c:6/65/Renpo_Yashiki_local_ruling_family_residences_Aerial_photograph.1975.jpg",1987,1442],["c:b/bf/Takedasi-Yakata20251017.jpg",6000,4000,"武田氏館"],["c:4/42/Katsunumashi_yakataato-1.jpg",4496,3000,"勝沼氏館"],["c:1/14/From_Fruit_park_the_view_of_Kofu_basin_and_Mt._Fuji.jpg",1943,1295,"山梨市"]]},{"id":"19_okachoshi","n":"岡銚子塚古墳","yomi":"おかちょうしづかこふん","cat":"遺跡","rank":"B","y":380,"era":["kofun"],"sh":"県指定史跡","ad":"笛吹市八代町岡","st":"JR中央本線 石和温泉駅から車で約15分","la":35.62,"lo":138.63,"hook":"ぶどう畑と桃畑にかこまれた丘に、鍵穴の形の大きなお墓。1600年ほど前、この地を治めた «王» が眠っている。","lead":"岡銚子塚古墳は、笛吹市八代町にある前方後円墳です。長さは約90mあり、4世紀後半ごろにつくられたと考えられています。甲府盆地の東側で力をもった豪族のお墓とされ、山梨県の史跡に指定されています。","story":["甲府盆地の東南、笛吹川の南にひろがる八代（やつしろ）の台地。果樹畑の中に、ゆるやかにふくらんだ緑の丘があります。上から見ると、四角と丸をつなげた鍵穴のような形。これが前方後円墳、岡銚子塚古墳です。","«なぜ銚子塚という名前なの?» 。«銚子» は、お酒をつぐための器のこと。古墳の形が銚子に似ているから、そう呼ばれるようになったといわれます。同じ山梨県の甲府市には、もっと大きな «甲斐銚子塚古墳» があり、区別するために地名の «岡» をつけて呼ばれています。","古墳がつくられた4世紀ごろ、ヤマト（今の奈良県）の王権を中心に、前方後円墳という形のお墓が各地に広がりました。«前方後円墳をつくる» ことは、ヤマトの王とつながりをもつ «しるし» でもあったと考えられています。甲府盆地にも、その波がとどいていたのです。","眠っているのは、この地域の水や田畑、人々をまとめた豪族の長でしょう。«王» が亡くなると、人々は土を運び、斜面に石をしき、何年もかけて大きなお墓を築きました。完成したときには、遠くからもよく見える、白く輝く丘だったかもしれません。","いまは草や木におおわれ、静かな丘になっています。でも古墳の上に立って盆地を見わたすと、この場所がまわりを見下ろす特別な位置にあることがわかります。«王» は、死んだあとも自分の国を見守りたかったのかもしれません。"],"tl":[["3世紀後半ごろ","ヤマトを中心に前方後円墳が広まり始める"],["4世紀後半ごろ","岡銚子塚古墳がつくられたと考えられる"],["4世紀後半ごろ","甲府市の曽根丘陵に甲斐銚子塚古墳がつくられる"],["昭和時代","山梨県の史跡に指定"]],"who":[["八代の豪族の長","古墳に葬られたと考えられる地域の支配者（名は不明）"],["古墳を築いた人々","土を運び、石を積み、大きな墓をつくった"],["ヤマト王権","前方後円墳という形を各地に広めた中央の勢力"]],"deep":["全長は約90mとされ、山梨県内の前方後円墳の中では、甲斐銚子塚古墳に次ぐ規模の大きなものの一つです。","つくられた時期は4世紀後半ごろと考えられています。甲斐銚子塚古墳とほぼ同じころで、甲府盆地の東と南に大きな勢力が並んでいた可能性があります。","古墳の斜面には «葺石（ふきいし）» がしかれていたと考えられ、完成時は石におおわれた姿だったとみられます。","前方後円墳の «前方部» と «後円部» のうち、主人が葬られるのはふつう後円部です。","甲府盆地では、4世紀の大きな前方後円墳のあと、6世紀になると姥塚古墳や加牟那塚古墳のような大きな円墳（横穴式石室）がつくられるようになります。","古墳の上や周りは畑や私有地に接しています。見学のときは畑に入らないように気をつけましょう。"],"look":["鍵穴形の墳丘（前方部と後円部）","後円部の上からの盆地の眺め","斜面の葺石のなごり","案内板の古墳の図"],"q":["«銚子塚» の «銚子» とは何のこと？","お酒をつぐための器です。古墳の形が似ていることから名づけられたといわれます。"],"koji":[],"myth":"葬られた人物は不明。名前の由来は言い伝え。","img":["前方後円墳","甲斐銚子塚古墳","笛吹市","古墳時代"],"wp":"岡・銚子塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:b/b8/Oka_Choshizuka_Kofun%2C_funkyu.jpg",5568,3712,"岡・銚子塚古墳"],["c:c/c4/Sakazukizuka_Kofun.jpg",4649,3099],["c:b/bf/Oka_Choshizuka_Kofun%2C_zenpoubu.jpg",5544,3676],["c:f/f5/Oka_Choshizuka_Kofun%2C_kouenbu.jpg",5568,3712],["c:3/3b/Oka_Choshizuka_Kofun%2C_funcho.jpg",5568,3712],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:4/49/Kai_Choshizuka_Kofun_zenkei.JPG",6016,4000,"甲斐銚子塚古墳"],["c:9/9f/Isawa_Spa_Town_Aug.2013.JPG",1920,1440,"笛吹市"]]},{"id":"19_ubazuka","n":"姥塚古墳（巨石の横穴式石室）","yomi":"うばづかこふん","cat":"遺跡","rank":"B","y":570,"era":["kofun"],"sh":"県指定史跡","ad":"笛吹市御坂町井之上（南照院の境内）","st":"JR中央本線 石和温泉駅から車で約15分","la":35.624,"lo":138.677,"hook":"お寺の境内の大きな丘に、ぽっかり開いた石の入口。中に入ると、人の背丈よりはるかに大きな石を積み上げた部屋が、奥へ奥へと続いている。","lead":"姥塚古墳は、笛吹市御坂町の南照院（なんしょういん）の境内にある大きな円墳です。中には巨大な石を積んでつくった «横穴式石室» があり、長さは約17mと東日本でも最大級とされます。6世紀後半ごろの古墳と考えられ、山梨県の史跡です。","story":["お寺の山門をくぐると、目の前にこんもりとした大きな丘があらわれます。«これが古墳?» と思うほどの大きさで、直径は約40mもあります。丘のすそには、大きな石でかこまれた入口が口を開けています。","中に入ると、ひんやりとした空気。天井も壁も、人の背丈よりずっと大きな石でできています。«こんな重い石を、どうやって運んで積んだの?» 。機械のない時代、たくさんの人が木のころや綱を使い、力を合わせて運んだと考えられています。","この石の部屋を «横穴式石室» といいます。横から入れる通路（羨道）と、遺体を納める部屋（玄室）からなり、家族や一族をあとから追加で葬ることができました。6世紀ごろ、甲府盆地でもこうした古墳がつくられるようになりました。","«姥塚（うばづか）» という名前は、«姥» つまりおばあさんにまつわる言い伝えから来たといわれますが、はっきりしたことはわかっていません。古墳はのちにお寺の境内となり、石室の奥には仏さまがまつられるようになりました。«古代の王の墓» が、長い時間をへて «祈りの場» に変わったのです。","ここに眠っているのは、甲府盆地の東南部、御坂のあたりを治めた有力者だと考えられます。石室の大きさは、その人物がどれほどの力をもっていたかを物語っています。暗い石室の奥に立ち、1400年以上前の人々の力と祈りを感じてみてください。"],"tl":[["6世紀ごろ","甲府盆地で横穴式石室をもつ古墳がつくられ始める"],["6世紀後半ごろ","姥塚古墳がつくられたと考えられる"],["のちの時代","古墳が南照院の境内となり、石室に仏がまつられる"],["昭和時代","山梨県の史跡に指定"]],"who":[["御坂の有力者","古墳に葬られたと考えられる地域の支配者（名は不明）"],["石室を築いた人々","巨石を運び、積み上げた"],["南照院","古墳を境内に守ってきた寺"]],"deep":["横穴式石室の全長は約17.5mとされ、東日本でも最大級の規模をもつ石室として知られます。","墳丘は直径約40m、高さも10m前後ある大きな円墳です。前方後円墳がつくられなくなった後の時代の、地域の有力者の墓と考えられます。","石室は大きな自然石を積み上げてつくられ、天井石も巨大です。石の積み方から、高い技術をもった集団がかかわったとみられます。","甲府盆地には、加牟那塚古墳（甲府市）など、6世紀後半ごろの大型の横穴式石室をもつ円墳がいくつかあり、姥塚古墳はその代表例です。","石室の中に仏がまつられるなど、古墳がのちの時代に信仰の場として使われた例は各地にあります。","石室は寺の境内にあり、見学のときは寺への礼儀を守りましょう。中は暗いので明かりがあると便利です。"],"look":["巨石でできた石室の入口","長い羨道と奥の玄室","天井の巨大な石","石室の奥にまつられた仏","南照院の境内と墳丘の大きさ"],"q":["姥塚古墳の中にある、横から入れる石の部屋を何という？","«横穴式石室» です。姥塚古墳のものは長さ約17mで、東日本最大級とされます。"],"koji":[],"myth":"«姥塚» の名の由来は伝承で、はっきりしない。","img":["横穴式石室","円墳","笛吹市","古墳時代"],"wp":"姥塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:5/59/Monjuin_Nishi_Kofun%2C_sendou-1.jpg",6002,3978,"横穴式石室"],["c:3/37/Hachimanyama_kofun-Aichi02.jpg",712,440,"円墳"],["c:9/9f/Isawa_Spa_Town_Aug.2013.JPG",1920,1440,"笛吹市"]]},{"id":"19_kamunazuka","n":"加牟那塚古墳","yomi":"かむなづかこふん","cat":"遺跡","rank":"B","y":570,"era":["kofun"],"sh":"県指定史跡","ad":"甲府市千塚","st":"JR甲府駅から車で約15分","la":35.68,"lo":138.539,"hook":"«千塚（ちづか）» ――千の塚がある土地。その名のとおり古墳がたくさんあった甲府の北西に、ひときわ大きな円墳がどっしりと座っている。","lead":"加牟那塚古墳は、甲府市千塚にある大きな円墳です。直径は約45mで、中には石を積んでつくった長い横穴式石室があります。6世紀後半ごろの古墳と考えられ、山梨県の史跡になっています。","story":["甲府の町の北西、湯村温泉の近くに «千塚» という地名があります。«千の塚» 。昔、このあたりには数えきれないほどの小さな古墳（塚）があったことから、この名がついたといわれます。その中で、ひときわ大きいのが加牟那塚古墳です。","住宅地の中に、直径約45mの丸い丘がこんもりと盛り上がっています。丘のすそには、石を積んでつくった入口。中は長い通路と部屋が続く «横穴式石室» になっていて、全長は十数mにもなります。","«加牟那（かむな）» という名前は、ちょっとふしぎな響きですね。«神奈» や «神名» に通じる、神さまにかかわることばから来たのではないか、ともいわれますが、はっきりしたことはわかっていません。昔の人も、この大きな塚を特別な場所だと感じていたのでしょう。","6世紀、甲府盆地では前方後円墳にかわって、横穴式石室をもつ大きな円墳が有力者のお墓になりました。東の笛吹市には姥塚古墳、西の甲府市にはこの加牟那塚古墳。«盆地のあちこちに、それぞれの地域の長がいた» ことが、古墳の分布から見えてきます。","まわりの小さな古墳の多くは、畑や家をつくるときに消えてしまいました。だからこそ、残った加牟那塚古墳は、«千の塚» の時代を今に伝える大切な証人です。石室の入口の前に立ち、この土地を治めた人と、その一族の物語を想像してみてください。"],"tl":[["6世紀ごろ","甲府盆地で横穴式石室をもつ円墳がつくられるようになる"],["6世紀後半ごろ","加牟那塚古墳がつくられたと考えられる"],["6〜7世紀ごろ","千塚周辺に多くの小さな古墳（群集墳）がつくられる"],["昭和時代","山梨県の史跡に指定"]],"who":[["千塚の有力者","古墳に葬られたと考えられる地域の長（名は不明）"],["群集墳の人々","まわりの小さな古墳に葬られた、一族や有力な家の人々"],["石室を築いた人々","大きな石を積んで石室をつくった"]],"deep":["墳丘は直径約45mで、県内でも大きな円墳の一つです。横穴式石室の全長は約16mとされ、姥塚古墳とともに山梨県を代表する大型石室です。","«千塚» の地名は、古墳時代後期に小さな古墳がたくさん集まってつくられた «群集墳» に由来すると考えられています。","群集墳は、6〜7世紀に、有力者だけでなく、より多くの家の人々が古墳をつくるようになったことを示すといわれます。","«加牟那» の名の由来ははっきりせず、神にかかわることばとする説などがあります。","古墳は住宅地の中にあり、公園のように整備されています。石室の中には入れない場合もあるので、現地の案内に従いましょう。","近くの湯村山には、戦国時代の武田氏の «湯村山城» の跡もあり、古墳時代と戦国時代の史跡をいっしょに歩けます。"],"look":["住宅地の中の大きな円墳","横穴式石室の入口","墳丘の高さ（上に登れる場合は周りを見わたす）","«千塚» の地名と周辺の地形"],"q":["«千塚» という地名は、何が多かったことから名づけられたといわれる？","小さな古墳（塚）がたくさんあったことからといわれます。"],"koji":[],"myth":"«加牟那» の名の由来ははっきりしない。","img":["横穴式石室","円墳","群集墳","甲府市"],"wp":"加牟那塚古墳","rel":{"ev":[],"grave":[]},"ph":[["c:d/d2/Kamunazuka_Kofun%2C_funkyu-1.jpg",5568,3712,"加牟那塚古墳"],["c:7/72/Kamunazuka_Kofun%2C_sendou-2.jpg",5568,3712],["c:e/ee/Kamunazuka_Kofun%2C_sendou-1.jpg",5568,3712],["c:b/ba/Kamunazuka_Kofun%2C_genshitsu-2.jpg",5568,3712],["c:1/1a/Kamunazuka_Kofun%2C_genshitsu-1.jpg",5568,3712],["c:e/e3/Kamunazuka_Kofun%2C_funkyu-2.jpg",5568,3712],["c:1/1c/Kamunazuka_Kofun%2C_entrance.jpg",5568,3712],["c:1/11/Kamunazuka_Kofun%2C_3D-N.jpg",9972,9021]]},{"id":"19_sonekyuryo","n":"曽根丘陵の古墳群（甲斐風土記の丘）","yomi":"そねきゅうりょうのこふんぐん","cat":"遺跡","rank":"B","y":370,"era":["kofun","jomon"],"sh":"国指定史跡","ad":"甲府市下曽根町（甲斐風土記の丘・曽根丘陵公園）","st":"JR甲府駅からバスで約30〜40分、«考古博物館» 付近下車","la":35.596,"lo":138.587,"hook":"甲府盆地の南のへりの丘に、長さ169mの巨大な前方後円墳。山梨最大の «王の墓» が、盆地全体を見下ろしている。","lead":"曽根丘陵は、甲府盆地の南側にある丘の連なりです。ここには山梨県で最も大きな前方後円墳 «甲斐銚子塚古墳» をはじめ、たくさんの古墳が集まっています。一帯は «甲斐風土記の丘・曽根丘陵公園» として整備され、山梨県立考古博物館もあります。","story":["甲府盆地の南、笛吹川をこえたところに、なだらかな丘が東西にのびています。この丘の上に立つと、盆地全体と、北の山々、晴れた日には富士山の方角まで見渡せます。«王の墓をつくるなら、ここしかない» ――古代の人々もそう考えたのでしょう。","丘の上でひときわ目立つのが、甲斐銚子塚古墳です。長さは約169m。4世紀後半ごろにつくられたと考えられる、山梨県最大の前方後円墳です。すぐそばには、直径約72mの大きな円墳 «丸山塚古墳» もあり、どちらも国の史跡に指定されています。","銚子塚古墳からは、«三角縁神獣鏡（さんかくぶちしんじゅうきょう）» という、ヤマトの王権とかかわりの深い鏡などが見つかったといわれます。«ヤマトの大王から、この地の王へおくられたのか?» 。甲斐の王が、遠いヤマトとつながりをもっていたことを示す手がかりとして注目されています。","曽根丘陵には、古墳だけでなく、縄文時代や弥生時代の遺跡も多く見つかっています。長い時代にわたって、人々がこの丘で暮らし、祈り、死者をほうむってきたのです。丘は、甲斐の国の «はじまりの記憶» がつまった場所といえます。","いまは公園として整えられ、古墳の上を歩いたり、芝生で遊んだりできます。考古博物館で出土品を見てから古墳に登ると、1600年前の王の姿が、ぐっと身近に感じられるはずです。"],"tl":[["縄文・弥生時代","曽根丘陵に集落がいとなまれる"],["4世紀後半ごろ","甲斐銚子塚古墳がつくられたと考えられる"],["4〜5世紀ごろ","丸山塚古墳など、周辺に大きな古墳がつくられる"],["昭和時代","«銚子塚古墳 附 丸山塚古墳» が国の史跡に指定"],["1982年","山梨県立考古博物館が開館"]],"who":[["甲斐銚子塚古墳の王","甲府盆地を治めたと考えられる豪族の長（名は不明）"],["ヤマト王権","前方後円墳や鏡を通じて地方の王とつながった"],["考古学者たち","発掘や研究で丘の歴史を明らかにしてきた"]],"deep":["甲斐銚子塚古墳は全長約169mで、山梨県最大の前方後円墳です。東日本の前期古墳の中でも大きなものの一つに数えられます。","国の史跡としての正式名は «銚子塚古墳 附 丸山塚古墳» で、二つの古墳がまとめて指定されています。","銚子塚古墳の出土品として、三角縁神獣鏡をふくむ鏡や、腕輪形の石製品などが知られ、ヤマトとの関係を考える資料とされます。","丸山塚古墳は直径約72mの円墳で、墳丘の上に登ることができます（公園の整備状況による）。","曽根丘陵の近くには、甲府と駿河を結ぶ «中道往還（なかみちおうかん）» が通り、古くから交通の要所でした。","山梨県立考古博物館では、曽根丘陵を中心に、県内の縄文時代から古墳時代までの出土品が展示されています。"],"look":["甲斐銚子塚古墳の墳丘（全長約169m）","丸山塚古墳の円墳","古墳の上からの甲府盆地の眺め","山梨県立考古博物館の出土品展示","公園内のほかの小さな古墳"],"q":["山梨県でいちばん大きな前方後円墳の名前は？","甲斐銚子塚古墳です。全長は約169mあります。"],"koji":[],"myth":"鏡の入手のいきさつ（ヤマトから贈られたかどうか）は推定。葬られた人物は不明。","img":["甲斐銚子塚古墳","丸山塚古墳","山梨県立考古博物館","三角縁神獣鏡"],"wp":"曽根丘陵公園","rel":{"ev":[],"grave":[]},"ph":[["c:0/0b/%E7%94%B2%E6%96%90%E9%A2%A8%E5%9C%9F%E8%A8%98%E3%81%AE%E4%B8%98%E3%81%AE%E9%81%8A%E5%85%B7_-_panoramio.jpg",1280,960,"曽根丘陵公園"],["c:3/30/Kai-Choshizuka-kofun_%E2%84%961.JPG",4000,3000],["c:4/49/Kai_Choshizuka_Kofun_zenkei.JPG",6016,4000,"甲斐銚子塚古墳"],["j:1/14/%E8%9F%B9%E6%B2%A2%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E4%B8%89%E8%A7%92%E7%B8%81%E5%90%8C%E5%90%91%E5%BC%8F%E7%A5%9E%E7%8D%A3%E9%8F%A1.JPG",3559,3359,"三角縁神獣鏡"]]},{"id":"19_toko_ji","n":"東光寺（武田義信幽閉の寺）","yomi":"とうこうじ","cat":"寺社","rank":"B","y":1565,"era":["kamakura","muromachi","azuchi"],"sh":"国の重要文化財（仏殿）","ad":"甲府市東光寺3丁目","st":"JR甲府駅から車・バスで約15分","la":35.67,"lo":138.596,"hook":"信玄の跡つぎだった長男・義信は、父に背いたとして、この寺に閉じこめられた。武田家の運命を大きく変えた親子の悲劇の舞台。","lead":"東光寺は、甲府市の東部にある臨済宗の古い寺で、武田信玄が定めた «甲府五山» の一つです。信玄の長男・武田義信が閉じこめられ、ここで亡くなったと伝わります。室町時代の仏殿は国の重要文化財です。","story":["武田信玄には、義信という長男がいました。義信は幼いころから跡つぎとして育てられ、妻には駿河の今川義元の娘をむかえました。武田・今川・北条の三つの家は、たがいに縁組みをして同盟を結んでいたのです。","ところが1560年、今川義元が桶狭間の戦いで織田信長に討たれます。今川家が弱くなると、信玄は南の駿河をねらうようになりました。«今川を攻めるなど、とんでもない!» 。今川の娘を妻にもつ義信は、父の方針に反対したと考えられています。","1565年、義信の家臣たちが信玄に背こうとした、という事件が明るみに出ます。信玄は家臣を処罰し、義信をこの東光寺に閉じこめました。これを «義信事件» といいます。親子のあいだで何があったのか、本当のところは今もよくわかっていません。","2年後の1567年、義信は東光寺で30歳の若さで亡くなりました。自害させられたとも、病気で亡くなったともいわれます。«もし義信が跡をついでいたら――» 。こののち武田家は、四男の勝頼が継ぐことになり、やがて1582年の滅亡へと向かっていきます。","東光寺にはもう一つの悲劇も伝わります。1542年、信玄にほろぼされた諏訪の領主・諏訪頼重が、この寺で自害したといわれるのです。静かな境内の庭や、室町時代から残る仏殿の前に立つと、戦国の世を生きた人々の苦しみが、しみじみと感じられます。"],"tl":[["鎌倉時代","蘭渓道隆がかかわり禅寺として再興されたと伝わる"],["1542年（天文11年）","諏訪頼重がこの寺で自害したと伝わる"],["戦国時代","武田信玄が «甲府五山» の一つに定める"],["1565年（永禄8年）","義信事件。武田義信が東光寺に幽閉される"],["1567年（永禄10年）","義信が東光寺で死去"],["現在","室町時代の仏殿が国の重要文化財として残る"]],"who":[["武田義信","信玄の長男。父に背いたとして東光寺に幽閉され、ここで亡くなった"],["武田信玄","義信の父。駿河侵攻をめぐり義信と対立したとされる"],["諏訪頼重","信濃の諏訪の領主。東光寺で自害したと伝わる"],["蘭渓道隆","鎌倉建長寺を開いた禅僧。寺の再興や庭園と結びつけて伝えられる"]],"deep":["«甲府五山» は、信玄が甲府の禅宗寺院の中から定めたとされる5つの寺で、長禅寺・東光寺・能成寺・円光院・法泉寺が数えられます。","仏殿（薬師堂）は室町時代の禅宗様の建物で、国の重要文化財です。戦国の兵火をくぐりぬけて残ったとされます。","寺の庭園は蘭渓道隆がつくったと伝わる池泉式の庭で、山梨県の名勝に指定されています（作者の伝えは伝承）。","義信事件の原因は、今川氏との関係をめぐる親子の対立とするのが一般的ですが、同時代の史料が少なく、細部は分かっていません。","義信の死因は、自害説と病死説があります。境内には義信の墓と伝わる墓があります。","義信の死のあと、妻（今川義元の娘）は駿河へ帰され、これが武田・今川の同盟が崩れるきっかけの一つになりました。"],"look":["室町時代の仏殿（国の重要文化財）","蘭渓道隆作と伝わる庭園","武田義信の墓と伝わる墓","諏訪頼重の墓と伝わる墓"],"q":["武田義信が東光寺に閉じこめられた事件を何という？","«義信事件» です（1565年）。義信は2年後にこの寺で亡くなりました。"],"koji":[],"myth":"義信事件の真相と義信の死因、諏訪頼重の自害の場所、庭園の作者は伝承・諸説を含む。","img":["武田義信","諏訪頼重","蘭渓道隆","甲府五山"],"wp":"東光寺 (甲府市)","rel":{"ev":[],"grave":[]},"ph":[["c:3/38/Tokoji-temple_Kofu-city.JPG",4000,3000,"東光寺 (甲府市)"],["c:b/b7/Tokoji-temple_%E2%84%962_Kofu-city.JPG",4000,3000],["c:a/ac/Tokoji-temple_garden.JPG",4000,3000],["c:f/ff/%E6%AD%A6%E7%94%B0%E7%BE%A9%E4%BF%A1%E5%83%8F.jpg",2185,2150,"武田義信"],["c:5/5e/Lanxi_Daolong.jpg",682,1544,"蘭渓道隆"]]},{"id":"19_chozenji","n":"長禅寺（信玄の母・大井夫人の菩提寺）","yomi":"ちょうぜんじ","cat":"寺社","rank":"B","y":1552,"era":["muromachi","azuchi"],"sh":"","ad":"甲府市愛宕町","st":"JR甲府駅から歩いて約20分（北口・南口どちらからも行ける）","la":35.66556,"lo":138.57728,"hook":"戦国最強といわれた武田信玄。その «お母さん» のために、信玄みずから甲府へ移した寺。","lead":"長禅寺は、武田信玄の母・大井夫人の菩提寺（先祖や家族をとむらう寺）です。もとは甲府盆地の西にあった大井氏の寺で、夫人が亡くなったあと、信玄が甲府の城下へ移しました。信玄が決めた «甲府五山» の第一位とされた、格の高いお寺です。","story":["戦国時代のはじめ、甲斐の国はばらばらでした。国の主・武田信虎と、西の方に力をもつ豪族・大井氏は争っていましたが、やがて仲直りのしるしとして、大井氏の娘が信虎の正室になります。これが大井夫人です。夫人は1521年に男の子を産みました。のちの武田晴信、つまり信玄です。","1541年、信玄は父・信虎を駿河（今の静岡県）へ追い出し、みずから国の主になりました。«なぜ父を?» ――理由ははっきりわかっていません。家臣や民の不満が高まっていたから、今川氏と示し合わせていたから、などの説があります。ふしぎなのは、母の大井夫人が夫について行かず、甲府の館に残ったことです。人びとは館の北の曲輪に住む夫人を «御北様（おきたさま）» と呼びました。","1552年、大井夫人は亡くなりました。信玄は、母の実家・大井氏の菩提寺だった長禅寺（今の南アルプス市にあった寺）を二つに分け、一つを甲府の城下へ移したと伝わります。«母上を、いつも近くでとむらいたい» ――そんな思いがあったのかもしれません。もとの場所に残った寺は、今も «古長禅寺» として続いています。","長禅寺には、夫人の一周忌の1553年に描かれた肖像画が伝わります。描いたのは信玄の弟で、夫人の子でもある武田信廉。尼の姿で手を合わせる母の上には、夫人がよんだ «春は花 秋は紅葉の色々も 日かずつもりて 散らばそのまま» という歌が書かれています。花も紅葉もいつかは散る――戦の世を生きた母の、静かな覚悟が伝わってくるようです。","武田氏がほろびたとき、寺の本尊は戦火で焼けたといわれます。それでも寺は江戸時代を生きのび、門前には幕府の甲府代官所が置かれた時期もありました。今、愛宕山のふもとの境内を歩くと、甲府の町の中にいながら、戦国の親子の物語にそっとふれることができます。"],"tl":[["1520年","大井氏の娘（大井夫人）が武田信虎に嫁ぐ"],["1521年","夫人が晴信（信玄）を産む"],["1541年","信玄が父・信虎を駿河へ追放。夫人は甲府に残る"],["1552年5月","大井夫人が亡くなる"],["1552年ごろ〜永禄年間","長禅寺が甲府に移される（年代は史料によって異なる）"],["1553年","信廉が母の肖像を描く（一周忌）"],["1582年","武田氏滅亡。本尊が兵火で焼けたと伝わる"],["1724年","甲斐が幕府の直轄地に。寺の前に甲府代官所（長禅寺前陣屋）が置かれる"]],"who":[["大井夫人（瑞雲院）","信玄の母。この寺でとむらわれている"],["武田信玄（晴信）","母のために寺を甲府へ移した"],["武田信虎","夫人の夫。1541年に追放される"],["武田信廉（逍遥軒）","信玄の弟。母の肖像画を描いた画家でもある"],["岐秀元伯","長禅寺の住職。若い信玄に禅を教えたといわれる"]],"deep":["«甲府五山» は信玄が京都・鎌倉の五山にならって定めた臨済宗の五つの寺（長禅寺・東光寺・能成寺・円光院・法泉寺）。長禅寺はその筆頭とされます。","肖像画 «絹本著色武田信虎夫人像» は国の重要文化財。縦約88cm。年がはっきりわかる信廉の作品として、もっとも早い時期のものとされます。","この肖像の賛（上に書かれた文）は、信虎が開いた大泉寺の住職が書き、逆に大泉寺の信虎像には長禅寺の住職が賛を書いています。二つの寺が、別れた夫婦を結ぶように交流していたことがわかります。","夫人像の手が体にくらべて小さいことから、男性の肖像の下絵（粉本）を流用したのでは、という指摘もあります。","移転の年は、『甲斐国志』は夫人が亡くなった天文21年（1552年）、別の記録は永禄年間（1558〜70年）としていて、はっきりしません。","前身の寺は、1316年ごろに禅僧・夢窓疎石によって真言宗から臨済宗に改められたと伝わります。"],"look":["山門と本堂（愛宕山を背にした境内のたたずまい）","大井夫人をしのぶ供養の場所（参拝は寺の案内に従って）","近くの甲府城跡・甲府駅まで歩き、戦国と江戸の甲府の位置関係をたしかめる","南アルプス市の古長禅寺（もとの寺）もあわせて訪ねると、移転の物語がよくわかる"],"q":["大井夫人の肖像画を描いたのはだれ？","夫人の子で、信玄の弟の武田信廉（逍遥軒）です。絵が得意な武将でした。"],"koji":[{"w":"春は花 秋は紅葉の色々も 日かずつもりて 散らばそのまま","m":"大井夫人の歌と伝わる。美しいものもやがて散る、それでよい、という心"}],"myth":"信玄が寺を移した年、夫人の墓の場所については記録によって違いがある。","img":["武田信玄","躑躅ヶ崎館","甲府五山"],"wp":"長禅寺 (甲府市)","rel":{"ev":[],"grave":[]},"ph":[["c:a/a9/Chozenji.jpg",2048,1536,"長禅寺 (甲府市)"],["c:3/33/Takeda_Harunobu.jpg",1400,1707,"武田信玄"],["c:c/c0/%E8%BA%91%E8%BA%85%E3%83%B6%E5%B4%8E%E9%A4%A8.jpg",1280,960,"躑躅ヶ崎館"]]},{"id":"19_daisenji","n":"大泉寺（武田信虎の墓所）","yomi":"だいせんじ","cat":"墓所","rank":"B","y":1574,"era":["muromachi","azuchi"],"sh":"県指定史跡（武田信虎墓）","ad":"甲府市古府中町","st":"JR甲府駅から北へ歩いて約30分（武田神社方面行きのバスを使うと近い）","la":35.677,"lo":138.58083,"hook":"息子に国を追われた父・信虎。30年あまりの放浪の果てに、彼が開いた寺で静かに眠る。","lead":"大泉寺は、信玄の父・武田信虎が開いたお寺です。信虎は1541年に息子の信玄によって国を追い出され、各地を転々としたのち、1574年に信濃の高遠で亡くなりました。遺体は甲府へ運ばれ、この寺に葬られたと伝わります。","story":["1519年、武田信虎は、それまで石和にあった本拠を北の相川のほとりへ移し、新しい館「躑躅ヶ崎館」と城下町をつくりました。これが «甲府» の始まりです。«甲斐の府中»、つまり国の中心という意味でした。大泉寺は、この新しい町づくりとともに生まれた寺です。","寺には、こんな話が伝わります。1521年、信虎の息子（のちの信玄）が生まれるとき、信虎はふしぎな夢を見た。そこで寺を曹洞宗に改め、名前も変えた――。本当かどうかはわかりませんが、信玄誕生と結びつけて語られるほど、武田家にとって大事な寺だったのです。","しかし20年後、父と子は運命的に別れます。1541年、娘をとついだ今川家（駿河）へ出かけた信虎は、帰ろうとした国境を息子の兵にふさがれました。«もう甲斐へは帰れぬのか» ――。信虎はそのまま今川家に身を寄せ、のちには京都などでも暮らしたといわれます。","時は流れ1573年、信玄が亡くなります。その翌年、信虎は信濃の高遠（伊那）で亡くなりました。80歳をこえていたといわれます。高遠城にいた息子の信廉は、年老いた父の姿を絵に残しました。深い緑の衣に黒い法衣、頭を丸めた老人。するどい目つきに、戦国を切りひらいた男の気迫が残っています。","葬儀は信濃から名僧を招いて行われ、信虎は自分が開いた大泉寺に葬られたと伝わります。追放から30年あまり。«いったんは国を追われた父が、最後は甲府に帰ってきた» ――そう考えると、境内の墓の前で少し胸があつくなります。"],"tl":[["1519年","信虎が本拠を甲府に移し、城下町づくりを始める。大泉寺の開創もこのころ"],["1521年","信玄誕生。これにまつわる寺の由来が伝わる"],["1541年","信虎が駿河へ追放される"],["1564年","火事で堂が焼け、のちに再建"],["1573年","信玄が亡くなる"],["1574年","信虎が信濃・高遠で亡くなり、大泉寺で葬儀。信廉が肖像画を描く"],["1582年","武田氏滅亡。のちも徳川氏から寺領を認められる"]],"who":[["武田信虎","寺を開いた人物。この寺に墓がある"],["武田信玄","信虎の子。父を追放したが、寺は保護した"],["武田信廉（逍遥軒）","信虎の子。父の肖像画を描いた"],["天桂禅長","甲府に招かれた禅僧。大泉寺の開山"],["北高全祝","信濃・岩村田の龍雲寺の名僧。信虎の葬儀をつとめた"]],"deep":["«絹本著色武田信虎像»（1574年、信廉筆）は国の重要文化財。高遠で直接父と対面して描いたと考えられ、戦国武将の肖像画の中でも迫力のある一幅として知られます。","大泉寺は、中山の広厳院、信濃岩村田の龍雲寺とともに、武田領国の曹洞宗の寺をまとめる «僧録所» の役目をもっていました。","信玄の長女・黄梅院（北条氏政の妻）が亡くなったあと、その菩提寺として建てられた黄梅院も、大泉寺の子院とされました。","境内の «富士見池» には、水面に冬の雪化粧の富士が映るという伝承があり、江戸時代の地誌『甲斐国志』にも記されています。","江戸時代、甲府藩主・柳沢氏の寺・永慶寺の仏殿がこの寺に移されたことがありますが、のちに焼けてしまいました。","信虎の追放の理由は、«家臣や民の不満»«今川氏との密約»«父子の対立» など諸説あり、いまも研究が続いています。"],"look":["武田信虎の墓（県指定史跡）","境内の富士見池（伝承の池）","寺の前を南北に通る «大泉寺小路»（戦国の城下町の道すじ）","近くの武田神社（躑躅ヶ崎館跡）とあわせて歩く"],"q":["信虎が本拠を甲府に移したのは何年？","1519年です。«甲府» という地名はここから始まりました。"],"koji":[],"myth":"信玄誕生の霊夢の話、信虎が大泉寺に葬られたことは寺の由来・伝承による。追放の理由は諸説。","img":["武田信虎","躑躅ヶ崎館","武田神社"],"wp":"大泉寺 (甲府市)","rel":{"ev":[],"grave":[]},"ph":[["c:1/15/Daisenji.jpg",1775,1148,"大泉寺 (甲府市)"],["c:f/fc/Takeda_Nobutora_by_Takeda_Nobukado_%28Daisenji_Kofu%29.jpg",358,864,"武田信虎"],["c:c/c0/%E8%BA%91%E8%BA%85%E3%83%B6%E5%B4%8E%E9%A4%A8.jpg",1280,960,"躑躅ヶ崎館"],["c:a/ad/Takeda-jinja-1.jpg",2627,1700,"武田神社"]]},{"id":"19_enkoin","n":"円光院（信玄正室・三条夫人の墓所）","yomi":"えんこういん","cat":"墓所","rank":"B","y":1570,"era":["muromachi","azuchi"],"sh":"県指定史跡（武田晴信室三条氏墓）","ad":"甲府市岩窪町","st":"JR甲府駅北口から車で約10分。歩くと約30分","la":35.68289,"lo":138.58708,"hook":"京の都から山国へ嫁いだお姫さま。信玄は彼女の名をそのまま、寺の名前にした。","lead":"円光院は、武田信玄の正室（正式な妻）・三条夫人のお墓がある寺です。夫人は京都の貴族・三条家の娘で、1570年に亡くなりました。信玄は夫人の法名 «円光院» にちなんで寺の名を改めたと伝わります。","story":["三条夫人は、京都の名門貴族・三条公頼の娘です。若いころの信玄（晴信）のもとへ嫁いできました。都の雅な暮らしから、山にかこまれた甲斐の国へ。«どんな気持ちで峠をこえたのだろう?» と想像すると、胸がふくらみます。夫人は信玄の長男・義信をはじめ、何人もの子を産みました。","テレビドラマや小説では、三条夫人は «気位が高く、夫とすれちがう妻» として描かれることがあります。けれどそれは主に創作のイメージです。夫人の葬儀で導師をつとめた名僧・快川紹喜の記録には、信玄と夫人は «比翼の契り»、つまり仲のよい夫婦だったと書かれています。","しかし夫人の晩年は悲しいものでした。長男の義信は父と対立して幽閉され、1567年に亡くなります。今川家に嫁いでいた義信の妻は駿河へ帰され、娘の黄梅院も北条家との関係が切れたのち亡くなりました。家族が次々と戦国の荒波にのまれていったのです。","1570年7月、夫人は亡くなりました。信玄は、この寺を夫人の菩提寺とし、寺の名を «円光院» に改めたと伝わります。そして3年後、自分も亡くなる直前、いつも陣中に持ち歩いた守り本尊の «刀八毘沙門天» と «勝軍地蔵» を、円光院に納めるよう言い残したといわれます。«戦の守りを、妻のそばに» ――信玄の最後の願いだったのでしょうか。","境内の西の山すそには、夫人の墓である石の塔（宝篋印塔）が立っています。明治時代の写真と比べると形が少しちがい、何度か組み直されたこともわかっています。すぐ近くには信玄の墓もあり、今も夫婦は同じ岩窪の地に眠っています。"],"tl":[["平安時代末","前身の寺（清光寺）が甲斐源氏の祖・源清光によって石和に開かれたと伝わる"],["室町時代","武田信守が再興し «成就院» となる"],["永禄年間（1558〜70年）","信玄が甲府城下へ移し、甲府五山の一つとする"],["1570年7月28日","三条夫人が亡くなる。寺名を円光院に改めたと伝わる"],["1573年","信玄が亡くなる。守り本尊を円光院に納めるよう遺言したと伝わる"],["1718年","墓前の石灯籠が寄進される（夫人の没後およそ150年）"],["1967年","夫人の墓が県の史跡に指定される"]],"who":[["三条夫人（円光院殿）","信玄の正室。この寺に墓がある"],["武田信玄","夫。寺名を夫人の法名にちなんで改めたと伝わる"],["武田義信","夫妻の長男。父と対立し1567年に亡くなる"],["快川紹喜","名僧。夫人の葬儀をつとめ、夫婦仲を書き残した"],["柳沢吉保","江戸時代の甲府藩主。石灯籠を寄進した"]],"deep":["墓は高さ約1.2mの宝篋印塔と石灯籠2基からなります。塔身の四面に «大日» と刻まれているのは、山梨県内では例がないとされます。","塔身の上面に «+» の線刻があり、最初は今の左側が正面だったと考えられています。何度も組み直された証拠です。","信玄の陣中守り本尊と伝わる «刀八毘沙門天» と «勝軍地蔵» の像は、2017年に山梨県の有形文化財に指定されました。","本尊の釈迦如来は南北朝時代の作で、衣の金色の細かな文様（截金）が見どころとされます。","安永8年（1779年）、甲府の代官がこの付近を掘ったところ、信玄の戒名と年月を記した棺が見つかったという記録があり、信玄の死後すぐの火葬説の手がかりとされています。","三条夫人を «冷たい妻» とするイメージは、主に近代の小説やドラマ由来です。"],"look":["三条夫人の墓（宝篋印塔と石灯籠）","本堂と山門","近くの «武田信玄公の墓»（歩いて数分）","寺の周りから見る甲府盆地の景色"],"q":["三条夫人はどこの出身？","京都の貴族・三条家の出身です。都から甲斐へ嫁いできました。"],"koji":[{"w":"比翼の契り","m":"翼を並べて飛ぶ鳥のように、仲のよい夫婦のたとえ。快川紹喜が信玄夫妻をこう記した"}],"myth":"寺名を改めた経緯・守り本尊の遺言は寺の由緒・伝承。ドラマの «気の強い三条夫人» 像は創作。","img":["武田信玄","甲府五山","快川紹喜"],"wp":"円光院 (甲府市)","rel":{"ev":[],"grave":[]},"ph":[["c:a/a9/Enkoin-temple_Kofu-city_Yamanashi_Japan.JPG",4000,3000,"円光院 (甲府市)"],["c:3/33/Takeda_Harunobu.jpg",1400,1707,"武田信玄"],["c:0/0d/Erinji_main_gate.JPG",4000,3000,"快川紹喜"]]},{"id":"19_shingen_haka","n":"武田信玄公の墓（甲府・岩窪）","yomi":"たけだしんげんこうのはか","cat":"墓所","rank":"B","y":1573,"era":["azuchi","edo"],"sh":"県指定史跡（武田信玄墓）","ad":"甲府市岩窪町","st":"JR甲府駅北口から車で約10分。円光院から歩いて数分","la":35.6843,"lo":138.5835,"hook":"«わが死を三年隠せ» ――戦国一の名将がねむる、住宅地の中の小さな墓所。","lead":"甲府市岩窪町にある、武田信玄の墓とされる場所です。ここは信玄を火葬した場所だと伝わり、江戸時代の1779年に墓石が建てられました。毎年、信玄の命日のころには地元の人たちが集まって墓前祭が行われます。","story":["1573年春。三河の野田城を攻めていた武田信玄は、病にたおれ、甲斐へ引き返す途中の信濃で亡くなりました。53歳。天下をめざす大遠征のさなかでした。信玄は «わしの死を三年のあいだ隠せ» と言い残したと、軍記物『甲陽軍鑑』は伝えます。","«なぜ隠す必要があったのか?» ――信玄の死が知られれば、織田・徳川・上杉などまわりの敵がいっせいに動くかもしれないからです。息子の勝頼は、父の死を伏せたまま国を守りました。本格的な葬儀が恵林寺（甲州市）で行われたのは、3年後の1576年のことです。","では、その間、信玄の遺体はどこにあったのでしょう。岩窪には «魔縁塚» と呼ばれる場所があり、ここでひそかに火葬したという言い伝えがありました。長い間それは伝説にすぎないと思われていましたが、江戸時代に大きな発見があります。","1779年、甲府の代官・中井清太夫がこの地を掘らせたところ、石の棺が出てきて、信玄の戒名と年月が刻まれていたといわれます。«やはりここだったのか» ――代官は墓を整え、墓石を建てました。今ある «法性院機山信玄» と刻まれた墓石は、このとき建てられたものです。","墓所は住宅地の中の小さな一角ですが、今も花が絶えません。すぐ近くには正室・三条夫人の眠る円光院があります。命日の4月12日前後には墓前祭が行われ、信玄をしたう人たちが静かに手を合わせます。"],"tl":[["1521年","武田信玄（晴信）誕生"],["1573年4月12日","西上作戦の途中、信濃で病死（旧暦）"],["1573〜76年","遺言により死が伏せられる"],["1576年","恵林寺で本格的な葬儀が行われる（導師・快川紹喜）"],["1779年","甲府代官・中井清太夫が岩窪を発掘。墓石を建てる"],["現在","命日のころに墓前祭が行われる"]],"who":[["武田信玄","甲斐の戦国大名。この地で火葬されたと伝わる"],["武田勝頼","信玄の子。遺言を守り父の死を伏せた"],["快川紹喜","恵林寺の住職。信玄の葬儀をつとめた"],["中井清太夫","江戸時代の甲府代官。発掘を行い墓を整えた"]],"deep":["信玄の亡くなった場所は信濃国の駒場（長野県阿智村）とする説が有名ですが、浪合・根羽とする説もあり、はっきりしません。","死因も、胃がん説、結核（労咳）説、日本住血吸虫症説などがあり、史料からは決めきれません。«鉄砲で撃たれた» という話は後世の伝承です。","«三年秘匿» の遺言は『甲陽軍鑑』に見える話です。ただし実際には、死のうわさは早くから周りの大名に伝わっていたこともわかっています。","信玄の墓は、ここのほか恵林寺（甲州市）、高野山、長野県阿智村の長岳寺などにもあり、各地で供養されています。","墓石の «法性院機山信玄» は信玄の法名。«機山» は号で、甲府駅前の信玄像の台座にも見られます。","1779年の発掘の記録は、円光院の近くで棺が見つかったとも伝えられ、火葬地の場所については今も議論があります。"],"look":["«法性院機山信玄» と刻まれた墓石","墓所の中の «魔縁塚» の由来を伝える説明","近くの円光院（三条夫人の墓）","甲府駅南口の信玄像とあわせて"],"q":["信玄が «死を隠せ» と言い残したと伝える本は？","『甲陽軍鑑』です。武田家の軍学書で、伝説もふくまれています。"],"koji":[{"w":"疾きこと風の如く","m":"信玄の旗印 «風林火山» のはじめ。もとは中国の兵法書『孫子』の言葉"}],"myth":"魔縁塚＝火葬地の話、三年秘匿の遺言、発掘の細部は伝承・記録による。死去の地・死因は諸説。","img":["恵林寺","甲陽軍鑑"],"wp":"武田信玄","rel":{"ev":[],"grave":[]},"ph":[["c:3/33/Takeda_Harunobu.jpg",1400,1707,"武田信玄"],["c:4/40/Shingenko_ubuyu_no_ido.JPG",4000,3000],["c:7/7e/Kai-Zenkoji-temple_main_gate.JPG",4000,3000],["c:e/e6/Grave_of_Takeda_Shingen_in_Kofu_city.JPG",4000,3000],["c:1/15/Grave_of_Takeda_Shingen_in_Erinji.JPG",4000,3000],["c:5/5f/Shingen_embankment_aerial_photo.jpg",1611,2778],["c:e/eb/Battle_of_Mikatagahara.jpg",2853,1491],["c:4/46/Takeda_Shingen.jpg",1601,2362]]},{"id":"19_yoshikiyo","n":"源義清の墓（甲斐源氏の祖）","yomi":"みなもとのよしきよのはか","cat":"墓所","rank":"B","y":1130,"era":["heian"],"sh":"","ad":"中巨摩郡昭和町西条（義清神社付近）","st":"JR身延線国母駅から歩いて約15分","la":35.63497,"lo":138.54603,"hook":"常陸からの «流れ者» が、のちの武田信玄へつながる一族の祖になった。","lead":"源義清は、平安時代の終わりに常陸国（今の茨城県）から甲斐へやってきた武士で、武田氏をはじめとする «甲斐源氏» の祖とされます。昭和町西条の義清神社には義清がまつられ、近くには義清の墓と伝わる塚があります。","story":["話は平安時代の終わり、1130年ごろにさかのぼります。源義清は、弓の名人として知られる新羅三郎義光の子。父の地盤だった常陸国の武田郷（今のひたちなか市）に住み、«武田冠者» と呼ばれていました。«武田» という名前は、じつは茨城の地名から始まったのです。","ところが、義清の子・清光が地元で乱暴をはたらいたとして訴えられます。貴族の日記『長秋記』には、1130年、常陸の国司の訴えによって義清・清光父子が甲斐へ流されたことが記されています。«流罪» ――いわば罰として遠くへ送られたのです。","流された先は、甲斐の市河荘（今の市川三郷町のあたり）。ところが、この親子はここで力をたくわえていきます。とくに子の清光は多くの子に恵まれ、その子どもたちが甲府盆地の各地に広がり、武田・加賀美・安田・逸見などの家が生まれました。«追放された親子» が、甲斐の国を動かす一族の出発点になったのです。","晩年の義清は、今の昭和町西条のあたりに住んだと伝わります。義清神社はその隠居所の跡に建てられたといわれ、1985年の発掘では12世紀の土器が見つかりました。ただし、義清の屋敷だと言い切れるものは出ていません。","神社の近くには、義清の墓と伝わる塚があります。«ここから武田信玄まで、およそ400年» ――田畑と住宅にかこまれた小さな塚ですが、甲斐源氏の長い物語の «一ページ目» にあたる場所です。"],"tl":[["平安時代後期","義清、常陸国武田郷に住み «武田冠者» と呼ばれる"],["1130年","『長秋記』に、義清・清光父子が甲斐へ配流されたことが記される"],["12世紀なかば","義清が昭和町西条あたりに移り住んだと伝わる"],["1149年ごろ","義清が亡くなったと伝わる（年には異説あり）"],["1180年","ひ孫の世代にあたる武田信義らが挙兵する"],["1985年","義清神社で発掘調査。12世紀の土師器が出土"]],"who":[["源義清（武田冠者）","甲斐源氏の祖。ここに墓と伝わる塚がある"],["源義光（新羅三郎）","義清の父。後三年の役で活躍した武将"],["源清光（逸見清光）","義清の子。多くの子が甲斐各地に広がった"],["武田信義","清光の子。武田氏の初代とされる"]],"deep":["«武田» の名は常陸国那珂郡武田郷に由来します。ひたちなか市には «武田氏館» が復元されており、茨城と山梨を結ぶ «武田氏発祥の地» 論争にもなっています。","配流の記録は源師時の日記『長秋記』大治5年（1130年）12月の条。平安時代の甲斐源氏の出発点を示す、数少ない同時代史料です。","義清・清光父子がはじめに住んだのは市河荘で、市川三郷町の «平塩の岡» に館があったと伝わります。","昭和町の義清神社には、義清がよんだとされる和歌の歌碑があります。","義清の墓とされる塚は、古墳ではないかという見方もあり、確かなことはわかっていません。","源義清という名の武将は同じ時代にほかにもいて（足利系の矢田義清など）、混同に注意が必要です。"],"look":["義清神社の社殿と歌碑","近くの義清の墓と伝わる塚","神社周辺の平らな土地（釜無川の流れがつくった盆地の地形）","市川三郷町の平塩の岡もあわせて訪ねる"],"q":["«武田» という名前はもともとどこの地名？","常陸国（茨城県）の武田郷です。義清がそこで «武田冠者» と呼ばれました。"],"koji":[],"myth":"墓・隠居所の位置、没年は伝承による。塚が本当に義清の墓かどうかは確かめられていない。","img":["甲斐源氏","源義光","武田氏"],"wp":"源義清","rel":{"ev":[],"grave":[]},"ph":[["c:b/b2/Minamoto_no_Yoshimitsu.jpg",2200,2200,"源義光"],["c:d/de/Kokubo_Station_2017.jpg",3086,2314,"近く: 国母駅"],["c:7/7d/Yoshikiyo_Shrine_Syouwa_Town.JPG",4608,3072,"近く: 昭和町"],["c:8/8f/Yamanashi_prefectural_KofuShowa_High_School.JPG",3954,2938,"近く: 山梨県立甲府昭和高等学校"],["c:e/ec/%E3%83%95%E3%82%AB%E3%82%B5%E3%83%AF%E6%B8%A9%E6%B3%89.jpg",1041,1022,"近く: フカサワ温泉"],["c:7/7a/GRANPARK.JPG",1280,960,"近く: グランパーク"],["c:8/8a/Oshihara_Park.png",1182,946,"近く: 押原公園"]]},{"id":"19_takeda_nobuyoshi","n":"武田信義館跡（甲斐源氏の棟梁）","yomi":"たけだのぶよしやかたあと","cat":"大名屋敷","rank":"B","y":1180,"era":["heian","kamakura"],"sh":"","ad":"韮崎市神山町武田","st":"JR韮崎駅から車で約10分（バスは本数が少ない）","la":35.7175,"lo":138.4265,"hook":"頼朝・義仲と «三人の源氏の大将» が並び立った時代。その一人が、ここにいた。","lead":"武田信義は、平安時代の終わりに甲斐源氏をひきいた武将で、«武田氏» の初代とされます。韮崎市神山町の武田のあたりに館をかまえたと伝わり、近くには元服した武田八幡宮、背後には白山城跡があります。館の建物は残っておらず、今は «館跡» と伝わる場所です。","story":["1140年、13歳の少年が武田八幡宮で元服（大人になる儀式）をしました。名は武田太郎信義。甲斐源氏の祖・義清の孫にあたります。この日から武田八幡宮は、武田家の氏神になったと伝わります。「武田信玄の «武田» は、ここから続いていく」――そう思うと、神社の石段も特別に見えてきます。","1180年、源平の争いが始まります。伊豆の源頼朝が挙兵したのと同じころ、信義たち甲斐源氏も立ち上がりました。信濃へ攻めこみ、駿河では平家方の役人を討ち取ります。そして富士川の戦いでは、頼朝と連携して平家の大軍を退けました。«水鳥の羽音におどろいて平家が逃げた» という有名な話の舞台です。","このころの東国には、頼朝、木曽義仲、そして武田信義という «三人の源氏の大将» が並んでいました。朝廷の記録には、平家が討つべき相手として、頼朝と並んで信義の名が書かれています。信義は、頼朝の家来ではなく、肩を並べる存在だったのです。","しかし、«大将は二人いらぬ» と考えた頼朝は、しだいに甲斐源氏をおさえこみます。1184年、信義の子・一条忠頼は鎌倉に招かれ、宴の席で殺されてしまいました。«なぜ息子が?» ――信義の心中は、史料には残っていません。甲斐源氏はやがて、鎌倉幕府の御家人のひとつになっていきます。","信義の亡くなった年は、『吾妻鏡』では1186年とされますが、それより後の記録にも名前が見えるため、もっと長生きしたという説もあります。館があったとされる神山町のあたりは、今は静かな田園です。背後の山には白山城跡があり、ここから甲府盆地をにらんだ武田の «はじまりの風景» を感じられます。"],"tl":[["1128年","源清光の子として生まれたと伝わる"],["1140年","武田八幡宮で元服し、武田太郎信義と名のる"],["1180年","甲斐源氏が挙兵。信濃・駿河に進み、富士川の戦いで平家を退ける"],["1184年","子の一条忠頼が鎌倉で殺される"],["1186年","『吾妻鏡』ではこの年に死去（異説あり）"],["戦国時代","子孫の武田氏が甲斐の守護・戦国大名となる"]],"who":[["武田信義","甲斐源氏の棟梁。ここに館があったと伝わる"],["源清光","信義の父。甲斐源氏の祖・義清の子"],["源頼朝","同じ源氏の大将。のちに甲斐源氏をおさえこむ"],["一条忠頼","信義の子。1184年に鎌倉で殺される"],["武田信光","信義の子。家を継ぎ、頼朝に近づいた"]],"deep":["信義は逸見光長と双子で、兄の光長が巳の刻、信義が午の刻に生まれたと『尊卑分脈』に記されます。","九条兼実の日記『玉葉』には、平家の追討の対象として頼朝と並んで «源信義» の名が書かれ、当時の朝廷が信義を重く見ていたことがわかります。","『吾妻鏡』には、頼朝が駿河守護に信義を任じたとありますが、実際は信義が実力で駿河をおさえたと考えられています。","信義の墓は韮崎市神山町鍋山の願成寺にあります。館跡・武田八幡宮・白山城跡・願成寺はたがいに近く、まとめてめぐれます。","兵法や弓馬の «武田流» は信義に始まると伝えられます。","館跡の正確な範囲は発掘で確かめられておらず、«館跡» の碑が立つあたりは伝承地です。"],"look":["武田信義館跡の碑（伝承地）","武田八幡宮（信義が元服した神社。本殿は国の重要文化財）","白山城跡（背後の山城）","願成寺の信義の墓"],"q":["信義が元服した神社はどこ？","韮崎市の武田八幡宮です。以後、武田家の氏神になったと伝わります。"],"koji":[],"myth":"館の場所・元服の話・生年は伝承や系図による。没年は1186年説とそれ以後の生存説がある。","img":["武田八幡宮","富士川の戦い","甲斐源氏","願成寺 (韮崎市)"],"wp":"武田信義","rel":{"ev":[],"grave":[]},"ph":[["c:8/84/Takeda_Nobuyoshi.jpg",1214,1467,"武田信義"],["c:6/61/%E6%AD%A6%E7%94%B0%E5%A4%AA%E9%83%8E%E4%BF%A1%E7%BE%A9%E4%B9%8B%E5%A2%93.jpg",4000,3000],["c:4/4a/%E6%AD%A6%E7%94%B0%E5%85%AB%E5%B9%A1%E5%AE%AE.jpg",4000,3000],["c:8/80/%E6%AD%A6%E7%94%B0%E4%BF%A1%E7%BE%A9%E9%A4%A8%E8%B7%A1.jpg",4000,3000],["c:d/df/%E6%AD%A6%E7%94%B0%E4%BF%A1%E7%BE%A9%E4%B9%8B%E5%A2%93.jpg",4000,3000],["c:f/f9/%E3%82%8F%E3%81%AB%E5%A1%9A%E3%81%AE%E3%82%B5%E3%82%AF%E3%83%A9.jpg",4000,3000],["c:5/50/Ganjoji_Temple_Nirasaki_city.JPG",4000,3000],["c:5/50/TakedahatimanguuDVC00241.JPG",240,400,"武田八幡宮"]]},{"id":"19_jissoji","n":"実相寺（山高神代桜）","yomi":"じっそうじ","cat":"寺社","rank":"B","y":1375,"era":["muromachi","taisho"],"sh":"国の天然記念物（山高神代ザクラ）","ad":"北杜市武川町山高","st":"JR中央本線日野春駅から車で約10分（桜の季節は臨時バスが出ることもある）","la":35.78078,"lo":138.36744,"hook":"日本武尊が植えた、と伝わる桜。2000年の «いのち» と向きあえる寺。","lead":"実相寺は、北杜市武川町にある日蓮宗のお寺です。境内には、樹齢2000年ともいわれるエドヒガンザクラ «山高神代桜» があり、日本で最初期の1922年に国の天然記念物に指定されました。春には南アルプスの雪山を背に、老木が花をつけます。","story":["甲斐駒ヶ岳のふもと、北杜市の山高の里。春、ここに全国から人が集まります。お目当ては、実相寺の境内に立つ一本の桜。幹は太く、ごつごつと割れ、ところどころ支えの柱に守られています。それでも枝の先には、うすい紅色の花がちゃんと咲くのです。","この桜には、こんな言い伝えがあります。むかし、東の国へ向かう途中の日本武尊（やまとたけるのみこと）がここに立ち寄り、記念に桜を植えた――。だから «神代（かみよ）の桜»。もちろん本当に日本武尊が植えたかはわかりません。けれど、«それくらい古い» と人びとが信じてきたことが、この名前に込められています。","鎌倉時代には、もう一つの伝説が加わります。日蓮が佐渡から帰る途中にここを訪れ、弱っていた桜のために祈ったところ、ふたたび元気になった。そこでこの桜は «妙法桜» とも呼ばれるようになったといいます。寺ももとは真言宗でしたが、のちに日蓮宗に改められました。","戦国時代、この寺は武田信玄ともつながります。1561年の川中島の戦いのとき、信玄は家臣に命じて、この寺で戦勝を祈らせたと伝わります。«桜の木の下で、兵たちの無事を祈ったのだろうか?» ――そんな場面を想像すると、老木の見てきた時間の長さに気が遠くなります。","近代になって、桜は «国の宝» としてあつかわれるようになりました。1922年、国の天然記念物に指定。福島の三春滝桜、岐阜の根尾谷淡墨桜とならぶ «日本三大桜» の一つに数えられます。弱った樹勢を回復させるための手入れも重ねられ、今も毎年、花を咲かせています。"],"tl":[["伝説の時代","日本武尊が植えたと伝わる"],["鎌倉時代","日蓮が樹勢回復を祈ったという伝説が生まれる"],["1375年","日蓮宗の僧・日応が寺をゆずり受けたとされる（寺の説）"],["永禄年間（1558〜70年）","寺が今の場所に移る"],["1561年","川中島の戦いに際し、信玄が戦勝祈願を命じたと伝わる"],["1922年","«山高神代ザクラ» が国の天然記念物に指定される"]],"who":[["日本武尊","桜を植えたと伝わる伝説の英雄"],["日蓮","桜のために祈ったと伝わる。日蓮宗の開祖"],["武田信玄","川中島の戦いで戦勝を祈らせたと伝わる"],["日応","寺を日蓮宗に改めた僧（寺の説）"]],"deep":["«神代桜» はエドヒガンという種類の桜。エドヒガンは長生きする種類で、全国の «巨木の桜» の多くがこの仲間です。","天然記念物の指定は1922年10月12日。指定名は «山高神代ザクラ» とカタカナで書かれます。","樹齢2000年というのは言い伝えにもとづく数字で、科学的に年を測ったものではありません。","日蓮宗に改めた時期は、«日蓮が立ち寄ったとき» とする説と、«1375年に日応が住職を論破してゆずり受けた» とする説があり、寺は後者をとっています。","境内には蔦木氏代々の墓と石の廟が残り、北杜市の文化財に指定されています。","桜のまわりには、長野県の高遠や福島の三春など各地の桜の子孫とされる木も植えられ、«桜の名所めぐり» ができるように整えられています。"],"look":["山高神代桜の幹（柵の外から。根をふまないように）","南アルプス・甲斐駒ヶ岳を背にした桜の景色","境内の蔦木氏の墓と石廟","寺の梵鐘（北杜市指定文化財）"],"q":["神代桜と並ぶ «日本三大桜» のほかの二つは？","福島の三春滝桜と、岐阜の根尾谷淡墨桜です。"],"koji":[],"myth":"日本武尊お手植え・日蓮の祈り・樹齢2000年はいずれも伝承。信玄の戦勝祈願も寺伝による。","img":["日本三大桜","甲斐駒ヶ岳"],"wp":"実相寺 (北杜市)","rel":{"ev":[],"grave":[]},"ph":[["c:2/25/Mt.Kaikomagatake_from_Hokuto-shi.JPG",1499,1023,"甲斐駒ヶ岳"],["j:b/bb/Hokuto_Yamanashi_Yamatakajindaizakura_1.JPG",4000,3000,"近く: 武川村 (山梨県)"],["c:c/ca/Yamanashi_Hokuto_Mukawa_Bankyu-in_20230329-04.jpg",5472,3648,"近く: 萬休院 (北杜市)"],["c:a/a9/%E6%97%A5%E9%87%8E%E6%98%A5%E9%A7%85%282026%E5%B9%B45%E6%9C%88%E6%92%AE%E5%BD%B1%29.jpg",4080,3072,"近く: 日野春駅"],["c:9/94/Suntory-hakushu-distillery.jpg",4000,3000,"近く: 白州町"],["c:6/6c/HokutoHighSchool.JPG",2272,1704,"近く: 山梨県立北杜高等学校"]]},{"id":"19_hokoji","n":"放光寺（源平時代の仏像の寺）","yomi":"ほうこうじ","cat":"寺社","rank":"B","y":1184,"era":["heian","kamakura"],"sh":"国の重要文化財（仏像4件）","ad":"甲州市塩山藤木","st":"JR中央本線塩山駅からバスで約15分、«放光寺入口» などで下車（本数に注意）","la":35.73442,"lo":138.71367,"hook":"天に向けて弓を引く、赤い愛染明王。源平の英雄・安田義定がのこした «祈りの寺»。","lead":"放光寺は、甲州市塩山にある真言宗の寺です。源平の戦いで活躍した甲斐源氏の武将・安田義定が、1184年にこの地に移して一族の寺にしたと伝わります。平安時代の終わりから鎌倉時代はじめの仏像がいくつも残り、国の重要文化財になっています。","story":["平安時代の終わり、甲斐源氏の一人・安田義定は、甲府盆地の東、今の山梨市や甲州市のあたりを本拠にしていました。1180年に源平の戦いが始まると、義定は富士川の戦いなどで活躍し、やがて木曽義仲とともに京都へ攻めのぼります。その手柄で «遠江守» という役職も手に入れました。","寺の由来によると、もとは大菩薩峠のふもとの山の中にあった天台宗の寺で、1184年、義定が屋敷の近くの藤木の地に移し、一族の菩提寺にしたといいます。境内の仁王門に立つ2体の金剛力士像は、ちょうどそのころに作られたと考えられています。«源平の戦いのまっただなかに、この像が作られた» ――そう思うと、にらみつける目にも力がこもって見えます。","寺の宝物殿には、もう一つの見どころがあります。赤い体の愛染明王が、弓に矢をつがえ、まっすぐ天をねらっている像です。«天弓愛染» と呼ばれる珍しい姿で、お経の «星の光を射るように» という言葉を形にしたものといわれます。同じ形の像は、全国でもほとんど例がありません。","しかし、義定の最期は悲しいものでした。源頼朝は、力をもちすぎた甲斐源氏を警戒します。1194年、義定は «謀反の疑い» をかけられ、命を落としました。『吾妻鏡』は処刑されたと書き、別の書物は «この寺で自害した» と伝えます。寺には義定の位牌が今も守られています。","その後、寺は武田信玄からも保護を受けましたが、1582年の織田・徳川軍の侵攻で本堂が焼けたと伝わります。それでも仏像は守られ、江戸時代に再建されました。春の桜、夏の蓮など «花の寺» としても知られ、静かな境内で800年以上前の祈りにふれることができます。"],"tl":[["平安時代","大菩薩山麓に前身の寺（法光寺）があったと伝わる"],["1180年","安田義定ら甲斐源氏が挙兵"],["1184年","義定が寺を藤木に移し、菩提寺としたと伝わる"],["1191年","義定が梵鐘を寄進（銘文による）"],["1194年","義定が謀反の疑いで死ぬ"],["1582年","織田・徳川軍の侵攻で本堂が焼けたと伝わる"],["寛文年間（1661〜73年）","幕府の作事奉行・保田宗雪が本堂を再建"]],"who":[["安田義定","甲斐源氏の武将。寺を移し菩提寺にしたと伝わる"],["源頼朝","鎌倉幕府を開いた人物。義定を死に追いこんだ"],["成朝","奈良の仏師。金剛力士像の作者と考える説がある"],["武田信玄","寺を保護し、戦勝祈願を行わせた"],["保田宗雪","江戸時代に本堂を再建した中興の祖"]],"deep":["国の重要文化財は、大日如来坐像（本尊・平安時代後期）、不動明王立像、愛染明王坐像、金剛力士立像2体の4件です。","金剛力士像は高さ約2.6m。作者を奈良仏師の成朝とみる説があり、成朝が源頼朝の注文で鎌倉にいた時期（1185〜86年ごろ）と重なるため注目されています。","天弓愛染明王の類例は、高野山の金剛峯寺像や京都府木津川市の神童寺像などが知られます。山梨県立博物館にはこの像のレプリカが展示されています。","義定の寄進した梵鐘には1191年の年紀があり、当時は «法光寺» と書かれていました。«放光寺» の表記が確認できるのは戦国時代の1548年からです。","寺には、1867年に寄贈された法隆寺金堂壁画（阿弥陀浄土図）の模写があり、現存最古の模写として注目されています。","義定の最期は、『吾妻鏡』では梟首（処刑）、『鎌倉大草紙』では放光寺で自害とされ、史料によって違います。"],"look":["仁王門の金剛力士像（鎌倉時代）","宝物殿の天弓愛染明王・大日如来・不動明王（拝観は寺の案内に従う）","安田義定の位牌と毘沙門堂","季節の花（桜・蓮・紅葉など）"],"q":["弓矢を天に向けた愛染明王の形を何という？","«天弓愛染» といいます。全国でも珍しい姿です。"],"koji":[],"myth":"寺の移転年・義定の自害説は寺伝・後世の書物による。金剛力士像の作者は推定。","img":["安田義定","愛染明王","金剛力士"],"wp":"放光寺 (甲州市)","rel":{"ev":[],"grave":[]},"ph":[["c:4/48/The_main_gate_of_a_Buddhist_temple_of_the_Hokoji-_temple.JPG",4000,3000,"放光寺 (甲州市)"],["c:e/eb/The_main_hall_of_a_Buddhist_temple_of_the_Hokoji-temple.JPG",4000,3000],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/ce/AizenMyoo.jpg",528,746,"愛染明王"]]},{"id":"19_saionji","n":"最恩寺（室町の仏殿）","yomi":"さいおんじ","cat":"寺社","rank":"B","y":1400,"era":["muromachi","azuchi"],"sh":"国の重要文化財（仏殿）","ad":"南巨摩郡南部町福士","st":"JR身延線井出駅からタクシーで約10分","la":35.23472,"lo":138.4725,"hook":"甲斐と駿河の国境近く。600年前の禅寺の建物と、16歳で亡くなった若き当主の肖像が待つ。","lead":"最恩寺は、山梨県のいちばん南、静岡県との境に近い南部町福士にある臨済宗の寺です。室町時代前期に建てられたと考えられる仏殿は、東日本の禅宗様の建物として最古級のものの一つで、国の重要文化財です。武田一族の穴山氏にゆかりが深い寺でもあります。","story":["富士川沿いの国道を南へ南へ。静岡県との境が近づくころ、福士川の谷にひっそりとたたずむのが最恩寺です。この道は、中世から «駿州往還（河内路）» と呼ばれ、甲斐と駿河を結ぶ大事な道でした。人も、物も、そして軍勢も、この谷を行き来したのです。","寺の言い伝えでは、平安時代に天台宗の寺として始まり、室町時代の応永年間に立翁という禅僧が臨済宗の寺としてよみがえらせたといいます。今残る仏殿は、ちょうどそのころ、1400年前後に建てられたと考えられています。花のつぼみのような形の «花頭窓»、弓なりの «弓欄間»。禅宗様と呼ばれる、すっきりと美しい建築です。","戦国時代、このあたりの «河内領» を治めていたのは、武田氏の一族・穴山氏でした。穴山氏は武田と今川の間に立つ、むずかしい立場の一族です。最恩寺には、穴山信君（梅雪）や子の勝千代が出した «寺を守る» 約束の文書が残されています。","1582年、武田氏がほろび、信君は徳川家康と行動をともにしていました。ところが本能寺の変の混乱の中、信君は京都近くで命を落とします。あとを継いだのは、まだ子どもの勝千代でした。家康に守られて育った勝千代は、1587年に元服しますが、その直後、疱瘡（天然痘）で亡くなります。わずか16歳でした。","«せめて、大人になったこの子の姿を残したい» ――母の見性院は息子の肖像を描かせ、最恩寺を菩提寺としました。絵の中の勝千代は、元服をすませた少年の姿で座っています。穴山家はこれで絶えましたが、寺は、若くして消えた一族の記憶を今も静かに守っています。"],"tl":[["平安時代中期","天台宗の寺として始まったと伝わる"],["応永年間（1394〜1428年）","立翁が臨済宗の寺として再興。仏殿もこのころの建立と考えられる"],["1568年","駿河侵攻の際、武田信玄が参詣したといわれる"],["1582年","穴山信君（梅雪）が本能寺の変の混乱の中で死去"],["1587年","穴山勝千代が16歳で病死。穴山家が絶える"],["1591年","母・見性院が勝千代の肖像を作らせる"]],"who":[["立翁","室町時代に寺を再興した禅僧と伝わる"],["穴山信君（梅雪）","河内領の領主。寺を保護した"],["穴山勝千代（信治）","信君の子。16歳で死去し、この寺が菩提寺になった"],["見性院","信君の妻で勝千代の母。信玄の娘"],["武田信玄","駿河侵攻のとき参詣したといわれる"]],"deep":["仏殿は、床を張る手法が «土間から床張りへ» 変わる途中の古い形を示し、建てられたのは応永年間ごろと考えられています。同じ禅宗様の仏殿は、県内の清白寺（山梨市）や東光寺（甲府市）にも残ります。","«絹本著色穴山勝千代画像» は山梨県指定文化財。1591年の作で、縦約90cm。小袖に穴山氏の家紋 «三盛花菱» が描かれています。","勝千代の死後、家康は五男の万千代（のちの武田信吉）に武田氏の名跡を継がせました。","寺の近くには、穴山氏の本拠だった南部の館跡や、甲駿国境の万沢口留番所跡など、国境の歴史を伝える場所が点在します。","信玄の参詣や寺領寄進は «といわれる» 伝承で、確かな史料では確認されていません。"],"look":["仏殿（室町時代・国の重要文化財）の花頭窓と弓欄間","仏殿の屋根の反りと、組物の細かな木組み","穴山勝千代の肖像（公開は限られる。事前に確認を）","寺の前を通る旧駿州往還の道すじ"],"q":["勝千代は何歳で亡くなった？","16歳です。元服した直後、疱瘡で亡くなりました。"],"koji":[],"myth":"創建年代・信玄の参詣は寺伝。仏殿の建立年は建築の特徴からの推定。","img":["穴山信君","見性院","禅宗様"],"wp":"最恩寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/76/%E6%9C%80%E6%81%A9%E5%AF%BA_-_panoramio.jpg",1600,1200,"最恩寺"],["c:a/a4/Anayama_Nobukimi.jpg",1935,1635,"穴山信君"],["c:0/04/Kozanji_Temple_%28Shimonoseki%29.JPG",1280,960,"禅宗様"]]},{"id":"19_honenji","n":"本遠寺（身延の大野山）","yomi":"ほんのんじ","cat":"寺社","rank":"B","y":1609,"era":["edo"],"sh":"国の重要文化財（本堂・鐘楼堂）","ad":"南巨摩郡身延町大野","st":"JR身延線身延駅から歩いて約25分","la":35.36217,"lo":138.44575,"hook":"«師が死ぬなら、わたしも» ――家康の側室が命がけで救った僧の寺。","lead":"本遠寺（ほんのんじ）は、身延町大野にある日蓮宗の寺です。徳川家康の側室・お万の方（養珠院）が深く信仰した僧・日遠のために、1609年に開かれました。1650年に建てられた本堂と鐘楼堂は国の重要文化財で、お万の方の墓もあります。","story":["1608年、江戸城で、浄土宗と日蓮宗の僧が教えの正しさをめぐって討論しました。«慶長宗論» と呼ばれる出来事です。日蓮宗側が負けたとされ、家康は日蓮宗の寺々に «念仏を悪く言うのはやめる» という誓いの書を出すよう命じました。","ところが、身延山久遠寺のトップだった日遠は、これを拒みます。«もう一度、正々堂々と討論させてほしい» ――。この抗議は幕府に逆らう行いとされ、日遠は駿府の安倍川の河原で処刑されることになってしまいました。","このとき立ち上がったのが、家康の側室・お万の方です。日遠を師としてあがめていたお万の方は、«師が処刑されるなら、わたしもいっしょに» と家康に願い出たと伝わります。死に装束を用意したという話もあります。その覚悟にうたれた家康は、日遠を許したといいます。","命をひろった日遠は、«罰を受けかけた身だから» と身延山をはなれ、大野の庵にひっそりと住みました。お万の方は、息子である紀州の徳川頼宣と水戸の徳川頼房に命じ、この地に立派な伽藍を寄進させます。こうして生まれたのが本遠寺です。今もこの寺は «お万さまの寺» と呼ばれています。","1653年、お万の方は江戸で亡くなりましたが、遺言によってこの寺に葬られ、師・日遠の墓のかたわらに眠っています。1867年の火事で多くの建物が焼けましたが、本堂と鐘楼堂だけは焼け残りました。檜皮ぶきの大きな屋根は、350年以上前の姿を今に伝えています。"],"tl":[["1604年","日遠が身延山久遠寺の22世となる"],["1608年","慶長宗論。日遠が抗議し、処刑されかける"],["1609年","お万の方の帰依を受け、日遠が大野に本遠寺を開く"],["1626年","本阿弥光悦が扁額を奉納したとされる"],["1650年","頼宣・頼房の寄進で本堂・鐘楼堂が建つ"],["1653年","お万の方が亡くなり、遺言でこの寺に葬られる"],["1867年","火事で本堂と鐘楼堂以外が焼ける"],["1986年","本堂・鐘楼堂が国の重要文化財に"]],"who":[["心性院日遠","開山。身延山22世。処刑をまぬがれ大野に隠れ住んだ"],["養珠院（お万の方）","家康の側室。日遠を救い、寺を建てさせた"],["徳川家康","日遠をいったん処刑しようとしたが許した"],["徳川頼宣・徳川頼房","お万の方の子。紀州・水戸徳川家の祖。伽藍を寄進"],["本阿弥光悦","芸術家。日蓮宗の信者で、扁額を書いたとされる"]],"deep":["本堂は入母屋造・檜皮葺、正面5間・側面7間。鐘楼堂は吹き放しの2階建て。どちらも1650年の建物で、1986年に国の重要文化財になりました。","お万の方の墓所は «徳川家康側室養珠院墓所» として山梨県の史跡に指定されています。","お万の方は、七面山がかつて女人禁制だった時代に、女性として初めて登ったと伝わり、«七面山女人踏み分けの祖» とも呼ばれます。","日遠は1630年の «身池対論» で不受不施派に勝ち、池上本門寺の貫首にもなりました。晩年は «宗門中興の三師» の一人と評されます。","宝蔵の釈迦如来立像は、頭の内側の墨書から1266年に仏師・覚慶が作ったとわかる鎌倉時代の像です（県指定文化財）。","お万の方が «いっしょに死ぬ» と願い出た話や死に装束の話は、寺や宗門に伝わる逸話です。"],"look":["本堂（檜皮葺の大屋根）","鐘楼堂（吹き放しの2階建て）","養珠院お万の方と日遠の墓所","本阿弥光悦の扁額と伝わる額","県の天然記念物のクスノキと、春のしだれ桜"],"q":["本遠寺を «お万さまの寺» と呼ぶのはなぜ？","家康の側室・お万の方が、師の日遠のために建てさせた寺だからです。"],"koji":[],"myth":"お万の方の助命嘆願・死に装束の逸話は寺伝。光悦扁額は銘による。","img":["養珠院","身延山久遠寺","徳川頼宣","徳川頼房"],"wp":"本遠寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/72/%E6%9C%AC%E9%81%A0%E5%AF%BA%E6%9C%AC%E5%A0%82.JPG",4000,3000,"本遠寺"],["c:d/db/Bronze_statue_of_%22Youjuin%22.jpg",960,1280,"養珠院"],["c:a/af/Kuonji-temple-Hondou.jpg",800,600,"身延山久遠寺"],["c:0/0a/Tokugawa_Yorinobu.jpg",588,607,"徳川頼宣"],["c:3/32/Tokugawa_Yorihusa.jpg",3050,4616,"徳川頼房"]]},{"id":"19_omuro_sengen","n":"冨士御室浅間神社（富士山最古の社伝）","yomi":"ふじおむろせんげんじんじゃ","cat":"寺社","rank":"B","y":699,"era":["asuka","muromachi","edo"],"sh":"国の重要文化財（本宮本殿）・世界文化遺産「富士山」の構成資産","ad":"南都留郡富士河口湖町勝山","st":"富士急行線河口湖駅から周遊バスなどで約15分、«富士御室浅間神社» 下車","la":35.40001,"lo":138.75517,"hook":"富士山の中に最初にまつられたと伝わる神社。武田信玄が娘の安産を祈った手紙が残る。","lead":"冨士御室浅間神社は、河口湖のほとりにある神社です。699年に富士山の二合目にまつられたのが始まりと伝わり、«富士山の山中でいちばん古い神社» とされます。今は湖畔の里宮に本殿が移され、世界文化遺産 «富士山» の構成資産にもなっています。","story":["社伝によれば、始まりは699年。富士山の吉田口登山道の二合目に神がまつられました。«御室（おむろ）» という名前は、石の柱でかこんだ中でお祭りをしたことに由来するといわれます。今のような社殿のない、古い形の祈りの場だったのかもしれません。","山の上の神社にお参りするのは大変です。そこで958年、湖の南岸に «里宮» がつくられたと伝わります。山の «本宮» と、ふもとの «里宮»。二つの宮は、中世には山で修行する修験者、江戸時代には富士山に登る «富士講» の人びととも結びついて栄えました。","戦国時代、この神社をあつく敬ったのが武田氏です。1557年、武田信玄はこの神社に一通の願い文を納めました。北条氏政に嫁いだ長女（黄梅院）の安産を祈るものです。«娘が無事に子を産めますように» ――。武田・北条・今川の «三国同盟» のために嫁いだ娘を思う、父としての信玄の顔が見えてきます。","山の本宮の本殿は、1612年に徳川家の家臣・鳥居成次が建てたものです。けれど二合目の厳しい気候の中で、建物は傷んでいきました。1973年、本殿は山から下ろされ、湖畔の里宮の隣に移されました。今、私たちは河口湖のほとりで、桃山時代の雰囲気を残す本殿を見ることができます。","4月29日には流鏑馬が奉納されます。平安時代、平将門の乱をしずめた藤原秀郷が、お礼として馬を走らせたのが始まりと伝わります。一度はとだえた流鏑馬は、1980年から鎌倉の鶴岡八幡宮の武田流の人たちを招いてよみがえりました。"],"tl":[["699年","富士山二合目に創建されたと伝わる"],["940年","藤原秀郷が流鏑馬を奉納したと伝わる"],["958年","河口湖の南岸に里宮が建てられたと伝わる"],["1557年","武田信玄が娘の安産祈願の願文を納める"],["1612年","鳥居成次が本宮本殿を建てる"],["1973年","本宮本殿を二合目から里宮の隣へ移す"],["2013年","世界文化遺産 «富士山» の構成資産に"]],"who":[["藤原義忠","神社を創建したと伝わる人物"],["武田信玄","娘の安産を祈る願文を納めた"],["黄梅院","信玄の長女。北条氏政の妻"],["鳥居成次","江戸時代はじめの谷村の領主。本殿を建てた"],["小佐野越後守","神社の別当（管理者）を代々つとめた家の名"]],"deep":["本宮本殿は一間社入母屋造で、正面に唐破風の向拝をもちます。『甲斐国志』に1612年建立とあり、国の重要文化財です。","富士山二合目の旧本宮の地は、今も富士河口湖町勝山の «飛び地» になっています。","神社に伝わる『勝山記』は、1466年から1563年までの出来事を地元の僧たちが書き継いだ年代記の写本で、戦国時代の富士北麓のようすを知る一級史料（山梨県指定文化財）です。","信玄は1566年にも同じ内容の願文を納めており、別の家に伝わる写しでは、願いがかなえば鎌倉往還の黒駒の関所を開放すると約束しています。","明治時代に «小室浅間神社» から今の名前に改められました。富士吉田市下吉田の «小室浅間神社» とは別の神社です。","流鏑馬は、かつて富士北麓の村々が合同で行っていましたが、争いがおきたため、1530年に武田家臣・板垣信方の命で村ごとに行うようになったと伝わります。"],"look":["本宮本殿（国の重要文化財。1973年に二合目から移築）","里宮の社殿と、湖畔の参道","里宮の右隣にある勝山民俗資料館（開館日は事前に確認を）","4月29日の流鏑馬（開催は事前に確認を）"],"q":["信玄がこの神社に祈ったのは何？","北条氏政に嫁いだ長女（黄梅院）の安産です。"],"koji":[],"myth":"699年の創建、958年の里宮創建、流鏑馬の起源はいずれも社伝。","img":["富士山","河口湖","勝山記","武田信玄"],"wp":"冨士御室浅間神社","rel":{"ev":[],"grave":[]},"ph":[["c:1/15/Fuji-omuro-sengen-jinja-Hongu.jpg",3648,2736,"冨士御室浅間神社"],["c:6/69/Fujiomurosengen-satomiya-honden.jpg",3024,4032],["c:2/24/Fujinomiya_Hongu_Sengen_Taisha_Honden.jpg",2816,2112],["c:d/d9/Kodaki_fuji_frm_shojinko.jpg",1530,1024],["c:5/55/Mt.Fuji_from_Mierula.jpg",4610,3457,"富士山"],["c:1/18/KawaguchiKo.jpg",2816,2112,"河口湖"],["c:c/cd/Fuji_Kawaguchi_357.JPG",4320,2880,"勝山記"],["c:3/33/Takeda_Harunobu.jpg",1400,1707,"武田信玄"]]},{"id":"19_komuro_sengen","n":"小室浅間神社（流鏑馬の祭り）","yomi":"おむろせんげんじんじゃ","cat":"寺社","rank":"B","y":807,"era":["heian","muromachi","edo"],"sh":"","ad":"富士吉田市下吉田3丁目","st":"富士急行線下吉田駅から歩いて約5分","la":35.49482,"lo":138.80317,"hook":"矢が当たるかより、馬の «足あと» が大事。1年の運を占う、ふしぎな流鏑馬。","lead":"小室浅間神社（正式には冨士山下宮小室浅間神社）は、富士吉田市下吉田にある神社で、地元では «下宮さん» と呼ばれます。毎年9月19日の流鏑馬祭りでは、馬が走ったあとの足あとで1年の吉凶を占う «馬蹄占（ばていうらない）» が行われ、山梨県の無形民俗文化財になっています。","story":["社伝によると、平安時代のはじめ、蝦夷を討つために東へ向かった坂上田村麻呂が、この地から富士山を拝んで勝利を祈りました。そして戦いに勝ったあとの807年、お礼として社殿を建てたのが始まりだといいます。富士の北のふもとで暮らす人びとにとって、ここは古くからの «村の守り神» でした。","この神社の名物は、なんといっても流鏑馬です。けれど、ふつうの流鏑馬とはだいぶ違います。«的に当たったかどうか» はあまり問題ではありません。大事なのは、馬が走ったあとに残る «ひづめの跡»。代々この役をつとめる «占人（うらびと）» が、足あとの形を見て、その年の作物や暮らしの吉凶を占うのです。","地元の人はこの祭りを «うまっとばし» と呼びます。甲州弁で «馬を走らせる» という意味です。祭りの前には、馬主や奉仕する人たちが神社の潔斎館にこもり、1週間ほど身を清めて暮らします。«なぜそこまで?» ――神さまの答えを正しく受け取るためには、まず自分が清らかでなければならない、と考えられてきたからです。","かつて流鏑馬は、富士北麓の村々が合同で行っていました。ところが、だれが中心になるかで村どうしの争いが激しくなります。1530年、武田家の重臣・板垣信方の指示で、村ごとに行うことになったと伝わります。戦国の武将が «祭りのけんか» まで仲裁していたのです。","境内では今も神馬が飼われ、5月5日には «神馬祭» が行われます。境内の桂の大木には、南北朝時代に亡くなった護良親王の首が葬られたという言い伝えもあります。富士山のふもとで、何百年も続いてきた人と馬と神さまの物語が、今も生きている場所です。"],"tl":[["793年","坂上田村麻呂が富士山を拝み戦勝を祈ったと伝わる"],["807年","社殿が建てられたと伝わる（創建）"],["1176年","流鏑馬を行うことが定められたと伝わる"],["1440年","毎年9月19日に行うことが定められたと伝わる"],["1530年","板垣信方の指示で、流鏑馬が村ごとの奉納になったと伝わる"],["明治時代","«冨士山下宮浅間神社» から «小室浅間神社» に改称"],["1993年","祭りを守るため、境内で神馬の飼育を始める"]],"who":[["坂上田村麻呂","平安時代の将軍。神社を建てたと伝わる"],["板垣信方","武田氏の重臣。流鏑馬を村ごとに行うよう命じたと伝わる"],["占人（うらびと）","馬の足あとで吉凶を占う、代々の役目の家"],["護良親王","後醍醐天皇の皇子。首が境内に葬られたという伝説がある"]],"deep":["祭りは1月15日の «馬出しのくじ» から始まり、9月1日の初馬揃、9月13日からの潔斎、18日の宵宮、19日の本祭りと続く、長い行事です。","1月14日の夜から行われる «筒粥祭» では、粥に入れた竹筒の中身で作物の出来や富士山の登山者の多さまで占います。戦国時代の年代記『勝山記』にも «ツゝカイ» として出てきます。","馬の額を飾る «オテンゴー（御天狗）» は、たてがみを組ひもで編んだ飾りで、馬の埴輪の額飾りを受けついだ形とも考えられています。","«下宮» の名前の由来には諸説あります。二合目の冨士御室浅間神社を «上宮» とする説は広く知られますが、神社側は由緒が違うとしてこれを否定しています。","本殿は1767年の建築で、山梨県で最大級の一間社本殿とされ、郡内地方の神社建築の手本になりました。","60年に一度、ご神体の衣を替える «御更衣祭» があり、前回は2010年に行われました。"],"look":["境内の馬場と神馬舎（神馬に会える）","桂の御神木と大塔宮社（護良親王の伝説）","拝殿の扁額（雷で焼けた杉の古木を使ったと伝わる）","9月19日の流鏑馬祭り（見学は神社の案内に従って）"],"q":["この神社の流鏑馬で、占いに使うのは何？","馬が走ったあとの «ひづめの跡（足あと）» です。これを «馬蹄占» といいます。"],"koji":[],"myth":"坂上田村麻呂の創建、流鏑馬の年代、護良親王の首の話はいずれも社伝・伝承。","img":["流鏑馬","富士吉田市","護良親王","坂上田村麻呂"],"wp":"小室浅間神社","rel":{"ev":[],"grave":[]},"ph":[["c:0/0a/Yabusame_01.jpg",1070,1574,"流鏑馬"],["c:6/6e/Fujiyoshida_montage.jpg",2870,3168,"富士吉田市"],["c:5/5a/%E8%AD%B7%E8%89%AF%E8%A6%AA%E7%8E%8B.jpg",533,367,"護良親王"],["c:8/8d/Sakanoue_Tamuramaro_sw.jpg",1513,1680,"坂上田村麻呂"]]},{"id":"19_iida_gawara","n":"飯田河原の戦い（信虎が今川勢を破る）","yomi":"いいだがわらのたたかい","cat":"古戦場","rank":"B","y":1521,"era":["muromachi"],"sh":"","ad":"甲府市飯田","st":"JR甲府駅から南西へ歩いて約20分（合戦地は荒川沿いの一帯で、はっきりした範囲は不明）","la":35.6655,"lo":138.5545,"hook":"甲府が敵に攻めこまれた日。その最中に、ひとりの赤ん坊――のちの信玄が生まれていた。","lead":"1521年、駿河の今川氏の軍勢が甲斐へ攻めこみ、できたばかりの甲府の近くまで迫りました。武田信虎は甲府の西を流れる荒川の河原、飯田河原でこれを迎えうち、撃退しました。この戦いのさなか、信虎の嫡男・晴信（信玄）が生まれています。","story":["1521年の春、駿河（静岡県）の今川氏の家臣・福島正成が、富士川をさかのぼって甲斐に攻めこんできました。甲斐の南部をおさえる穴山氏も、一時は今川方についたと考えられています。信虎が甲府に本拠を移して、まだ2年。新しい町は、いきなり大きな危機をむかえたのです。","秋になると今川勢は勢いを強め、9月には甲府盆地の西、今の南アルプス市にあった大井氏の富田城を落とします。敵は甲府のすぐそばまで迫りました。信虎は、身重の妻・大井夫人を館の背後の山城・要害山城へ避難させ、決戦にそなえます。«ここで負ければ、甲斐はすべて失われる» ――まさに崖っぷちでした。","10月16日、信虎の軍は、甲府の西を流れる荒川の河原、飯田河原で今川勢とぶつかりました。数の上では今川勢のほうが多かったと伝わりますが、信虎は敵を打ち破り、退かせることに成功します。のちの記録には、«川をせき止めてから一気に堤を切った» といった作戦の話も伝わりますが、確かな史料にはありません。","そしてこの戦いのさなか、要害山城で大井夫人が男の子を産みました。のちの武田晴信、つまり信玄です。その幼名 «勝千代» は、この勝利にちなむともいわれます。«戦の中で生まれた子» ――信玄の生涯を思うと、なんとも象徴的な誕生でした。","信虎はさらに11月23日、上条河原（今の甲斐市）の戦いでも今川勢を破り、駿河へ追い返しました。この二つの勝利で、信虎の甲斐統一は大きく前進します。今の飯田のあたりは住宅やお店が並ぶ町中ですが、荒川の流れを見ながら、甲府をぎりぎりで守った戦いを思いうかべてみましょう。"],"tl":[["1519年","信虎が本拠を甲府に移す"],["1521年2月","今川方の福島正成らが甲斐に攻めこむ"],["1521年9月16日","今川勢が大井氏の富田城を落とす"],["1521年10月16日","飯田河原の戦い。信虎が今川勢を退ける"],["1521年11月3日","要害山城で晴信（信玄）が生まれる"],["1521年11月23日","上条河原の戦いで今川勢を破る"],["1522年正月","武田・今川の間で和睦"]],"who":[["武田信虎","甲斐の守護。今川勢を撃退した"],["福島正成","今川氏の家臣。攻めこんだ軍の中心とされる"],["大井夫人","信虎の妻。戦いのさなかに信玄を産む"],["武田信玄（晴信）","この戦いの最中に生まれた"],["今川氏親","駿河の大名。当時の今川家当主"]],"deep":["戦いの経過は『高白斎記』『勝山記』などの年代記に見えますが、兵の数や作戦の細かい話は、後の軍記物に多く見られる内容です。","«今川勢8000、武田勢2000» といった兵力の数字はよく紹介されますが、確かな同時代史料で裏付けられたものではありません。","福島正成はこの一連の戦いで討ち死にしたとされますが、上条河原で討たれたとする記録など、場所や経過には異説があります。北条綱成を正成の子とする話もありますが、これも諸説です。","信玄の誕生日は大永元年11月3日。飯田河原と上条河原の二つの勝利にはさまれた日です。","«勝千代» という幼名が勝利にちなむという話は、後世に広まった言い伝えです。","攻めこまれたとき、信虎が大井夫人を避難させた要害山城（甲府市上積翠寺町）は国の史跡 «武田氏館跡» の一部です。"],"look":["荒川の河原と、甲府盆地を囲む山々（合戦地の地形をイメージ）","北の要害山城跡（信玄誕生の地と伝わる積翠寺も近い）","武田神社（躑躅ヶ崎館跡）で信虎の甲府づくりを知る"],"q":["飯田河原の戦いのさなかに生まれた有名人は？","武田信玄（晴信）です。要害山城で生まれたと伝わります。"],"koji":[],"myth":"兵力・作戦（川のせき止め）・福島正成の最期・幼名の由来は諸説や後世の伝承。合戦地の正確な位置は不明。","img":["武田信虎","要害山城","福島正成","今川氏親"],"wp":"飯田河原の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:f/fc/Takeda_Nobutora_by_Takeda_Nobukado_%28Daisenji_Kofu%29.jpg",358,864,"武田信虎"],["c:6/60/Mt.Yogai_Kofu_city.JPG",4000,3000,"要害山城"],["c:b/b8/%E4%BB%8A%E5%B7%9D%E6%B0%8F%E8%A6%AA%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1320,1483,"今川氏親"]]},{"id":"19_kurokoma_kassen","n":"黒駒合戦（天正壬午の乱）","yomi":"くろこまかっせん","cat":"古戦場","rank":"B","y":1582,"era":["azuchi"],"sh":"","ad":"笛吹市御坂町上黒駒・下黒駒","st":"JR石和温泉駅から車で約15分","la":35.61,"lo":138.69,"hook":"信長の死で «持ち主のいなくなった» 甲斐。家康と北条が奪いあった戦いの、勝敗を分けた一戦。","lead":"1582年、本能寺の変で織田信長が亡くなると、ほろびたばかりの武田氏の領地をめぐって、徳川家康と北条氏が争いました。これを «天正壬午の乱» といいます。その中の8月12日、笛吹市御坂町の黒駒で、少ない徳川勢が北条の別働隊を打ち破ったのが «黒駒合戦» です。","story":["1582年3月、織田信長と徳川家康の軍に攻められ、武田氏はほろびました。甲斐は信長の家臣・河尻秀隆が治めることになります。ところがわずか3か月後の6月2日、京都で本能寺の変が起き、信長が亡くなりました。甲斐では一揆が起こって河尻は殺され、国は «持ち主のいない» 状態になってしまいます。","«この国を取るのはだれか?» ――名乗りをあげたのが、東の北条氏と、南の徳川家康でした。家康は武田の旧臣たちを味方に引き入れながら甲斐へ入り、新府城（韮崎市）に陣をかまえます。対する北条氏直は大軍をひきいて北の若神子（北杜市）に陣取り、両軍はにらみ合いになりました。","北条はさらに、別働隊を南から送りこみます。富士山の北、郡内の方から御坂峠をこえて甲府盆地に入り、家康の背後をつこうとしたのです。«前と後ろからはさめば、家康は逃げ場を失う» ――北条の作戦でした。","8月12日、峠を下りてきた北条勢を、黒駒のあたりで待ちうけたのが、鳥居元忠らの徳川勢でした。数ではずっと少なかったといわれますが、徳川勢は北条勢を打ち破り、多くの兵を討ち取りました。この勝利で北条の «はさみうち» の作戦はくずれ、甲斐の中で北条は動きにくくなります。","にらみ合いは秋まで続きましたが、10月29日、ついに両者は和睦します。甲斐と信濃は家康、上野は北条のものとし、家康の娘・督姫が北条氏直に嫁ぐことになりました。こうして甲斐は徳川のものとなり、のちの江戸幕府の時代へとつながっていきます。黒駒の静かな山里は、その分かれ道となった場所です。"],"tl":[["1582年3月","織田・徳川軍の侵攻で武田氏滅亡"],["1582年6月2日","本能寺の変。信長が亡くなる"],["1582年6月18日","甲斐の一揆で河尻秀隆が殺される"],["1582年7〜8月","家康が新府城、北条氏直が若神子に陣をしき対陣"],["1582年8月12日","黒駒合戦。鳥居元忠らが北条勢を破る"],["1582年10月29日","徳川・北条が和睦。甲斐・信濃は家康のものに"]],"who":[["徳川家康","甲斐を手に入れた大名。新府城に陣をしいた"],["鳥居元忠","家康の家臣。黒駒で北条勢を破った"],["北条氏直","北条家の当主。若神子に陣をしいた"],["北条氏忠","氏直の一族。御坂から攻めこんだ別働隊をひきいたとされる"],["河尻秀隆","信長の家臣。甲斐を治めたが一揆で殺された"]],"deep":["«天正壬午の乱» という呼び名は、1980年代以降に研究者が使い始めて広まりました。どの範囲の争いを指すかは研究者によって違います。","兵力は、徳川勢2000、北条勢1万などと紹介されることが多いですが、史料によって数字が違い、確かではありません。","北条方は御坂峠に «御坂城» を築いて拠点にしました。御坂城跡は今も峠の上に土塁などが残ります。","黒駒の勝利のあと、郡内（都留郡）には鳥居元忠が置かれ、谷村などを治めることになりました。","甲斐の武田旧臣たちは、この年に家康へ忠誠を誓う起請文を出しました（天正壬午起請文）。彼らの多くはのちに徳川家臣団の一員となります。","«黒駒» の地名は、聖徳太子が乗ったという «甲斐の黒駒»（黒い名馬）の伝説と結びつけて語られます。"],"look":["黒駒の集落と、御坂峠へ続く谷の地形（北条勢が下りてきた道）","御坂峠の御坂城跡（登山の装備で）","新府城跡（韮崎市）・若神子（北杜市）とあわせて、対陣の全体像をつかむ"],"q":["天正壬午の乱で、家康と甲斐を争った大名家は？","北条氏です。最後は和睦し、甲斐は家康のものになりました。"],"koji":[],"myth":"兵力や戦死者の数は史料によって大きく違う。合戦地の正確な範囲も不明。","img":["鳥居元忠","新府城","北条氏直"],"wp":"天正壬午の乱","rel":{"ev":[],"grave":[]},"ph":[["c:b/b9/Kawajiri_Hidetaka%27s_tomb.JPG",4000,3000],["c:9/90/Distant_view_of_the_Koyama_Castle_Kai_Province.JPG",4000,3000],["j:0/09/%E7%94%B2%E6%96%90%E5%A5%88%E7%A5%9E%E7%A4%BE_%28%E7%AC%9B%E5%90%B9%E5%B8%82%E4%B8%80%E5%AE%AE%E7%94%BA%E6%A9%8B%E7%AB%8B%29_%E6%8B%9D%E6%AE%BF%E6%96%9C%E3%82%81.JPG",3648,2736],["c:0/0f/Torii_Mototada.jpg",354,501,"鳥居元忠"],["c:7/7e/Shinpu_Castle.jpg",2048,1536,"新府城"],["c:2/2c/Hojo_Ujinao.jpg",466,745,"北条氏直"]]},{"id":"19_midai","n":"御勅使川の石積出し（信玄の治水）","yomi":"みだいがわのいしつみだし","cat":"産業","rank":"B","y":1560,"era":["muromachi","edo"],"sh":"国指定史跡（御勅使川旧堤防〈将棋頭・石積出〉）","ad":"南アルプス市有野","st":"JR甲府駅から車で約30分（公共交通では行きにくい）","la":35.65353,"lo":138.41631,"hook":"暴れ川と戦った人びとの «石の知恵»。川の流れを «はじき返す» 巨大な石積み。","lead":"御勅使川（みだいがわ）は、甲府盆地の西で何度も大洪水を起こしてきた «暴れ川» です。戦国時代から、武田信玄の治水と結びつけて語られる石の堤防や «石積出し» が築かれ、流れをおさえてきました。その一部が «御勅使川旧堤防（将棋頭・石積出）» として国の史跡になっています。","story":["南アルプスの山から流れ出る御勅使川は、ふだんは水の少ない川です。ところが大雨が降ると、山をけずった大量の土砂といっしょに一気にあふれ出し、甲府盆地の西をのみこみました。川の名前は、大水が出る «水出川» とも、平安時代に洪水の見舞いに朝廷から «勅使» が来たからともいわれます。","«どうすればこの暴れ川をおさえられるのか?» ――戦国時代、甲斐を治めた武田信玄の時代に、大がかりな治水が行われたと伝わります。下流の釜無川には堤防（信玄堤）を築き、御勅使川の流れを竜王の «高岩» にぶつけて勢いを弱めた、というのです。","その上流の南アルプス市有野に残るのが «石積出し» です。川の岸から斜めに突き出すように、大きな石を積み上げた堤防がいくつも並んでいます。これで激流を受け止め、流れを川の中央へ «はじき返し»、堤防が一気に切れるのを防いだのです。一番、二番…と番号がつけられ、今も石の列を見ることができます。","下流には、将棋の駒のような形をした石の堤防 «将棋頭» もあります。先のとがった部分で流れを二つに分け、水の勢いを弱めるしくみです。«一か所で力ずくで止めるのではなく、流れをいなして弱める» ――ここに、昔の人の治水の知恵が表れています。","ただし、これらがいつ、だれによって作られたかは、はっきりしていません。«信玄の治水» として語られてきましたが、江戸時代や明治時代にも洪水のたびに修理や作り直しが行われ、今残る石積みにはさまざまな時代のものがまじっていると考えられています。石の一つ一つに、何百年も川と向きあってきた人びとの汗がしみこんでいます。"],"tl":[["825年","大洪水が起き、朝廷から勅使が来たと伝わる（川名の由来の一説）"],["15〜16世紀はじめ","大きな氾濫で流路が変わったと考えられている"],["1560年","竜王の堤防（信玄堤）に関する最古の武田家文書が出される"],["1653年","堤防が決壊し、西郡一帯に被害"],["1896年","大洪水。その後、将棋頭から続く長い石堤が築かれる"],["2003年","«御勅使川旧堤防（将棋頭・石積出）» が国の史跡に"]],"who":[["武田信玄","治水事業を始めたと伝わる戦国大名"],["文室秋津","平安時代の甲斐国司。勅使の派遣を朝廷に願ったと伝わる"],["流域の村人たち","江戸時代以降、洪水のたびに堤防の修理を担った"]],"deep":["御勅使川は長さ約19kmと短いのに、上流の地層（御坂層）がくずれやすいため、大量の砂礫を運びます。その砂礫でできたのが広い «御勅使川扇状地» です。","扇状地の上は水はけがよすぎて、江戸時代には «原七郷» と呼ばれる水の乏しい土地になりました。ここはのちに果樹の産地になります。","発掘調査では、御勅使川には今の流れのほかに5本ほどの古い流路の跡が見つかっており、昔は大きく流れを変えていたことがわかっています。","«信玄が御勅使川の流れを人工的に北へ移した» という話については、今の流路は自然にできた可能性もあるという研究結果もあります。","将棋頭は南アルプス市六科（白根将棋頭）と韮崎市竜岡（竜岡将棋頭）にあり、石積出しとあわせて3か所が国の史跡です。","«信玄堤» という呼び名は江戸時代後期から見え、武田時代の史料では «竜王川除（かわよけ）» と書かれています。"],"look":["石積出し（一番〜の番号付きの石堤）","白根将棋頭と竜岡将棋頭のとがった形","河原に広がる大きな石や砂礫（暴れ川の証拠）","下流の信玄堤公園（甲斐市）もあわせて"],"q":["流れを二つに分ける、将棋の駒の形をした堤防を何という？","«将棋頭（しょうぎがしら）» です。"],"koji":[],"myth":"信玄が築いたという話は伝承が中心で、築造時期ははっきりしない。川名の由来も諸説。","img":["信玄堤","釜無川","治水"],"wp":"御勅使川","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/Midaiminamikouen.JPG",2352,1568,"御勅使川"],["c:7/79/Midai_river_erosion_control_dike.JPG",4000,3000],["c:2/23/Aerial_view_of_the_ruins_of_medieval_flood_control_Midai_river.jpg",3567,2198],["c:4/4f/Tatsuoka-shougigashira.JPG",2352,1568],["c:6/6b/Shirane-shougigashira.JPG",2352,1568],["c:a/a1/Midai-gawa_Kyuteibo_Ishitusumidashi.jpg",1920,1440],["c:3/38/Outside_of_Shingen_embankment.JPG",4000,3000,"信玄堤"],["c:c/c9/Mt.Iwamoto.jpg",1800,1350,"釜無川"]]},{"id":"19_kajikazawa","n":"鰍沢河岸（富士川舟運の拠点）","yomi":"かじかざわがし","cat":"町","rank":"B","y":1607,"era":["edo","meiji"],"sh":"","ad":"南巨摩郡富士川町鰍沢","st":"JR身延線鰍沢口駅から歩いて約20分（富士川を渡る）","la":35.5485,"lo":138.4625,"hook":"日本三大急流を舟が行き来した、山国の «港町»。","lead":"鰍沢（かじかざわ）は、日本三大急流の一つ富士川のほとりにある町です。江戸時代のはじめに富士川の舟運が開かれると、鰍沢は «河岸（かし）»、つまり川の港として大いに栄えました。甲斐の年貢米を下り、駿河の塩を上らせる、山国の玄関口でした。","story":["海のない甲斐の国。重い米や塩を運ぶのは、昔はたいへんな仕事でした。山道を馬や人の背で運ぶしかなかったからです。そこに目をつけたのが、京都の豪商・角倉了以でした。«川を道にすればよい» ――了以は岩をくだき、流れを整えて、富士川を舟が通れる川にしたのです。1607年ごろのことと伝わります。","こうして、甲府盆地の南の出口にある鰍沢・青柳・黒沢の三つの河岸から、舟が駿河の岩淵（今の静岡県富士市）まで下るようになりました。甲斐や信濃の年貢米は舟で岩淵まで運ばれ、そこから清水の港をへて江戸へ送られました。«川の道» が、山国と大都市・江戸をつないだのです。","帰りの舟には、塩や海産物が積まれました。«下りは急流に乗ってあっというま、上りは何日もかかった» と伝わります。上りの舟は、岸から船頭たちが綱で引っぱってさかのぼったといいます。鰍沢の河岸跡の発掘では、マグロやイルカなど駿河湾の魚の骨も見つかっていて、海の幸が山国まで届いていたことがわかります。","にぎわう鰍沢は、文化の舞台にもなりました。葛飾北斎は『富嶽三十六景』に «甲州石班澤（かじかざわ）» を描き、荒々しい流れで網を打つ漁師と富士山を組み合わせました。また、三遊亭圓朝の落語 «鰍沢» は、雪の山道で迷った旅人がこの地で恐ろしい目にあう話です。身延山へお参りする人びとも、舟を使って行き来しました。","明治時代には舟運会社もでき、最盛期をむかえます。しかし1903年に中央線が甲府まで通り、1928年に身延線が全線開通すると、舟の役目は鉄道にうつっていきました。今の鰍沢は静かな町ですが、川沿いの道や古い家並みに、«山国の港町» の面影をさがすことができます。"],"tl":[["1607年ごろ","角倉了以が富士川の開削を行い、舟運が始まる"],["江戸時代","鰍沢・青柳・黒沢の «三河岸» から年貢米を岩淵へ下す"],["1830年代","葛飾北斎『富嶽三十六景』に «甲州石班澤» が描かれる"],["明治時代","富士川運輸会社が設立され、舟運が最盛期に"],["1903年","中央線が甲府まで開通"],["1928年","身延線が全線開通し、舟運はしだいに役目を終える"],["2010年","鰍沢町が増穂町と合併し富士川町に"]],"who":[["角倉了以","京都の豪商。富士川の舟運を開いた"],["葛飾北斎","浮世絵師。«甲州石班澤» を描いた"],["三遊亭圓朝","落語家。鰍沢を舞台にした噺 «鰍沢» を作った"],["船頭たち","急流で舟をあやつり、上りでは綱で舟を引いた"]],"deep":["«日本三大急流» は、富士川・最上川・球磨川とされます。","鰍沢河岸跡の発掘では、駿河湾でとれたマグロやイルカの仲間など、多様な海産物の骨が出土しています。同じような例は甲府城下町遺跡や谷村城跡でも見つかっています。","富士川の舟は «高瀬舟» と呼ばれる平たい底の舟で、急流や浅瀬でも進めるように工夫されていました。","舟運で上ってきた塩は、甲斐だけでなく信濃にも運ばれました。富士川は «塩の道» の一部でもありました。","北斎が甲斐を実際に訪れたかどうかは、確かな記録がなく分かっていません。","鰍沢は陸の街道・駿州往還（河内路）の宿場でもあり、«水陸の交差点» として発展しました。"],"look":["富士川の流れと、鰍沢の河岸があった川べり","旧街道沿いの古い町並み・蔵","富士川町の春の名所・大法師公園（桜）","北斎 «甲州石班澤» と見比べながら富士川を眺める"],"q":["富士川の舟運を開いた京都の豪商は？","角倉了以（すみのくら・りょうい）です。"],"koji":[],"myth":"舟運開始の正確な年、上り下りの日数は資料によって違う。落語 «鰍沢» は創作の話。","img":["富士川","角倉了以","甲州石班澤","鰍沢"],"wp":"鰍沢町","rel":{"ev":[],"grave":[]},"ph":[["c:5/58/Oboshi-park_cherry_blossoms.JPG",4000,3000,"鰍沢町"],["c:f/fc/Kajikazawa_in_Kai_province.jpg",4486,2948],["c:c/c9/Mt.Iwamoto.jpg",1800,1350,"富士川"],["c:7/7c/Wooden_statue_of_Suminokura_Ryoi.jpg",1344,1420,"角倉了以"],["c:c/c2/Katsushika_Hokusai%2C_kajikazawa_nella_provincia_di_kai%2C_dalla_serie_delle_36_vedute_del_monte_fuji%2C_1831_ca.jpg",3420,2328,"甲州石班澤"]]},{"id":"19_narada","n":"奈良田（孝謙天皇の伝承の里）","yomi":"ならだ","cat":"伝承","rank":"B","y":760,"era":["nara","showa"],"sh":"","ad":"南巨摩郡早川町奈良田","st":"JR身延線身延駅から早川町乗合バスで約90分（本数が少ないので要確認）","la":35.57667,"lo":138.30028,"hook":"«ここも真に奈良である» ――女帝が8年暮らしたと伝わる、南アルプスのふところの隠れ里。","lead":"奈良田は、南アルプスのふもと、早川の最上流にある山里です。奈良時代の女性天皇・孝謙天皇が病気を治すためにこの地へ来て、8年間暮らしたという伝説が残り、«奈良田» の名もそこから生まれたといわれます。独特の方言や山の暮らしの文化が残る «秘境» として知られます。","story":["身延からバスに揺られて1時間半。早川の谷をどんどん奥へ進むと、南アルプスの山々に囲まれた小さな集落、奈良田に着きます。ここには、奈良の都の天皇にまつわる、ふしぎな言い伝えがあります。","伝説によると、奈良時代、孝謙天皇が病をいやすため、よい温泉を求めて甲斐の山奥までやって来ました。はじめは少し南の西山温泉に入り、さらに霊験あらたかな湯を求めて奥へ。そしてこの地を見つけ、住まいを移したといいます。","住まいから早川の流れまで、土地が七つの段になっているのを見た天皇は、«奈良の都は七条だが、この地は七段。ここも真に奈良である» と言ったそうです。これが «奈良田» という名前の由来だと伝えられています。天皇は8年間ここで暮らし、村人から «奈良王» と呼ばれたといいます。住まいの跡とされる場所には、今は奈良王神社がまつられています。","«本当に天皇が来たの?» ――歴史の記録には、孝謙天皇が甲斐へ行ったという話はまったくありません。けれど、山深い里の人びとが «自分たちの村は都とつながっている» と語り伝えてきたこと自体が、この土地の誇りと文化を表しているのです。奈良田には、周りの地域とまったく違うアクセントの «奈良田方言» が残り、言葉の研究者からも注目されてきました。","昭和に入ると、奈良田は大きく変わります。1953年、発電用の西山ダムができ、古くからの温泉などがダム湖（奈良田湖）の底に沈みました。その後、新しく源泉が掘られ、温泉は «女帝の湯» の名でよみがえりました。北岳・間ノ岳・農鳥岳の白峰三山を歩いた登山者が、疲れた体をいやしに下りてくる里でもあります。"],"tl":[["奈良時代（伝説）","孝謙天皇が湯治に訪れ、8年暮らしたと伝わる"],["江戸時代","山深い村として焼畑や林業などで暮らす"],["1889年","町村制で奈良田村が発足（翌年、西山村に改称）"],["1953年","西山ダム（奈良田湖）が完成し、古い温泉などが湖底に沈む"],["1956年","周りの村と合併し早川町の一部に"],["1979年","新しい源泉を使った町営温泉が開業"]],"who":[["孝謙天皇","奈良時代の女性天皇。この地に住んだという伝説がある"],["奈良田の人びと","伝説と独自の方言・山の暮らしを受けついできた"],["白峰三山の登山者","南アルプス縦走の下山口として奈良田を訪れる"]],"deep":["孝謙天皇（のち重祚して称徳天皇）は、聖武天皇の娘。史料上は甲斐に行った記録はなく、奈良田の話は «貴人流離譚» と呼ばれる各地の伝説の一つと考えられます。","«奈良田方言» は、周りの山梨方言と違う独特のアクセントや言葉をもち、方言学で «言語の島» として知られます。","奈良田には «七不思議» と呼ばれる言い伝えがあり、孝謙天皇にまつわる話が多くふくまれます。","早川町は日本でも人口の少ない町の一つで、奈良田はその最奥部。ここから北の広河原へは、夏から秋にかけてマイカー規制があります。","今の温泉は泉質の違う二つの源泉があり、一つは色が刻々と変わるため «七不思議の湯» とも呼ばれます。","焼畑など山の暮らしの道具は、町の資料館などで紹介されています。"],"look":["奈良王神社（孝謙天皇の住まいの跡と伝わる）","奈良田湖と、周りの南アルプスの山々","温泉 «女帝の湯»","集落に残る古い民家や、山の暮らしの展示"],"q":["«奈良田» の名前の由来になった、孝謙天皇の言葉とは？","«奈良の都は七条、ここは七段。ここも真に奈良である» と言ったと伝わります。"],"koji":[],"myth":"孝謙天皇の来訪・8年の滞在・地名の由来はすべて伝説で、史料の裏付けはない。","img":["孝謙天皇","奈良田温泉","早川町","奈良田方言"],"wp":"西山村 (山梨県)","rel":{"ev":[],"grave":[]},"ph":[["c:1/17/Empress_K%C5%8Dken_01.jpg",713,1026,"孝謙天皇"],["c:e/e4/Narada_Onsen_Shiranekan.jpg",3811,2541,"奈良田温泉"],["c:f/fd/Stone_pavement_of_Akasawa.JPG",4000,3000,"早川町"]]},{"id":"19_shimobe","n":"下部温泉（信玄の隠し湯）","yomi":"しもべおんせん","cat":"伝承","rank":"B","y":1560,"era":["heian","muromachi","edo"],"sh":"","ad":"南巨摩郡身延町下部","st":"JR身延線下部温泉駅から温泉街まで歩いて約15〜20分","la":35.42278,"lo":138.48194,"hook":"傷ついた武田の兵が湯にひたった――と伝わる、ぬるくて長湯できる «隠し湯»。","lead":"下部温泉は、身延町の山あいにある古い温泉です。平安時代から湯がわいていたと伝わり、日蓮も湯治をしたことが手紙からわかります。戦国時代には武田信玄が兵の傷をいやした «隠し湯» だったという言い伝えがあり、今も湯治の温泉街として親しまれています。","story":["下部川に沿って宿が並ぶ、静かな温泉街。ここには «信玄の隠し湯» という言い伝えがあります。戦で傷ついた武田の兵たちが、ひそかにこの湯で傷をいやした――。敵に知られないように «隠した» 湯、というわけです。","でも、«本当に信玄の隠し湯だったの?» と聞かれると、答えは «わからない» です。山梨県や長野県には «信玄の隠し湯» とされる温泉がいくつもあり、多くは後から結びつけられた話だと考えられています。ただ、それだけ «信玄» と «温泉» の組み合わせが人びとに愛されてきた、ということでもあります。","温泉の歴史そのものは、もっと古くまでさかのぼります。江戸時代の地誌『甲斐国志』には、836年に熊野権現があらわれて湯がわいたという伝説が書かれています。鎌倉時代には、身延山にこもった日蓮がこの湯で湯治をしたことが、日蓮自身の手紙からわかっています。","下部温泉の湯は、とてもぬるいことで知られます。昔からの源泉は体温より少し低いくらいで、長い時間じっとつかる «湯治» にぴったりでした。«熱い湯でさっと» ではなく、«ぬるい湯でゆっくり» ――それが、傷や病をいやす昔ながらの入り方でした。","近くには、戦国時代に武田氏の金山として知られる湯之奥の中山金山があり、駅前には金山の博物館もあります。«温泉と金山» ――どちらも、山の恵みで国を支えた甲斐らしい組み合わせです。昭和の1956年には国民保養温泉地に指定され、今も身延山への参拝客や湯治の人たちが訪れています。"],"tl":[["836年","熊野権現があらわれ湯がわいたと伝わる（『甲斐国志』）"],["鎌倉時代","日蓮が湯治をする（書状による）"],["戦国時代","武田信玄の «隠し湯» だったと伝わる"],["江戸時代","湯治場として栄え、身延山参詣の人も利用"],["1928年","身延線が全線開通し、浴客が増える"],["1956年","国民保養温泉地に指定"]],"who":[["日蓮","鎌倉時代の僧。この湯で湯治をした"],["武田信玄","兵の傷をいやしたという «隠し湯» の伝説がある"],["抜隊得勝","塩山・向嶽寺の開山。湯治をしたといわれる"],["湯治客たち","ぬるい湯に長くつかり、体をいやした"]],"deep":["『甲斐国志』には、甲斐の国造・塩海足尼が見つけて «塩部（しおべ）の湯» と名づけたという、もう一つの伝説も記されています。","«信玄の隠し湯» の話は戦国時代の史料にはなく、後の時代に結びつけられた «付会伝説» と考えられています。","古い源泉はとてもぬるく、多くの宿が源泉そのままの湯と、温めた湯の二つの浴槽を用意しています。","2006年には新しく高温の源泉が掘られ、«しもべ奥の湯高温源泉» として使われています。","近くの湯之奥金山遺跡（中山金山など）は «甲斐金山遺跡» として国の史跡です。武田氏の «甲州金» を支えたと考えられています。","«熊野権現» の伝承から、温泉街には熊野神社がまつられています。"],"look":["下部川沿いの温泉街の景色","足もとから湯がわく古い宿の湯船（日帰り入浴は各宿に確認を）","駅前の湯之奥金山博物館と足湯","温泉街の熊野神社"],"q":["下部温泉の昔からの源泉の特ちょうは？","とてもぬるいことです。長い時間つかる湯治に向いています。"],"koji":[],"myth":"«信玄の隠し湯»、熊野権現・塩海足尼の発見談はいずれも伝説。","img":["日蓮","湯之奥金山","甲州金"],"wp":"下部温泉","rel":{"ev":[],"grave":[]},"ph":[["c:2/28/Shimobe-onsen.jpg",640,480,"下部温泉"],["c:5/52/Shimobe_Hot_springs_aerial_photograph.JPG",1636,1228],["c:0/06/Nichiren_Daishonin_Hakii_Portrait.jpg",600,612,"日蓮"],["c:1/1a/Koshu1bu-zyu.jpg",160,160,"甲州金"]]},{"id":"19_kitafuji","n":"北富士演習場（旧陸軍の演習地）","yomi":"きたふじえんしゅうじょう","cat":"昭和","rank":"B","y":1936,"era":["showa"],"sh":"","ad":"富士吉田市・南都留郡山中湖村","st":"演習場内は立入禁止。周辺の道路や展望地から見るだけにすること（富士急行線富士山駅から車で約15分）","la":35.41667,"lo":138.8,"hook":"富士山のすそ野に広がる «入会地»。暮らしの森が戦車と砲声の場になった、昭和の記憶。","lead":"北富士演習場は、富士山の北のすそ野、富士吉田市と山中湖村にまたがる広い演習場です。1936年に旧陸軍が開き、戦後はアメリカ軍に接収され、今は陸上自衛隊が管理し、アメリカ軍も使っています。もともと村人が薪や草を取る «入会地» だったため、長い間、土地をめぐる運動の舞台にもなりました。","story":["富士山の北のすそ野には、江戸時代から «入会地（いりあいち）» と呼ばれる土地が広がっていました。村の人たちが共同で使い、薪や炭の材料、屋根をふく茅、牛馬のえさの草などを取る場所です。山のふもとの暮らしは、この土地なしには成り立ちませんでした。","1936年、この地に陸軍の演習場が開かれます。戦争の時代に向かう中、兵士たちが大砲や銃の訓練をする場所になりました。それでも村人の入会の権利は、ある程度は黙認されていたといわれます。","1945年、戦争が終わると、演習場は連合国軍（アメリカ軍）に接収されました。砲弾が飛びかい、林が標的にされ、村人は暮らしの場を失っていきます。«この土地は、わたしたちの生活の場だ» ――地元の農民たちは、着弾地に座りこむなどして抗議を続けました。1960年には、忍野村の女性たちが «忍草母の会» をつくり、«土は万年、金はいっとき» を合言葉に入会権を守る運動を始めました。","1970年には、演習場内で野焼きの準備をしていた少年たちが不発弾にふれて爆発し、1人が亡くなり、1人が重傷を負う痛ましい事故も起きています。演習場の歴史には、こうした犠牲や、暮らしを守ろうとした人びとの長い苦労が刻まれています。","1973年からは陸上自衛隊が管理する演習場となりました。今も地元の組合と国が協定を結び、決められた日には住民が入って林業や山菜取りを行い、入会を確かめる野焼きが続けられています。立ち入りはできませんが、富士山の雄大なすそ野を眺めながら、ここで起きてきたことを静かに思いうかべたい場所です。"],"tl":[["江戸時代","富士北麓の村々の入会地として使われる"],["1936年","旧陸軍が演習場を開設"],["1945年","敗戦により連合国軍が接収"],["1960年","忍野村の女性たちが «忍草母の会» を結成"],["1970年","演習場内で不発弾が爆発し、少年1人が死亡"],["1973年","陸上自衛隊が管理する演習場に"]],"who":[["入会地の村人たち","薪や草を取る暮らしの場として土地を使ってきた"],["忍草母の会","入会権を守るため運動を続けた忍野村の女性たちの会"],["旧陸軍・アメリカ軍・陸上自衛隊","時代ごとに演習場を使ってきた組織"]],"deep":["演習場の広さは約4,600ha。国有地だけでなく、県有地や民有地もふくまれます。","地元の入会組合と国は、5年ごとに使用協定を結び直しています。","入会の権利を確かめる行事として、組合による野焼き（火入れ）が年中行事になっています。","«忍草母の会» の運動は、のちに千葉県の成田空港反対運動にも影響をあたえたといわれます。","戦後の演習場周辺では、治安の悪化や事故など、住民の生活に大きな影響が出たことが記録されています。","現在はドローンの飛行が法律で規制されている防衛関係施設です。"],"look":["周辺の展望地から見る富士山のすそ野（演習場内は立入禁止）","富士吉田市・忍野村の資料館などで入会の歴史を学ぶ","周辺道路では標識や規制に必ず従うこと"],"q":["村の人が共同で薪や草を取る土地を何という？","«入会地（いりあいち）» といいます。"],"koji":[{"w":"土は万年、金はいっとき","m":"«忍草母の会» の合言葉。土地は永遠に人を養うが、お金はすぐになくなる、という意味"}],"myth":"","img":["富士山","入会権","忍野村"],"wp":"北富士演習場","rel":{"ev":[],"grave":[]},"ph":[["c:0/09/Mount_Fuji_from_Hotel_Mt_Fuji_%282014-12-06%29.jpg",5184,2560,"北富士演習場"],["c:f/fc/North_Fuji_Maneuver_Area_Aerial_photograph_2007.jpg",7590,8445],["c:5/51/From_Mount_Fuji_%2828820785224%29.jpg",4608,3456],["c:b/bd/USMC-111109-M-TF033-022.jpg",2000,1333],["c:5/55/Mt.Fuji_from_Mierula.jpg",4610,3457,"富士山"],["c:2/22/231028_Waku-ike_Oshino_Hakkai_springs_Oshino_Yamanashi_pref_Japan01s3.jpg",5472,3648,"忍野村"]]},{"id":"19_rentai49","n":"歩兵第49連隊跡（甲府の連隊）","yomi":"ほへいだいよんじゅうくれんたいあと","cat":"昭和","rank":"B","y":1909,"era":["meiji","taisho","showa"],"sh":"","ad":"甲府市緑が丘・北新あたり","st":"JR甲府駅北口からバスで約10分（跡地は公園・学校・住宅地になっている）","la":35.6785,"lo":138.5605,"hook":"«郷土の連隊» を町をあげてむかえた明治。その兵士の多くが、遠い南の島から帰らなかった。","lead":"歩兵第49連隊は、甲府に置かれた旧日本陸軍の連隊で、«甲府連隊» と呼ばれました。1909年に甲府の北、相川村（今の甲府市緑が丘あたり）の兵営に入り、山梨県の若者たちが兵士として入隊しました。太平洋戦争では、フィリピンのレイテ島の戦いで大部分が亡くなっています。","story":["日露戦争が終わった1905年ごろ、甲府の町では «連隊をよぼう» という運動がさかんになりました。連隊が来れば、およそ3000人の兵士が町に住み、お金も人も集まります。それに、山梨の若者が遠くの部隊に行かずに、ふるさとで兵役をつとめられる――。市や県の議会も、国に連隊を置くよう願い出ました。","この運動を強く後押ししたのが、«甲州財閥» と呼ばれた実業家の若尾家です。国が土地の寄付を条件にすると、若尾民造は約10万坪（約33万㎡）の土地を寄付すると約束しました。こうして甲府への兵営の設置が決まり、1909年4月、千葉の習志野から連隊が到着します。町は «郷土の連隊» を歓迎しました。","兵営のまわりには練兵場や陸軍病院が置かれ、甲府は «軍都» としての顔ももつようになります。1918年の米騒動では、県知事の求めで連隊が町の騒ぎをしずめるために出動しました。1936年の二・二六事件のときには、反乱をしずめる側として東京へ向かっています。","やがて連隊は満州（中国東北部）に送られ、太平洋戦争の終わりが近づいた1944年、フィリピンのレイテ島の戦いに投入されました。アメリカ軍の圧倒的な力の前に、連隊の大部分は壊滅したといわれます。«ふるさとの家族に、もう一度会いたい» ――そう願いながら、多くの山梨の若者が南の島で命を落としました。","1945年7月には、甲府の町そのものも空襲で焼かれます。戦後、兵営の跡地は公園や学校、住宅地に変わりました。山梨大学に残る赤れんがの建物は、連隊の糧秣庫（食料や馬のえさの倉庫）だったものといわれています。平和な町並みの中で、ここにあった連隊と、帰らなかった人びとのことを忘れずにいたい場所です。"],"tl":[["1905年","日露戦争中、新しい師団の部隊として編成される"],["1907年","第1師団に編入。甲府に兵営を置くことが決まる"],["1909年4月","連隊が甲府（相川村）の新しい兵営に到着"],["1918年","米騒動の鎮圧に出動"],["1936年","二・二六事件の鎮圧に出動。その後満州へ"],["1944年","フィリピン・レイテ島の戦いで大部分が壊滅"],["1945年8月","終戦。セブ島で武装解除"]],"who":[["若尾民造","甲州財閥の実業家。兵営用地を寄付した"],["連隊の兵士たち","山梨県などから入隊した若者たち"],["甲府市民","連隊の誘致運動を進め、«郷土の連隊» として迎えた"]],"deep":["連隊の用地は約12万坪。半分が兵営と陸軍病院、半分が練兵場になりました。今の甲府市緑が丘・北新・天神町あたりにあたります。","連隊の兵士は山梨県のほか、神奈川県の一部（今の藤沢市あたり）からも集められました。","山梨大学（甲府市武田）に残る赤れんがの建物は、連隊の旧糧秣庫を活かしたものとされます。","レイテ島の戦いは1944年10月から始まり、日本軍は大きな犠牲を出しました。連隊は最終的にセブ島で終戦をむかえています。","連隊誘致は、経済効果のほか «県民や子どもたちへの教育効果» も期待されていたと記録されています。","兵営の工事は甲府の地元の建設業者が請け負い、1909年3月に完成しました。"],"look":["跡地の緑が丘スポーツ公園とその周辺（当時の敷地の広さを想像する）","山梨大学の赤れんが館（外観。見学は大学の案内に従う）","山梨県立博物館などで郷土の戦争の資料を見る"],"q":["甲府に連隊を置くための土地を寄付した実業家の家は？","甲州財閥の若尾家です。若尾民造が約10万坪の寄付を約束しました。"],"koji":[],"myth":"","img":["レイテ島の戦い","甲府空襲","若尾逸平"],"wp":"歩兵第49連隊","rel":{"ev":[],"grave":[]},"ph":[["c:8/89/Japanese_Army_Infantry_Regiment_%E2%84%9649_Ruins_Kofu_City.JPG",4000,3000,"歩兵第49連隊"],["c:1/17/Japanese_Army_Infantry_Regiment_%E2%84%9649_red_brick_warehouse.JPG",4000,3000],["c:0/0e/Douglas_MacArthur_lands_Leyte1.jpg",1600,1199,"レイテ島の戦い"],["c:8/8c/Air_raid_Kofu-City.jpg",2474,1807,"甲府空襲"],["c:7/73/Ippei_Wakao.jpg",349,488,"若尾逸平"]]},{"id":"19_hikage_tunnel","n":"大日影トンネル（明治の鉄道遺産）","yomi":"おおひかげとんねる","cat":"近代","rank":"B","y":1903,"era":["meiji","heisei"],"sh":"近代化産業遺産・土木学会選奨土木遺産","ad":"甲州市勝沼町深沢","st":"JR中央本線勝沼ぶどう郷駅から歩いてすぐ","la":35.66984,"lo":138.74386,"hook":"明治のれんがに、蒸気機関車のすすがそのまま。1.4kmを歩いて抜ける «時間のトンネル»。","lead":"大日影トンネルは、明治時代に中央本線のために掘られた、れんが造りの鉄道トンネルです。1903年の開通から90年あまり列車が走り、1997年に役目を終えました。今は長さ約1.4kmの遊歩道として、歩いて通り抜けることができます。","story":["明治のなかば、東京と甲府を鉄道で結ぶ計画が進みました。ところが、その間には笹子峠をはじめとする険しい山々が立ちはだかります。«山を越えられないなら、山をくぐればいい»――こうして、いくつものトンネルが掘られました。大日影トンネルもその一つで、1902年に貫通し、1903年に八王子〜甲府間が開通しました。","鉄道の開通で、甲州の暮らしは一変しました。それまで何日もかかった東京への道のりが大きく縮まり、勝沼のぶどうやワインが大量に都会へ運ばれるようになったのです。«ぶどうの郷» 勝沼が全国に知られるようになった陰には、このトンネルの働きがありました。","トンネルの中に入ると、ひんやりした空気に包まれます。壁は明治の職人が一つ一つ積んだれんが。見上げると、天井のあちこちが黒くすすけています。これは、かつて蒸気機関車が吐き出した煙のあとです。«ここを、汽車が煙をあげて走っていたんだ» ――すすの色が、100年以上前の風景を語りかけてきます。","1968年に複線化で隣に新しいトンネルができ、大日影トンネルは下り線専用に。そして1997年、線路の改良で役目を終えました。しばらく放置されていましたが、2005年にJRから旧勝沼町へゆずられ、2007年に遊歩道に生まれ変わりました。レールや待避所、キロポストも残され、鉄道の «現場» をそのまま感じられます。","その後、水もれなどのため長い間閉鎖されていましたが、改修工事をへて2024年に通行が再開されました。トンネルを抜けた先の旧深沢トンネルは、ワインを熟成させる «ワインカーヴ» として使われています。明治の鉄道遺産が、今もワインの町を支え続けているのです。"],"tl":[["1896年","中央本線 八王子〜甲府間の建設が始まる"],["1902年","大日影トンネルが貫通"],["1903年","八王子〜甲府間が単線で開通"],["1931年","この区間が電化される"],["1968年","複線化で新大日影トンネルが開通。旧トンネルは下り専用に"],["1997年","新しいトンネルの完成で使われなくなる"],["2007年","遊歩道として公開"],["2024年","改修工事をへて通行再開"]],"who":[["明治の鉄道建設の技術者・職人たち","れんがを積み、山をくぐるトンネルを掘った"],["勝沼のぶどう・ワイン農家","鉄道で東京へ産物を送り、産地を大きく育てた"],["甲州市（旧勝沼町）","トンネルをゆずり受け、遊歩道として整備した"]],"deep":["遊歩道の長さは1367.8m、幅は約3.6〜3.7m、高さ4.9m。片道30分ほどかかります。","勝沼ぶどう郷駅に向かって25‰（1000mで25m）の下り勾配がついています。","中には待避所が36か所あり、いくつかには建設当時のようすを伝えるパネルがあります。約330mの水路も見られます。","大日影トンネルは、深沢トンネル、勝沼宿の旧田中銀行、祝橋などとともに、ワイン産業を支えた遺産として «近代化産業遺産» に認定されています。","トンネル内にトイレはなく、公開時間（9時〜15時ごろ）や休みがあるので、事前に確認が必要です。","«大日影» の名は、トンネルが通る山の地名に由来します。"],"look":["明治のれんが積みの壁と、天井に残る蒸気機関車のすす","保存されたレールとキロポスト・勾配標","壁の待避所と説明パネル","出口近くの深沢トンネル（ワインカーヴ）"],"q":["トンネルの天井が黒いのはなぜ？","昔、蒸気機関車が吐き出した煙のすすがついたからです。"],"koji":[],"myth":"","img":["中央本線","勝沼ぶどう郷駅","甲州市"],"wp":"大日影トンネル遊歩道","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Oohikagetunnel-yuhodo.JPG",1898,2545,"大日影トンネル遊歩道"],["c:9/92/Oohikage-tunnel_%28200808%29.jpg",640,426],["c:e/e3/JRE_Chuo-Main-Line_Multiple-lines.jpg",2736,1824,"中央本線"],["c:f/f6/JR_Chuo-Main-Line_Katsunumabudokyo_Station_building.jpg",4017,2289,"勝沼ぶどう郷駅"],["c:1/1e/Marufuji_Winery_190907f.jpg",4496,3000,"甲州市"]]},{"id":"19_yamura_shi","n":"谷村（郡内の城下町・都留市）","yomi":"やむら","cat":"町","rank":"B","y":1532,"era":["muromachi","edo"],"sh":"","ad":"都留市上谷・下谷","st":"富士急行線谷村町駅から歩いて約5分","la":35.5515,"lo":138.9054,"hook":"芭蕉も半年を過ごした、富士山のふもとの小さな城下町。","lead":"谷村（やむら）は、今の都留市の中心にあたる町です。戦国時代には郡内地方を治めた小山田氏の館が置かれ、江戸時代には谷村藩の城下町として整えられました。俳人・松尾芭蕉が滞在したことでも知られます。城の建物は残っておらず、跡地は市役所などになっています。","story":["甲斐の国は、大きく «国中（くになか）» と «郡内（ぐんない）» に分かれていました。甲府盆地の国中に対し、郡内は富士山の北から東の山がちな地域です。戦国時代、この郡内を治めていたのが小山田氏でした。武田氏に従いながらも、独自の力をもつ有力な一族です。","1530年、小山田氏の館があった中津森で火事があり、館が焼けてしまいます。そこで新しい館を建てたのが、桂川と山にはさまれた谷村の地でした。1532年ごろに館が完成し、以後、小山田氏4代の本拠となります。«なぜ谷村に?» ――富士山へ向かう道と甲州街道を結ぶ交通の要所だったからと考えられます。","1582年、武田氏がほろびるとき、小山田信茂は最後に武田勝頼を見捨てたとされ、その後、織田信忠に処刑されてしまいます。小山田氏はここで絶えました。江戸時代になると、秋元氏が谷村藩主となり、用水路の «谷村大堰» や «家中川» を開いて、城下町を整えていきました。","1683年、この町に一人の旅人がやってきます。江戸の大火で家を失った俳人・松尾芭蕉です。谷村藩の家老で、芭蕉の門人でもあった高山伝右衛門（麋塒）に招かれ、芭蕉はこの地で半年ほど過ごしたといわれます。«富士山のふもとで、芭蕉は何を思ったのだろう?» ――町には芭蕉ゆかりの碑が残ります。","1704年、秋元氏が川越へ移ると、谷村城は廃城になり、郡内は幕府の代官が治める土地になりました。城下町は、絹織物 «郡内織（甲斐絹）» の産地としてにぎわいます。今も町の中を流れる家中川の清らかな水が、城下町の面影を伝えています。"],"tl":[["1530年","小山田氏の中津森館が焼ける"],["1532年ごろ","谷村に新しい館が完成"],["1582年","武田氏滅亡。小山田信茂が処刑され、小山田氏が絶える"],["1633年","秋元泰朝が谷村に入り、谷村藩が成立"],["1683年","松尾芭蕉が谷村に滞在したといわれる"],["1704年","秋元氏が川越へ移り、谷村城は廃城に"],["2014年","谷村城跡で初めての本格的な発掘調査"]],"who":[["小山田信有","郡内の国衆。谷村に館を移した"],["小山田信茂","小山田氏最後の当主。武田氏滅亡の際に勝頼から離れた"],["秋元富朝","谷村藩主。谷村大堰などの用水を開いた"],["松尾芭蕉","俳人。天和の大火のあと谷村に滞在"],["高山伝右衛門（麋塒）","谷村藩の家老で俳人。芭蕉を招いた"]],"deep":["谷村城の位置は、江戸時代の城下絵図から都留市役所から谷村第一小学校のあたりと考えられていますが、目に見える遺構はほとんど残っていません。","2014年の発掘では、石積みの地下室（穴蔵）が見つかり、アワビやサザエ、マダイ、マグロなど海の幸の骨が出土しました。19世紀の谷村陣屋の時代のものと考えられています。","桂川をはさんだ対岸には勝山城跡があり、谷村城の «詰めの城» だったという説もあります。","宇治から将軍に献上される «お茶壺» は、夏の間、谷村で保管されてから江戸へ運ばれたと伝えられます。","小山田信茂が勝頼を裏切ったとされる話は『甲陽軍鑑』などの記述によるもので、実際の事情については諸説あります。","«郡内織» は江戸時代から知られた絹織物で、のちの «甲斐絹» につながります。"],"look":["家中川の流れ（城下町の用水）","都留市役所周辺の谷村城跡の案内","松尾芭蕉ゆかりの碑","勝山城跡（桂川の対岸の山）"],"q":["谷村に半年ほど滞在したといわれる有名な俳人は？","松尾芭蕉です。江戸の大火で家を失ったあと、門人に招かれました。"],"koji":[],"myth":"芭蕉の滞在期間、お茶壺の保管の話、信茂の «裏切り» の経緯は諸説・伝承がある。","img":["谷村城","松尾芭蕉","小山田信茂"],"wp":"都留市","rel":{"ev":[],"grave":[]},"ph":[["c:9/97/SC_Maglev_Test_Ride_%2817844163173%29.jpg",5472,3648,"都留市"],["c:e/ef/Tsuru_city_center_area_Aerial_photograph.1975.jpg",4351,5392],["c:f/f5/Tsuru_University_Main_Building_ac_%281%29.jpg",5935,3946],["c:b/bf/Center_of_town_planning_and_Interaction%2C_Tsuru_2015-11-21_%281%29_sa.jpg",5472,3648],["c:4/4a/Yamanashi_Maglev_Test_Track5.jpg",3157,2040],["c:f/ff/Tsuru_IC_Tollgate1.jpg",2560,1920],["c:6/6d/Tsuru_Municipal_Hospital.JPG",2048,1536],["c:2/26/Tsuru_City_Fire_Department.JPG",2048,1536]]},{"id":"19_isawa","n":"甲斐国府跡（笛吹市春日居・御坂の国衙）","yomi":"かいこくふあと","cat":"遺跡","rank":"B","y":750,"era":["nara","heian"],"sh":"","ad":"笛吹市春日居町国府（初期国府の推定地）・御坂町国衙（後期国府の推定地）","st":"JR石和温泉駅・春日居町駅から車で約10分","la":35.66101,"lo":138.65103,"hook":"甲斐の国の «県庁» はどこにあったのか。地名だけが語る、1200年前のなぞ。","lead":"奈良・平安時代、甲斐の国を治める役所 «国府（国衙）» は、今の笛吹市にあったと考えられています。はじめは春日居町の «国府（こう）»、のちに御坂町の «国衙（こくが）» へ移ったとする説が有力ですが、役所の建物はまだ発掘で確かめられていません。近くには国の史跡 «甲斐国分寺跡» があります。","story":["奈良時代、日本の国々には都から «国司» が送られ、国府と呼ばれる役所で政治を行いました。今でいう «県庁» のようなものです。甲斐の国府はどこにあったのでしょう。手がかりの一つは、地名です。笛吹市春日居町には «国府（こう）»、御坂町には «国衙（こくが）» という地名が今も残っています。","平安時代の辞書『和名類聚抄』には、甲斐の国府は八代郡にあると書かれています。八代郡にあたるのは御坂町の国衙のあたりです。一方、春日居町の国府のあたりには古い寺の跡（寺本廃寺）があり、土地が東西南北にきちんと区切られていることから、«ここが最初の国府だったのでは?» と考えられてきました。","そこで生まれたのが、«はじめは春日居、のちに御坂へ移った» という説です。江戸時代の学者も唱えていた考えで、今も多くの人が支持しています。さらに、国分寺がある一宮町のあたりに «途中の国府» があったとする «三回移った» 説もあります。«どれが正しいの?» ――じつは、役所の建物の跡は、まだ発掘で見つかっていないのです。","国府の近くには、国ごとに建てられた国分寺と国分尼寺がありました。笛吹市一宮町に残る «甲斐国分寺跡» では、大きな塔の礎石などが見られ、国の史跡になっています。また春日居町の甲斐奈神社は、国司がまとめてお参りする «総社» だった可能性がある神社とされます。","甲斐は、朝廷に馬を納める «牧» の国としても知られ、聖徳太子が乗ったという «甲斐の黒駒» の伝説もあります。国府のあった笛吹市の田畑や住宅地を歩くと、目に見える遺構は少なくても、«国の中心» だった土地の広がりを感じることができます。"],"tl":[["7世紀後半","甲斐国が整えられ、国府が置かれたと考えられる"],["8世紀","甲斐国分寺・国分尼寺が建てられる"],["825年","御勅使川の洪水で、国司が朝廷に勅使を願ったと伝わる"],["10世紀","『和名類聚抄』に «国府は八代郡» と記される"],["江戸時代","『甲斐名勝志』などで国府移転説が唱えられる"],["1967年ごろ","研究者が方六町の国府の範囲を推定"]],"who":[["国司たち","都から送られ、甲斐の政治を行った役人"],["文室秋津","平安時代の甲斐国司。洪水の対策を朝廷に願ったと伝わる"],["萩原元克","江戸時代の学者。『甲斐名勝志』で国府移転説を記した"],["聖徳太子","«甲斐の黒駒» に乗ったという伝説の人物"]],"deep":["国府の場所は «二転説»（春日居→御坂）と «三転説»（春日居→一宮→御坂）があり、どちらも確定していません。","春日居町の初期国府推定地は、国府ではなく山梨郡の役所（郡家）だった可能性も指摘されています。","«国府（こう）» という地名は、全国各地で国府があった場所の手がかりになっていますが、それだけでは証拠になりません。","甲斐国分寺跡（笛吹市一宮町国分）は国の史跡で、七重塔の礎石が残るとされます。国分尼寺跡も近くにあります。","『延喜式』には、甲斐に朝廷の牧（御牧）が置かれたことが書かれ、甲斐は良い馬の産地として知られていました。","春日居町の国府推定地は、この案内の地図ピンの位置（甲斐奈神社付近）。御坂町国衙の後期国府推定地は、そこから南へ数kmの場所にあります。"],"look":["春日居町国府・御坂町国衙の地名が残る町並み","甲斐奈神社（総社の可能性があるとされる神社）","甲斐国分寺跡・国分尼寺跡（笛吹市一宮町）","山梨県立博物館（笛吹市御坂町）で古代甲斐の展示を見る"],"q":["甲斐の国府があった可能性がある笛吹市の二つの地名は？","春日居町の «国府（こう）» と、御坂町の «国衙（こくが）» です。"],"koji":[],"myth":"国府の位置・移転の回数は学説が分かれ、官衙の遺構は未発見。黒駒は伝説。","img":["甲斐国分寺","国府","甲斐の黒駒"],"wp":"甲斐国","rel":{"ev":[],"grave":[]},"ph":[["c:6/6a/Sakaorimiya_zenkei.jpg",4000,3000],["c:3/30/Kai-Choshizuka-kofun_%E2%84%961.JPG",4000,3000],["c:f/ff/Kai_Kokuga_government_ruins.jpg",3264,2448],["c:2/27/Ichinomiya_asama-jinja.jpg",2352,1568],["c:c/cc/Kai-kokubunji_hondou.JPG",3642,2726,"甲斐国分寺"],["c:4/49/Musashikokufuato.jpg",1600,1200,"国府"],["c:a/a5/Misaki-uma.jpg",1280,960,"甲斐の黒駒"]]},{"id":"19_shimoyama","n":"下山館跡（穴山梅雪の本拠）","yomi":"しもやまやかたあと","cat":"大名屋敷","rank":"B","y":1582,"era":["muromachi","azuchi"],"sh":"","ad":"南巨摩郡身延町下山","st":"JR身延線甲斐下山駅から歩いて約15分","la":35.4275,"lo":138.4455,"hook":"武田の一門でありながら、最後に武田を見限った男。その館があった山あいの町。","lead":"下山館は、武田氏の一族・穴山氏の本拠となった館です。富士川沿いの «河内領» を治めた穴山氏は、戦国時代にここを中心に町をつくりました。当主の穴山信君（梅雪）は、1582年に武田勝頼を離れて織田・徳川方につき、その直後に本能寺の変の混乱の中で命を落としました。館の建物は残っていません。","story":["富士川をさかのぼり、身延山の少し北。山にかこまれた下山の町は、戦国時代、穴山氏の «城下町» でした。穴山氏は武田氏の分家で、信玄の親類にあたります。甲斐の南、駿河（今川氏）との国境に近い «河内領» を治め、武田と今川の間をとりもつ、特別な立場の一族でした。","穴山信友の代に、本拠はそれまでの南部（今の南部町）から、より甲府に近い下山へ移されました。信友の妻は武田信虎の娘、その子・信君の妻は信玄の娘（見性院）。二代続けて武田宗家と結婚し、«御一門衆» と呼ばれる武田家のいちばん近い親族になったのです。","信君は、信玄・勝頼の二代に仕え、駿河の江尻城をまかされる重臣でした。ところが1582年、織田信長の軍が攻めてくると、信君は徳川家康を通じて織田方につきます。武田一門の重鎮の «寝返り» は、武田家に大きな衝撃をあたえました。«なぜ?» ――勝頼との関係の悪化や、自分の家を守るためなど、理由はさまざまに考えられています。","武田氏がほろびたあと、信君は信長から領地を認められ、家康とともに安土城へ、そして堺へと旅をします。その途中の6月2日、本能寺の変の知らせが届きました。家康は «伊賀越え» で三河へ逃げ帰りますが、信君は別行動をとり、京都の南のあたりで一揆に襲われて命を落としたといわれます。","信君の死後、家康は穴山家の家臣たちを守り、子の勝千代にあとを継がせました。ところが勝千代も1587年、16歳で亡くなり、穴山家は絶えてしまいます。今の下山には、館があったとされる場所に日蓮宗の寺・本国寺が建ち、腕のいい «下山大工» の町としての伝統も語り継がれています。"],"tl":[["16世紀前半","穴山信友が本拠を南部から下山へ移し、城下町を整える"],["1541年","信玄が家督をつぐ（穴山氏は武田一門として仕える）"],["1569年ごろ","武田氏が駿河に進出。信君は江尻城代になる"],["1580年","信君が出家して «梅雪斎不白» と名のる"],["1582年2〜3月","信君が織田・徳川方につく。武田氏滅亡"],["1582年6月2日","本能寺の変。信君が京都近くで命を落とす"],["1587年","子の勝千代が病死し、穴山家が絶える"]],"who":[["穴山信友","信君の父。本拠を下山に移した"],["穴山信君（梅雪）","穴山家当主。最後に武田を離れた"],["見性院","信君の妻で信玄の娘。夫と子を失ったのち、家康に保護された"],["穴山勝千代","信君の子。16歳で死去"],["徳川家康","信君と行動をともにし、のちに穴山家臣を保護した"]],"deep":["信君の最期は、『フロイス日本史』では家康から遅れて移動中に落ち武者狩りに襲われたとし、別の史料は家康を疑って別行動をとったためとするなど、説が分かれます。","下山は甲府にも駿府（今川氏の本拠）にも近い位置にあり、穴山氏が両方と独自の関係をもっていたことを示しているといわれます。","河内領は山がちで、木材の切り出しや板の加工、鷹の飼育、狩猟など «山の仕事» がさかんでした。«下山大工» はその技術を伝える大工集団として知られます。","下山館跡が今の本国寺の場所だとする見方がありますが、館の範囲や構造は発掘で十分に確かめられていません。","勝千代の死後、家康は武田ゆかりの側室・下山殿（於都摩の方）との間の子・万千代（武田信吉）に武田の名跡を継がせました。","穴山信君は後世 «武田二十四将» の一人にも数えられます。"],"look":["本国寺の境内（館跡と伝わる場所。参拝のマナーを守って）","下山の町並みと、富士川・早川の合流する地形","身延山久遠寺や南部町の最恩寺（勝千代の菩提寺）とあわせて"],"q":["穴山信君が出家してから名のった名前は？","«梅雪（ばいせつ）» です。穴山梅雪の名でよく知られます。"],"koji":[],"myth":"館跡の正確な位置、信君が離反した理由、最期の様子は諸説ある。","img":["見性院","本能寺の変","伊賀越え"],"wp":"穴山信君","rel":{"ev":[],"grave":[]},"ph":[["c:a/a4/Anayama_Nobukimi.jpg",1935,1635,"穴山信君"],["c:d/d7/Anayama_izunokami.jpg",730,1060],["c:e/e3/Honnoj.jpg",3200,1565,"本能寺の変"]]},{"id":"19_kofu_han","n":"甲府藩（柳沢吉保・吉里の城下町）","yomi":"こうふはん","cat":"町","rank":"B","y":1704,"era":["edo"],"sh":"国指定史跡（甲府城跡）","ad":"甲府市丸の内（甲府城跡・舞鶴城公園）","st":"JR甲府駅南口から歩いて約5分","la":35.66529,"lo":138.57134,"hook":"将軍の «右腕» が手に入れた、江戸を守る西の要。20年で終わった柳沢家の甲府。","lead":"甲府藩は、江戸時代に甲府城を中心として甲斐を治めた藩です。徳川の親族が藩主をつとめたあと、1704年に5代将軍綱吉の側用人・柳沢吉保が藩主となり、子の吉里とともに城と城下町を整えました。1724年に柳沢家が大和郡山へ移ると、甲斐は幕府の直轄地になりました。","story":["甲府駅の南口を出るとすぐ、石垣の城跡が見えます。甲府城です。武田氏がほろびたあと、徳川家康や豊臣秀吉の家臣たちによって築かれ、江戸時代には «江戸の西を守る要» とされました。だからこそ、城主には将軍の家族や、とくに信頼された人物が選ばれたのです。","1704年、この城の主になったのが柳沢吉保です。吉保は、身分の低い家から出発し、5代将軍綱吉のそば近くに仕える «側用人» として出世を重ねた人物でした。«将軍の右腕» ともいわれた吉保にとって、甲府城をまかされることは、大きな名誉でした。","吉保は、自分の家が甲斐源氏・武田氏の流れをくむと考えていました。そのため、甲斐をとても大事にし、恵林寺にある武田信玄の墓所を整えたり、信玄の法要を行ったりしたと伝わります。甲府城も大がかりに修理され、城下町もにぎわいました。«江戸にも負けない» 町づくりをめざしたともいわれます。","1709年、吉保は隠居し、長男の吉里があとを継ぎます。吉里は甲府に入り、城下の整備を進めました。ところが1724年、8代将軍吉宗の «享保の改革» の中で、柳沢家は大和郡山（奈良県）へ移されることになります。«なぜ甲府から?» ――幕府が甲斐を直接治め、財政を強くするためだったと考えられています。","柳沢家が去ったあと、甲府には «甲府勤番» と呼ばれる幕府の役人が江戸から送られました。遠くへ行かされることから «山流し» とも呼ばれ、あまり歓迎されない役目だったといいます。今の甲府城跡には、復元された稲荷櫓や鉄門が立ち、天守台からは甲府の町と富士山を見わたせます。"],"tl":[["1583年ごろ〜","徳川家康の命で甲府城の築城が計画されたといわれる"],["1590年代","豊臣系大名のもとで甲府城がほぼ完成"],["1661年","徳川綱重のもとで甲府藩の藩政が本格的に始まる"],["1704年","徳川綱豊が将軍の後継ぎに。柳沢吉保が甲府藩主となる"],["1709年","吉保が隠居し、吉里が藩主に"],["1724年","柳沢家が大和郡山へ移り、甲斐は幕府直轄地に。甲府勤番が置かれる"],["2019年","甲府城跡が国の史跡に指定される"]],"who":[["柳沢吉保","5代将軍綱吉の側用人。甲府藩主となった"],["柳沢吉里","吉保の子。甲府城と城下町を整えた"],["徳川綱吉","5代将軍。吉保を重く用いた"],["徳川綱豊（家宣）","甲府藩主から6代将軍になった"],["徳川吉宗","8代将軍。享保の改革で柳沢家を大和郡山へ移した"]],"deep":["甲府藩主のうち、徳川綱重・綱豊（家宣）は将軍の一族で、綱豊はのちに6代将軍家宣となりました。«甲府宰相» と呼ばれた家です。","柳沢家の石高は約15万石。吉里の弟2人にそれぞれ1万石ずつを分けた «甲府新田藩» もありました。","吉保は甲府の岩窪に黄檗宗の永慶寺を建てました。柳沢家が去ったあと、その仏殿は大泉寺に移されたと伝わります。","吉保自身は将軍のそばを離れられず、甲府に来ることはなかったといわれます。","甲府城跡からは金箔をはった鯱瓦が出土しており、豊臣時代の城の豪華さを伝えます（山梨県指定文化財）。","甲府城は明治時代に廃城となり、中央線の線路が城跡の一部を通っています。2004年に稲荷櫓、2013年に鉄門が復元されました。"],"look":["天守台と野面積みの石垣","復元された稲荷櫓と鉄門","城跡から見る甲府の町と富士山","城跡の北、甲府駅北口側の歴史公園（復元された山手渡櫓門）"],"q":["甲府藩主から将軍になった人物は？","徳川綱豊、のちの6代将軍・徳川家宣です。"],"koji":[],"myth":"吉保が甲府に来なかったこと、甲府勤番 «山流し» の評判は伝えられる話。","img":["甲府城","柳沢吉保","柳沢吉里","甲府勤番"],"wp":"甲府藩","rel":{"ev":[],"grave":[]},"ph":[["c:3/3b/Koufu_Castle_%284936837377%29.jpg",1280,853,"甲府城"],["c:1/13/Yanagisawa_Yoshiyasu.jpg",627,658,"柳沢吉保"],["c:9/95/Lake_Kawaguchiko_Sakura_Mount_Fuji_3.JPG",3872,2592,"近く: 山梨県"],["c:f/f7/K%C5%8Dfu_Station_201904a.jpg",4496,3000,"近く: 甲府駅"],["c:5/5f/SAINTS25_cropped.jpg",463,771,"近く: セインツ.25"],["c:3/31/Yamako-dept.JPG",1280,960,"近く: 山交百貨店"],["c:4/4a/KOKORI_at_Kofu_city.JPG",3000,4000,"近く: 山梨県立宝石美術専門学校"]]}];
